--
-- Name: _tg_derivar_template_v2(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public._tg_derivar_template_v2() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF TG_OP = 'INSERT'
     OR NEW.conteudo_comum IS NULL
     OR (
       TG_OP = 'UPDATE' AND (
         NEW.conteudo IS DISTINCT FROM OLD.conteudo
         OR NEW.valor_a_vista IS DISTINCT FROM OLD.valor_a_vista
         OR NEW.campos_obrigatorios IS DISTINCT FROM OLD.campos_obrigatorios
         OR NEW.chave_pix IS DISTINCT FROM OLD.chave_pix
         OR NEW.link_parcelamento IS DISTINCT FROM OLD.link_parcelamento
         OR NEW.posicao_pagamento IS DISTINCT FROM OLD.posicao_pagamento
         OR NEW.instrucao_selfie IS DISTINCT FROM OLD.instrucao_selfie
         OR NEW.num_testemunhas IS DISTINCT FROM OLD.num_testemunhas
         OR NEW.produto_id IS DISTINCT FROM OLD.produto_id
       )
     )
  THEN
    -- BLINDAGEM (B5): derivar metadados inertes JAMAIS aborta o save do template.
    BEGIN
      PERFORM public.derivar_template_v2(NEW.id);
    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING 'derivar_template_v2 falhou para template % (save preservado): %', NEW.id, SQLERRM;
    END;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public._tg_derivar_template_v2() OWNER TO postgres;

--
-- Name: abrir_objetivo_pilha(uuid, uuid, text, text, uuid, integer, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.abrir_objetivo_pilha(p_conversa_id uuid, p_tenant_id uuid, p_objetivo text, p_contexto text DEFAULT NULL::text, p_lead_id uuid DEFAULT NULL::uuid, p_prioridade integer DEFAULT 5, p_origem text DEFAULT 'porteiro'::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_id uuid;
BEGIN
  -- Limite duro: max 5 objetivos abertos por conversa
  IF (SELECT count(*) FROM public.pilha_objetivos 
      WHERE conversa_id = p_conversa_id AND status = 'aberto' AND deleted_at IS NULL) >= 5 THEN
    -- Fecha o mais antigo automaticamente
    UPDATE public.pilha_objetivos 
    SET status = 'expirado', fechado_em = now(), motivo_fechamento = 'limite excedido (max 5)'
    WHERE id = (SELECT id FROM public.pilha_objetivos 
                WHERE conversa_id = p_conversa_id AND status = 'aberto' AND deleted_at IS NULL
                ORDER BY criado_em ASC LIMIT 1);
  END IF;

  -- Não duplicar: se já tem objetivo igual aberto, retorna ele
  SELECT id INTO v_id FROM public.pilha_objetivos
  WHERE conversa_id = p_conversa_id 
    AND status = 'aberto' 
    AND deleted_at IS NULL
    AND lower(objetivo) = lower(p_objetivo)
  LIMIT 1;

  IF v_id IS NOT NULL THEN
    RETURN v_id;
  END IF;

  INSERT INTO public.pilha_objetivos
    (conversa_id, tenant_id, lead_id, objetivo, contexto, prioridade, origem)
  VALUES
    (p_conversa_id, p_tenant_id, p_lead_id, p_objetivo, p_contexto, p_prioridade, p_origem)
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;


ALTER FUNCTION public.abrir_objetivo_pilha(p_conversa_id uuid, p_tenant_id uuid, p_objetivo text, p_contexto text, p_lead_id uuid, p_prioridade integer, p_origem text) OWNER TO postgres;

--
-- Name: admin_agregar(text, text[], jsonb, jsonb, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.admin_agregar(p_tabela text, p_group_by text[] DEFAULT ARRAY[]::text[], p_metricas jsonb DEFAULT '[{"alias": "total", "coluna": "*", "funcao": "count"}]'::jsonb, p_filtros jsonb DEFAULT '{}'::jsonb, p_limite integer DEFAULT 100) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
  v_whitelist TEXT[] := ARRAY[
    'conversas', 'leads', 'mensagens', 'profiles',
    'campanhas', 'fases_campanha', 'leads_campanha',
    'lead_memory_fatos', 'admin_ia_blocos', 'admin_ia_memoria',
    'admin_ia_propostas', 'admin_ia_acoes', 'admin_ia_reflexao',
    'blocos_conhecimento', 'blocos_comportamento', 'blocos_gatilho', 'blocos_meta',
    'registro_reflexao', 'observacoes_tag', 'logs_requisicao_llm'
  ];
  v_select TEXT := '';
  v_group_clause TEXT := '';
  v_where TEXT := '';
  v_query TEXT;
  v_metrica JSONB;
  v_func TEXT;
  v_col TEXT;
  v_alias TEXT;
  v_filtro_key TEXT;
  v_filtro_val TEXT;
  v_resultado JSONB;
  v_safe_ident TEXT := '^[a-z_][a-z0-9_]{0,40}$';
BEGIN
  IF NOT (p_tabela = ANY(v_whitelist)) THEN
    RAISE EXCEPTION 'tabela_fora_whitelist:%', p_tabela;
  END IF;

  -- group_by
  IF array_length(p_group_by, 1) > 0 THEN
    FOR i IN 1..array_length(p_group_by, 1) LOOP
      IF NOT (p_group_by[i] ~ v_safe_ident) THEN
        RAISE EXCEPTION 'group_by_invalido:%', p_group_by[i];
      END IF;
      v_select := v_select || quote_ident(p_group_by[i]) || ', ';
      IF v_group_clause = '' THEN v_group_clause := ' GROUP BY ' || quote_ident(p_group_by[i]);
      ELSE v_group_clause := v_group_clause || ', ' || quote_ident(p_group_by[i]); END IF;
    END LOOP;
  END IF;

  -- metricas
  FOR v_metrica IN SELECT jsonb_array_elements(p_metricas) LOOP
    v_func := lower(v_metrica->>'funcao');
    v_col := v_metrica->>'coluna';
    v_alias := v_metrica->>'alias';
    IF NOT (v_func IN ('count', 'sum', 'avg', 'min', 'max')) THEN
      RAISE EXCEPTION 'funcao_invalida:%', v_func;
    END IF;
    IF v_col != '*' AND NOT (v_col ~ v_safe_ident) THEN
      RAISE EXCEPTION 'coluna_invalida:%', v_col;
    END IF;
    IF NOT (v_alias ~ v_safe_ident) THEN
      RAISE EXCEPTION 'alias_invalido:%', v_alias;
    END IF;
    v_select := v_select || upper(v_func) || '(' || (CASE WHEN v_col='*' THEN '*' ELSE quote_ident(v_col) END) || ') AS ' || quote_ident(v_alias) || ', ';
  END LOOP;

  v_select := rtrim(v_select, ', ');

  -- filtros simples (jsonb tipo {coluna: valor})
  FOR v_filtro_key IN SELECT * FROM jsonb_object_keys(p_filtros) LOOP
    IF NOT (v_filtro_key ~ v_safe_ident) THEN
      RAISE EXCEPTION 'filtro_invalido:%', v_filtro_key;
    END IF;
    v_filtro_val := p_filtros->>v_filtro_key;
    IF v_where = '' THEN v_where := ' WHERE '; ELSE v_where := v_where || ' AND '; END IF;
    v_where := v_where || quote_ident(v_filtro_key) || ' = ' || quote_literal(v_filtro_val);
  END LOOP;

  v_query := 'SELECT ' || v_select || ' FROM public.' || quote_ident(p_tabela) || v_where || v_group_clause || ' LIMIT ' || least(coalesce(p_limite, 100), 500);

  PERFORM set_config('statement_timeout', '5s', true);
  EXECUTE 'SELECT coalesce(jsonb_agg(t), ''[]''::jsonb) FROM (' || v_query || ') t' INTO v_resultado;
  RETURN v_resultado;
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('erro', SQLERRM, 'sql_state', SQLSTATE);
END;
$_$;


ALTER FUNCTION public.admin_agregar(p_tabela text, p_group_by text[], p_metricas jsonb, p_filtros jsonb, p_limite integer) OWNER TO postgres;

--
-- Name: admin_descrever_tabela(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.admin_descrever_tabela(p_tabela text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_whitelist TEXT[] := ARRAY[
    'conversas', 'leads', 'profiles', 'mensagens',
    'campanhas', 'fases_campanha', 'leads_campanha',
    'memoria_lead', 'lead_memory_fatos', 'crenca_conversa',
    'admin_ia_blocos', 'admin_ia_memoria', 'admin_ia_propostas',
    'admin_ia_relatorios', 'admin_ia_agendamentos', 'admin_ia_acoes',
    'admin_ia_conversas', 'admin_ia_reflexao',
    'blocos_conhecimento', 'blocos_comportamento', 'blocos_gatilho',
    'blocos_humanizacao', 'blocos_variacao', 'blocos_meta',
    'memoria_episodica', 'blocos_procedurais', 'registro_reflexao',
    'observacoes_tag', 'vocabulario_canonico',
    'agentes_usuario', 'logs_requisicao_llm',
    'acao_pausa_blocos', 'automacao_blocos', 'automacao_semantica',
    'diretriz_bolha_blocos', 'emocao_blocos', 'prova_social_blocos',
    'manipulacao_blocos', 'manipulacao_log', 'regras_operacionais_blocos',
    'blocos_padrao', 'candidatos_bloco', 'auditoria_blocos',
    'vocabulario_curadoria', 'alias_vocabulario_tag',
    'overrides_tenant_blocos_conhecimento', 'overrides_tenant_blocos_comportamento',
    'overrides_tenant_blocos_gatilho', 'overrides_tenant_blocos_humanizacao',
    'overrides_tenant_blocos_variacao', 'overrides_tenant_blocos_meta',
    'meta_indicacao_campanha', 'comissoes_indicacao_campanha',
    'loja_implantacao'
  ];
  v_colunas JSONB;
  v_count BIGINT;
  v_samples JSONB;
BEGIN
  IF NOT (p_tabela = ANY(v_whitelist)) THEN
    RAISE EXCEPTION 'tabela_fora_da_whitelist:%', p_tabela;
  END IF;

  PERFORM set_config('statement_timeout', '5s', true);
  PERFORM set_config('search_path', 'public', true);

  -- Colunas
  SELECT coalesce(jsonb_agg(jsonb_build_object('nome', column_name, 'tipo', data_type, 'nullable', is_nullable) ORDER BY ordinal_position), '[]'::jsonb)
  INTO v_colunas
  FROM information_schema.columns
  WHERE table_schema = 'public' AND table_name = p_tabela;

  -- Count aproximado (estimado via reltuples; rápido em tabelas grandes)
  EXECUTE 'SELECT count(*) FROM public.' || quote_ident(p_tabela) INTO v_count;

  -- 3 samples (apenas leitura — função tem SECURITY DEFINER, RLS bypass intencional pra exploração admin)
  EXECUTE 'SELECT coalesce(jsonb_agg(t), ''[]''::jsonb) FROM (SELECT * FROM public.' || quote_ident(p_tabela) || ' LIMIT 3) t' INTO v_samples;

  RETURN jsonb_build_object(
    'tabela', p_tabela,
    'total_linhas', v_count,
    'colunas', v_colunas,
    'samples', v_samples
  );
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('erro', SQLERRM, 'sql_state', SQLSTATE);
END;
$$;


ALTER FUNCTION public.admin_descrever_tabela(p_tabela text) OWNER TO postgres;

--
-- Name: admin_excluir_usuarios(uuid[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.admin_excluir_usuarios(p_user_ids uuid[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_caller_role text; v_uid uuid; v_deleted int := 0;
BEGIN
  SELECT system_role INTO v_caller_role FROM public.profiles WHERE id = (SELECT auth.uid()) LIMIT 1;
  IF v_caller_role IS DISTINCT FROM 'platform_admin' THEN RAISE EXCEPTION 'Apenas administradores podem deletar usuarios'; END IF;
  IF (SELECT auth.uid()) = ANY(p_user_ids) THEN RAISE EXCEPTION 'Voce nao pode deletar sua propria conta'; END IF;
  DELETE FROM public.blocos_conhecimento WHERE agente_id IN (SELECT id FROM public.agentes_usuario WHERE user_id = ANY(p_user_ids));
  DELETE FROM public.leads WHERE id IN (SELECT l.id FROM public.leads l JOIN public.conversas c ON c.lead_id = l.id WHERE c.tenant_id = ANY(p_user_ids));
  DELETE FROM public.conversas WHERE tenant_id = ANY(p_user_ids);
  FOREACH v_uid IN ARRAY p_user_ids LOOP DELETE FROM auth.users WHERE id = v_uid; v_deleted := v_deleted + 1; END LOOP;
  RETURN jsonb_build_object('deleted', v_deleted);
END;
$$;


ALTER FUNCTION public.admin_excluir_usuarios(p_user_ids uuid[]) OWNER TO postgres;

--
-- Name: admin_liberar_pacote_tenant(uuid, uuid, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.admin_liberar_pacote_tenant(p_pacote_id uuid, p_tenant_id uuid, p_liberar boolean DEFAULT true) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_pc public.pacotes_conhecimento%ROWTYPE;
  v_slug text;
BEGIN
  IF NOT public.eh_admin_plataforma() THEN
    RAISE EXCEPTION 'apenas admin' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO v_pc FROM public.pacotes_conhecimento WHERE id = p_pacote_id AND origem = 'admin';
  IF v_pc.loja_aplicativo_id IS NULL THEN
    RAISE EXCEPTION 'pacote não está publicado na Loja' USING ERRCODE = '22023';
  END IF;
  SELECT slug INTO v_slug FROM public.loja_aplicativos WHERE id = v_pc.loja_aplicativo_id;

  IF p_liberar THEN
    INSERT INTO public.aplicativos_instalados (user_id, aplicativo_id, aplicativo_slug)
    VALUES (p_tenant_id, v_pc.loja_aplicativo_id, v_slug)
    ON CONFLICT (user_id, aplicativo_id) DO NOTHING;
  ELSE
    DELETE FROM public.aplicativos_instalados
     WHERE user_id = p_tenant_id AND aplicativo_id = v_pc.loja_aplicativo_id;
    UPDATE public.pacotes_conhecimento_ativacao
       SET ligado = false
     WHERE pacote_id = p_pacote_id AND tenant_id = p_tenant_id AND ligado;
  END IF;
END;
$$;


ALTER FUNCTION public.admin_liberar_pacote_tenant(p_pacote_id uuid, p_tenant_id uuid, p_liberar boolean) OWNER TO postgres;

--
-- Name: admin_publicar_pacote_loja(uuid, numeric, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.admin_publicar_pacote_loja(p_pacote_id uuid, p_preco_mensal numeric DEFAULT NULL::numeric, p_publicado boolean DEFAULT true) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_pc public.pacotes_conhecimento%ROWTYPE;
  v_app uuid;
BEGIN
  IF NOT public.eh_admin_plataforma() THEN
    RAISE EXCEPTION 'apenas admin' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO v_pc FROM public.pacotes_conhecimento WHERE id = p_pacote_id AND origem = 'admin';
  IF v_pc.id IS NULL THEN
    RAISE EXCEPTION 'pacote admin % não encontrado', p_pacote_id USING ERRCODE = 'P0002';
  END IF;

  IF v_pc.loja_aplicativo_id IS NULL THEN
    INSERT INTO public.loja_aplicativos (slug, nome, descricao, icone, categoria, preco_mensal, is_active, ordem)
    VALUES ('pacote-' || replace(v_pc.id::text, '-', ''), v_pc.nome, v_pc.descricao, v_pc.icone,
            'conhecimento', p_preco_mensal, p_publicado, v_pc.ordem)
    RETURNING id INTO v_app;
    UPDATE public.pacotes_conhecimento SET loja_aplicativo_id = v_app WHERE id = v_pc.id;
  ELSE
    v_app := v_pc.loja_aplicativo_id;
    UPDATE public.loja_aplicativos
       SET nome = v_pc.nome, descricao = v_pc.descricao, icone = v_pc.icone,
           preco_mensal = p_preco_mensal, is_active = p_publicado, ordem = v_pc.ordem
     WHERE id = v_app;
  END IF;

  -- Pacote de nicho: o item da Loja também fica restrito ao nicho.
  DELETE FROM public.aplicativos_nicho WHERE aplicativo_id = v_app;
  IF v_pc.nicho_id IS NOT NULL THEN
    INSERT INTO public.aplicativos_nicho (aplicativo_id, nicho_id) VALUES (v_app, v_pc.nicho_id);
  END IF;

  RETURN v_app;
END;
$$;


ALTER FUNCTION public.admin_publicar_pacote_loja(p_pacote_id uuid, p_preco_mensal numeric, p_publicado boolean) OWNER TO postgres;

--
-- Name: admin_query_sql(text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.admin_query_sql(p_query text, p_limite integer DEFAULT 100) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
  v_query TEXT := trim(p_query);
  v_lower TEXT := lower(v_query);
  v_resultado JSONB;
  v_limite INT := least(coalesce(p_limite, 100), 500);
  v_whitelist TEXT[] := ARRAY[
    'conversas', 'leads', 'profiles', 'mensagens',
    'campanhas', 'fases_campanha', 'leads_campanha',
    'memoria_lead', 'lead_memory_fatos', 'crenca_conversa',
    'admin_ia_blocos', 'admin_ia_memoria', 'admin_ia_propostas',
    'admin_ia_relatorios', 'admin_ia_agendamentos', 'admin_ia_acoes',
    'admin_ia_conversas', 'admin_ia_reflexao',
    'blocos_conhecimento', 'blocos_comportamento', 'blocos_gatilho',
    'blocos_humanizacao', 'blocos_variacao', 'blocos_meta',
    'memoria_episodica', 'blocos_procedurais', 'registro_reflexao',
    'observacoes_tag', 'vocabulario_canonico',
    'agentes_usuario', 'logs_requisicao_llm',
    'acao_pausa_blocos', 'automacao_blocos', 'automacao_semantica',
    'diretriz_bolha_blocos', 'emocao_blocos', 'prova_social_blocos',
    'manipulacao_blocos', 'manipulacao_log', 'regras_operacionais_blocos',
    'blocos_padrao', 'candidatos_bloco', 'auditoria_blocos',
    'vocabulario_curadoria', 'alias_vocabulario_tag',
    'overrides_tenant_blocos_conhecimento', 'overrides_tenant_blocos_comportamento',
    'overrides_tenant_blocos_gatilho', 'overrides_tenant_blocos_humanizacao',
    'overrides_tenant_blocos_variacao', 'overrides_tenant_blocos_meta',
    'meta_indicacao_campanha', 'comissoes_indicacao_campanha',
    'loja_implantacao'
  ];
  v_t TEXT;
  v_tabela_ok BOOLEAN := false;
BEGIN
  IF v_query = '' THEN RAISE EXCEPTION 'query_vazia'; END IF;
  IF NOT v_lower ~ '^\s*select\s' THEN RAISE EXCEPTION 'apenas_select_permitido'; END IF;
  IF v_lower ~* '\m(insert|update|delete|drop|truncate|alter|create|grant|revoke|copy|do)\M' THEN
    RAISE EXCEPTION 'mutacao_proibida'; END IF;
  IF position(';' IN trim(trailing ';' FROM v_query)) > 0 THEN
    RAISE EXCEPTION 'multiplas_statements_proibidas'; END IF;
  FOREACH v_t IN ARRAY v_whitelist LOOP
    IF v_lower ~ ('(from|join)\s+(public\.)?' || v_t || '(\s|$|,|\)|;)') THEN
      v_tabela_ok := true; EXIT;
    END IF;
  END LOOP;
  IF NOT v_tabela_ok THEN RAISE EXCEPTION 'nenhuma_tabela_do_whitelist_encontrada'; END IF;
  IF NOT v_lower ~* '\mlimit\s+\d+' THEN
    v_query := v_query || ' LIMIT ' || v_limite; END IF;
  PERFORM set_config('statement_timeout', '5s', true);
  PERFORM set_config('search_path', 'public', true);
  EXECUTE 'SELECT coalesce(jsonb_agg(t), ''[]''::jsonb) FROM (' || v_query || ') t' INTO v_resultado;
  RETURN v_resultado;
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('erro', SQLERRM, 'sql_state', SQLSTATE);
END;
$_$;


ALTER FUNCTION public.admin_query_sql(p_query text, p_limite integer) OWNER TO postgres;

--
-- Name: admin_uso_pacote(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.admin_uso_pacote(p_pacote_id uuid) RETURNS TABLE(tenant_id uuid, tenant_nome text, instalado boolean, agentes_ligados integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF NOT public.eh_admin_plataforma() THEN
    RAISE EXCEPTION 'apenas admin' USING ERRCODE = '42501';
  END IF;
  RETURN QUERY
  WITH pc AS (SELECT * FROM public.pacotes_conhecimento WHERE id = p_pacote_id),
  t AS (
    SELECT ai.user_id AS tid FROM public.aplicativos_instalados ai, pc WHERE ai.aplicativo_id = pc.loja_aplicativo_id
    UNION
    SELECT pa.tenant_id FROM public.pacotes_conhecimento_ativacao pa WHERE pa.pacote_id = p_pacote_id
  )
  SELECT t.tid,
         coalesce(p.full_name, p.email, t.tid::text),
         EXISTS (SELECT 1 FROM public.aplicativos_instalados ai, pc WHERE ai.user_id = t.tid AND ai.aplicativo_id = pc.loja_aplicativo_id),
         (SELECT count(*)::int FROM public.pacotes_conhecimento_ativacao pa WHERE pa.pacote_id = p_pacote_id AND pa.tenant_id = t.tid AND pa.ligado)
  FROM t LEFT JOIN public.profiles p ON p.id = t.tid
  ORDER BY 2;
END;
$$;


ALTER FUNCTION public.admin_uso_pacote(p_pacote_id uuid) OWNER TO postgres;

--
-- Name: adquirir_trava_motor(uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.adquirir_trava_motor(p_conversation_id uuid, p_ttl_segundos integer DEFAULT 180) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_linhas integer;
BEGIN
  INSERT INTO public.travas_conversa (conversation_id, locked_at, expires_at)
  VALUES (p_conversation_id, now(), now() + make_interval(secs => p_ttl_segundos))
  ON CONFLICT (conversation_id) DO UPDATE
    SET locked_at = now(), expires_at = now() + make_interval(secs => p_ttl_segundos)
    WHERE public.travas_conversa.expires_at < now();
  GET DIAGNOSTICS v_linhas = ROW_COUNT;
  RETURN v_linhas > 0;
END;
$$;


ALTER FUNCTION public.adquirir_trava_motor(p_conversation_id uuid, p_ttl_segundos integer) OWNER TO postgres;

--
-- Name: agendar_pos_venda_relacionamento(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.agendar_pos_venda_relacionamento() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_agente uuid;
  v_cfg jsonb;
  v_horas jsonb;
  v_total int;
  v_i int := 0;
  v_h jsonb;
begin
  if new.conversa_id is null then return new; end if;
  begin
    v_agente := coalesce(new.agente_id, (select c.agente_id from public.conversas c where c.id = new.conversa_id));
    if v_agente is null then return new; end if;
    select a.configuracao -> 'pos_venda_relacionamento' into v_cfg from public.agentes_usuario a where a.id = v_agente;
    if v_cfg is null or coalesce((v_cfg ->> 'ativo')::boolean, false) = false then return new; end if;

    v_horas := case when jsonb_typeof(v_cfg -> 'horas') = 'array' then v_cfg -> 'horas' else '[1,3,5]'::jsonb end;
    v_total := jsonb_array_length(v_horas);
    -- Idempotente: contrato reassinado/atualizado não duplica os toques.
    if exists (select 1 from public.acoes_agendadas x
                where x.conversation_id = new.conversa_id and x.action_type = 'pos_venda_relacionamento'
                  and x.carga ->> 'contrato_id' = new.id::text) then
      return new;
    end if;
    for v_h in select * from jsonb_array_elements(v_horas) loop
      v_i := v_i + 1;
      insert into public.acoes_agendadas (conversation_id, agente_id, tenant_id, lead_id, action_type, scheduled_at, status, carga)
      values (new.conversa_id, v_agente, new.tenant_id, new.lead_id, 'pos_venda_relacionamento',
              new.assinado_em + make_interval(mins => (v_h::text::numeric * 60)::int), 'pendente',
              jsonb_build_object('tentativa', v_i, 'total_tentativas', v_total, 'contrato_id', new.id,
                                 'silencio_min_minutos', coalesce((v_cfg ->> 'silencio_min_minutos')::int, 40),
                                 'origem', 'trigger_contrato_assinado'));
    end loop;
  exception when others then
    raise warning 'agendar_pos_venda_relacionamento falhou (contrato %): %', new.id, sqlerrm;
  end;
  return new;
end;
$$;


ALTER FUNCTION public.agendar_pos_venda_relacionamento() OWNER TO postgres;

--
-- Name: agendar_reuniao(text, timestamp with time zone, integer, integer, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.agendar_reuniao(p_titulo text, p_agendada_para timestamp with time zone, p_duracao_min integer DEFAULT 60, p_max integer DEFAULT 6, p_exige_aprovacao boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid uuid := (select auth.uid());
  v_tenant uuid;
  v_sala_id uuid;
  v_evento_id uuid;
  v_chave uuid;
  v_titulo text;
  v_teto integer;
  v_max integer;
begin
  if v_uid is null then
    raise exception 'nao_autenticado';
  end if;
  if p_agendada_para is null then
    raise exception 'data_obrigatoria';
  end if;

  select coalesce(p.parent_user_id, p.id) into v_tenant
    from public.profiles p where p.id = v_uid;
  if v_tenant is null then
    v_tenant := v_uid;
  end if;

  select coalesce(reuniao_limite_participantes, 6) into v_teto from public.config_plataforma limit 1;
  if v_teto is null then v_teto := 6; end if;
  v_max := least(greatest(coalesce(p_max, 6), 2), v_teto);

  v_titulo := coalesce(nullif(btrim(p_titulo), ''), 'Reunião');

  insert into public.salas_reuniao (tenant_id, criada_por, titulo, status, max_participantes, agendada_para, duracao_min, exige_aprovacao)
    values (v_tenant, v_uid, v_titulo, 'agendada', v_max, p_agendada_para, coalesce(p_duracao_min, 60), coalesce(p_exige_aprovacao, false))
    returning id, chave_publica into v_sala_id, v_chave;

  insert into public.eventos_agenda (tenant_id, criado_por, titulo, tipo, inicio_em, fim_em, sala_reuniao_id, cor)
    values (v_tenant, v_uid, v_titulo, 'reuniao', p_agendada_para,
            p_agendada_para + (coalesce(p_duracao_min, 60) || ' minutes')::interval, v_sala_id, 'azul')
    returning id into v_evento_id;

  return jsonb_build_object('sala_id', v_sala_id, 'evento_id', v_evento_id, 'chave_publica', v_chave, 'max_participantes', v_max);
end;
$$;


ALTER FUNCTION public.agendar_reuniao(p_titulo text, p_agendada_para timestamp with time zone, p_duracao_min integer, p_max integer, p_exige_aprovacao boolean) OWNER TO postgres;

--
-- Name: agendar_reuniao_lead(uuid, uuid, uuid, uuid, timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.agendar_reuniao_lead(p_tenant_id uuid, p_conversa_id uuid, p_lead_id uuid, p_agente_id uuid, p_inicio timestamp with time zone, p_titulo text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_cfg public.agenda_config_tenant%ROWTYPE;
  v_dur integer;
  v_titulo text;
  v_sala_id uuid;
  v_chave uuid;
  v_evento_id uuid;
  v_compromisso_id uuid;
  v_tem_disp boolean;
  v_slot_ok boolean := true;
  v_lembrete_em timestamptz := NULL;
  v_modo text;
  v_qtd integer;
  v_item jsonb;
  v_lembretes jsonb := '[]'::jsonb;
BEGIN
  IF p_tenant_id IS NULL OR p_inicio IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'erro', 'tenant e inicio obrigatórios');
  END IF;
  IF p_inicio <= now() THEN
    RETURN jsonb_build_object('ok', false, 'erro', 'horario_no_passado');
  END IF;

  SELECT * INTO v_cfg FROM public.agenda_config_tenant WHERE tenant_id = p_tenant_id;
  IF v_cfg.id IS NULL OR v_cfg.agente_pode_agendar IS DISTINCT FROM true THEN
    RETURN jsonb_build_object('ok', false, 'erro', 'agenda_desativada_pro_agente');
  END IF;
  v_dur := COALESCE(v_cfg.duracao_padrao_min, 30);
  v_titulo := COALESCE(NULLIF(btrim(p_titulo), ''), 'Reunião');

  -- Horário precisa bater num slot livre QUANDO o tenant configurou disponibilidade.
  SELECT EXISTS (SELECT 1 FROM public.disponibilidade d WHERE d.tenant_id = p_tenant_id AND d.ativo = true)
    INTO v_tem_disp;
  IF v_tem_disp THEN
    SELECT EXISTS (
      SELECT 1 FROM public.slots_disponiveis(p_tenant_id, (p_inicio AT TIME ZONE 'America/Sao_Paulo')::date)
      WHERE slot_inicio = p_inicio
    ) INTO v_slot_ok;
    IF NOT v_slot_ok THEN
      RETURN jsonb_build_object('ok', false, 'erro', 'horario_indisponivel');
    END IF;
  END IF;

  -- Sala do app Reunião (link público /sala/{chave})
  INSERT INTO public.salas_reuniao (tenant_id, criada_por, titulo, status, max_participantes, agendada_para, duracao_min, exige_aprovacao)
  VALUES (p_tenant_id, p_tenant_id, v_titulo, 'agendada', 6, p_inicio, v_dur, false)
  RETURNING id, chave_publica INTO v_sala_id, v_chave;

  -- Evento na agenda do tenant
  INSERT INTO public.eventos_agenda (tenant_id, criado_por, titulo, tipo, inicio_em, fim_em, sala_reuniao_id, cor, origem)
  VALUES (p_tenant_id, p_tenant_id, v_titulo, 'reuniao', p_inicio, p_inicio + (v_dur || ' minutes')::interval, v_sala_id, 'azul', 'agente')
  RETURNING id INTO v_evento_id;

  -- Compromisso vinculado ao lead (anti-overbooking do slots_disponiveis + dossiê)
  INSERT INTO public.compromissos (conversation_id, lead_id, tenant_id, descricao, scheduled_at, origem, criado_por, status, duracao_min, link_call, lembretes_config)
  VALUES (p_conversa_id, p_lead_id, p_tenant_id, v_titulo, p_inicio, 'combinado', p_tenant_id, 'pendente', v_dur,
          '/sala/' || v_chave::text, v_cfg.lembrete)
  RETURNING id INTO v_compromisso_id;

  -- Lembretes pro lead (acoes_agendadas → processar-acompanhamentos → [LEMBRETE_REUNIAO]).
  IF p_conversa_id IS NOT NULL THEN
    IF jsonb_typeof(v_cfg.lembrete->'multiplos') = 'array' THEN
      -- Config nova: N lembretes independentes (dias/horas/minutos antes).
      FOR v_item IN SELECT * FROM jsonb_array_elements(v_cfg.lembrete->'multiplos') LOOP
        v_modo := COALESCE(v_item->>'modo', '');
        v_qtd  := GREATEST(COALESCE((v_item->>'quantidade')::int, 0), 0);
        IF v_modo IN ('minutos','horas','dias') AND v_qtd > 0 THEN
          v_lembrete_em := p_inicio - (v_qtd || CASE v_modo WHEN 'dias' THEN ' days' WHEN 'horas' THEN ' hours' ELSE ' minutes' END)::interval;
          IF v_lembrete_em > now() THEN
            INSERT INTO public.acoes_agendadas (conversation_id, agente_id, lead_id, tenant_id, action_type, scheduled_at, status, carga)
            VALUES (p_conversa_id, p_agente_id, p_lead_id, p_tenant_id, 'lembrete_reuniao', v_lembrete_em, 'pendente',
                    jsonb_build_object('titulo', v_titulo, 'reuniao_em', p_inicio, 'link_sala', '/sala/' || v_chave::text,
                                       'compromisso_id', v_compromisso_id, 'origem', 'agendar_reuniao_lead'));
            v_lembretes := v_lembretes || to_jsonb(v_lembrete_em);
          END IF;
        END IF;
      END LOOP;
      -- Informativo do retorno: o primeiro disparo (mais distante da reunião).
      SELECT min(x::timestamptz) INTO v_lembrete_em FROM jsonb_array_elements_text(v_lembretes) x;
    ELSE
      -- Config legada: um único lembrete modo/quantidade.
      v_modo := COALESCE(v_cfg.lembrete->>'modo', 'desativado');
      v_qtd  := GREATEST(COALESCE((v_cfg.lembrete->>'quantidade')::int, 0), 0);
      IF v_modo IN ('horas','dias') AND v_qtd > 0 THEN
        v_lembrete_em := p_inicio - (v_qtd || CASE WHEN v_modo = 'dias' THEN ' days' ELSE ' hours' END)::interval;
        IF v_lembrete_em > now() THEN
          INSERT INTO public.acoes_agendadas (conversation_id, agente_id, lead_id, tenant_id, action_type, scheduled_at, status, carga)
          VALUES (p_conversa_id, p_agente_id, p_lead_id, p_tenant_id, 'lembrete_reuniao', v_lembrete_em, 'pendente',
                  jsonb_build_object('titulo', v_titulo, 'reuniao_em', p_inicio, 'link_sala', '/sala/' || v_chave::text,
                                     'compromisso_id', v_compromisso_id, 'origem', 'agendar_reuniao_lead'));
          v_lembretes := v_lembretes || to_jsonb(v_lembrete_em);
        ELSE
          v_lembrete_em := NULL;
        END IF;
      ELSE
        v_lembrete_em := NULL;
      END IF;
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'chave_publica', v_chave,
    'sala_id', v_sala_id,
    'evento_id', v_evento_id,
    'compromisso_id', v_compromisso_id,
    'inicio', p_inicio,
    'duracao_min', v_dur,
    'lembrete_em', v_lembrete_em,
    'lembretes', v_lembretes
  );
END;
$$;


ALTER FUNCTION public.agendar_reuniao_lead(p_tenant_id uuid, p_conversa_id uuid, p_lead_id uuid, p_agente_id uuid, p_inicio timestamp with time zone, p_titulo text) OWNER TO postgres;

--
-- Name: agregar_comparativo_nicho(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.agregar_comparativo_nicho() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_inseridos int := 0;
  v_nicho record;
  v_count int;
  v_taxa_media numeric;
  v_ticket_media numeric;
  v_ruido numeric;
  v_epsilon constant numeric := 0.1;
BEGIN
  -- Pra cada nicho com 10+ tenants destilados
  FOR v_nicho IN
    SELECT p.nicho_id, count(*) AS n
    FROM public.perfil_empresa pe
    JOIN public.profiles p ON p.id = pe.tenant_id
    WHERE p.nicho_id IS NOT NULL
      AND pe.taxa_conversao_estimada IS NOT NULL
    GROUP BY p.nicho_id
    HAVING count(*) >= 10
  LOOP
    -- Taxa conversão média (com ruído Laplace ε=0.1, sensitivity=1, mu=0)
    SELECT avg(pe.taxa_conversao_estimada), count(*)
      INTO v_taxa_media, v_count
    FROM public.perfil_empresa pe
    JOIN public.profiles p ON p.id = pe.tenant_id
    WHERE p.nicho_id = v_nicho.nicho_id
      AND pe.taxa_conversao_estimada IS NOT NULL;

    -- Ruído Laplace simplificado: U(-1,1) * scale, scale = sensitivity/epsilon
    -- (versão prod-ready usaria Box-Muller pra dist Laplace exata)
    v_ruido := (random() * 2 - 1) * (1.0 / v_epsilon) * 0.01;  -- escalado pra não estourar [0,1]
    v_taxa_media := greatest(0, least(1, v_taxa_media + v_ruido));

    -- Ticket médio (NULL por enquanto — depende de B3-V2 popular)
    SELECT avg(pe.ticket_medio_estimado)
      INTO v_ticket_media
    FROM public.perfil_empresa pe
    JOIN public.profiles p ON p.id = pe.tenant_id
    WHERE p.nicho_id = v_nicho.nicho_id
      AND pe.ticket_medio_estimado IS NOT NULL;

    -- UPSERT taxa_conversao
    INSERT INTO public.comparativo_nicho
      (nicho_id, metrica, valor_anonimizado, count_tenants, epsilon, janela_dias, expira_em)
    VALUES
      (v_nicho.nicho_id, 'taxa_conversao_media',
       jsonb_build_object('valor', round(v_taxa_media, 4), 'unidade', 'fracao'),
       v_count, v_epsilon, 30, now() + interval '7 days')
    ON CONFLICT (nicho_id, metrica, janela_dias) DO UPDATE SET
      valor_anonimizado = excluded.valor_anonimizado,
      count_tenants = excluded.count_tenants,
      epsilon = excluded.epsilon,
      calculado_em = now(),
      expira_em = now() + interval '7 days';
    v_inseridos := v_inseridos + 1;

    -- UPSERT ticket_medio se disponível
    IF v_ticket_media IS NOT NULL THEN
      INSERT INTO public.comparativo_nicho
        (nicho_id, metrica, valor_anonimizado, count_tenants, epsilon, janela_dias, expira_em)
      VALUES
        (v_nicho.nicho_id, 'ticket_medio',
         jsonb_build_object('valor', round(v_ticket_media + (random() * 2 - 1) * (50.0 / v_epsilon), 2), 'unidade', 'BRL'),
         v_count, v_epsilon, 30, now() + interval '7 days')
      ON CONFLICT (nicho_id, metrica, janela_dias) DO UPDATE SET
        valor_anonimizado = excluded.valor_anonimizado,
        count_tenants = excluded.count_tenants,
        epsilon = excluded.epsilon,
        calculado_em = now(),
        expira_em = now() + interval '7 days';
      v_inseridos := v_inseridos + 1;
    END IF;
  END LOOP;

  RETURN v_inseridos;
END;
$$;


ALTER FUNCTION public.agregar_comparativo_nicho() OWNER TO postgres;

--
-- Name: FUNCTION agregar_comparativo_nicho(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.agregar_comparativo_nicho() IS 'B5 cron — agrega perfil_empresa por nicho, publica comparativo_nicho com k≥10 + ε=0.1 ruído Laplace simplificado. Quando nicho atinge 10+ tenants destilados, métrica vira pública (anonimizada) pra todos do nicho.';


--
-- Name: alternar_check_nota(uuid, text, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.alternar_check_nota(p_nota_id uuid, p_check_id text, p_marcado boolean) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  UPDATE public.notas_app
  SET checks = (
    SELECT jsonb_agg(
      CASE WHEN elem->>'id' = p_check_id
        THEN jsonb_set(elem, '{marcado}', to_jsonb(p_marcado))
        ELSE elem
      END
    )
    FROM jsonb_array_elements(checks) elem
  )
  WHERE id = p_nota_id;
END;
$$;


ALTER FUNCTION public.alternar_check_nota(p_nota_id uuid, p_check_id text, p_marcado boolean) OWNER TO postgres;

--
-- Name: alternar_checkpoint_publico(uuid, text, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.alternar_checkpoint_publico(p_token uuid, p_checkpoint_id text, p_value boolean) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
  UPDATE public.leads
  SET client_checkpoints = jsonb_set(
    COALESCE(client_checkpoints, '{}'::jsonb),
    ARRAY[p_checkpoint_id],
    to_jsonb(p_value)
  )
  WHERE chave_rastreamento = p_token;
$$;


