--
-- Name: amostragem_estratificada(integer, integer, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.amostragem_estratificada(p_max_conversas integer DEFAULT 50, p_dias integer DEFAULT 7, p_tenant_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_resultado jsonb;
BEGIN
  PERFORM set_config('search_path', 'public', true);
  PERFORM set_config('statement_timeout', '8s', true);

  SELECT coalesce(jsonb_agg(t ORDER BY t.peso DESC), '[]'::jsonb)
  INTO v_resultado
  FROM (
    SELECT c.id AS conversation_id,
           c.tenant_id,
           c.lead_id,
           c.status,
           c.created_at,
           (SELECT COUNT(*) FROM public.mensagens m WHERE m.conversation_id = c.id AND m.deleted_at IS NULL) AS turnos,
           CASE
             WHEN c.created_at > now() - interval '1 day' THEN 1.0
             WHEN c.created_at > now() - interval '3 days' THEN 0.7
             ELSE 0.4
           END AS peso
    FROM public.conversas c
    WHERE c.created_at > now() - (p_dias || ' days')::interval
      AND (p_tenant_id IS NULL OR c.tenant_id = p_tenant_id)
      AND c.phone NOT ILIKE 'chat-test-%'
    ORDER BY peso DESC, RANDOM()
    LIMIT p_max_conversas
  ) t;

  RETURN v_resultado;
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('erro', SQLERRM);
END $$;


ALTER FUNCTION public.amostragem_estratificada(p_max_conversas integer, p_dias integer, p_tenant_id uuid) OWNER TO postgres;

--
-- Name: analisar_causa_efeito_tenant(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.analisar_causa_efeito_tenant(p_tenant_id uuid) RETURNS TABLE(metrica text, ferramenta_ou_cargo text, n_amostras bigint, taxa_conversao_quando_usada numeric, taxa_conversao_geral numeric, diferenca_pp numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_taxa_geral numeric;
BEGIN
  -- Taxa geral
  SELECT 
    CASE WHEN count(*) FILTER (WHERE desfecho IN ('convertido','perdido','sumiu')) > 0
      THEN count(*) FILTER (WHERE desfecho='convertido')::numeric 
        / count(*) FILTER (WHERE desfecho IN ('convertido','perdido','sumiu')) 
      ELSE 0 END
  INTO v_taxa_geral
  FROM public.leads
  WHERE tenant_id = p_tenant_id AND deleted_at IS NULL;

  RETURN QUERY
  -- Análise por cargo final usado
  WITH leads_classificados AS (
    SELECT l.id, l.desfecho, l.cargo_ativo_id
    FROM public.leads l
    WHERE l.tenant_id = p_tenant_id 
      AND l.deleted_at IS NULL 
      AND l.desfecho IN ('convertido','perdido','sumiu')
  )
  SELECT
    'cargo_final'::text AS metrica,
    coalesce(c.nome, 'sem_cargo') AS ferramenta_ou_cargo,
    count(*) AS n_amostras,
    (count(*) FILTER (WHERE lc.desfecho='convertido')::numeric / NULLIF(count(*), 0))::numeric(5,4) AS taxa_quando,
    v_taxa_geral::numeric(5,4) AS taxa_geral,
    ((count(*) FILTER (WHERE lc.desfecho='convertido')::numeric / NULLIF(count(*), 0)) - v_taxa_geral)::numeric(5,4) AS diff
  FROM leads_classificados lc
  LEFT JOIN public.cargos c ON c.id = lc.cargo_ativo_id
  GROUP BY c.nome
  HAVING count(*) >= 5
  ORDER BY diff DESC NULLS LAST;
END;
$$;


ALTER FUNCTION public.analisar_causa_efeito_tenant(p_tenant_id uuid) OWNER TO postgres;

--
-- Name: aplicar_fusao_tag(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.aplicar_fusao_tag(p_suggestion_id uuid, p_canonical text DEFAULT NULL::text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_sug      public.sugestoes_fusao_tag%ROWTYPE;
  v_destino  text;
  v_origens  text[];
  v_origem   text;
  v_leads_atualizados integer := 0;
  v_total integer := 0;
  v_user     uuid;
BEGIN
  v_user := auth.uid();
  SELECT * INTO v_sug FROM public.sugestoes_fusao_tag WHERE id = p_suggestion_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'sugestao nao encontrada'; END IF;
  IF v_sug.status NOT IN ('pending', 'pendente') THEN RAISE EXCEPTION 'sugestao ja decidida (status=%)', v_sug.status; END IF;
  v_destino := COALESCE(p_canonical, v_sug.suggested_canonical);
  IF v_sug.tags IS NOT NULL AND array_length(v_sug.tags, 1) > 0 THEN
    v_origens := array(SELECT t FROM unnest(v_sug.tags) t WHERE t <> v_destino);
  ELSE
    v_origens := array(SELECT t FROM unnest(ARRAY[v_sug.tag_a, v_sug.tag_b]) t WHERE t <> v_destino AND t IS NOT NULL);
  END IF;
  IF array_length(v_origens, 1) IS NULL OR array_length(v_origens, 1) = 0 THEN
    RAISE EXCEPTION 'nenhuma tag origem (canonical %s sozinha?)', v_destino;
  END IF;
  FOREACH v_origem IN ARRAY v_origens LOOP
    WITH afetados AS (
      UPDATE public.leads
      SET tags = (SELECT array_agg(DISTINCT t) FROM (SELECT CASE WHEN x = v_origem THEN v_destino ELSE x END AS t FROM unnest(tags) x) z)
      FROM public.profiles p
      WHERE p.id = public.leads.tenant_id AND p.nicho_id = v_sug.nicho_id AND public.leads.tags @> ARRAY[v_origem]
      RETURNING public.leads.id
    )
    SELECT count(*) INTO v_leads_atualizados FROM afetados;
    UPDATE public.candidatos_tag
    SET num_leads_independentes = num_leads_independentes + COALESCE((SELECT num_leads_independentes FROM public.candidatos_tag WHERE nicho_id = v_sug.nicho_id AND tag_text = v_origem), 0), atualizado_em = now()
    WHERE nicho_id = v_sug.nicho_id AND tag_text = v_destino;
    DELETE FROM public.candidatos_tag WHERE nicho_id = v_sug.nicho_id AND tag_text = v_origem;
    UPDATE public.observacoes_tag o SET tag_text = v_destino FROM public.profiles p WHERE p.id = o.tenant_id AND p.nicho_id = v_sug.nicho_id AND o.tag_text = v_origem;
    INSERT INTO public.registro_fusao_tag (nicho_id, tag_origem, tag_destino, num_observacoes_movidas, applied_at, applied_by, origem_suggestion_id)
    VALUES (v_sug.nicho_id, v_origem, v_destino, v_leads_atualizados, now(), v_user, p_suggestion_id);
    v_total := v_total + v_leads_atualizados;
  END LOOP;
  UPDATE public.sugestoes_fusao_tag SET status = 'aprovado', decided_at = now(), decided_by = v_user WHERE id = p_suggestion_id;
  RETURN v_total;
END;
$$;


ALTER FUNCTION public.aplicar_fusao_tag(p_suggestion_id uuid, p_canonical text) OWNER TO postgres;

--
-- Name: aplicar_vetores_lote(text, uuid[], text[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.aplicar_vetores_lote(p_tabela text, p_ids uuid[], p_vetores text[]) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
  n integer := 0;
  tem_status boolean;
BEGIN
  IF p_tabela NOT IN (
    'blocos_comportamento','blocos_gatilho','blocos_humanizacao','memoria_lead','lead_memory_fatos',
    'perguntas_sem_resposta','blocos_conhecimento','blocos_variacao','blocos_meta','memoria_episodica',
    'blocos_procedurais','emocao_blocos','prova_social_blocos','anti_padroes','diretriz_bolha_blocos',
    'manipulacao_blocos','agente_identidade','regras_operacionais_blocos','pivots_categoria_intent',
    'acao_pausa_blocos','automacao_blocos','admin_ia_blocos','admin_ia_memoria','fase_requisitos',
    'candidatos_tag','ferramentas_dinamicas','pacotes_conhecimento_blocos','memoria_dono'
  ) THEN
    RAISE EXCEPTION 'tabela nao permitida: %', p_tabela;
  END IF;
  IF p_ids IS NULL OR array_length(p_ids,1) IS NULL
     OR array_length(p_ids,1) <> array_length(p_vetores,1) THEN
    RETURN 0;
  END IF;
  SELECT EXISTS (
    SELECT 1 FROM information_schema.columns
    WHERE table_schema='public' AND table_name=p_tabela AND column_name='embedding_status'
  ) INTO tem_status;
  IF tem_status THEN
    EXECUTE format(
      'UPDATE public.%I AS t SET vetor_semantico = v.vec::extensions.halfvec, embedding_status = ''pronto'' '
      'FROM (SELECT unnest($1::uuid[]) AS id, unnest($2::text[]) AS vec) AS v WHERE t.id = v.id',
      p_tabela
    ) USING p_ids, p_vetores;
  ELSE
    EXECUTE format(
      'UPDATE public.%I AS t SET vetor_semantico = v.vec::extensions.halfvec '
      'FROM (SELECT unnest($1::uuid[]) AS id, unnest($2::text[]) AS vec) AS v WHERE t.id = v.id',
      p_tabela
    ) USING p_ids, p_vetores;
  END IF;
  GET DIAGNOSTICS n = ROW_COUNT;
  RETURN n;
END;
$_$;


ALTER FUNCTION public.aplicar_vetores_lote(p_tabela text, p_ids uuid[], p_vetores text[]) OWNER TO postgres;

