--
-- Name: aprovar_recarga(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.aprovar_recarga(p_recarga_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_tenant uuid;
  v_pacote uuid;
  v_credito numeric(10,2);
  v_status text;
  v_saldo numeric(10,2);
BEGIN
  IF NOT public.eh_admin_plataforma() THEN
    RETURN jsonb_build_object('ok', false, 'erro', 'nao_autorizado');
  END IF;

  SELECT tenant_id, pacote_id, status INTO v_tenant, v_pacote, v_status
  FROM public.consultas_recargas WHERE id = p_recarga_id FOR UPDATE;

  IF v_tenant IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'erro', 'recarga_nao_encontrada');
  END IF;
  IF v_status = 'aprovado' THEN
    RETURN jsonb_build_object('ok', true, 'erro', 'ja_aprovado');
  END IF;

  -- Crédito canônico: lido do pacote, não da linha da recarga.
  SELECT credito INTO v_credito FROM public.consultas_pacotes
    WHERE id = v_pacote AND ativo = true AND deleted_at IS NULL;
  IF v_credito IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'erro', 'pacote_invalido');
  END IF;

  INSERT INTO public.consultas_saldo (tenant_id) VALUES (v_tenant)
    ON CONFLICT (tenant_id) DO NOTHING;

  SELECT saldo INTO v_saldo FROM public.consultas_saldo
    WHERE tenant_id = v_tenant FOR UPDATE;

  UPDATE public.consultas_saldo
    SET saldo = saldo + v_credito, atualizado_em = now()
    WHERE tenant_id = v_tenant;

  -- Sincroniza a linha com o valor canônico (corrige eventual forja).
  UPDATE public.consultas_recargas
    SET status = 'aprovado', credito = v_credito,
        aprovado_por = (select auth.uid()), aprovado_em = now()
    WHERE id = p_recarga_id;

  INSERT INTO public.consultas_carteira_mov (tenant_id, tipo, valor, saldo_apos, recarga_id)
    VALUES (v_tenant, 'credito', v_credito, v_saldo + v_credito, p_recarga_id);

  RETURN jsonb_build_object('ok', true, 'saldo_apos', v_saldo + v_credito);
END;
$$;


ALTER FUNCTION public.aprovar_recarga(p_recarga_id uuid) OWNER TO postgres;

--
-- Name: aprovar_trecho_conversa_para_rag(uuid, uuid, uuid[], text, text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.aprovar_trecho_conversa_para_rag(p_tenant_id uuid, p_conversation_id uuid, p_message_ids uuid[], p_tipo text, p_categoria text, p_admin_id uuid, p_chunk_candidate_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_conteudo text;
  v_chunk_id uuid;
  v_count int;
BEGIN
  PERFORM 1 FROM public.conversas WHERE id = p_conversation_id AND tenant_id = p_tenant_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'conversation % não pertence ao tenant %', p_conversation_id, p_tenant_id USING ERRCODE = 'insufficient_privilege'; END IF;
  SELECT string_agg(m.role || ': ' || m.content, E'\n' ORDER BY m.created_at ASC), count(*)
  INTO v_conteudo, v_count FROM public.mensagens m
  WHERE m.id = ANY(p_message_ids) AND m.conversation_id = p_conversation_id;
  IF v_count = 0 OR v_conteudo IS NULL THEN RAISE EXCEPTION 'nenhuma mensagem encontrada pra excerto' USING ERRCODE = 'no_data_found'; END IF;
  INSERT INTO public.blocos_conhecimento (tenant_id, escopo, tipo, categoria, conteudo, embedding_status, ativa, created_by, criado_em, atualizado_em)
  VALUES (p_tenant_id, 'tenant', p_tipo, p_categoria, v_conteudo, 'pendente', true, p_admin_id, now(), now())
  RETURNING id INTO v_chunk_id;
  IF p_chunk_candidate_id IS NOT NULL THEN
    UPDATE public.candidatos_bloco SET status = 'promoted', promoted_bloco_id = v_chunk_id, promoted_bloco_table = 'blocos_conhecimento', decided_at = now(), decided_by = p_admin_id
    WHERE id = p_chunk_candidate_id AND tenant_id = p_tenant_id;
  END IF;
  RETURN v_chunk_id;
END;
$$;


ALTER FUNCTION public.aprovar_trecho_conversa_para_rag(p_tenant_id uuid, p_conversation_id uuid, p_message_ids uuid[], p_tipo text, p_categoria text, p_admin_id uuid, p_chunk_candidate_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION aprovar_trecho_conversa_para_rag(p_tenant_id uuid, p_conversation_id uuid, p_message_ids uuid[], p_tipo text, p_categoria text, p_admin_id uuid, p_chunk_candidate_id uuid); Type: COMMENT; Schema: public; Owner: postgres
