--
-- Name: atualizar_dados_escrita(uuid, text, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.atualizar_dados_escrita(p_owner uuid, p_sql text, p_confirmar_em_massa boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if exists (
    select 1 from public.profiles pr
    where pr.id = p_owner
      and pr.parent_user_id is not null
      and coalesce(pr.system_role, '') <> 'platform_admin'
  ) then
    return jsonb_build_object('ok', false, 'erro',
      'sem_permissao: alterar dados da conta é privilégio do dono. Peça ao titular.');
  end if;
  return public.atualizar_dados_escrita_nucleo(p_owner, p_sql, p_confirmar_em_massa);
end;
$$;


ALTER FUNCTION public.atualizar_dados_escrita(p_owner uuid, p_sql text, p_confirmar_em_massa boolean) OWNER TO postgres;

--
-- Name: atualizar_dados_escrita_nucleo(uuid, text, boolean); Type: FUNCTION; Schema: public; Owner: consultor_dados_ro
--

CREATE FUNCTION public.atualizar_dados_escrita_nucleo(p_owner uuid, p_sql text, p_confirmar_em_massa boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_sql text;
  v_tabela text;
  v_permitida boolean;
  v_linhas jsonb;
  v_total integer;
  v_teto constant integer := 50;
begin
  if p_owner is null then
    return jsonb_build_object('ok', false, 'erro', 'dono da operação ausente');
  end if;

  v_sql := btrim(coalesce(p_sql, ''));
  v_sql := regexp_replace(v_sql, ';\s*$', '');
  if v_sql = '' then
    return jsonb_build_object('ok', false, 'erro', 'comando vazio');
  end if;
  if length(v_sql) > 8000 then
    return jsonb_build_object('ok', false, 'erro', 'comando longo demais (máx 8000 caracteres)');
  end if;
  if position(';' in v_sql) > 0 then
    return jsonb_build_object('ok', false, 'erro', 'apenas um comando por vez');
  end if;
  if v_sql ~* '\yreturning\y' then
    return jsonb_build_object('ok', false, 'erro', 'não use RETURNING — o resultado já volta sozinho');
  end if;
  if v_sql ~* '\y(delete|truncate|drop|alter|create|grant|revoke|merge)\y' then
    return jsonb_build_object('ok', false, 'erro', 'só UPDATE ou INSERT são permitidos. Apagar = UPDATE com deleted_at/ativo (soft delete).');
  end if;

  if v_sql ~* '^update\s' then
    v_tabela := lower((regexp_match(v_sql, '^update\s+(?:only\s+)?(?:public\.)?"?([a-z_][a-z0-9_]*)"?', 'i'))[1]);
    if v_sql !~* '\ywhere\y' then
      return jsonb_build_object('ok', false, 'erro', 'UPDATE sem WHERE é proibido — filtre pelo id ou por condição específica');
    end if;
  elsif v_sql ~* '^insert\s+into\s' then
    v_tabela := lower((regexp_match(v_sql, '^insert\s+into\s+(?:public\.)?"?([a-z_][a-z0-9_]*)"?', 'i'))[1]);
  else
    return jsonb_build_object('ok', false, 'erro', 'comando precisa começar com UPDATE ou INSERT INTO');
  end if;

  if v_tabela is null then
    return jsonb_build_object('ok', false, 'erro', 'não consegui identificar a tabela alvo');
  end if;

  select coalesce(bool_or(permite_escrita and ativo), false) into v_permitida
  from public.tabelas_consulta_permitidas where tabela = v_tabela;
  if not v_permitida then
    return jsonb_build_object('ok', false, 'erro',
      'tabela ''' || v_tabela || ''' não aceita escrita por aqui. Consulte a ação esquema pra ver o que é editável.');
  end if;

  perform set_config('search_path', 'public', true);
  perform set_config('statement_timeout', '8000', true);
  perform set_config(
    'request.jwt.claims',
    json_build_object('sub', p_owner::text, 'role', 'authenticated')::text,
    true
  );

  begin
    execute format(
      'with _r as (%s returning *) select coalesce(jsonb_agg(_r), ''[]''::jsonb) from _r',
      v_sql
    ) into v_linhas;
    v_total := coalesce(jsonb_array_length(v_linhas), 0);
    if v_total > v_teto and not coalesce(p_confirmar_em_massa, false) then
      raise exception 'TETO_MASSA:%', v_total;
    end if;
  exception
    when others then
      if sqlerrm like 'TETO_MASSA:%' then
        return jsonb_build_object('ok', false, 'erro',
          'a operação afetaria ' || replace(sqlerrm, 'TETO_MASSA:', '') || ' linhas (teto ' || v_teto ||
          ') — NADA foi alterado. Refine o WHERE, ou repita com confirmar_em_massa=true SÓ se o usuário confirmar explicitamente.');
      end if;
      return jsonb_build_object('ok', false, 'erro', 'falha ao executar: ' || sqlerrm);
  end;

  if length(v_linhas::text) > 60000 then
    v_linhas := jsonb_build_array(jsonb_build_object('aviso', 'resultado grande demais pra exibir — alteração feita'));
  end if;

  return jsonb_build_object(
    'ok', true,
    'tabela', v_tabela,
    'linhas_afetadas', v_total,
    'linhas', coalesce(v_linhas, '[]'::jsonb)
  );
end;
$_$;


ALTER FUNCTION public.atualizar_dados_escrita_nucleo(p_owner uuid, p_sql text, p_confirmar_em_massa boolean) OWNER TO consultor_dados_ro;

--
-- Name: atualizar_em_massa_leads_campanha(uuid, uuid, uuid[], text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.atualizar_em_massa_leads_campanha(p_tenant_id uuid, p_campaign_id uuid, p_lead_ids uuid[], p_acao text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_afetados int := 0;
BEGIN
  IF p_acao NOT IN ('pausar','reativar','arquivar') THEN
    RAISE EXCEPTION 'ação inválida: %. Aceitas: pausar|reativar|arquivar', p_acao
      USING ERRCODE = 'invalid_parameter_value';
  END IF;

  -- Valida tenant ownership
  PERFORM 1 FROM public.campanhas
   WHERE id = p_campaign_id AND tenant_id = p_tenant_id AND deleted_at IS NULL;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'campaign % não pertence ao tenant %', p_campaign_id, p_tenant_id
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  IF p_acao = 'pausar' THEN
    UPDATE public.leads_campanha
       SET state = 'pausado'
     WHERE id = ANY(p_lead_ids) AND campaign_id = p_campaign_id;
  ELSIF p_acao = 'reativar' THEN
    UPDATE public.leads_campanha
       SET state = 'ativo'
     WHERE id = ANY(p_lead_ids) AND campaign_id = p_campaign_id AND state = 'pausado';
  ELSIF p_acao = 'arquivar' THEN
    UPDATE public.leads_campanha
       SET archived_at = now()
     WHERE id = ANY(p_lead_ids) AND campaign_id = p_campaign_id AND archived_at IS NULL;
  END IF;

  GET DIAGNOSTICS v_afetados = ROW_COUNT;
  RETURN v_afetados;
END;
$$;


ALTER FUNCTION public.atualizar_em_massa_leads_campanha(p_tenant_id uuid, p_campaign_id uuid, p_lead_ids uuid[], p_acao text) OWNER TO postgres;

