--
-- Name: avaliar_criterio_segmento(text[], jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.avaliar_criterio_segmento(p_tags text[], p_criterio jsonb) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_chave    text;
  v_op       text;
  v_valores  text[];
  v_tag_val  text;
BEGIN
  v_chave := p_criterio->>'chave';
  v_op    := p_criterio->>'operador';

  SELECT substring(t FROM length(v_chave) + 2)
  INTO v_tag_val
  FROM unnest(p_tags) AS t
  WHERE t LIKE v_chave || ':%'
  LIMIT 1;

  CASE v_op
    WHEN 'eq' THEN
      RETURN (v_chave || ':' || (p_criterio->>'valor')) = ANY(p_tags);
    WHEN 'neq' THEN
      RETURN NOT ((v_chave || ':' || (p_criterio->>'valor')) = ANY(p_tags));
    WHEN 'in', 'contains_any' THEN
      SELECT ARRAY(SELECT jsonb_array_elements_text(p_criterio->'valores')) INTO v_valores;
      RETURN EXISTS (
        SELECT 1 FROM unnest(p_tags) AS t
        WHERE t LIKE v_chave || ':%'
          AND substring(t FROM length(v_chave) + 2) = ANY(v_valores)
      );
    WHEN 'not_in' THEN
      SELECT ARRAY(SELECT jsonb_array_elements_text(p_criterio->'valores')) INTO v_valores;
      RETURN NOT EXISTS (
        SELECT 1 FROM unnest(p_tags) AS t
        WHERE t LIKE v_chave || ':%'
          AND substring(t FROM length(v_chave) + 2) = ANY(v_valores)
      );
    WHEN 'contains_all' THEN
      SELECT ARRAY(SELECT jsonb_array_elements_text(p_criterio->'valores')) INTO v_valores;
      RETURN (
        SELECT COUNT(*) FROM unnest(v_valores) AS v
        WHERE (v_chave || ':' || v) = ANY(p_tags)
      ) = array_length(v_valores, 1);
    WHEN 'gte' THEN
      RETURN v_tag_val IS NOT NULL AND v_tag_val::numeric >= (p_criterio->>'valor')::numeric;
    WHEN 'gt' THEN
      RETURN v_tag_val IS NOT NULL AND v_tag_val::numeric > (p_criterio->>'valor')::numeric;
    WHEN 'lte' THEN
      RETURN v_tag_val IS NOT NULL AND v_tag_val::numeric <= (p_criterio->>'valor')::numeric;
    WHEN 'lt' THEN
      RETURN v_tag_val IS NOT NULL AND v_tag_val::numeric < (p_criterio->>'valor')::numeric;
    WHEN 'between' THEN
      RETURN v_tag_val IS NOT NULL
        AND v_tag_val::numeric >= (p_criterio->>'valor_min')::numeric
        AND v_tag_val::numeric <= (p_criterio->>'valor_max')::numeric;
    WHEN 'is_null' THEN
      RETURN NOT EXISTS (SELECT 1 FROM unnest(p_tags) AS t WHERE t LIKE v_chave || ':%');
    WHEN 'is_not_null' THEN
      RETURN EXISTS (SELECT 1 FROM unnest(p_tags) AS t WHERE t LIKE v_chave || ':%');
    ELSE
      RETURN true;
  END CASE;
EXCEPTION WHEN OTHERS THEN
  RETURN true;
END;
$$;


ALTER FUNCTION public.avaliar_criterio_segmento(p_tags text[], p_criterio jsonb) OWNER TO postgres;

--
-- Name: avisar_dono_reservas_vencidas(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.avisar_dono_reservas_vencidas() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_qtd integer := 0;
  v_g record;
begin
  for v_g in
    select pr.tenant_id, pr.rifa_id, r.titulo,
           array_agg(pr.id) as ids,
           count(*) as n,
           string_agg(
             coalesce(pr.nome, 'Sem nome') || ' (' || array_to_string(pr.numeros, ', ') || ') R$ ' ||
             replace(to_char(pr.valor_centavos / 100.0, 'FM999999990D00'), '.', ','),
             ' · ' order by pr.created_at) as lista
    from public.pedidos_rifa pr
    join public.rifas r on r.id = pr.rifa_id
    where pr.status = 'reservado'
      and pr.expira_em is not null
      and pr.expira_em < now()
      and pr.aviso_dono_em is null
      and pr.divida_gerada_em is null
      and pr.divida_dispensada_em is null
      and r.status = 'ativa'
      and r.deleted_at is null
    group by pr.tenant_id, pr.rifa_id, r.titulo
  loop
    insert into public.notificacoes (user_id, tipo, icone, titulo, mensagem, acao, acao_label)
    values (
      v_g.tenant_id, 'aviso', 'rifa',
      'Reservas sem pagamento — ' || v_g.titulo,
      v_g.n || ' reserva(s) passaram do prazo de pagamento sem pagar: ' || v_g.lista ||
        '. Em Rifas > Pedidos, escolha "Mandar pra dívida" ou "Não cobrar". Se não decidir, ' ||
        'o sorteio lança como dívida, como sempre.',
      'rifas', 'Abrir Rifas'
    );
    update public.pedidos_rifa set aviso_dono_em = now() where id = any(v_g.ids);
    v_qtd := v_qtd + v_g.n;
  end loop;
  return v_qtd;
end;
$_$;


ALTER FUNCTION public.avisar_dono_reservas_vencidas() OWNER TO postgres;

--
-- Name: avisar_evento_contrato(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.avisar_evento_contrato() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_titulo text := COALESCE(NEW.titulo, NEW.nome_template, 'Contrato');
BEGIN
  -- Contrato assinado (assinado_em: NULL -> timestamp)
  IF NEW.assinado_em IS NOT NULL AND OLD.assinado_em IS NULL THEN
    IF NEW.tenant_id IS NOT NULL THEN
      INSERT INTO public.notificacoes (user_id, tipo, icone, titulo, mensagem, acao, acao_label)
      VALUES (
        NEW.tenant_id, 'contrato_assinado', 'check',
        'Contrato assinado',
        v_titulo || ' foi assinado pelo cliente.',
        CASE WHEN NEW.conversa_id IS NOT NULL THEN 'conversas' END,
        CASE WHEN NEW.conversa_id IS NOT NULL THEN 'Abrir conversa' END
      );
    END IF;
    IF NEW.conversa_id IS NOT NULL THEN
      INSERT INTO public.mensagens (conversation_id, role, content, carga)
      VALUES (
        NEW.conversa_id, 'system', '[CONTRATO_ASSINADO]',
        jsonb_build_object('tipo_marco', 'contrato_assinado', 'contrato_id', NEW.id, 'titulo', v_titulo)
      );
    END IF;
  END IF;

  -- Comprovante enviado (url_comprovante_pagamento: NULL -> url)
  IF NEW.url_comprovante_pagamento IS NOT NULL AND OLD.url_comprovante_pagamento IS NULL THEN
    IF NEW.tenant_id IS NOT NULL THEN
      INSERT INTO public.notificacoes (user_id, tipo, icone, titulo, mensagem, acao, acao_label)
      VALUES (
        NEW.tenant_id, 'comprovante_enviado', 'doc',
        'Comprovante enviado',
        'O cliente enviou o comprovante de pagamento de ' || v_titulo || '.',
        CASE WHEN NEW.conversa_id IS NOT NULL THEN 'conversas' END,
        CASE WHEN NEW.conversa_id IS NOT NULL THEN 'Abrir conversa' END
      );
    END IF;
    IF NEW.conversa_id IS NOT NULL THEN
      INSERT INTO public.mensagens (conversation_id, role, content, carga)
      VALUES (
        NEW.conversa_id, 'system', '[COMPROVANTE_ENVIADO]',
        jsonb_build_object('tipo_marco', 'comprovante_enviado', 'contrato_id', NEW.id, 'titulo', v_titulo)
      );
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.avisar_evento_contrato() OWNER TO postgres;

--
-- Name: avisar_reservas_rifa_a_vencer(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.avisar_reservas_rifa_a_vencer() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_qtd integer := 0;
  v_p record;
  v_texto text;
begin
  for v_p in
    select pr.id, pr.tenant_id, pr.conversa_id, pr.numeros, pr.valor_centavos, pr.expira_em,
           r.titulo, r.data_sorteio_prevista, coalesce(rc.chave_pix, pf.chave_pix) as chave_pix
    from public.pedidos_rifa pr
    join public.rifas r on r.id = pr.rifa_id
    join public.conversas c on c.id = pr.conversa_id
    left join public.profiles pf on pf.id = pr.tenant_id
    left join public.rifas_config_tenant rc on rc.tenant_id = pr.tenant_id
    where pr.status = 'reservado'
      and pr.aviso_expiracao_em is null
      and pr.conversa_id is not null
      and pr.expira_em is not null
      and pr.expira_em > now()
      and pr.expira_em <= now() + interval '10 minutes'
      and c.status <> 'encerrada'
      and coalesce(c.channel, '') <> 'teste'
    limit 50
  loop
    v_texto :=
      'Oi! Passando pra lembrar: seus números da rifa "' || v_p.titulo || '" (' ||
      array_to_string(v_p.numeros, ', ') || ') estão reservados, e o pagamento vai até as ' ||
      to_char(v_p.expira_em at time zone 'America/Sao_Paulo', 'HH24:MI') ||
      case when v_p.data_sorteio_prevista is not null then ' (1h antes do sorteio)' else '' end ||
      '. Valor: R$ ' ||
      replace(to_char(v_p.valor_centavos / 100.0, 'FM999999990D00'), '.', ',') ||
      case when v_p.chave_pix is not null then ' — PIX: ' || v_p.chave_pix else '' end ||
      '. Assim que pagar, é só mandar o comprovante aqui na conversa que eu confirmo 😉';

    insert into public.caixa_saida_mensagens
      (tenant_id, conversation_id, status, content, bubble_order, scheduled_at, carga)
    values
      (v_p.tenant_id, v_p.conversa_id, 'pendente', v_texto, 0, now(),
       jsonb_build_object('origem', 'cron_aviso_reserva_rifa', 'pedido_id', v_p.id));

    update public.pedidos_rifa set aviso_expiracao_em = now(), updated_at = now()
    where id = v_p.id;
    v_qtd := v_qtd + 1;
  end loop;
  return v_qtd;
end;
$_$;


ALTER FUNCTION public.avisar_reservas_rifa_a_vencer() OWNER TO postgres;

--
-- Name: FUNCTION avisar_reservas_rifa_a_vencer(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.avisar_reservas_rifa_a_vencer() IS 'Manda 1 lembrete por pedido ~10 min antes da reserva expirar (número, valor, PIX e link). Roda no cron avisar_reservas_rifa, */5min, logo antes do expirar_reservas_rifa.';


--
-- Name: blocos_atuais_tenant(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.blocos_atuais_tenant(p_tenant_id uuid, p_gaveta text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_resultado jsonb;
v_query text;
BEGIN
  PERFORM set_config('search_path', 'public', true);
  PERFORM set_config('statement_timeout', '5s', true);

  IF p_gaveta NOT IN ('blocos_conhecimento','blocos_comportamento','blocos_gatilho','blocos_humanizacao','blocos_variacao','blocos_meta','blocos_procedurais','emocao_blocos','prova_social_blocos','acao_pausa_blocos','automacao_blocos','diretriz_bolha_blocos') THEN
    RETURN jsonb_build_object('erro', 'gaveta_invalida');
  END IF;

  v_query := format('SELECT coalesce(jsonb_agg(t), ''[]''::jsonb) FROM (SELECT id, escopo, ativo FROM public.%I WHERE (escopo=''tenant'' AND tenant_id=%L) OR escopo=''global'' OR (escopo=''nicho'') LIMIT 200) t', p_gaveta, p_tenant_id);
  EXECUTE v_query INTO v_resultado;

  RETURN coalesce(v_resultado, '[]'::jsonb);
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('erro', SQLERRM);
END $$;


ALTER FUNCTION public.blocos_atuais_tenant(p_tenant_id uuid, p_gaveta text) OWNER TO postgres;

