--
-- Name: bufferar_mensagem_entrante(text, uuid, uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.bufferar_mensagem_entrante(p_phone text, p_agent_id uuid, p_channel_id uuid, p_text text, p_media_url text DEFAULT NULL::text, p_media_type text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_existing record; v_msg jsonb;
BEGIN
  v_msg := jsonb_build_object(
    'text', COALESCE(p_text, ''), 'media_url', p_media_url,
    'media_type', p_media_type, 'received_at', now());
  SELECT * INTO v_existing FROM public.buffer_mensagens
  WHERE phone = p_phone AND agente_id = p_agent_id AND processed = false FOR UPDATE;
  IF v_existing IS NULL THEN
    INSERT INTO public.buffer_mensagens (phone, agente_id, channel_id, mensagens, is_composing, first_at, last_activity_at)
    VALUES (p_phone, p_agent_id, p_channel_id, jsonb_build_array(v_msg), false, now(), now());
    RETURN jsonb_build_object('is_first', true);
  ELSE
    UPDATE public.buffer_mensagens
    SET mensagens = mensagens || jsonb_build_array(v_msg), is_composing = false, last_activity_at = now()
    WHERE id = v_existing.id;
    RETURN jsonb_build_object('is_first', false);
  END IF;
END;
$$;


ALTER FUNCTION public.bufferar_mensagem_entrante(p_phone text, p_agent_id uuid, p_channel_id uuid, p_text text, p_media_url text, p_media_type text) OWNER TO postgres;

--
-- Name: busca_hibrida_acao_pausa(text, extensions.halfvec, uuid, uuid, integer, double precision, double precision, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.busca_hibrida_acao_pausa(p_query text, p_query_embedding extensions.halfvec, p_tenant_id uuid, p_nicho_id uuid DEFAULT NULL::uuid, p_match_count integer DEFAULT 5, p_full_text_weight double precision DEFAULT 1.0, p_semantic_weight double precision DEFAULT 1.5, p_rrf_k integer DEFAULT 50) RETURNS TABLE(id uuid, escopo text, gatilho_descricao text, gatilho_falas jsonb, duracao_min integer, mensagem_retorno text, prioridade integer, similarity double precision, rrf_score double precision)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
  RETURN QUERY
  WITH full_text AS (
    SELECT a.id,
      row_number() OVER (
        ORDER BY ts_rank_cd(
          to_tsvector('portuguese',
            coalesce(a.gatilho_descricao,'') || ' ' ||
            coalesce(a.gatilho_falas::text,'')
          ),
          websearch_to_tsquery('portuguese', p_query)
        ) DESC
      ) AS rank
    FROM public.acao_pausa_blocos a
    WHERE a.ativo = true
      AND (
        a.escopo = 'global'
        OR (a.escopo = 'nicho' AND a.nicho_id = p_nicho_id)
        OR (a.escopo = 'tenant' AND a.tenant_id = p_tenant_id)
      )
      AND to_tsvector('portuguese',
        coalesce(a.gatilho_descricao,'') || ' ' ||
        coalesce(a.gatilho_falas::text,'')
      ) @@ websearch_to_tsquery('portuguese', p_query)
    LIMIT p_match_count * 2
  ),
  semantic AS (
    SELECT a.id,
      row_number() OVER (ORDER BY a.vetor_semantico <=> p_query_embedding) AS rank,
      1 - (a.vetor_semantico <=> p_query_embedding) AS sim
    FROM public.acao_pausa_blocos a
    WHERE a.ativo = true
      AND a.vetor_semantico IS NOT NULL
      AND (
        a.escopo = 'global'
        OR (a.escopo = 'nicho' AND a.nicho_id = p_nicho_id)
        OR (a.escopo = 'tenant' AND a.tenant_id = p_tenant_id)
      )
    ORDER BY a.vetor_semantico <=> p_query_embedding
    LIMIT p_match_count * 2
  )
  SELECT
    a.id,
    a.escopo,
    a.gatilho_descricao,
    a.gatilho_falas,
    a.duracao_min,
    a.mensagem_retorno,
    a.prioridade,
    coalesce(s.sim, 0)::float AS similarity,
    (
      coalesce(1.0 / (p_rrf_k + ft.rank), 0) * p_full_text_weight +
      coalesce(1.0 / (p_rrf_k + s.rank), 0) * p_semantic_weight
    )::float AS rrf_score
  FROM public.acao_pausa_blocos a
  LEFT JOIN full_text ft ON ft.id = a.id
  LEFT JOIN semantic  s  ON s.id = a.id
  WHERE ft.id IS NOT NULL OR s.id IS NOT NULL
  ORDER BY rrf_score DESC
  LIMIT p_match_count;
END;
$$;


ALTER FUNCTION public.busca_hibrida_acao_pausa(p_query text, p_query_embedding extensions.halfvec, p_tenant_id uuid, p_nicho_id uuid, p_match_count integer, p_full_text_weight double precision, p_semantic_weight double precision, p_rrf_k integer) OWNER TO postgres;

--
-- Name: busca_hibrida_agente_identidade(text, extensions.halfvec, uuid, integer, numeric, integer, double precision, double precision); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.busca_hibrida_agente_identidade(p_query_text text, p_query_embedding extensions.halfvec, p_agente_id uuid, p_top_k integer DEFAULT 5, p_threshold numeric DEFAULT 0.4, p_rrf_k integer DEFAULT 50, p_fts_weight double precision DEFAULT 1.0, p_sem_weight double precision DEFAULT 1.0) RETURNS TABLE(id uuid, dimensao text, texto text, raciocinio text, intensidade numeric, score double precision)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
  RETURN QUERY
  SELECT ai.id,
         ai.dimensao,
         ai.texto,
         ai.raciocinio,
         ai.intensidade,
         9999.0::double precision AS score
  FROM public.agente_identidade ai
  WHERE ai.agente_id         = p_agente_id
    AND ai.status            = 'ativa'
    AND ai.tenant_desativada = false
    AND (ai.real_world_valid_to IS NULL OR ai.real_world_valid_to > now())
    AND ai.dimensao          = 'motivacao'

  UNION ALL

  SELECT f.id, f.dimensao, f.texto, f.raciocinio, f.intensidade, f.rrf_score
  FROM (
    WITH base AS (
      SELECT ai2.id, ai2.dimensao, ai2.texto, ai2.raciocinio, ai2.intensidade, ai2.vetor_semantico
      FROM public.agente_identidade ai2
      WHERE ai2.agente_id        = p_agente_id
        AND ai2.status           = 'ativa'
        AND ai2.tenant_desativada = false
        AND (ai2.real_world_valid_to IS NULL OR ai2.real_world_valid_to > now())
        AND ai2.dimensao        <> 'motivacao'
    ),
    full_text AS (
      SELECT b.id,
             ROW_NUMBER() OVER (ORDER BY ts_rank_cd(to_tsvector('portuguese', b.dimensao || ' ' || b.texto), websearch_to_tsquery('portuguese', p_query_text)) DESC) AS rnk
      FROM base b
      WHERE p_query_text IS NOT NULL AND p_query_text <> ''
        AND to_tsvector('portuguese', b.dimensao || ' ' || b.texto) @@ websearch_to_tsquery('portuguese', p_query_text)
      LIMIT 60
    ),
    semantic AS (
      SELECT b.id,
             ROW_NUMBER() OVER (ORDER BY b.vetor_semantico <=> p_query_embedding) AS rnk
      FROM base b
      WHERE b.vetor_semantico IS NOT NULL
      ORDER BY b.vetor_semantico <=> p_query_embedding
      LIMIT 60
    ),
    fused AS (
      SELECT b.id, b.dimensao, b.texto, b.raciocinio, b.intensidade,
             (coalesce(p_fts_weight * 1.0 / (p_rrf_k + ft.rnk), 0.0) + coalesce(p_sem_weight * 1.0 / (p_rrf_k + s.rnk), 0.0))::double precision AS rrf_score
      FROM base b
      LEFT JOIN full_text ft ON ft.id = b.id
      LEFT JOIN semantic   s  ON s.id  = b.id
      WHERE ft.id IS NOT NULL OR s.id IS NOT NULL
    )
    SELECT fused.id, fused.dimensao, fused.texto, fused.raciocinio, fused.intensidade, fused.rrf_score
    FROM fused
    WHERE fused.rrf_score >= p_threshold::double precision
    ORDER BY fused.rrf_score DESC
    LIMIT p_top_k
  ) f

  ORDER BY score DESC;
END;
$$;


ALTER FUNCTION public.busca_hibrida_agente_identidade(p_query_text text, p_query_embedding extensions.halfvec, p_agente_id uuid, p_top_k integer, p_threshold numeric, p_rrf_k integer, p_fts_weight double precision, p_sem_weight double precision) OWNER TO postgres;

--
-- Name: FUNCTION busca_hibrida_agente_identidade(p_query_text text, p_query_embedding extensions.halfvec, p_agente_id uuid, p_top_k integer, p_threshold numeric, p_rrf_k integer, p_fts_weight double precision, p_sem_weight double precision); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.busca_hibrida_agente_identidade(p_query_text text, p_query_embedding extensions.halfvec, p_agente_id uuid, p_top_k integer, p_threshold numeric, p_rrf_k integer, p_fts_weight double precision, p_sem_weight double precision) IS 'Busca híbrida (BM25 + cosine + RRF) em agente_identidade. Âncora motivacao sempre retorna (score 9999). Motor agente-vivo v188.';


--
-- Name: busca_hibrida_anti_padroes(text, extensions.halfvec, uuid, uuid, integer, numeric, integer, double precision, double precision, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.busca_hibrida_anti_padroes(p_query_text text, p_query_embedding extensions.halfvec, p_tenant_id uuid, p_nicho_id uuid, p_top_k integer DEFAULT 5, p_threshold numeric DEFAULT 0.4, p_rrf_k integer DEFAULT 50, p_fts_weight double precision DEFAULT 1.0, p_sem_weight double precision DEFAULT 1.0, p_tipo_campanha text DEFAULT NULL::text) RETURNS TABLE(id uuid, situacao text, acao_correta text, por_que text, escopo text, score double precision)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
  RETURN QUERY
  WITH base AS (
    SELECT ap.id, ap.situacao, ap.acao_correta, ap.por_que, ap.escopo, ap.vetor_semantico
    FROM public.anti_padroes ap
    WHERE ap.ativo = true
      AND (ap.real_world_valid_to IS NULL OR ap.real_world_valid_to > now())
      AND (p_tipo_campanha IS NULL OR ap.tipo_campanha = p_tipo_campanha)
      AND (
        ap.escopo = 'global'
        OR (ap.escopo = 'nicho'  AND ap.nicho_id  = p_nicho_id)
        OR (ap.escopo = 'tenant' AND ap.tenant_id = p_tenant_id)
      )
      AND NOT (
        ap.escopo = 'nicho' AND p_tenant_id IS NOT NULL
        AND EXISTS (SELECT 1 FROM public.overrides_tenant_blocos_anti_padroes ov
                    WHERE ov.bloco_id = ap.id AND ov.tenant_id = p_tenant_id AND ov.ativo = false)
      )
  ),
  full_text AS (
    SELECT b.id,
           ROW_NUMBER() OVER (ORDER BY ts_rank_cd(to_tsvector('portuguese', b.situacao || ' ' || b.acao_correta), websearch_to_tsquery('portuguese', p_query_text)) DESC) AS rnk
    FROM base b
    WHERE p_query_text IS NOT NULL AND p_query_text <> ''
      AND to_tsvector('portuguese', b.situacao || ' ' || b.acao_correta) @@ websearch_to_tsquery('portuguese', p_query_text)
    LIMIT 60
  ),
  semantic AS (
    SELECT b.id,
           ROW_NUMBER() OVER (ORDER BY b.vetor_semantico <=> p_query_embedding) AS rnk
    FROM base b
    WHERE b.vetor_semantico IS NOT NULL
    ORDER BY b.vetor_semantico <=> p_query_embedding
    LIMIT 60
  ),
  fused AS (
    SELECT b.id, b.situacao, b.acao_correta, b.por_que, b.escopo,
           (coalesce(p_fts_weight * 1.0 / (p_rrf_k + ft.rnk), 0.0) + coalesce(p_sem_weight * 1.0 / (p_rrf_k + s.rnk), 0.0))::double precision AS rrf_score
    FROM base b
    LEFT JOIN full_text ft ON ft.id = b.id
    LEFT JOIN semantic   s  ON s.id  = b.id
    WHERE ft.id IS NOT NULL OR s.id IS NOT NULL
  )
  SELECT f.id, f.situacao, f.acao_correta, f.por_que, f.escopo, f.rrf_score
  FROM fused f
  WHERE f.rrf_score >= p_threshold::double precision
  ORDER BY f.rrf_score DESC
  LIMIT p_top_k;
END;
$$;


ALTER FUNCTION public.busca_hibrida_anti_padroes(p_query_text text, p_query_embedding extensions.halfvec, p_tenant_id uuid, p_nicho_id uuid, p_top_k integer, p_threshold numeric, p_rrf_k integer, p_fts_weight double precision, p_sem_weight double precision, p_tipo_campanha text) OWNER TO postgres;

--
-- Name: FUNCTION busca_hibrida_anti_padroes(p_query_text text, p_query_embedding extensions.halfvec, p_tenant_id uuid, p_nicho_id uuid, p_top_k integer, p_threshold numeric, p_rrf_k integer, p_fts_weight double precision, p_sem_weight double precision, p_tipo_campanha text); Type: COMMENT; Schema: public; Owner: postgres
--

