-- Name: FUNCTION busca_hibrida_conhecimento(p_query_text text, p_query_embedding extensions.halfvec, p_agent_id uuid, p_nicho_id uuid, p_tipo text, p_category text, p_match_count integer, p_full_text_weight double precision, p_semantic_weight double precision, p_rrf_k integer, p_tom text); Type: COMMENT; Schema: public; Owner: postgres
