--
-- Name: FUNCTION busca_hibrida_gatilho(p_query_text text, p_query_embedding extensions.halfvec, p_tenant_id uuid, p_nicho_id uuid, p_match_count integer, p_full_text_weight double precision, p_semantic_weight double precision, p_rrf_k integer); Type: COMMENT; Schema: public; Owner: postgres
