COMMENT ON FUNCTION public.busca_hibrida_manipulacao(p_query_text text, p_query_embedding extensions.halfvec, p_tenant_id uuid, p_nicho_id uuid, p_top_k integer, p_threshold numeric, p_rrf_k integer, p_fts_weight double precision, p_sem_weight double precision) IS 'Busca híbrida em manipulacao_chunks. Escopo global. Threshold padrão 0.65 (alta confiança para detecção). Motor agente-vivo v188.';


--
-- Name: busca_hibrida_memoria_episodica(text, extensions.halfvec, uuid, uuid, integer, double precision, double precision, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.busca_hibrida_memoria_episodica(p_query_text text, p_query_embedding extensions.halfvec, p_tenant_id uuid, p_lead_id uuid DEFAULT NULL::uuid, p_match_count integer DEFAULT 5, p_full_text_weight double precision DEFAULT 1.0, p_semantic_weight double precision DEFAULT 1.0, p_rrf_k integer DEFAULT 50) RETURNS TABLE(id uuid, episodio_resumo text, outcome text, emocao text, gancho text, score double precision, decay_factor numeric, criado_em timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
  WITH base AS (
    SELECT em.id, em.episodio_resumo, em.outcome, em.emocao, em.gancho,
           em.vetor_semantico, em.decay_factor, em.criado_em
    FROM public.memoria_episodica em
    WHERE em.ativa = true
      AND em.tenant_id = p_tenant_id
      AND (p_lead_id IS NULL OR em.lead_id = p_lead_id)
  ),
  full_text AS (
    SELECT b.id,
           row_number() OVER (
             ORDER BY ts_rank_cd(
               to_tsvector('portuguese', b.episodio_resumo || coalesce(' ' || b.gancho, '')),
               websearch_to_tsquery('portuguese', p_query_text)
             ) DESC
           ) AS rnk
    FROM base b
    WHERE p_query_text IS NOT NULL AND p_query_text <> ''
      AND to_tsvector('portuguese', b.episodio_resumo || coalesce(' ' || b.gancho, ''))
          @@ websearch_to_tsquery('portuguese', p_query_text)
    LIMIT 60
  ),
  semantic AS (
    SELECT b.id,
           row_number() OVER (ORDER BY b.vetor_semantico <=> p_query_embedding) AS rnk
    FROM base b
    WHERE b.vetor_semantico IS NOT NULL
    ORDER BY b.vetor_semantico <=> p_query_embedding
    LIMIT 60
  ),
  fused AS (
    SELECT b.id, b.episodio_resumo, b.outcome, b.emocao, b.gancho, b.decay_factor, b.criado_em,
           (coalesce(p_full_text_weight * 1.0 / (p_rrf_k + ft.rnk), 0.0)
            + coalesce(p_semantic_weight * 1.0 / (p_rrf_k + s.rnk), 0.0))::double precision AS rrf_score
    FROM base b
    LEFT JOIN full_text ft ON ft.id = b.id
    LEFT JOIN semantic   s  ON s.id  = b.id
    WHERE ft.id IS NOT NULL OR s.id IS NOT NULL
  )
  SELECT f.id, f.episodio_resumo, f.outcome, f.emocao, f.gancho,
         (f.rrf_score * coalesce(f.decay_factor, 1.0))::double precision AS score,
         f.decay_factor, f.criado_em
  FROM fused f
  ORDER BY f.rrf_score * coalesce(f.decay_factor, 1.0) DESC
  LIMIT p_match_count;
$$;


ALTER FUNCTION public.busca_hibrida_memoria_episodica(p_query_text text, p_query_embedding extensions.halfvec, p_tenant_id uuid, p_lead_id uuid, p_match_count integer, p_full_text_weight double precision, p_semantic_weight double precision, p_rrf_k integer) OWNER TO postgres;

--
-- Name: busca_hibrida_memoria_lead(uuid, text, extensions.halfvec, integer, double precision, double precision, integer, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.busca_hibrida_memoria_lead(p_lead_id uuid, p_query_text text, p_query_embedding extensions.halfvec, p_match_count integer DEFAULT 5, p_full_text_weight double precision DEFAULT 1.0, p_semantic_weight double precision DEFAULT 1.0, p_rrf_k integer DEFAULT 50, p_tenant_id uuid DEFAULT NULL::uuid) RETURNS TABLE(id uuid, fato text, categoria text, relevancia text, score double precision)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
  WITH keyword AS (
    SELECT lm.id,
           row_number() OVER (
             ORDER BY ts_rank(to_tsvector('portuguese', lm.fato), plainto_tsquery('portuguese', p_query_text)) DESC
           ) AS rank_k
    FROM public.memoria_lead lm
    WHERE lm.lead_id          = p_lead_id
      AND lm.tenant_id        = public.tenant_efetivo(p_tenant_id)
      AND lm.ativa            = true
      AND lm.embedding_status = 'pronto'
      AND lm.fonte            != 'teste'
      AND to_tsvector('portuguese', lm.fato) @@ plainto_tsquery('portuguese', p_query_text)
    LIMIT p_match_count * 2
  ),
  semantic AS (
    SELECT lm.id,
           row_number() OVER (ORDER BY lm.vetor_semantico <=> p_query_embedding ASC) AS rank_s
    FROM public.memoria_lead lm
    WHERE lm.lead_id          = p_lead_id
      AND lm.tenant_id        = public.tenant_efetivo(p_tenant_id)
      AND lm.ativa            = true
      AND lm.embedding_status = 'pronto'
      AND lm.fonte            != 'teste'
    ORDER BY lm.vetor_semantico <=> p_query_embedding ASC
    LIMIT p_match_count * 2
  )
  SELECT
    lm.id,
    lm.fato,
    lm.categoria,
    lm.relevancia,
    COALESCE(p_full_text_weight * (1.0 / (p_rrf_k + k.rank_k)), 0.0)
    + COALESCE(p_semantic_weight * (1.0 / (p_rrf_k + s.rank_s)), 0.0) AS score
  FROM public.memoria_lead lm
  LEFT JOIN keyword  k ON k.id = lm.id
  LEFT JOIN semantic s ON s.id = lm.id
  WHERE lm.lead_id          = p_lead_id
    AND lm.tenant_id        = public.tenant_efetivo(p_tenant_id)
    AND lm.ativa            = true
    AND lm.fonte            != 'teste'
    AND (k.id IS NOT NULL OR s.id IS NOT NULL)
  ORDER BY score DESC
  LIMIT p_match_count;
$$;


ALTER FUNCTION public.busca_hibrida_memoria_lead(p_lead_id uuid, p_query_text text, p_query_embedding extensions.halfvec, p_match_count integer, p_full_text_weight double precision, p_semantic_weight double precision, p_rrf_k integer, p_tenant_id uuid) OWNER TO postgres;

--
-- Name: busca_hibrida_memoria_lead_v2(uuid, text, extensions.halfvec, integer, double precision, double precision, integer, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.busca_hibrida_memoria_lead_v2(p_lead_id uuid, p_query_text text, p_query_embedding extensions.halfvec, p_match_count integer DEFAULT 30, p_full_text_weight double precision DEFAULT 1.0, p_semantic_weight double precision DEFAULT 1.0, p_rrf_k integer DEFAULT 50, p_tenant_id uuid DEFAULT NULL::uuid) RETURNS TABLE(id uuid, fato text, categoria text, relevancia text, confianca numeric, criado_em timestamp with time zone, ultima_evocacao_em timestamp with time zone, vezes_evocado integer, valencia_emocional numeric, confirmado_pelo_lead boolean, valido_desde timestamp with time zone, score double precision)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
  WITH base AS (
    SELECT lm.*
    FROM public.memoria_lead lm
    WHERE lm.lead_id          = p_lead_id
      AND lm.tenant_id        = public.tenant_efetivo(p_tenant_id)
      AND lm.ativa            = true
      AND lm.embedding_status = 'pronto'
      AND lm.fonte            != 'teste'
      AND (lm.valido_ate         IS NULL OR lm.valido_ate         > now())
      AND (lm.sistema_expirou_em IS NULL OR lm.sistema_expirou_em > now())
  ),
  keyword AS (
    SELECT b.id,
           row_number() OVER (
             ORDER BY ts_rank(to_tsvector('portuguese', b.fato), plainto_tsquery('portuguese', p_query_text)) DESC
           ) AS rank_k
    FROM base b
    WHERE to_tsvector('portuguese', b.fato) @@ plainto_tsquery('portuguese', p_query_text)
    LIMIT p_match_count * 2
  ),
  semantic AS (
    SELECT b.id,
           row_number() OVER (ORDER BY b.vetor_semantico <=> p_query_embedding ASC) AS rank_s
    FROM base b
    ORDER BY b.vetor_semantico <=> p_query_embedding ASC
    LIMIT p_match_count * 2
  )
  SELECT
    b.id, b.fato, b.categoria, b.relevancia, b.confianca, b.criado_em,
    b.ultima_evocacao_em, b.vezes_evocado, b.valencia_emocional, b.confirmado_pelo_lead,
    b.valido_desde,
    (
      ( COALESCE(p_full_text_weight * (1.0 / (p_rrf_k + k.rank_k)), 0.0)
      + COALESCE(p_semantic_weight * (1.0 / (p_rrf_k + s.rank_s)), 0.0) )
      * power(COALESCE(b.confianca, 0.5), 0.6)
    ) AS score
  FROM base b
  LEFT JOIN keyword  k ON k.id = b.id
  LEFT JOIN semantic s ON s.id = b.id
  WHERE (k.id IS NOT NULL OR s.id IS NOT NULL)
  ORDER BY score DESC
  LIMIT p_match_count;
$$;


ALTER FUNCTION public.busca_hibrida_memoria_lead_v2(p_lead_id uuid, p_query_text text, p_query_embedding extensions.halfvec, p_match_count integer, p_full_text_weight double precision, p_semantic_weight double precision, p_rrf_k integer, p_tenant_id uuid) OWNER TO postgres;

--
-- Name: busca_hibrida_meta(text, extensions.halfvec, uuid, uuid, text, integer, double precision, double precision, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.busca_hibrida_meta(p_query_text text, p_query_embedding extensions.halfvec, p_tenant_id uuid DEFAULT NULL::uuid, p_nicho_id uuid DEFAULT NULL::uuid, p_tag text DEFAULT 'qualquer'::text, p_match_count integer DEFAULT 20, p_full_text_weight double precision DEFAULT 1.0, p_semantic_weight double precision DEFAULT 1.0, p_rrf_k integer DEFAULT 50) RETURNS TABLE(id uuid, escopo text, tag text, corpo text, citacao_kb text, prioridade integer, tags text[], imutavel boolean, rrf_score double precision)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
  WITH base AS (
    SELECT mc.*
    FROM public.blocos_meta mc
    WHERE mc.ativo = true
      AND (
        mc.escopo = 'global'
        OR (mc.escopo = 'nicho'  AND p_nicho_id  IS NOT NULL AND mc.nicho_id  = p_nicho_id)
        OR (mc.escopo = 'tenant' AND p_tenant_id IS NOT NULL AND mc.tenant_id = p_tenant_id)
      )
      AND (mc.tag = p_tag OR p_tag = 'qualquer' OR p_tag IS NULL)
      AND NOT EXISTS (
        SELECT 1 FROM public.overrides_tenant_blocos_meta o
        WHERE o.bloco_id = mc.id
          AND p_tenant_id IS NOT NULL
          AND o.tenant_id = p_tenant_id
          AND o.ativo = false
      )
  ),
  full_text AS (
    SELECT b.id,
           ROW_NUMBER() OVER (
             ORDER BY ts_rank_cd(
               to_tsvector('portuguese', coalesce(b.corpo, '')),
               websearch_to_tsquery('portuguese', p_query_text)
             ) DESC
           ) AS rnk
    FROM base b
    WHERE p_query_text IS NOT NULL AND p_query_text <> ''
      AND to_tsvector('portuguese', coalesce(b.corpo, ''))
          @@ websearch_to_tsquery('portuguese', p_query_text)
    LIMIT 60
  ),
  semantic AS (
    SELECT b.id,
           ROW_NUMBER() OVER (ORDER BY b.vetor_semantico <=> p_query_embedding) AS rnk
    FROM base b
    WHERE b.vetor_semantico IS NOT NULL
    ORDER BY b.vetor_semantico <=> p_query_embedding
    LIMIT 60
  )
  SELECT b.id,
         b.escopo,
         b.tag,
         b.corpo,
         b.citacao_kb,
         b.prioridade,
         b.tags,
         b.imutavel,
         (coalesce(p_full_text_weight * 1.0 / (p_rrf_k + ft.rnk), 0.0)
        + coalesce(p_semantic_weight * 1.0 / (p_rrf_k + s.rnk), 0.0)) AS rrf_score
  FROM base b
  LEFT JOIN full_text ft ON ft.id = b.id
  LEFT JOIN semantic  s  ON s.id  = b.id
  WHERE ft.id IS NOT NULL OR s.id IS NOT NULL
  ORDER BY rrf_score DESC, b.prioridade DESC NULLS LAST
  LIMIT p_match_count;
$$;


ALTER FUNCTION public.busca_hibrida_meta(p_query_text text, p_query_embedding extensions.halfvec, p_tenant_id uuid, p_nicho_id uuid, p_tag text, p_match_count integer, p_full_text_weight double precision, p_semantic_weight double precision, p_rrf_k integer) OWNER TO postgres;

