-- Name: FUNCTION busca_hibrida_procedurais(p_query_text text, p_query_embedding extensions.halfvec, p_tenant_id uuid, p_nicho_id uuid, p_top_k integer, p_threshold numeric, p_rrf_k integer, p_fts_weight double precision, p_sem_weight double precision); Type: COMMENT; Schema: public; Owner: postgres
