--
-- Name: FUNCTION busca_hibrida_regras_operacionais(p_query_text text, p_query_embedding extensions.halfvec, p_categoria text, p_tenant_id uuid, p_nicho_id uuid, p_top_k integer, p_threshold numeric, p_rrf_k integer, p_fts_weight double precision, p_sem_weight double precision); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.busca_hibrida_regras_operacionais(p_query_text text, p_query_embedding extensions.halfvec, p_categoria text, p_tenant_id uuid, p_nicho_id uuid, p_top_k integer, p_threshold numeric, p_rrf_k integer, p_fts_weight double precision, p_sem_weight double precision) IS 'Busca híbrida (BM25 + cosine + RRF) em regras_operacionais_chunks. Filtros: categoria, escopo (global/nicho/tenant). Prioridade soma 0.001/unidade no score final. Motor agente-vivo v188 RAG-first.';


--
-- Name: busca_hibrida_variacao(text, extensions.halfvec, uuid, uuid, uuid, integer, integer, text, text[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.busca_hibrida_variacao(p_query_text text, p_query_embedding extensions.halfvec, p_agent_id uuid DEFAULT NULL::uuid, p_nicho_id uuid DEFAULT NULL::uuid, p_tenant_id uuid DEFAULT NULL::uuid, p_match_count integer DEFAULT 10, p_rrf_k integer DEFAULT 50, p_categoria text DEFAULT NULL::text, p_tags text[] DEFAULT NULL::text[]) RETURNS TABLE(id uuid, nome_variation text, instrucao text, categoria text, subcategoria text, escopo text, prioridade integer, rrf_score double precision)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
  WITH base AS (
    SELECT vc.*
    FROM public.blocos_variacao vc
    WHERE vc.ativo = true
      AND (
        vc.escopo = 'global'
        OR (vc.escopo = 'nicho'  AND p_nicho_id  IS NOT NULL AND vc.nicho_id  = p_nicho_id)
        OR (vc.escopo = 'tenant' AND p_tenant_id IS NOT NULL AND vc.tenant_id = p_tenant_id)
      )
      AND NOT (
        vc.escopo = 'nicho' AND p_tenant_id IS NOT NULL
        AND EXISTS (SELECT 1 FROM public.overrides_tenant_blocos_variacao ov
                    WHERE ov.bloco_id=vc.id AND ov.tenant_id=p_tenant_id AND ov.ativo=false)
      )
      AND (p_categoria IS NULL OR vc.categoria = p_categoria)
      AND (p_tags      IS NULL OR array_length(p_tags, 1) IS NULL OR vc.subcategoria = ANY(p_tags))
  ),
  full_text AS (
    SELECT b.id,
           ROW_NUMBER() OVER (
             ORDER BY ts_rank_cd(
               to_tsvector('portuguese', coalesce(b.nome_variation, '') || ' ' || coalesce(b.instrucao, '')),
               websearch_to_tsquery('portuguese', p_query_text)
             ) DESC
           ) AS rnk
    FROM base b
    WHERE p_query_text IS NOT NULL AND p_query_text <> ''
      AND to_tsvector('portuguese', coalesce(b.nome_variation, '') || ' ' || coalesce(b.instrucao, ''))
          @@ websearch_to_tsquery('portuguese', p_query_text)
    LIMIT 40
  ),
  semantic AS (
    SELECT b.id,
           ROW_NUMBER() OVER (ORDER BY b.vetor_semantico <=> p_query_embedding) AS rnk
    FROM base b
    WHERE b.vetor_semantico IS NOT NULL
    ORDER BY b.vetor_semantico <=> p_query_embedding
    LIMIT 40
  )
  SELECT
    b.id, b.nome_variation, b.instrucao, b.categoria, b.subcategoria, b.escopo, b.prioridade,
    (coalesce(1.0 / (p_rrf_k + ft.rnk), 0.0) + coalesce(1.0 / (p_rrf_k + s.rnk), 0.0)) AS rrf_score
  FROM base b
  LEFT JOIN full_text ft ON ft.id = b.id
  LEFT JOIN semantic  s  ON s.id  = b.id
  WHERE ft.id IS NOT NULL OR s.id IS NOT NULL
  ORDER BY rrf_score DESC, b.prioridade DESC NULLS LAST
  LIMIT p_match_count;
$$;


ALTER FUNCTION public.busca_hibrida_variacao(p_query_text text, p_query_embedding extensions.halfvec, p_agent_id uuid, p_nicho_id uuid, p_tenant_id uuid, p_match_count integer, p_rrf_k integer, p_categoria text, p_tags text[]) OWNER TO postgres;

--
-- Name: busca_vetorial(extensions.vector, uuid, integer, double precision, text[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.busca_vetorial(query_embedding extensions.vector, p_agent_id uuid, match_count integer DEFAULT 8, similarity_threshold double precision DEFAULT 0.45, p_exclude_categories text[] DEFAULT ARRAY['fluxo'::text]) RETURNS TABLE(id uuid, title text, content text, category text, tags text[], similarity double precision)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  RETURN QUERY
  SELECT kc.id, kc.title, kc.content, kc.category, kc.tags, 1 - (kc.vetor_semantico <=> query_embedding) AS similarity
  FROM public.blocos_conhecimento kc
  WHERE kc.agente_id = p_agent_id AND kc.vetor_semantico IS NOT NULL
    AND (p_exclude_categories IS NULL OR kc.category IS NULL OR kc.category <> ALL(p_exclude_categories))
    AND 1 - (kc.vetor_semantico <=> query_embedding) >= similarity_threshold
  ORDER BY kc.vetor_semantico <=> query_embedding LIMIT match_count;
END;
$$;


ALTER FUNCTION public.busca_vetorial(query_embedding extensions.vector, p_agent_id uuid, match_count integer, similarity_threshold double precision, p_exclude_categories text[]) OWNER TO postgres;

--
-- Name: buscar_leads_por_descricao(uuid, extensions.halfvec, integer, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.buscar_leads_por_descricao(p_tenant_id uuid, p_query_embedding extensions.halfvec, p_match_count integer DEFAULT 100, p_min_similarity numeric DEFAULT 0.6) RETURNS TABLE(lead_id uuid, similarity numeric, num_fatos integer, fatos_resumo text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
  IF p_query_embedding IS NULL THEN
    RETURN;
  END IF;

  RETURN QUERY
  WITH centroides AS (
    SELECT
      lm.lead_id AS lid,
      AVG(lm.vetor_semantico) AS centroide,
      count(*)::int AS num_fatos,
      string_agg(lm.fato, ' · ' ORDER BY lm.criado_em DESC) AS fatos_resumo
    FROM public.memoria_lead lm
    WHERE lm.tenant_id = p_tenant_id
      AND lm.ativa = true
      AND lm.sistema_expirou_em IS NULL
      AND lm.vetor_semantico IS NOT NULL
    GROUP BY lm.lead_id
    HAVING count(*) > 0
  )
  SELECT
    c.lid,
    (1 - (c.centroide <=> p_query_embedding))::numeric,
    c.num_fatos,
    LEFT(c.fatos_resumo, 500)
  FROM centroides c
  WHERE (1 - (c.centroide <=> p_query_embedding)) >= p_min_similarity
  ORDER BY c.centroide <=> p_query_embedding ASC
  LIMIT p_match_count;
END;
$$;


ALTER FUNCTION public.buscar_leads_por_descricao(p_tenant_id uuid, p_query_embedding extensions.halfvec, p_match_count integer, p_min_similarity numeric) OWNER TO postgres;

--
-- Name: FUNCTION buscar_leads_por_descricao(p_tenant_id uuid, p_query_embedding extensions.halfvec, p_match_count integer, p_min_similarity numeric); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.buscar_leads_por_descricao(p_tenant_id uuid, p_query_embedding extensions.halfvec, p_match_count integer, p_min_similarity numeric) IS 'Wizard Campanha Semântica Modo C: recebe embedding da descrição em pt-BR (Cohere embed-v4.0, halfvec 1536) e retorna leads cujo centroide das memórias casa via cosine. Tenant scoped — sem cross-tenant.';


--
-- Name: buscar_leads_por_significado(uuid, text, extensions.halfvec, integer, double precision, double precision, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.buscar_leads_por_significado(p_tenant_id uuid, p_query_text text, p_query_embedding extensions.halfvec, p_match_count integer DEFAULT 12, p_full_text_weight double precision DEFAULT 1.0, p_semantic_weight double precision DEFAULT 1.5, p_rrf_k integer DEFAULT 50) RETURNS TABLE(lead_id uuid, name text, phone text, temperatura_lead text, fase_pipeline text, updated_at timestamp with time zone, fato_match text, categoria text, score double precision)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
  WITH keyword AS (
    SELECT lm.id,
           row_number() OVER (
             ORDER BY ts_rank(to_tsvector('portuguese', lm.fato), plainto_tsquery('portuguese', p_query_text)) DESC
           ) AS rank_k
    FROM public.memoria_lead lm
    WHERE lm.tenant_id        = p_tenant_id
      AND lm.ativa            = true
      AND lm.embedding_status = 'pronto'
      AND lm.fonte            != 'teste'
      AND to_tsvector('portuguese', lm.fato) @@ plainto_tsquery('portuguese', p_query_text)
    LIMIT p_match_count * 8
  ),
  semantic AS (
    SELECT lm.id,
           row_number() OVER (ORDER BY lm.vetor_semantico <=> p_query_embedding ASC) AS rank_s
    FROM public.memoria_lead lm
    WHERE lm.tenant_id        = p_tenant_id
      AND lm.ativa            = true
      AND lm.embedding_status = 'pronto'
      AND lm.fonte            != 'teste'
    ORDER BY lm.vetor_semantico <=> p_query_embedding ASC
    LIMIT p_match_count * 8
  ),
  fatos_rankeados AS (
    SELECT
      lm.lead_id,
      lm.fato,
      lm.categoria,
      COALESCE(p_full_text_weight * (1.0 / (p_rrf_k + k.rank_k)), 0.0)
      + COALESCE(p_semantic_weight * (1.0 / (p_rrf_k + s.rank_s)), 0.0) AS score
    FROM public.memoria_lead lm
    LEFT JOIN keyword  k ON k.id = lm.id
    LEFT JOIN semantic s ON s.id = lm.id
    WHERE lm.tenant_id = p_tenant_id
      AND lm.ativa     = true
      AND lm.fonte     != 'teste'
      AND (k.id IS NOT NULL OR s.id IS NOT NULL)
  ),
  melhor_por_lead AS (
    SELECT DISTINCT ON (fr.lead_id)
      fr.lead_id,
      fr.fato AS fato_match,
      fr.categoria,
      fr.score
    FROM fatos_rankeados fr
    ORDER BY fr.lead_id, fr.score DESC
  )
  SELECT
    l.id AS lead_id,
    l.name,
    l.phone,
    l.temperatura_lead,
    l.fase_pipeline,
    l.updated_at,
    mpl.fato_match,
    mpl.categoria,
    mpl.score
  FROM melhor_por_lead mpl
  JOIN public.leads l ON l.id = mpl.lead_id
  WHERE l.tenant_id    = p_tenant_id
    AND l.deleted_at IS NULL
  ORDER BY mpl.score DESC
  LIMIT p_match_count;
$$;


ALTER FUNCTION public.buscar_leads_por_significado(p_tenant_id uuid, p_query_text text, p_query_embedding extensions.halfvec, p_match_count integer, p_full_text_weight double precision, p_semantic_weight double precision, p_rrf_k integer) OWNER TO postgres;

--
-- Name: buscar_leads_similares(uuid, uuid, integer, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.buscar_leads_similares(p_tenant_id uuid, p_lead_id_referencia uuid, p_match_count integer DEFAULT 10, p_min_similarity numeric DEFAULT 0.65) RETURNS TABLE(lead_id uuid, similarity numeric, num_fatos integer, fatos_resumo text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_centroide_ref extensions.halfvec;
  v_num_fatos_ref int;
BEGIN
  SELECT
    AVG(lm.vetor_semantico),
    count(*)
  INTO v_centroide_ref, v_num_fatos_ref
  FROM public.memoria_lead lm
  WHERE lm.tenant_id = p_tenant_id
    AND lm.lead_id = p_lead_id_referencia
    AND lm.ativa = true
    AND lm.sistema_expirou_em IS NULL
    AND lm.vetor_semantico IS NOT NULL;

  IF v_centroide_ref IS NULL OR v_num_fatos_ref = 0 THEN
    RETURN;
  END IF;

  RETURN QUERY
  WITH centroides AS (
    SELECT
      lm.lead_id AS lid,
      AVG(lm.vetor_semantico) AS centroide,
      count(*)::int AS num_fatos,
      string_agg(lm.fato, ' · ' ORDER BY lm.criado_em DESC) AS fatos_resumo
    FROM public.memoria_lead lm
    WHERE lm.tenant_id = p_tenant_id
      AND lm.lead_id <> p_lead_id_referencia
      AND lm.ativa = true
      AND lm.sistema_expirou_em IS NULL
      AND lm.vetor_semantico IS NOT NULL
    GROUP BY lm.lead_id
    HAVING count(*) > 0
  )
  SELECT
    c.lid,
    (1 - (c.centroide <=> v_centroide_ref))::numeric,
    c.num_fatos,
    LEFT(c.fatos_resumo, 500)
  FROM centroides c
  WHERE (1 - (c.centroide <=> v_centroide_ref)) >= p_min_similarity
  ORDER BY c.centroide <=> v_centroide_ref ASC
  LIMIT p_match_count;
END;
$$;


ALTER FUNCTION public.buscar_leads_similares(p_tenant_id uuid, p_lead_id_referencia uuid, p_match_count integer, p_min_similarity numeric) OWNER TO postgres;

--
-- Name: FUNCTION buscar_leads_similares(p_tenant_id uuid, p_lead_id_referencia uuid, p_match_count integer, p_min_similarity numeric); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.buscar_leads_similares(p_tenant_id uuid, p_lead_id_referencia uuid, p_match_count integer, p_min_similarity numeric) IS 'Sprint C: top-N leads mais similares ao lead-referência via centroide dos embeddings de lead_memory vivos. Base pro Wizard Campanha Semântica.';


--
-- Name: buscar_memoria_dono(uuid, extensions.halfvec, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.buscar_memoria_dono(p_owner_id uuid, p_query_embedding extensions.halfvec, p_match_count integer DEFAULT 30) RETURNS TABLE(id uuid, fato text, categoria text, relevancia text, vezes_evocado integer, ultima_evocacao_em timestamp with time zone, criado_em timestamp with time zone, valido_ate timestamp with time zone, score double precision)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select m.id, m.fato, m.categoria, m.relevancia, m.vezes_evocado, m.ultima_evocacao_em, m.criado_em, m.valido_ate,
         (1 - (m.vetor_semantico operator(extensions.<=>) p_query_embedding))::double precision as score
    from public.memoria_dono m
   where m.owner_id = p_owner_id and m.ativa
     and m.vetor_semantico is not null
     and (m.valido_ate is null or m.valido_ate > now())
   order by m.vetor_semantico operator(extensions.<=>) p_query_embedding
   limit greatest(1, least(coalesce(p_match_count, 30), 100));
$$;


ALTER FUNCTION public.buscar_memoria_dono(p_owner_id uuid, p_query_embedding extensions.halfvec, p_match_count integer) OWNER TO postgres;

--
-- Name: buscar_ou_criar_conversa(text, uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.buscar_ou_criar_conversa(p_phone text, p_tenant_id uuid, p_agent_id uuid, p_channel text DEFAULT 'chat'::text, p_first_fase text DEFAULT 'saudacao'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_conv record;
  v_lead_id uuid;
  v_ficha record;
  v_lead_converted boolean;
  v_agent_active boolean;
BEGIN
  p_tenant_id := public.tenant_efetivo(p_tenant_id);

  PERFORM pg_advisory_xact_lock(hashtext(p_phone || COALESCE(p_tenant_id::text, '')));

  SELECT COALESCE(is_active, true) INTO v_agent_active
  FROM public.agentes_usuario
  WHERE id = p_agent_id;

  SELECT * INTO v_conv FROM public.conversas
  WHERE phone = ANY(public.telefones_equivalentes(p_phone)) AND tenant_id IS NOT DISTINCT FROM p_tenant_id AND status IN ('active', 'ativa')
  ORDER BY created_at DESC LIMIT 1;
  IF v_conv IS NULL THEN
    SELECT * INTO v_conv FROM public.conversas
    WHERE phone = ANY(public.telefones_equivalentes(p_phone)) AND tenant_id IS NOT DISTINCT FROM p_tenant_id
      AND status IN ('human', 'closed', 'humano', 'encerrada')
      AND created_at > now() - interval '30 days'
    ORDER BY created_at DESC LIMIT 1;
    IF v_conv IS NOT NULL THEN
      UPDATE public.conversas SET status = 'ativa' WHERE id = v_conv.id RETURNING * INTO v_conv;
    END IF;
  END IF;
  IF v_conv IS NOT NULL THEN
    SELECT (converted_at IS NOT NULL) INTO v_lead_converted FROM public.leads WHERE id = v_conv.lead_id;
    IF v_lead_converted AND v_conv.agent_enabled = true THEN
      UPDATE public.conversas SET agent_enabled = false WHERE id = v_conv.id;
      v_conv.agent_enabled := false;
    END IF;
  END IF;
  IF v_conv IS NULL THEN
    SELECT id INTO v_lead_id FROM public.leads
    WHERE phone = ANY(public.telefones_equivalentes(p_phone)) AND tenant_id IS NOT DISTINCT FROM p_tenant_id
    ORDER BY created_at DESC LIMIT 1;
    IF v_lead_id IS NULL THEN
      INSERT INTO public.leads (agente_id, phone, name, canal_externo, tenant_id)
      VALUES (p_agent_id, p_phone, p_phone, p_channel, p_tenant_id) RETURNING id INTO v_lead_id;
    END IF;
    SELECT (converted_at IS NOT NULL) INTO v_lead_converted FROM public.leads WHERE id = v_lead_id;
    INSERT INTO public.conversas (lead_id, phone, status, channel, tenant_id, agent_enabled, agente_id)
    VALUES (
      v_lead_id, p_phone, 'ativa', p_channel, p_tenant_id,
      v_agent_active AND NOT COALESCE(v_lead_converted, false),
      p_agent_id
    )
    RETURNING * INTO v_conv;
  END IF;
  SELECT * INTO v_ficha FROM public.fichas_lead WHERE conversation_id = v_conv.id LIMIT 1;
  IF v_ficha IS NULL THEN
    INSERT INTO public.fichas_lead (conversation_id, lead_id, agente_id, fase, ciclo, dados_capturados)
    VALUES (v_conv.id, v_conv.lead_id, p_agent_id, p_first_fase, 1, '{}'::jsonb);
  END IF;
  RETURN jsonb_build_object('conversation', jsonb_build_object('id', v_conv.id, 'lead_id', v_conv.lead_id, 'status', v_conv.status));
END;
$$;


ALTER FUNCTION public.buscar_ou_criar_conversa(p_phone text, p_tenant_id uuid, p_agent_id uuid, p_channel text, p_first_fase text) OWNER TO postgres;

--
-- Name: buscar_pergunta_similar(uuid, extensions.halfvec, double precision); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.buscar_pergunta_similar(p_tenant_id uuid, p_embedding extensions.halfvec, p_limiar double precision DEFAULT 0.88) RETURNS TABLE(id uuid, pergunta text, resposta_do_dono text, status_loop text, ocorrencias integer, bloco_criado_id uuid, similaridade double precision)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
  SELECT ps.id, ps.pergunta, ps.resposta_do_dono, ps.status_loop, ps.ocorrencias,
         ps.bloco_criado_id,
         1 - (ps.vetor_semantico OPERATOR(extensions.<=>) p_embedding) AS similaridade
  FROM public.perguntas_sem_resposta ps
  WHERE ps.tenant_id = p_tenant_id
    AND ps.vetor_semantico IS NOT NULL
    AND (ps.status_loop = 'aguardando_dono' OR ps.resposta_do_dono IS NOT NULL)
    AND 1 - (ps.vetor_semantico OPERATOR(extensions.<=>) p_embedding) >= p_limiar
  ORDER BY ps.vetor_semantico OPERATOR(extensions.<=>) p_embedding
  LIMIT 1;
$$;


ALTER FUNCTION public.buscar_pergunta_similar(p_tenant_id uuid, p_embedding extensions.halfvec, p_limiar double precision) OWNER TO postgres;

--
-- Name: buscar_produto_fuzzy(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.buscar_produto_fuzzy(p_tenant_id uuid, p_termo text) RETURNS TABLE(id uuid, nome text, descricao_curta text, pontuacao real)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  SELECT p.id, p.nome, p.descricao_curta,
         GREATEST(
           extensions.similarity(lower(p.nome), lower(p_termo)),
           extensions.similarity(lower(coalesce(p.slug, '')), lower(p_termo)),
           (SELECT COALESCE(MAX(extensions.similarity(lower(k), lower(p_termo))), 0)
              FROM unnest(coalesce(p.palavras_chave, ARRAY[]::text[])) k)
         )::real AS pontuacao
  FROM public.produtos p
  WHERE p.user_id = p_tenant_id
    AND p.ativo = true
  ORDER BY pontuacao DESC, p.ordem NULLS LAST
  LIMIT 3;
$$;


ALTER FUNCTION public.buscar_produto_fuzzy(p_tenant_id uuid, p_termo text) OWNER TO postgres;

--
-- Name: buscar_triggers_temporais(text, text, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.buscar_triggers_temporais(p_condicao_tipo text, p_escopo text DEFAULT NULL::text, p_nicho_id uuid DEFAULT NULL::uuid, p_tenant_id uuid DEFAULT NULL::uuid, p_fase_aplicavel text DEFAULT NULL::text) RETURNS TABLE(id uuid, nome_trigger text, tempo_aguardar_minutos integer, acao_disparada text, acao_payload jsonb, fase_aplicavel text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  -- Δ 2026-09-15 (Amorim): tenant com gatilho PRÓPRIO (linha escopo='tenant', ativa OU
  -- inativa, não deletada) pro condicao_tipo SUBSTITUI os globais/nicho desse tipo — senão a
  -- cadência sob medida ("a cada 2 dias") somava com a global (1h/6h/24h/3d). Linha inativa
  -- serve pra só desligar os globais de um tipo. Sem linha de tenant: comportamento antigo.
  WITH tem_proprio AS (
    SELECT EXISTS (
      SELECT 1 FROM public.blocos_gatilho g
      WHERE g.escopo = 'tenant' AND g.tenant_id = p_tenant_id
        AND g.condicao_tipo = p_condicao_tipo AND g.deleted_at IS NULL
    ) AS sim
  )
  SELECT
    tc.id,
    tc.nome_trigger,
    tc.tempo_aguardar_minutos,
    tc.acao_disparada,
    tc.acao_payload,
    tc.fase_aplicavel
  FROM public.blocos_gatilho tc, tem_proprio
  WHERE tc.ativo = true
    AND tc.deleted_at IS NULL
    AND tc.condicao_tipo = p_condicao_tipo
    AND (
      p_fase_aplicavel IS NULL
      OR tc.fase_aplicavel = p_fase_aplicavel
      OR tc.fase_aplicavel IS NULL
    )
    AND (
      (p_escopo = 'global' AND tc.escopo = 'global')
      OR (p_escopo = 'nicho'
          AND tc.escopo IN ('global', 'nicho')
          AND (tc.nicho_id = p_nicho_id OR tc.escopo = 'global'))
      OR (p_escopo = 'tenant'
          AND (
            (NOT tem_proprio.sim AND tc.escopo = 'global')
            OR (NOT tem_proprio.sim AND tc.escopo = 'nicho' AND tc.nicho_id = p_nicho_id)
            OR (tc.escopo = 'tenant' AND tc.tenant_id = p_tenant_id)
          ))
      OR p_escopo IS NULL
    )
  ORDER BY
    CASE tc.escopo
      WHEN 'tenant' THEN 1
      WHEN 'nicho'  THEN 2
      WHEN 'global' THEN 3
      ELSE 4
    END,
    tc.tempo_aguardar_minutos ASC;
$$;


ALTER FUNCTION public.buscar_triggers_temporais(p_condicao_tipo text, p_escopo text, p_nicho_id uuid, p_tenant_id uuid, p_fase_aplicavel text) OWNER TO postgres;

--
-- Name: calcular_plano_pagamento(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.calcular_plano_pagamento(p_itens jsonb) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_total      bigint := 0;
  v_entrada    bigint := 0;
  v_teto       int    := NULL;
  v_parcelas   jsonb  := '[]'::jsonb;
  v_item       jsonb;
  v_qtd        int;
  v_preco      bigint;
  v_n          int;
  v_base       bigint;
  v_resto      bigint;
  v_por_prod   jsonb := '[]'::jsonb;
  v_qtd_itens  int := 0;
  v_cravado    bigint := NULL;
  v_oferecidas int[]  := NULL;
  v_lista      int[];
  v_nomeadas   jsonb  := NULL;
BEGIN
  IF p_itens IS NULL OR jsonb_typeof(p_itens) <> 'array' OR jsonb_array_length(p_itens) = 0 THEN
    RAISE EXCEPTION 'calcular_plano_pagamento: lista de itens vazia';
  END IF;

  FOR v_item IN SELECT * FROM jsonb_array_elements(p_itens) LOOP
    v_qtd_itens := v_qtd_itens + 1;
    v_qtd   := GREATEST(1, COALESCE((v_item->>'qtd')::int, 1));
    v_preco := COALESCE((v_item->>'preco_centavos')::bigint, 0);
    IF v_preco <= 0 THEN
      RAISE EXCEPTION 'calcular_plano_pagamento: item % sem preco_centavos válido', COALESCE(v_item->>'nome', v_item->>'produto_id');
    END IF;
    v_total   := v_total + (v_qtd * v_preco);
    v_entrada := v_entrada + COALESCE((v_item->>'entrada_centavos')::bigint, 0);
    v_teto := LEAST(COALESCE(v_teto, 2147483647), GREATEST(1, COALESCE((v_item->>'max_parcelas')::int, 1)));
    -- cravado só vale pra pacote de 1 item (multi-produto divide — risco aceito blueprint §9)
    v_cravado := NULLIF((v_item->>'valor_parcela_cravado_centavos'), '')::bigint;

    -- v5: oferta explícita do dono do produto. Mesma restrição do cravado (1 item só).
    v_oferecidas := NULL;
    IF jsonb_typeof(v_item->'parcelas_oferecidas') = 'array'
       AND jsonb_array_length(v_item->'parcelas_oferecidas') > 0 THEN
      SELECT array_agg(x::int) INTO v_oferecidas
      FROM jsonb_array_elements_text(v_item->'parcelas_oferecidas') AS t(x);
    END IF;

    -- v6: opções nomeadas do produto (total próprio por opção). Só 1 item com qtd 1.
    v_nomeadas := NULL;
    IF jsonb_typeof(v_item->'opcoes_pagamento') = 'array'
       AND jsonb_array_length(v_item->'opcoes_pagamento') > 0 AND v_qtd = 1 THEN
      SELECT jsonb_agg(jsonb_build_object(
               'id', COALESCE(NULLIF(o->>'id', ''), 'opcao_' || ord),
               'rotulo', COALESCE(NULLIF(o->>'rotulo', ''), 'Opção ' || ord),
               'total_centavos', (o->>'total_centavos')::bigint,
               'entrada_centavos', COALESCE((o->>'entrada_centavos')::bigint, 0),
               'parcelas', GREATEST(1, COALESCE((o->>'parcelas')::int, 1)),
               'valor_parcela_centavos', COALESCE((o->>'valor_parcela_centavos')::bigint, (o->>'total_centavos')::bigint),
               'observacao', NULLIF(o->>'observacao', '')
             ) ORDER BY ord)
        INTO v_nomeadas
      FROM jsonb_array_elements(v_item->'opcoes_pagamento') WITH ORDINALITY AS t(o, ord)
      WHERE COALESCE((o->>'total_centavos')::bigint, 0) > 0;
    END IF;

    v_por_prod := v_por_prod || jsonb_build_object(
      'produto_id', v_item->>'produto_id',
      'nome', v_item->>'nome',
      'qtd', v_qtd,
      'preco_centavos', v_preco,
      'subtotal_centavos', v_qtd * v_preco
    );
  END LOOP;

  v_teto := COALESCE(v_teto, 1);
  v_entrada := LEAST(v_entrada, v_total);
  IF v_qtd_itens > 1 THEN v_cravado := NULL; v_oferecidas := NULL; v_nomeadas := NULL; END IF;

  -- quais n gerar: a oferta do dono (limitada ao teto) ou, sem ela, o leque completo
  IF v_oferecidas IS NOT NULL THEN
    SELECT array_agg(DISTINCT n ORDER BY n) INTO v_lista
    FROM unnest(v_oferecidas) AS n
    WHERE n BETWEEN 1 AND v_teto;
  END IF;
  IF v_lista IS NULL OR array_length(v_lista, 1) IS NULL THEN
    SELECT array_agg(n ORDER BY n) INTO v_lista FROM generate_series(1, v_teto) AS n;
  END IF;

  FOREACH v_n IN ARRAY v_lista LOOP
    IF v_cravado IS NOT NULL AND v_n = v_teto THEN
      -- parcela cravada pelo dono: total parcelado = entrada + n × cravado (pode ter juros embutido)
      v_parcelas := v_parcelas || jsonb_build_object(
        'parcelas', v_n,
        'valor_parcela_centavos', v_cravado,
        'primeira_parcela_centavos', v_cravado,
        'entrada_centavos', v_entrada,
        'total_centavos', v_entrada + (v_n * v_cravado),
        'origem_parcela', 'cravada'
      );
    ELSE
      v_base  := (v_total - v_entrada) / v_n;
      v_resto := (v_total - v_entrada) - (v_base * v_n);
      v_parcelas := v_parcelas || jsonb_build_object(
        'parcelas', v_n,
        'valor_parcela_centavos', v_base,
        'primeira_parcela_centavos', v_base + v_resto,
        'entrada_centavos', v_entrada,
        'total_centavos', v_total,
        'origem_parcela', 'calculada'
      );
    END IF;
  END LOOP;

  RETURN jsonb_build_object(
    'opcoes_nomeadas', v_nomeadas,
    'total_centavos', v_total,
    'entrada_centavos', v_entrada,
    'max_parcelas', v_teto,
    'opcoes', v_parcelas,
    'por_produto', v_por_prod,
    'versao_funcao', 'v6-2026-09-17',
    'entradas_calculo', p_itens
  );
END;
$$;


ALTER FUNCTION public.calcular_plano_pagamento(p_itens jsonb) OWNER TO postgres;

--
-- Name: FUNCTION calcular_plano_pagamento(p_itens jsonb); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.calcular_plano_pagamento(p_itens jsonb) IS 'Monta as opções de parcelamento do contrato. v6 (2026-09-17): devolve opcoes_nomeadas (produtos.opcoes_pagamento) quando o contrato tem 1 produto com qtd 1. v5 (2026-09-04): respeita produtos.parcelas_oferecidas quando vier preenchido — antes gerava sempre 1..max_parcelas e as opções extras dividiam o valor à vista, cobrando menos que o parcelado real.';


--
-- Name: calcular_style_profile(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.calcular_style_profile(p_lead_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_profile jsonb; v_total integer := 0; v_total_chars bigint := 0; v_tamanho_medio integer := 0;
  v_com_emoji integer := 0; v_com_audio integer := 0; v_usa_emoji boolean := false; v_usa_audio boolean := false;
  v_pct_audio float := 0.0; v_registro text := 'neutro'; v_emojis_freq text[] := '{}';
BEGIN
  SELECT COUNT(*)::integer, COALESCE(SUM(length(m.content)), 0)::bigint,
    COUNT(*) FILTER (WHERE m.content ~ '[😀-🙏🌀-🗿🚀-🛿🇦-🇿✂-➰Ⓜ-🉑]' OR m.carga->>'has_audio' = 'true' OR m.carga->>'media_type' = 'audio' OR (m.carga IS NOT NULL AND (m.carga->>'emoji_count')::int > 0))::integer,
    COUNT(*) FILTER (WHERE m.carga->>'has_audio' = 'true' OR m.carga->>'media_type' = 'audio')::integer
  INTO v_total, v_total_chars, v_com_emoji, v_com_audio
  FROM (SELECT m.content, m.carga FROM public.mensagens m JOIN public.conversas c ON c.id = m.conversation_id WHERE c.lead_id = p_lead_id AND m.role = 'user' AND m.deleted_at IS NULL ORDER BY m.created_at DESC LIMIT 30) m;
  IF v_total = 0 THEN RETURN NULL; END IF;
  v_tamanho_medio := (v_total_chars / v_total)::integer;
  v_usa_emoji := (v_com_emoji::float / v_total) >= 0.20;
  v_usa_audio := v_com_audio > 0;
  v_pct_audio := ROUND((v_com_audio::float / v_total)::numeric, 2)::float;
  IF v_usa_emoji OR v_tamanho_medio < 60 THEN v_registro := 'informal';
  ELSIF v_tamanho_medio > 200 AND NOT v_usa_emoji THEN v_registro := 'formal';
  ELSE v_registro := 'neutro'; END IF;
  SELECT ARRAY(SELECT DISTINCT regexp_matches(m2.content, '[\U0001F300-\U0001FAFF\U00002600-\U000027BF\U0000FE00-\U0000FE0F]+', 'g')
    FROM public.mensagens m2 JOIN public.conversas c2 ON c2.id = m2.conversation_id
    WHERE c2.lead_id = p_lead_id AND m2.role = 'user' AND m2.deleted_at IS NULL AND m2.content ~ '[\U0001F300-\U0001FAFF\U00002600-\U000027BF]' ORDER BY 1 LIMIT 5) INTO v_emojis_freq;
  v_profile := jsonb_build_object('registro', v_registro,'tamanho_medio_msg', v_tamanho_medio,'usa_emoji', v_usa_emoji,'emojis_frequentes', v_emojis_freq,'usa_audio', v_usa_audio,'pct_audio_vs_texto', v_pct_audio);
  UPDATE public.leads_campanha SET perfil_estilo = v_profile WHERE lead_id = p_lead_id AND state = 'ativo';
  RETURN v_profile;
END;
$$;


ALTER FUNCTION public.calcular_style_profile(p_lead_id uuid) OWNER TO postgres;

