--
-- Name: chaves_de_segmentacao(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.chaves_de_segmentacao(p_tenant_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with vivos as (
    select l.tags, l.temperatura_lead, l.fase_pipeline, l.desfecho, l.origem_lead, l.converted_at,
           l.ultima_resposta_lead_em, l.location, l.opt_out_at
      from public.leads l
     where l.tenant_id = p_tenant_id and l.deleted_at is null
  ),
  tags as (
    select split_part(t, ':', 1) as chave, substr(t, position(':' in t) + 1) as valor, count(*) as n
      from vivos v, unnest(coalesce(v.tags, '{}')) as t
     where position(':' in t) > 0
     group by 1, 2
  ),
  tags_agrupadas as (
    select chave, jsonb_agg(jsonb_build_object('valor', valor, 'n', n) order by n desc) as valores, sum(n) as total
      from (select * from tags order by n desc) x
     group by chave
  )
  select jsonb_build_object(
    'tenant_id', p_tenant_id,
    'total_leads', (select count(*) from vivos),
    'na_base', (select count(*) from vivos where location = 'base'),
    'com_opt_out', (select count(*) from vivos where opt_out_at is not null),
    'temperatura', (select coalesce(jsonb_object_agg(coalesce(temperatura_lead,'sem'), n), '{}'::jsonb)
                      from (select temperatura_lead, count(*) n from vivos group by 1) t),
    'fase_pipeline', (select coalesce(jsonb_object_agg(coalesce(fase_pipeline,'sem'), n), '{}'::jsonb)
                        from (select fase_pipeline, count(*) n from vivos group by 1) t),
    'desfecho', (select coalesce(jsonb_object_agg(coalesce(desfecho,'sem'), n), '{}'::jsonb)
                   from (select desfecho, count(*) n from vivos group by 1) t),
    'origem', (select coalesce(jsonb_object_agg(coalesce(origem_lead,'sem'), n), '{}'::jsonb)
                 from (select origem_lead, count(*) n from vivos group by 1) t),
    'comprou', (select count(*) from vivos where converted_at is not null),
    'calados_7d', (select count(*) from vivos where ultima_resposta_lead_em < now() - interval '7 days'),
    'calados_15d', (select count(*) from vivos where ultima_resposta_lead_em < now() - interval '15 days'),
    'calados_30d', (select count(*) from vivos where ultima_resposta_lead_em < now() - interval '30 days'),
    'tags', (select coalesce(jsonb_object_agg(chave, jsonb_build_object('total', total, 'valores', valores)), '{}'::jsonb)
               from (select * from tags_agrupadas order by total desc limit 40) g)
  );
$$;


ALTER FUNCTION public.chaves_de_segmentacao(p_tenant_id uuid) OWNER TO postgres;

--
-- Name: clusterizar_tags_observadas(numeric, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.clusterizar_tags_observadas(p_threshold numeric DEFAULT 0.85, p_min_obs integer DEFAULT 3, p_janela_dias integer DEFAULT 7) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_inseridas int := 0;
BEGIN
  WITH tags_frequentes AS (
    SELECT tenant_id, LOWER(TRIM(tag_text)) AS tag_norm, count(*)::int AS num_obs
    FROM public.observacoes_tag
    WHERE criado_em > now() - (p_janela_dias || ' days')::interval
    GROUP BY tenant_id, LOWER(TRIM(tag_text)) HAVING count(*) >= p_min_obs
  ),
  pares AS (
    SELECT a.tenant_id, a.tag_norm AS tag_a, b.tag_norm AS tag_b,
      extensions.similarity(a.tag_norm, b.tag_norm)::numeric(4,3) AS sim,
      CASE WHEN a.num_obs >= b.num_obs THEN a.tag_norm ELSE b.tag_norm END AS canonical
    FROM tags_frequentes a JOIN tags_frequentes b ON a.tenant_id = b.tenant_id AND a.tag_norm < b.tag_norm
    WHERE extensions.similarity(a.tag_norm, b.tag_norm) >= p_threshold
  ),
  inseridos AS (
    INSERT INTO public.sugestoes_fusao_tag (tenant_id, tag_a, tag_b, similarity, suggested_canonical, status, motivo)
    SELECT tenant_id, tag_a, tag_b, sim, canonical, 'pendente', 'cron-clusterizar-tags trgm' FROM pares
    ON CONFLICT DO NOTHING RETURNING id
  )
  SELECT count(*) INTO v_inseridas FROM inseridos;
  RETURN v_inseridas;
END;
$$;


ALTER FUNCTION public.clusterizar_tags_observadas(p_threshold numeric, p_min_obs integer, p_janela_dias integer) OWNER TO postgres;

--
-- Name: FUNCTION clusterizar_tags_observadas(p_threshold numeric, p_min_obs integer, p_janela_dias integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.clusterizar_tags_observadas(p_threshold numeric, p_min_obs integer, p_janela_dias integer) IS 'Sprint C: agrupa tag_observations similares via pg_trgm, insere sugestões em tag_merge_suggestions. Cron clusterizar-tags semanal.';


