--
-- Name: confirmar_agendamento_publico(uuid, timestamp with time zone, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.confirmar_agendamento_publico(p_token uuid, p_inicio timestamp with time zone, p_dados jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_reg public.agendamentos_link%ROWTYPE;
  v_res jsonb;
  v_nome text;
  v_motivo text;
  v_titulo text;
BEGIN
  IF p_token IS NULL OR p_inicio IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'erro', 'token_e_inicio_obrigatorios');
  END IF;
  PERFORM public.verificar_limite_taxa_publico(p_token::text, 'confirmar_agendamento_publico', 10);

  SELECT * INTO v_reg FROM public.agendamentos_link WHERE chave_publica = p_token FOR UPDATE;
  IF v_reg.id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'erro', 'nao_encontrado');
  END IF;
  IF v_reg.status = 'agendado' THEN
    RETURN jsonb_build_object('ok', false, 'erro', 'ja_agendado');
  END IF;

  v_nome   := COALESCE(NULLIF(btrim(p_dados->>'nome'), ''), 'Contato');
  v_motivo := NULLIF(btrim(p_dados->>'motivo'), '');
  v_titulo := 'Reunião — ' || v_nome;
  IF v_motivo IS NOT NULL THEN
    v_titulo := v_titulo || ': ' || v_motivo;
  END IF;

  v_res := public.agendar_reuniao_lead(
    v_reg.tenant_id, v_reg.conversa_id, v_reg.lead_id, v_reg.agente_id,
    p_inicio, v_titulo
  );
  IF (v_res->>'ok')::boolean IS DISTINCT FROM true THEN
    RETURN v_res;
  END IF;

  UPDATE public.agendamentos_link
     SET status = 'agendado',
         dados_cliente = COALESCE(p_dados, '{}'::jsonb),
         scheduled_at = p_inicio,
         sala_reuniao_id = (v_res->>'sala_id')::uuid,
         compromisso_id = (v_res->>'compromisso_id')::uuid,
         updated_at = now()
   WHERE id = v_reg.id;

  RETURN jsonb_build_object(
    'ok', true,
    'scheduled_at', p_inicio,
    'link_sala', '/sala/' || (v_res->>'chave_publica')
  );
END;
$$;


ALTER FUNCTION public.confirmar_agendamento_publico(p_token uuid, p_inicio timestamp with time zone, p_dados jsonb) OWNER TO postgres;

--
-- Name: confirmar_exclusao_dados(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: consultor_dados_ro
--

CREATE FUNCTION public.confirmar_exclusao_dados(p_owner uuid, p_conversa uuid, p_bilhete uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_conf record;
  v_where text;
  v_backup jsonb;
  v_total integer;
begin
  perform set_config('search_path', 'public', true);
  perform set_config('statement_timeout', '15000', true);
  perform set_config('request.jwt.claims',
    json_build_object('sub', p_owner::text, 'role', 'authenticated')::text, true);

  select * into v_conf from public.confirmacoes_exclusao
  where id = p_bilhete and owner_id = p_owner and conversa_id = p_conversa;
  if v_conf is null then
    return jsonb_build_object('ok', false, 'erro', 'bilhete não encontrado — prepare a exclusão de novo');
  end if;
  if v_conf.usado_em is not null then
    return jsonb_build_object('ok', false, 'erro', 'esse bilhete já foi usado');
  end if;
  if v_conf.criado_em < now() - interval '30 minutes' then
    return jsonb_build_object('ok', false, 'erro', 'bilhete expirado (30 min) — prepare de novo');
  end if;

  -- Gate dos 2 turnos: precisa existir fala NOVA do usuário depois do preparo.
  if not exists (
    select 1 from public.mentor_mensagens m
    where m.conversa_id = p_conversa and m.papel = 'user' and m.criado_em > v_conf.criado_em
  ) then
    return jsonb_build_object('ok', false, 'erro',
      'ainda não houve confirmação do usuário. Mostre o que será excluído e espere ele responder — só então confirme.');
  end if;

  v_where := (regexp_match(v_conf.comando, '\ywhere\y(.*)$', 'i'))[1];

  begin
    -- Backup antes de sumir (lixeira invisível ao sistema, resgate 30 dias).
    execute format('select coalesce(jsonb_agg(t), ''[]''::jsonb) from (select * from public.%I where %s) t',
                   v_conf.tabela, v_where) into v_backup;
    execute format(
      'with _r as (delete from public.%I where %s returning *) select count(*) from _r',
      v_conf.tabela, v_where
    ) into v_total;
  exception when others then
    return jsonb_build_object('ok', false, 'erro', 'falha ao excluir: ' || sqlerrm);
  end;

  insert into public.lixeira_exclusoes (owner_id, tabela, linha, comando)
  select p_owner, v_conf.tabela, l, v_conf.comando
  from jsonb_array_elements(coalesce(v_backup, '[]'::jsonb)) l;

  update public.confirmacoes_exclusao set usado_em = now() where id = p_bilhete;

  return jsonb_build_object('ok', true, 'etapa', 'excluido',
    'tabela', v_conf.tabela, 'linhas_excluidas', v_total);
end;
$_$;


ALTER FUNCTION public.confirmar_exclusao_dados(p_owner uuid, p_conversa uuid, p_bilhete uuid) OWNER TO consultor_dados_ro;

