--
-- Name: consulta_pode_vender(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.consulta_pode_vender(p_tenant_id uuid DEFAULT NULL::uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_tenant uuid := public.tenant_efetivo(p_tenant_id);
  v_exige_instalacao boolean;
  v_instalado boolean;
  v_toggle boolean;
  v_tipo_padrao uuid;
  v_saldo numeric(10,2);
  v_custo_ref numeric(10,2);
BEGIN
  IF v_tenant IS NULL THEN
    RETURN false;
  END IF;

  -- Portão 1: instalação. App só exige instalação se estiver no catálogo ativo da loja.
  SELECT EXISTS (
    SELECT 1 FROM public.loja_aplicativos
    WHERE slug = 'consulta' AND is_active = true
  ) INTO v_exige_instalacao;

  IF v_exige_instalacao THEN
    SELECT EXISTS (
      SELECT 1 FROM public.aplicativos_instalados
      WHERE user_id = v_tenant AND aplicativo_slug = 'consulta'
    ) INTO v_instalado;
    IF NOT v_instalado THEN
      RETURN false;
    END IF;
  END IF;

  -- Portão 2: toggle ligado (+ captura o tipo padrão pra régua de saldo)
  SELECT agente_pode_vender, tipo_padrao_id
    INTO v_toggle, v_tipo_padrao
  FROM public.consultas_config_tenant
  WHERE tenant_id = v_tenant;

  IF COALESCE(v_toggle, false) = false THEN
    RETURN false;
  END IF;

  -- Portão 3: saldo >= custo de 1 consulta
  SELECT COALESCE(saldo, 0) INTO v_saldo
  FROM public.consultas_saldo
  WHERE tenant_id = v_tenant;
  v_saldo := COALESCE(v_saldo, 0);

  v_custo_ref := (
    SELECT custo FROM public.consultas_tipos
    WHERE id = v_tipo_padrao AND ativo = true AND deleted_at IS NULL
  );
  IF v_custo_ref IS NULL THEN
    v_custo_ref := (
      SELECT MIN(custo) FROM public.consultas_tipos
      WHERE ativo = true AND deleted_at IS NULL
    );
  END IF;

  IF v_custo_ref IS NULL OR v_saldo < v_custo_ref THEN
    RETURN false;
  END IF;

  RETURN true;
END;
$$;


ALTER FUNCTION public.consulta_pode_vender(p_tenant_id uuid) OWNER TO postgres;

--
-- Name: consultar_dados_leitura(uuid, text, integer); Type: FUNCTION; Schema: public; Owner: consultor_dados_ro
--

CREATE FUNCTION public.consultar_dados_leitura(p_owner uuid, p_sql text, p_limite integer DEFAULT 100) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_sql text;
  v_limite integer;
  v_relacoes text[];
  v_bloqueadas text[];
  v_linhas jsonb;
  v_total integer;
begin
  if p_owner is null then
    return jsonb_build_object('ok', false, 'erro', 'dono da consulta ausente');
  end if;

  v_sql := btrim(coalesce(p_sql, ''));
  v_sql := regexp_replace(v_sql, ';\s*$', '');
  if v_sql = '' then
    return jsonb_build_object('ok', false, 'erro', 'consulta vazia');
  end if;
  if length(v_sql) > 8000 then
    return jsonb_build_object('ok', false, 'erro', 'consulta longa demais (máx 8000 caracteres)');
  end if;
  if v_sql !~* '^(select|with)\y' then
    return jsonb_build_object('ok', false, 'erro', 'somente SELECT é permitido');
  end if;
  if position(';' in v_sql) > 0 then
    return jsonb_build_object('ok', false, 'erro', 'apenas um comando por consulta');
  end if;
  if v_sql ~* '\y(insert|update|delete|merge)\y' then
    return jsonb_build_object('ok', false, 'erro', 'somente consulta de leitura é permitida (palavra de escrita detectada)');
  end if;

  v_limite := least(greatest(coalesce(p_limite, 100), 1), 500);

  perform set_config('search_path', 'public', true);
  perform set_config('statement_timeout', '8000', true);
  perform set_config(
    'request.jwt.claims',
    json_build_object('sub', p_owner::text, 'role', 'authenticated')::text,
    true
  );

  -- Valida sintaxe + extrai relações citadas diretamente (sem executar nada).
  -- CREATE VIEW já rejeita CTE data-modifying e FOR UPDATE por regra do Postgres.
  begin
    execute 'create or replace temp view _consulta_llm_v as ' || v_sql;
  exception when others then
    return jsonb_build_object('ok', false, 'erro', 'consulta inválida: ' || sqlerrm);
  end;

  select array_agg(distinct c2.relname) into v_relacoes
  from pg_catalog.pg_class c1
  join pg_catalog.pg_rewrite r on r.ev_class = c1.oid
  join pg_catalog.pg_depend d on d.objid = r.oid and d.refclassid = 'pg_class'::pg_catalog.regclass
  join pg_catalog.pg_class c2 on c2.oid = d.refobjid and c2.oid <> c1.oid
  where c1.relname = '_consulta_llm_v'
    and c1.relnamespace = pg_catalog.pg_my_temp_schema();

  execute 'drop view if exists _consulta_llm_v';

  select array_agg(rel) into v_bloqueadas
  from unnest(coalesce(v_relacoes, array[]::text[])) rel
  where rel not in (select tabela from public.tabelas_consulta_permitidas where ativo);

  if v_bloqueadas is not null and array_length(v_bloqueadas, 1) > 0 then
    return jsonb_build_object(
      'ok', false,
      'erro', 'tabela(s) fora da área permitida: ' || array_to_string(v_bloqueadas, ', ')
        || '. Chame a ação esquema pra ver as tabelas disponíveis.'
    );
  end if;

  -- Executa embrulhado com limite+1 pra detectar truncamento. RLS vale como o dono.
  begin
    execute format(
      'select coalesce(jsonb_agg(t), ''[]''::jsonb) from (select q.* from (%s) q limit %s) t',
      v_sql, v_limite + 1
    ) into v_linhas;
  exception when others then
    return jsonb_build_object('ok', false, 'erro', 'falha ao executar: ' || sqlerrm);
  end;

  v_total := coalesce(jsonb_array_length(v_linhas), 0);
  if v_total > v_limite then
    select jsonb_agg(t.e) into v_linhas
    from (
      select e from jsonb_array_elements(v_linhas) with ordinality as x(e, ord)
      where x.ord <= v_limite
    ) t(e);
  end if;

  if length(v_linhas::text) > 60000 then
    return jsonb_build_object(
      'ok', false,
      'erro', 'resultado grande demais — refaça com agregação (count, sum, group by) ou menos colunas'
    );
  end if;

  return jsonb_build_object(
    'ok', true,
    'linhas', coalesce(v_linhas, '[]'::jsonb),
    'total_retornado', least(v_total, v_limite),
    'truncado', v_total > v_limite
  );
end;
$_$;


ALTER FUNCTION public.consultar_dados_leitura(p_owner uuid, p_sql text, p_limite integer) OWNER TO consultor_dados_ro;

--
-- Name: consultar_meus_numeros_rifa(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.consultar_meus_numeros_rifa(p_token uuid, p_phone text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_r public.rifas%rowtype;
  v_phone text := regexp_replace(coalesce(p_phone, ''), '\D', '', 'g');
  v_pedidos jsonb;
begin
  if length(v_phone) < 10 then
    return jsonb_build_object('ok', false, 'erro', 'phone_invalido');
  end if;

  perform public.verificar_limite_taxa_publico(v_phone, 'rifa_meus_numeros', 20);

  select * into v_r from public.rifas
  where chave_publica = p_token and deleted_at is null;
  if not found or v_r.status = 'rascunho' then
    return jsonb_build_object('ok', false, 'erro', 'rifa_nao_encontrada');
  end if;

  select coalesce(jsonb_agg(jsonb_build_object(
           'status', p.status,
           'numeros', to_jsonb(p.numeros),
           'qtd', p.qtd_numeros,
           'valor_centavos', p.valor_centavos,
           'criado_em', p.created_at
         ) order by p.created_at desc), '[]'::jsonb)
    into v_pedidos
  from (
    select * from public.pedidos_rifa
    where rifa_id = v_r.id and phone = v_phone
    order by created_at desc
    limit 20
  ) p;

  return jsonb_build_object('ok', true, 'rifa_titulo', v_r.titulo, 'pedidos', v_pedidos);
end;
$$;


ALTER FUNCTION public.consultar_meus_numeros_rifa(p_token uuid, p_phone text) OWNER TO postgres;

--
-- Name: contar_publico_campanha(uuid, text, jsonb, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.contar_publico_campanha(p_tenant_id uuid, p_type text, p_filters jsonb, p_inatividade_ms bigint) RETURNS integer
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
DECLARE
  v_count integer;
  v_corte timestamptz;
BEGIN
  v_corte := now() - make_interval(secs => (p_inatividade_ms::numeric / 1000)::double precision);

  IF p_type = 'cobranca' THEN
    SELECT COUNT(DISTINCT l.id) INTO v_count
    FROM public.leads l
    JOIN public.pagamentos_cliente cp ON cp.lead_id = l.id AND cp.status = 'pendente' AND cp.data_vencimento < CURRENT_DATE
    LEFT JOIN public.leads_campanha cl ON cl.lead_id = l.id AND cl.state = 'ativo'
    LEFT JOIN public.exclusoes_tenant o ON o.lead_id = l.id AND o.tenant_id = p_tenant_id
    WHERE l.tenant_id = p_tenant_id
      AND l.location = 'base'
      AND l.deleted_at IS NULL
      AND cl.id IS NULL
      AND o.id IS NULL;
    RETURN v_count;
  END IF;

  SELECT COUNT(*) INTO v_count
  FROM public.leads l
  LEFT JOIN public.leads_campanha cl ON cl.lead_id = l.id AND cl.state = 'ativo'
  LEFT JOIN public.exclusoes_tenant o ON o.lead_id = l.id AND o.tenant_id = p_tenant_id
  WHERE l.tenant_id = p_tenant_id
    AND l.location = 'base'
    AND l.deleted_at IS NULL
    AND l.updated_at < v_corte
    AND cl.id IS NULL
    AND o.id IS NULL
    AND (
      p_filters->'tags' IS NULL
      OR jsonb_array_length(p_filters->'tags') = 0
      OR (
        (p_filters->>'operator' = 'OR' AND l.tags && ARRAY(SELECT jsonb_array_elements_text(p_filters->'tags')))
        OR (COALESCE(p_filters->>'operator', 'AND') = 'AND' AND l.tags @> ARRAY(SELECT jsonb_array_elements_text(p_filters->'tags')))
      )
    );
  RETURN v_count;
END;
$$;


ALTER FUNCTION public.contar_publico_campanha(p_tenant_id uuid, p_type text, p_filters jsonb, p_inatividade_ms bigint) OWNER TO postgres;

--
-- Name: contrato_manual_item_sintetico(text, numeric, numeric, integer, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.contrato_manual_item_sintetico(p_nome text, p_total numeric, p_entrada numeric, p_parcelas integer, p_valor_parc numeric) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  SELECT jsonb_build_array(
    jsonb_build_object(
      'produto_id', NULL,
      'nome', COALESCE(NULLIF(p_nome, ''), 'Contrato'),
      'qtd', 1,
      'preco_centavos', round(p_total * 100)::bigint,
      'entrada_centavos', round(COALESCE(p_entrada, 0) * 100)::bigint,
      -- Plano cravado usa o nº de parcelas do próprio template; sem cravo, mantém o
      -- piso 5 da regra de 2026-08-10.
      'max_parcelas',
        CASE
          WHEN p_valor_parc IS NOT NULL AND p_valor_parc > 0 AND COALESCE(p_parcelas, 0) > 0
            THEN p_parcelas
          ELSE GREATEST(COALESCE(p_parcelas, 5), 5)
        END,
      'valor_parcela_cravado_centavos',
        CASE WHEN p_valor_parc IS NULL THEN NULL ELSE round(p_valor_parc * 100)::bigint END
    )
    -- Δ 2026-09-08: com valor de parcela cravado, declara a oferta explícita — é o
    -- mesmo campo que o caminho do agente já manda, e faz `calcular_plano_pagamento`
    -- devolver só esse plano em vez de abrir o leque.
    || CASE
         WHEN p_valor_parc IS NOT NULL AND p_valor_parc > 0 AND COALESCE(p_parcelas, 0) > 0
           THEN jsonb_build_object('parcelas_oferecidas', jsonb_build_array(p_parcelas))
         ELSE '{}'::jsonb
       END
  );
$$;


ALTER FUNCTION public.contrato_manual_item_sintetico(p_nome text, p_total numeric, p_entrada numeric, p_parcelas integer, p_valor_parc numeric) OWNER TO postgres;

--
-- Name: FUNCTION contrato_manual_item_sintetico(p_nome text, p_total numeric, p_entrada numeric, p_parcelas integer, p_valor_parc numeric); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.contrato_manual_item_sintetico(p_nome text, p_total numeric, p_entrada numeric, p_parcelas integer, p_valor_parc numeric) IS 'Item sintético do contrato manual para calcular_plano_pagamento. Com valor de parcela cravado, declara parcelas_oferecidas=[n] e o plano do dono é o único oferecido; sem cravo, mantém o leque com piso 5 (regra 2026-08-10). Δ 2026-09-08.';


--
-- Name: conversas_recentes_tenant(uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.conversas_recentes_tenant(p_tenant_id uuid, p_dias integer DEFAULT 30, p_limite integer DEFAULT 50) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_resultado jsonb;
BEGIN
  PERFORM set_config('search_path', 'public', true);
  PERFORM set_config('statement_timeout', '5s', true);

  SELECT coalesce(jsonb_agg(t ORDER BY t.created_at DESC), '[]'::jsonb)
  INTO v_resultado
  FROM (
    SELECT c.id, c.lead_id, c.phone, c.status, c.created_at,
           l.name AS lead_name, l.fase_pipeline, l.temperatura_lead, l.is_hot,
           (SELECT COUNT(*) FROM public.mensagens m WHERE m.conversation_id = c.id AND m.deleted_at IS NULL) AS turnos
    FROM public.conversas c
    LEFT JOIN public.leads l ON l.id = c.lead_id
    WHERE c.tenant_id = p_tenant_id
      AND c.created_at > now() - (p_dias || ' days')::interval
      AND c.phone NOT ILIKE 'chat-test-%'
    ORDER BY c.created_at DESC
    LIMIT p_limite
  ) t;

  RETURN v_resultado;
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('erro', SQLERRM);
END
$$;


ALTER FUNCTION public.conversas_recentes_tenant(p_tenant_id uuid, p_dias integer, p_limite integer) OWNER TO postgres;

--
-- Name: conversas_unread_humano(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.conversas_unread_humano(p_tenant_id uuid) RETURNS TABLE(conversation_id uuid, ultima_msg_em timestamp with time zone, qtd_msgs_novas integer, needs_human_help boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  SELECT
    c.id AS conversation_id,
    MAX(m.created_at) AS ultima_msg_em,
    count(*)::int AS qtd_msgs_novas,
    coalesce(bool_or(l.precisa_humano), false) AS needs_human_help
  FROM public.conversas c
  JOIN public.mensagens m ON m.conversation_id = c.id
  LEFT JOIN public.leads l ON l.id = c.lead_id
  WHERE c.tenant_id = p_tenant_id
    AND c.agent_enabled = false
    AND m.role = 'user'
    AND m.deleted_at IS NULL
    AND m.created_at > coalesce(c.visto_em, '1970-01-01'::timestamptz)
    AND (
      p_tenant_id = (select auth.uid())
      OR EXISTS (
        SELECT 1 FROM public.profiles
        WHERE id = (select auth.uid()) AND parent_user_id = p_tenant_id
      )
    )
  GROUP BY c.id;
$$;


ALTER FUNCTION public.conversas_unread_humano(p_tenant_id uuid) OWNER TO postgres;

--
-- Name: converter_em_cliente(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.converter_em_cliente(p_campaign_lead_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_caller uuid := auth.uid();
  v_lead   uuid;
  v_tenant uuid;
BEGIN
  IF v_caller IS NULL THEN
    RAISE EXCEPTION 'unauthenticated';
  END IF;

  SELECT cl.lead_id, c.tenant_id
    INTO v_lead, v_tenant
    FROM public.leads_campanha cl
    JOIN public.campanhas c ON c.id = cl.campaign_id
   WHERE cl.id = p_campaign_lead_id;

  IF v_lead IS NULL THEN
    RAISE EXCEPTION 'not_found';
  END IF;

  IF NOT (
       v_tenant = v_caller
    OR EXISTS (
         SELECT 1 FROM public.profiles p
          WHERE p.id = v_caller AND p.parent_user_id = v_tenant
       )
    OR public.is_platform_admin()
  ) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;

  -- Marca lead convertido
  UPDATE public.leads
     SET converted_at = COALESCE(converted_at, now()),
         updated_at   = now()
   WHERE id = v_lead;

  -- Fecha + arquiva campaign_lead
  UPDATE public.leads_campanha
     SET state        = 'fechado',
         exit_reason  = 'convertido',
         closed_at    = COALESCE(closed_at, now()),
         archived_at  = COALESCE(archived_at, now())
   WHERE id = p_campaign_lead_id;
END;
$$;


ALTER FUNCTION public.converter_em_cliente(p_campaign_lead_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION converter_em_cliente(p_campaign_lead_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.converter_em_cliente(p_campaign_lead_id uuid) IS 'Marca lead como convertido (leads.converted_at) e fecha+arquiva campaign_lead.';


--
-- Name: copiar_templates_produto_para_novo_tenant(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.copiar_templates_produto_para_novo_tenant() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
DECLARE
  tmpl RECORD;
  novo_produto_id uuid;
BEGIN
  IF NEW.nicho_id IS NULL THEN
    RETURN NEW;
  END IF;

  FOR tmpl IN
    SELECT * FROM produto_templates
    WHERE nicho_id = NEW.nicho_id AND ativo = true
  LOOP
    INSERT INTO produtos (user_id, nome, prazo_entrega, garantia)
    VALUES (NEW.id, tmpl.nome, tmpl.prazo_entrega, tmpl.garantia)
    RETURNING id INTO novo_produto_id;

    INSERT INTO produto_conhecimento (produto_id, tipo, titulo, conteudo, ordem)
    SELECT novo_produto_id, tipo, titulo, conteudo, ordem
    FROM produto_template_conhecimento
    WHERE produto_template_id = tmpl.id
    ORDER BY ordem NULLS LAST;

    INSERT INTO produto_midias (produto_id, arquivo_url, arquivo_nome, arquivo_tipo, descricao, ordem)
    SELECT novo_produto_id, arquivo_url, arquivo_nome, arquivo_tipo, descricao, ordem
    FROM produto_template_midias
    WHERE produto_template_id = tmpl.id
    ORDER BY ordem NULLS LAST;
  END LOOP;

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.copiar_templates_produto_para_novo_tenant() OWNER TO postgres;

--
-- Name: creditar_saldo_admin(uuid, numeric, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.creditar_saldo_admin(p_tenant_id uuid, p_valor numeric, p_motivo text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_saldo numeric(10,2);
BEGIN
  IF NOT public.eh_admin_plataforma() THEN
    RETURN jsonb_build_object('ok', false, 'erro', 'nao_autorizado');
  END IF;
  IF p_tenant_id IS NULL OR p_valor IS NULL OR p_valor <= 0 THEN
    RETURN jsonb_build_object('ok', false, 'erro', 'parametros_invalidos');
  END IF;

  INSERT INTO public.consultas_saldo (tenant_id) VALUES (p_tenant_id)
    ON CONFLICT (tenant_id) DO NOTHING;

  SELECT saldo INTO v_saldo FROM public.consultas_saldo
    WHERE tenant_id = p_tenant_id FOR UPDATE;

  UPDATE public.consultas_saldo
    SET saldo = saldo + p_valor, atualizado_em = now()
    WHERE tenant_id = p_tenant_id;

  INSERT INTO public.consultas_carteira_mov (tenant_id, tipo, valor, saldo_apos)
    VALUES (p_tenant_id, 'credito', p_valor, v_saldo + p_valor);

  RETURN jsonb_build_object('ok', true, 'saldo_apos', v_saldo + p_valor, 'motivo', p_motivo);
END;
$$;


ALTER FUNCTION public.creditar_saldo_admin(p_tenant_id uuid, p_valor numeric, p_motivo text) OWNER TO postgres;

--
-- Name: crenca_resumo_tenant(uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.crenca_resumo_tenant(p_tenant_id uuid, p_dias integer DEFAULT 7) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_resultado jsonb;
BEGIN
  PERFORM set_config('search_path', 'public', true);
  PERFORM set_config('statement_timeout', '5s', true);

  SELECT coalesce(jsonb_agg(t ORDER BY t.total DESC), '[]'::jsonb)
  INTO v_resultado
  FROM (
    SELECT cb.proxima_intencao AS intencao,
           COUNT(*) AS total
    FROM public.crenca_conversa cb
    WHERE cb.tenant_id = p_tenant_id
      AND cb.updated_at > now() - (p_dias || ' days')::interval
      AND cb.proxima_intencao IS NOT NULL
    GROUP BY cb.proxima_intencao
    HAVING COUNT(*) >= 2
  ) t;

  RETURN v_resultado;
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('erro', SQLERRM);
END $$;


ALTER FUNCTION public.crenca_resumo_tenant(p_tenant_id uuid, p_dias integer) OWNER TO postgres;

--
-- Name: criar_cliente_manual(text, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.criar_cliente_manual(p_name text, p_phone text, p_product text DEFAULT NULL::text, p_email text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_user_id uuid; v_agent_id uuid; v_lead_id uuid; v_conv_id uuid; v_token text; v_existing_lead_id uuid;
BEGIN
  SELECT COALESCE(p.parent_user_id, p.id) INTO v_user_id FROM public.profiles p WHERE p.id = (SELECT auth.uid());
  IF v_user_id IS NULL THEN RAISE EXCEPTION 'Usuário não autenticado'; END IF;
  SELECT l.id INTO v_existing_lead_id FROM public.leads l WHERE l.tenant_id = v_user_id AND l.phone = p_phone LIMIT 1;
  IF v_existing_lead_id IS NOT NULL THEN RAISE EXCEPTION 'Já existe um lead com este telefone'; END IF;
  SELECT ua.id INTO v_agent_id FROM public.agentes_usuario ua WHERE ua.user_id = v_user_id LIMIT 1;
  v_token := encode(gen_random_bytes(16), 'hex');
  INSERT INTO public.leads (tenant_id, name, nome_exibicao, phone, email, produto, fase_pipeline, fase_cliente, converted_at, chave_rastreamento, origem_lead, temperatura_lead)
  VALUES (v_user_id, p_name, p_name, p_phone, p_email, COALESCE(p_product, ''), 'fechado', 'documentacao', now(), v_token, 'manual', 'quente') RETURNING id INTO v_lead_id;
  INSERT INTO public.conversas (tenant_id, lead_id, phone, channel, status, agent_enabled)
  VALUES (v_user_id, v_lead_id, p_phone, 'whatsapp', 'ativa', true) RETURNING id INTO v_conv_id;
  IF v_agent_id IS NOT NULL THEN
    INSERT INTO public.fichas_lead (conversation_id, lead_id, agente_id, ciclo, fase) VALUES (v_conv_id, v_lead_id, v_agent_id, 1, 'fechado');
  END IF;
  RETURN jsonb_build_object('lead_id', v_lead_id, 'conversation_id', v_conv_id, 'tracking_token', v_token);
END;
$$;


ALTER FUNCTION public.criar_cliente_manual(p_name text, p_phone text, p_product text, p_email text) OWNER TO postgres;

--
-- Name: criar_contrato_livre(text, text, uuid, uuid, jsonb, text, jsonb, text, integer, text, text, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.criar_contrato_livre(p_texto text, p_titulo text DEFAULT 'Contrato'::text, p_lead_id uuid DEFAULT NULL::uuid, p_conversa_id uuid DEFAULT NULL::uuid, p_dados_cliente jsonb DEFAULT '{}'::jsonb, p_origem text DEFAULT 'mestre_livre'::text, p_campos_obrigatorios jsonb DEFAULT '[]'::jsonb, p_instrucao_selfie text DEFAULT NULL::text, p_num_testemunhas integer DEFAULT 0, p_chave_pix text DEFAULT NULL::text, p_link_parcelamento text DEFAULT NULL::text, p_posicao_pagamento text DEFAULT NULL::text, p_tenant_id uuid DEFAULT NULL::uuid) RETURNS TABLE(id uuid, chave_publica uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_tenant_id uuid;
  v_agente_id uuid;
  v_id        uuid;
  v_chave     uuid := gen_random_uuid();
BEGIN
  -- Tranca de identidade (2026-09-08): não pode viver só no GRANT.
  PERFORM public.tenant_efetivo(p_tenant_id);
  IF p_texto IS NULL OR btrim(p_texto) = '' THEN
    RAISE EXCEPTION 'texto do contrato obrigatorio' USING ERRCODE = '22023';
  END IF;

  -- auth.uid() prevalece (frontend). Só usa p_tenant_id quando null (service_role / Mentor).
  v_tenant_id := COALESCE((SELECT auth.uid()), p_tenant_id);
  IF v_tenant_id IS NULL THEN
    RAISE EXCEPTION 'autenticacao obrigatoria' USING ERRCODE = '42501';
  END IF;

  -- Fix vazamento entre tenants (2026-09-01, Theus): p_conversa_id/p_lead_id vêm direto do
  -- argumento da tool-call da LLM (canal Mentor, gerar_link_contrato_livre) — sem essa
  -- checagem, uma UUID errada (alucinação/confusão da LLM) grava um contrato com tenant_id
  -- certo mas conversa_id/lead_id de OUTRO tenant, que depois vaza pro prompt de conversa
  -- desse outro tenant via a view compromissos_ativos.
  IF p_conversa_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.conversas c WHERE c.id = p_conversa_id AND c.tenant_id = v_tenant_id
  ) THEN
    RAISE EXCEPTION 'conversa nao pertence a este tenant' USING ERRCODE = '42501';
  END IF;

  IF p_lead_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.leads l WHERE l.id = p_lead_id AND l.tenant_id = v_tenant_id
  ) THEN
    RAISE EXCEPTION 'lead nao pertence a este tenant' USING ERRCODE = '42501';
  END IF;

  SELECT a.id INTO v_agente_id
  FROM public.agentes a
  WHERE a.user_id = v_tenant_id
  ORDER BY a.created_at ASC
  LIMIT 1;

  INSERT INTO public.contratos (
    chave_publica, conversa_id, lead_id, agente_id, tenant_id,
    titulo, texto_contrato, dados_cliente, status, origem,
    campos_obrigatorios, instrucao_selfie, num_testemunhas,
    chave_pix, link_parcelamento, posicao_pagamento, created_at
  ) VALUES (
    v_chave, p_conversa_id, p_lead_id, v_agente_id, v_tenant_id,
    p_titulo, p_texto, p_dados_cliente, 'pendente', p_origem,
    coalesce(p_campos_obrigatorios, '[]'::jsonb), p_instrucao_selfie,
    coalesce(p_num_testemunhas, 0),
    p_chave_pix, p_link_parcelamento, p_posicao_pagamento, now()
  )
  RETURNING public.contratos.id INTO v_id;

  RETURN QUERY SELECT v_id, v_chave;
END;
$$;


ALTER FUNCTION public.criar_contrato_livre(p_texto text, p_titulo text, p_lead_id uuid, p_conversa_id uuid, p_dados_cliente jsonb, p_origem text, p_campos_obrigatorios jsonb, p_instrucao_selfie text, p_num_testemunhas integer, p_chave_pix text, p_link_parcelamento text, p_posicao_pagamento text, p_tenant_id uuid) OWNER TO postgres;

--
-- Name: criar_contrato_livre_de_template(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.criar_contrato_livre_de_template(p_template_id uuid, p_tenant_id uuid DEFAULT NULL::uuid) RETURNS TABLE(contrato_id uuid, chave_publica uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
  v_tenant_id uuid;
  v_agente_id uuid;
  v_tpl       public.contratos_template%ROWTYPE;
  v_cfg       public.config_contrato%ROWTYPE;
  v_texto     text;
  v_tok       text;
  v_total     numeric;
  v_parc      jsonb;
  v_entrada   numeric;
  v_parcelas  integer;
  v_valor_parc numeric;
  v_total_parc numeric;
  v_cond_full text;
  v_var_avista text;
  v_var_parc  text;
  v_inerte    text;
  v_chave     uuid := gen_random_uuid();
  v_id        uuid;
  v_dados_pag jsonb;
  v_planos_junto jsonb;
BEGIN
  -- Tranca de identidade (2026-09-08): não pode viver só no GRANT.
  PERFORM public.tenant_efetivo(p_tenant_id);
  v_tenant_id := COALESCE((SELECT auth.uid()), p_tenant_id);
  IF v_tenant_id IS NULL THEN
    RAISE EXCEPTION 'autenticacao obrigatoria' USING ERRCODE = '42501';
  END IF;

  IF p_template_id IS NULL THEN
    RAISE EXCEPTION 'p_template_id obrigatorio' USING ERRCODE = '22023';
  END IF;

  SELECT t.* INTO v_tpl
  FROM public.contratos_template t
  WHERE t.id = p_template_id
    AND t.user_id = v_tenant_id
    AND t.ativo = true;

  IF v_tpl.id IS NULL THEN
    RAISE EXCEPTION 'template % não encontrado, inativo ou de outro tenant', p_template_id
      USING ERRCODE = '42704';
  END IF;

  SELECT * INTO v_cfg
  FROM public.config_contrato cc
  WHERE cc.tenant_id = v_tenant_id;

  SELECT a.id INTO v_agente_id
  FROM public.agentes a
  WHERE a.user_id = v_tenant_id
  ORDER BY a.created_at ASC
  LIMIT 1;

  v_texto := CASE
    WHEN v_tpl.conteudo_comum IS NOT NULL AND left(ltrim(v_tpl.conteudo_comum), 9) = '{"type":"'
      THEN COALESCE(NULLIF(v_tpl.conteudo, ''), '')
    ELSE COALESCE(NULLIF(v_tpl.conteudo_comum, ''), v_tpl.conteudo, '')
  END;

  v_total := COALESCE(v_tpl.valor_a_vista, 0);

  v_parc       := COALESCE(v_tpl.opcoes_parcelamento -> 0, '{}'::jsonb);
  v_entrada    := NULLIF(v_parc ->> 'entrada', '')::numeric;
  v_parcelas   := NULLIF(v_parc ->> 'parcelas', '')::integer;
  v_valor_parc := NULLIF(v_parc ->> 'valor_parcela', '')::numeric;
  v_total_parc := COALESCE(v_entrada, 0) + COALESCE(v_parcelas, 0) * COALESCE(v_valor_parc, 0);

  IF position('{COND_PAGAMENTO}' IN v_texto) > 0 THEN
    v_cond_full := substring(v_texto from '\{COND_PAGAMENTO\}[\s\S]*?\{/COND_PAGAMENTO\}');
    IF v_cond_full IS NOT NULL THEN
      v_var_avista := substring(v_cond_full from '\{SE_A_VISTA\}([\s\S]*?)\{/SE_A_VISTA\}');
      v_var_parc   := substring(v_cond_full from '\{SE_PARCELADO\}([\s\S]*?)\{/SE_PARCELADO\}');
      IF v_var_avista IS NULL AND v_var_parc IS NULL THEN
        v_var_avista := substring(v_cond_full from '\{COND_PAGAMENTO\}([\s\S]*?)\{/COND_PAGAMENTO\}');
        v_var_parc   := v_var_avista;
      END IF;
      v_texto := replace(v_texto, v_cond_full, '@@COND_PAGAMENTO_INERTE@@');
    END IF;
  END IF;

  v_texto := replace(v_texto, '{SE_A_VISTA}', '');
  v_texto := replace(v_texto, '{/SE_A_VISTA}', '');
  v_texto := replace(v_texto, '{SE_PARCELADO}', '');
  v_texto := replace(v_texto, '{/SE_PARCELADO}', '');

  v_texto := replace(v_texto, '{PRODUTO_PRECO}',
    'R$ ' || replace(to_char(round(v_total, 2), 'FM999999990.00'), '.', ','));
  v_texto := replace(v_texto, '{TOTAL_AVISTA}',
    'R$ ' || replace(to_char(round(v_total, 2), 'FM999999990.00'), '.', ','));
  v_texto := replace(v_texto, '{CHAVE_PIX}', COALESCE(v_tpl.chave_pix, ''));
  v_texto := replace(v_texto, '{LINK_PAGAMENTO}', COALESCE(v_tpl.link_parcelamento, ''));
  v_texto := replace(v_texto, '{VALOR_ENTRADA}',
    CASE WHEN v_entrada IS NULL THEN '' ELSE 'R$ ' || replace(to_char(round(v_entrada, 2), 'FM999999990.00'), '.', ',') END);
  v_texto := replace(v_texto, '{NUMERO_PARCELAS}', COALESCE(v_parcelas::text, ''));
  v_texto := replace(v_texto, '{VALOR_PARCELA}',
    CASE WHEN v_valor_parc IS NULL THEN '' ELSE 'R$ ' || replace(to_char(round(v_valor_parc, 2), 'FM999999990.00'), '.', ',') END);
  v_texto := replace(v_texto, '{TOTAL_PARCELADO}',
    CASE WHEN v_total_parc = 0 THEN '' ELSE 'R$ ' || replace(to_char(round(v_total_parc, 2), 'FM999999990.00'), '.', ',') END);

  v_texto := replace(v_texto, '{ITENS_CONTRATADOS}', '');
  v_texto := replace(v_texto, '{CLAUSULAS_POR_PRODUTO}', '');

  v_texto := replace(v_texto, '[NOME_COMPLETO]', '{{nome_completo}}');
  v_texto := replace(v_texto, '[NOME]',          '{{nome_completo}}');
  v_texto := replace(v_texto, '[CPF]',           '{{cpf}}');
  v_texto := replace(v_texto, '[TELEFONE]',      '{{telefone}}');
  v_texto := replace(v_texto, '[EMAIL]',         '{{email}}');
  FOR v_tok IN
    SELECT DISTINCT (regexp_matches(v_texto, '\[([A-Z0-9_]+)\]', 'g'))[1]
  LOOP
    v_texto := replace(v_texto, '[' || v_tok || ']', '{{' || lower(v_tok) || '}}');
  END LOOP;

  IF v_cond_full IS NOT NULL THEN
    v_inerte := '{{COND_PAG_INI}}{{VAR_AVISTA}}' || COALESCE(v_var_avista, '')
                || '{{/VAR_AVISTA}}{{VAR_PARCELADO}}' || COALESCE(v_var_parc, '')
                || '{{/VAR_PARCELADO}}{{COND_PAG_FIM}}';
    v_inerte := replace(v_inerte, '{TOTAL_AVISTA}',
      'R$ ' || replace(to_char(round(v_total, 2), 'FM999999990.00'), '.', ','));
    v_texto := replace(v_texto, '@@COND_PAGAMENTO_INERTE@@', v_inerte);
  END IF;

  -- Leque de parcelas: teto mínimo 5 (regra 2026-08-10 — nunca uma forma só)
  v_planos_junto := NULL;
  IF v_total > 0 THEN
    v_planos_junto := public.calcular_plano_pagamento(
      public.contrato_manual_item_sintetico(v_tpl.nome, v_total, v_entrada, v_parcelas, v_valor_parc)
    );
  END IF;

  v_dados_pag := jsonb_build_object(
    'total_avista',  v_total,
    'max_parcelas',  GREATEST(COALESCE(v_parcelas, 5), 5),
    'entrada',       v_entrada,
    'valor_parcela', v_valor_parc,
    'parcelas',      v_parcelas,
    'pagamento',     COALESCE(v_tpl.pagamento, '{}'::jsonb),
    'por_produto',   '[]'::jsonb
  );
  IF v_planos_junto IS NOT NULL THEN
    v_dados_pag := v_dados_pag || jsonb_build_object(
      'planos', jsonb_build_object('junto', v_planos_junto, 'separado', '[]'::jsonb)
    );
  END IF;

  INSERT INTO public.contratos (
    tenant_id, lead_id, agente_id, conversa_id, nome_template,
    titulo, texto_contrato, origem, status, dados_cliente,
    chave_pix, link_parcelamento, posicao_pagamento,
    num_testemunhas, instrucao_selfie, campos_obrigatorios,
    logo_url, nome_empresa, descricao_empresa, cor_pagina,
    dados_pagamento, chave_publica
  ) VALUES (
    v_tenant_id, NULL, v_agente_id, NULL, v_tpl.nome,
    COALESCE(NULLIF(v_tpl.nome, ''), 'Contrato'), v_texto,
    'manual_template', 'pendente', '{}'::jsonb,
    v_tpl.chave_pix, v_tpl.link_parcelamento, v_tpl.posicao_pagamento,
    COALESCE(v_tpl.num_testemunhas, 0), v_tpl.instrucao_selfie,
    to_jsonb(COALESCE(v_tpl.campos_obrigatorios, ARRAY[]::text[])),
    v_cfg.logo_url, v_cfg.nome_empresa, v_cfg.descricao_empresa, v_cfg.cor_pagina,
    v_dados_pag, v_chave
  )
  RETURNING id INTO v_id;

  RETURN QUERY SELECT v_id, v_chave;
END;
$_$;


ALTER FUNCTION public.criar_contrato_livre_de_template(p_template_id uuid, p_tenant_id uuid) OWNER TO postgres;

--
-- Name: criar_evento_agenda(text, timestamp with time zone, text, timestamp with time zone, text, boolean, text, jsonb, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.criar_evento_agenda(p_titulo text, p_inicio_em timestamp with time zone, p_tipo text DEFAULT 'outro'::text, p_fim_em timestamp with time zone DEFAULT NULL::timestamp with time zone, p_descricao text DEFAULT NULL::text, p_dia_inteiro boolean DEFAULT false, p_cor text DEFAULT 'azul'::text, p_convidados jsonb DEFAULT '[]'::jsonb, p_criar_sala boolean DEFAULT false) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid uuid := (select auth.uid());
  v_tenant uuid;
  v_id uuid;
  v_sala_id uuid := null;
  v_teto integer;
  v_max integer;
  v_dur integer;
  v_convidados jsonb := coalesce(p_convidados, '[]'::jsonb);
begin
  if v_uid is null then
    raise exception 'nao_autenticado';
  end if;
  if p_inicio_em is null then
    raise exception 'inicio_obrigatorio';
  end if;
  if coalesce(nullif(btrim(p_titulo), ''), '') = '' then
    raise exception 'titulo_obrigatorio';
  end if;
  if p_tipo not in ('reuniao','tarefa','lembrete','outro','compromisso') then
    raise exception 'tipo_invalido';
  end if;
  if jsonb_typeof(v_convidados) <> 'array' then
    raise exception 'convidados_invalido';
  end if;

  select coalesce(p.parent_user_id, p.id) into v_tenant
    from public.profiles p where p.id = v_uid;
  if v_tenant is null then
    v_tenant := v_uid;
  end if;

  -- Sala do app Reunião só quando explicitamente pedida e o evento é reunião.
  if coalesce(p_criar_sala, false) and p_tipo = 'reuniao' then
    select coalesce(reuniao_limite_participantes, 6) into v_teto from public.config_plataforma limit 1;
    if v_teto is null then v_teto := 6; end if;
    v_max := least(greatest(6, 2), v_teto);
    v_dur := coalesce(
      nullif(floor(extract(epoch from (p_fim_em - p_inicio_em)) / 60)::int, 0),
      60
    );
    if v_dur < 1 then v_dur := 60; end if;
    insert into public.salas_reuniao (tenant_id, criada_por, titulo, status, max_participantes, agendada_para, duracao_min)
      values (v_tenant, v_uid, btrim(p_titulo), 'agendada', v_max, p_inicio_em, v_dur)
      returning id into v_sala_id;
  end if;

  insert into public.eventos_agenda (tenant_id, criado_por, titulo, descricao, tipo, inicio_em, fim_em, dia_inteiro, cor, sala_reuniao_id, convidados)
    values (v_tenant, v_uid, btrim(p_titulo), p_descricao, p_tipo, p_inicio_em, p_fim_em,
            coalesce(p_dia_inteiro, false), coalesce(nullif(btrim(p_cor),''),'azul'), v_sala_id, v_convidados)
    returning id into v_id;

  return v_id;
end;
$$;


ALTER FUNCTION public.criar_evento_agenda(p_titulo text, p_inicio_em timestamp with time zone, p_tipo text, p_fim_em timestamp with time zone, p_descricao text, p_dia_inteiro boolean, p_cor text, p_convidados jsonb, p_criar_sala boolean) OWNER TO postgres;

--
-- Name: criar_pedido_loja(text, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.criar_pedido_loja(p_tipo text, p_item_id uuid, p_comprovante_url text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_uid uuid := (select auth.uid());
  v_nome text;
  v_preco numeric;
  v_pedido uuid;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'nao_autorizado';
  END IF;

  IF p_tipo = 'plano' THEN
    SELECT nome, preco_mensal INTO v_nome, v_preco
      FROM public.loja_planos WHERE id = p_item_id AND is_active = true;
  ELSIF p_tipo = 'pacote_extra' THEN
    SELECT nome, preco INTO v_nome, v_preco
      FROM public.loja_pacotes_extra WHERE id = p_item_id AND is_active = true;
  ELSIF p_tipo = 'plus' THEN
    SELECT nome, preco INTO v_nome, v_preco
      FROM public.loja_plus WHERE id = p_item_id AND is_active = true;
  ELSIF p_tipo = 'implantacao' THEN
    SELECT nome, preco INTO v_nome, v_preco
      FROM public.loja_implantacao WHERE id = p_item_id AND is_active = true;
  ELSE
    RAISE EXCEPTION 'tipo_invalido';
  END IF;

  IF v_preco IS NULL THEN
    RAISE EXCEPTION 'item_indisponivel';
  END IF;

  INSERT INTO public.pedidos_compra
    (user_id, tipo, item_id, item_nome, item_preco, comprovante_url, status)
  VALUES
    (v_uid, p_tipo, p_item_id, v_nome, v_preco, p_comprovante_url, 'pendente')
  RETURNING id INTO v_pedido;

  RETURN v_pedido;
END;
$$;


