--
-- Name: criar_sala_agora(text, integer, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.criar_sala_agora(p_titulo text, p_max integer DEFAULT 6, p_exige_aprovacao boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid uuid := (select auth.uid());
  v_tenant uuid;
  v_sala_id uuid;
  v_chave uuid;
  v_titulo text;
  v_teto integer;
  v_max integer;
begin
  if v_uid is null then
    raise exception 'nao_autenticado';
  end if;

  select coalesce(p.parent_user_id, p.id) into v_tenant
    from public.profiles p where p.id = v_uid;
  if v_tenant is null then
    v_tenant := v_uid;
  end if;

  select coalesce(reuniao_limite_participantes, 6) into v_teto from public.config_plataforma limit 1;
  if v_teto is null then v_teto := 6; end if;
  v_max := least(greatest(coalesce(p_max, 6), 2), v_teto);

  v_titulo := coalesce(nullif(btrim(p_titulo), ''), 'Reunião');

  insert into public.salas_reuniao (tenant_id, criada_por, titulo, status, max_participantes, iniciada_em, exige_aprovacao)
    values (v_tenant, v_uid, v_titulo, 'ao_vivo', v_max, now(), coalesce(p_exige_aprovacao, false))
    returning id, chave_publica into v_sala_id, v_chave;

  insert into public.salas_reuniao_participantes (sala_id, user_id, papel)
    values (v_sala_id, v_uid, 'anfitriao');

  return jsonb_build_object(
    'sala_id', v_sala_id,
    'chave_publica', v_chave,
    'titulo', v_titulo,
    'max_participantes', v_max,
    'exige_aprovacao', coalesce(p_exige_aprovacao, false)
  );
end;
$$;


ALTER FUNCTION public.criar_sala_agora(p_titulo text, p_max integer, p_exige_aprovacao boolean) OWNER TO postgres;

--
-- Name: criar_template_a_partir_de_texto(text, text, jsonb, uuid, integer, text, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.criar_template_a_partir_de_texto(p_nome text, p_texto text, p_placeholders jsonb DEFAULT '[]'::jsonb, p_produto_id uuid DEFAULT NULL::uuid, p_num_testemunhas integer DEFAULT 1, p_instrucao_selfie text DEFAULT NULL::text, p_ativar boolean DEFAULT false) RETURNS TABLE(id uuid, chunks_rag_gerados integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_user_id    uuid;
  v_id         uuid;
  v_rag_total  integer := 0;
BEGIN
  IF p_nome IS NULL OR btrim(p_nome) = '' THEN
    RAISE EXCEPTION 'nome do template obrigatorio' USING ERRCODE = '22023';
  END IF;
  IF p_texto IS NULL OR btrim(p_texto) = '' THEN
    RAISE EXCEPTION 'texto do template obrigatorio' USING ERRCODE = '22023';
  END IF;

  v_user_id := (SELECT auth.uid());
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'autenticacao obrigatoria' USING ERRCODE = '42501';
  END IF;

  INSERT INTO public.contratos_template (
    user_id, produto_id, nome, conteudo, placeholders,
    num_testemunhas, instrucao_selfie, ativo
  ) VALUES (
    v_user_id, p_produto_id, p_nome, p_texto, p_placeholders,
    p_num_testemunhas, p_instrucao_selfie, p_ativar
  )
  RETURNING public.contratos_template.id INTO v_id;

  IF p_ativar THEN
    BEGIN
      SELECT chunks_total INTO v_rag_total
      FROM public.sincronizar_template_contrato_para_rag(v_id);
    EXCEPTION WHEN OTHERS THEN
      v_rag_total := 0;
    END;
  END IF;

  RETURN QUERY SELECT v_id, v_rag_total;
END;
$$;


ALTER FUNCTION public.criar_template_a_partir_de_texto(p_nome text, p_texto text, p_placeholders jsonb, p_produto_id uuid, p_num_testemunhas integer, p_instrucao_selfie text, p_ativar boolean) OWNER TO postgres;

--
-- Name: FUNCTION criar_template_a_partir_de_texto(p_nome text, p_texto text, p_placeholders jsonb, p_produto_id uuid, p_num_testemunhas integer, p_instrucao_selfie text, p_ativar boolean); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.criar_template_a_partir_de_texto(p_nome text, p_texto text, p_placeholders jsonb, p_produto_id uuid, p_num_testemunhas integer, p_instrucao_selfie text, p_ativar boolean) IS 'Cria template de contrato a partir de texto bruto + placeholders detectados (agente mestre Onda 3). Se p_ativar=true, dispara atomizacao RAG automatica.';


--
-- Name: cronjob_delete_config(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.cronjob_delete_config(p_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_jobid int;
BEGIN
  IF NOT public._eh_platform_admin() THEN
    RAISE EXCEPTION 'Apenas platform_admin pode gerenciar cronjobs';
  END IF;

  SELECT jobid_pg_cron INTO v_jobid FROM public.agendamentos_config WHERE id = p_id;
  IF NOT FOUND THEN
    RETURN false;
  END IF;

  IF v_jobid IS NOT NULL THEN
    BEGIN
      PERFORM cron.unschedule(v_jobid);
    EXCEPTION WHEN OTHERS THEN
      NULL;
    END;
  END IF;

  DELETE FROM public.agendamentos_config WHERE id = p_id;
  RETURN true;
END;
$$;


ALTER FUNCTION public.cronjob_delete_config(p_id uuid) OWNER TO postgres;

--
-- Name: cronjob_run_now(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.cronjob_run_now(p_cronjob_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'vault', 'extensions'
    AS $$
DECLARE
  v_config record;
  v_log_id uuid;
  v_request_id bigint;
BEGIN
  SELECT * INTO v_config FROM public.agendamentos_config WHERE id = p_cronjob_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'erro', 'cronjob nao encontrado');
  END IF;

  -- Inserir log com resultado='disparado_manualmente'
  INSERT INTO public.agendamentos_log (cronjob_id, cronjob_nome, iniciou_em, resultado)
  VALUES (v_config.id, v_config.nome, now(), 'disparado_manualmente')
  RETURNING id INTO v_log_id;

  IF v_config.edge_function IS NOT NULL THEN
    -- Disparar via http_post
    SELECT net.http_post(
      url := 'https://pdamarjxcmkzbhqxtapl.supabase.co/functions/v1/' || v_config.edge_function,
      headers := jsonb_build_object(
        'Content-Type', 'application/json',
        'Authorization', 'Bearer ' || (SELECT decrypted_secret FROM vault.decrypted_secrets WHERE name = 'service_role_key' LIMIT 1)
      ),
      body := coalesce(v_config.parametros, '{}'::jsonb)
    ) INTO v_request_id;

    UPDATE public.agendamentos_log
    SET payload_input = coalesce(v_config.parametros, '{}'::jsonb)
    WHERE id = v_log_id;

    RETURN jsonb_build_object('ok', true, 'request_id', v_request_id, 'log_id', v_log_id);

  ELSIF v_config.sql_inline IS NOT NULL THEN
    EXECUTE v_config.sql_inline;
    UPDATE public.agendamentos_log
    SET resultado = 'sucesso',
        terminou_em = now(),
        duracao_ms = EXTRACT(MILLISECONDS FROM (now() - iniciou_em))::int
    WHERE id = v_log_id;
    RETURN jsonb_build_object('ok', true, 'log_id', v_log_id);

  ELSE
    UPDATE public.agendamentos_log
    SET resultado = 'erro',
        erro_mensagem = 'sem edge_function nem sql_inline'
    WHERE id = v_log_id;
    RETURN jsonb_build_object('ok', false, 'erro', 'cronjob sem ação configurada');
  END IF;
END;
$$;


ALTER FUNCTION public.cronjob_run_now(p_cronjob_id uuid) OWNER TO postgres;

--
-- Name: cronjob_save_config(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.cronjob_save_config(p_id uuid, p_payload jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_id uuid := p_id;
  v_nome text := p_payload->>'nome';
  v_descricao text := p_payload->>'descricao';
  v_categoria text := coalesce(p_payload->>'categoria', 'custom');
  v_modo text := coalesce(p_payload->>'modo', 'horario');
  v_cron_expr text := p_payload->>'cron_expr';
  v_edge_function text := p_payload->>'edge_function';
  v_sql_inline text := p_payload->>'sql_inline';
  v_parametros jsonb := coalesce(p_payload->'parametros', '{}'::jsonb);
  v_ativo boolean := coalesce((p_payload->>'ativo')::boolean, true);
  v_motivo text := p_payload->>'motivo_criacao';
  v_jobid_anterior int;
  v_jobid_novo int;
  v_command text;
BEGIN
  IF NOT public._eh_platform_admin() THEN
    RAISE EXCEPTION 'Apenas platform_admin pode gerenciar cronjobs';
  END IF;

  IF v_nome IS NULL OR length(trim(v_nome)) = 0 THEN
    RAISE EXCEPTION 'nome eh obrigatorio';
  END IF;

  IF v_id IS NULL THEN
    INSERT INTO public.agendamentos_config
      (nome, descricao, categoria, modo, cron_expr, edge_function, sql_inline, parametros, ativo, motivo_criacao, criado_por)
    VALUES
      (v_nome, v_descricao, v_categoria, v_modo, v_cron_expr, v_edge_function, v_sql_inline, v_parametros, v_ativo, v_motivo, (select auth.uid()))
    RETURNING id INTO v_id;
  ELSE
    SELECT jobid_pg_cron INTO v_jobid_anterior FROM public.agendamentos_config WHERE id = v_id;

    UPDATE public.agendamentos_config
       SET nome = v_nome,
           descricao = v_descricao,
           categoria = v_categoria,
           modo = v_modo,
           cron_expr = v_cron_expr,
           edge_function = v_edge_function,
           sql_inline = v_sql_inline,
           parametros = v_parametros,
           ativo = v_ativo,
           motivo_criacao = coalesce(v_motivo, motivo_criacao),
           atualizado_em = now()
     WHERE id = v_id;

    IF v_jobid_anterior IS NOT NULL THEN
      BEGIN
        PERFORM cron.unschedule(v_jobid_anterior);
      EXCEPTION WHEN OTHERS THEN
        NULL;
      END;
      UPDATE public.agendamentos_config SET jobid_pg_cron = NULL WHERE id = v_id;
    END IF;
  END IF;

  -- Sincroniza pg_cron: agenda quando ativo + cron_expr + (edge_function OU sql_inline)
  IF v_ativo AND v_cron_expr IS NOT NULL AND (v_edge_function IS NOT NULL OR v_sql_inline IS NOT NULL) THEN
    IF v_edge_function IS NOT NULL THEN
      v_command := public._cronjob_montar_command(v_edge_function, v_parametros);
    ELSE
      v_command := v_sql_inline;
    END IF;

    BEGIN
      v_jobid_novo := cron.schedule(v_nome, v_cron_expr, v_command);
      UPDATE public.agendamentos_config SET jobid_pg_cron = v_jobid_novo WHERE id = v_id;
    EXCEPTION WHEN OTHERS THEN
      RAISE NOTICE 'Falha ao agendar cron %: %', v_nome, SQLERRM;
    END;
  END IF;

  RETURN v_id;
END;
$$;


ALTER FUNCTION public.cronjob_save_config(p_id uuid, p_payload jsonb) OWNER TO postgres;

--
-- Name: cronjob_toggle_ativo(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.cronjob_toggle_ativo(p_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_atual record;
  v_novo_ativo boolean;
  v_jobid_novo int;
  v_command text;
BEGIN
  IF NOT public._eh_platform_admin() THEN
    RAISE EXCEPTION 'Apenas platform_admin pode gerenciar cronjobs';
  END IF;

  SELECT * INTO v_atual FROM public.agendamentos_config WHERE id = p_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Cronjob % não encontrado', p_id;
  END IF;

  v_novo_ativo := NOT v_atual.ativo;

  -- Sincroniza pg_cron
  IF v_novo_ativo THEN
    -- Agendar
    IF v_atual.cron_expr IS NOT NULL AND v_atual.edge_function IS NOT NULL THEN
      v_command := public._cronjob_montar_command(v_atual.edge_function, coalesce(v_atual.parametros, '{}'::jsonb));
      BEGIN
        v_jobid_novo := cron.schedule(v_atual.nome, v_atual.cron_expr, v_command);
      EXCEPTION WHEN OTHERS THEN
        RAISE NOTICE 'Falha ao agendar %: %', v_atual.nome, SQLERRM;
        v_jobid_novo := NULL;
      END;
    END IF;
  ELSE
    -- Desagendar
    IF v_atual.jobid_pg_cron IS NOT NULL THEN
      BEGIN
        PERFORM cron.unschedule(v_atual.jobid_pg_cron);
      EXCEPTION WHEN OTHERS THEN
        NULL;
      END;
    END IF;
    v_jobid_novo := NULL;
  END IF;

  UPDATE public.agendamentos_config
     SET ativo = v_novo_ativo,
         jobid_pg_cron = v_jobid_novo,
         atualizado_em = now()
   WHERE id = p_id;

  RETURN v_novo_ativo;
END;
$$;


ALTER FUNCTION public.cronjob_toggle_ativo(p_id uuid) OWNER TO postgres;

--
-- Name: cronjobs_saude(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.cronjobs_saude(p_dias integer DEFAULT 7) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_resultado jsonb;
BEGIN
  PERFORM set_config('search_path', 'public', true);
  PERFORM set_config('statement_timeout', '5s', true);

  SELECT coalesce(jsonb_agg(t ORDER BY t.execucoes DESC), '[]'::jsonb)
  INTO v_resultado
  FROM (
    SELECT cronjob_nome,
           COUNT(*) AS execucoes,
           COUNT(*) FILTER (WHERE resultado='sucesso') AS sucessos,
           COUNT(*) FILTER (WHERE resultado='erro') AS erros,
           MAX(iniciou_em) AS ultima
    FROM public.agendamentos_log
    WHERE iniciou_em > now() - (p_dias || ' days')::interval
    GROUP BY cronjob_nome
  ) t;

  RETURN v_resultado;
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('erro', SQLERRM);
END $$;


ALTER FUNCTION public.cronjobs_saude(p_dias integer) OWNER TO postgres;

