--
-- Name: debitar_carteira_consulta(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.debitar_carteira_consulta(p_consulta_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_tenant uuid;
  v_custo numeric(10,2);
  v_saldo numeric(10,2);
BEGIN
  SELECT c.tenant_id, COALESCE(c.custo, t.custo)
    INTO v_tenant, v_custo
  FROM public.consultas c
  LEFT JOIN public.consultas_tipos t ON t.id = c.tipo_id
  WHERE c.id = p_consulta_id;

  IF v_tenant IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'erro', 'consulta_nao_encontrada');
  END IF;
  IF v_custo IS NULL OR v_custo <= 0 THEN
    RETURN jsonb_build_object('ok', false, 'erro', 'custo_invalido');
  END IF;

  IF EXISTS (SELECT 1 FROM public.consultas_carteira_mov
             WHERE consulta_id = p_consulta_id AND tipo = 'debito') THEN
    RETURN jsonb_build_object('ok', true, 'erro', 'ja_debitado');
  END IF;

  INSERT INTO public.consultas_saldo (tenant_id) VALUES (v_tenant)
    ON CONFLICT (tenant_id) DO NOTHING;

  SELECT saldo INTO v_saldo FROM public.consultas_saldo
    WHERE tenant_id = v_tenant FOR UPDATE;

  IF v_saldo < v_custo THEN
    RETURN jsonb_build_object('ok', false, 'erro', 'saldo_insuficiente',
                              'saldo', v_saldo, 'custo', v_custo);
  END IF;

  UPDATE public.consultas_saldo
    SET saldo = saldo - v_custo, atualizado_em = now()
    WHERE tenant_id = v_tenant;

  UPDATE public.consultas SET custo = v_custo
    WHERE id = p_consulta_id AND custo IS NULL;

  INSERT INTO public.consultas_carteira_mov (tenant_id, tipo, valor, saldo_apos, consulta_id)
    VALUES (v_tenant, 'debito', v_custo, v_saldo - v_custo, p_consulta_id);

  RETURN jsonb_build_object('ok', true, 'saldo_apos', v_saldo - v_custo);
END;
$$;


ALTER FUNCTION public.debitar_carteira_consulta(p_consulta_id uuid) OWNER TO postgres;

--
-- Name: decay_episodios(numeric, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.decay_episodios(p_decay_per_day numeric DEFAULT 0.02, p_threshold_desativar numeric DEFAULT 0.05) RETURNS TABLE(episodios_decaidos integer, episodios_desativados integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_decaidos int := 0;
  v_desativados int := 0;
BEGIN
  WITH atualizados AS (
    UPDATE public.memoria_episodica em
       SET decay_factor = GREATEST(
             0.0,
             em.decay_factor - (EXTRACT(EPOCH FROM (now() - em.atualizado_em)) / 86400.0 * p_decay_per_day)
           ),
           atualizado_em = now()
     WHERE em.ativa = true
       AND em.decay_factor > 0
    RETURNING em.id, em.decay_factor
  ),
  desativados AS (
    UPDATE public.memoria_episodica em
       SET ativa = false,
           atualizado_em = now()
      FROM atualizados a
     WHERE em.id = a.id
       AND a.decay_factor <= p_threshold_desativar
    RETURNING em.id
  )
  SELECT
    (SELECT count(*) FROM atualizados),
    (SELECT count(*) FROM desativados)
  INTO v_decaidos, v_desativados;

  RETURN QUERY SELECT v_decaidos, v_desativados;
END;
$$;


ALTER FUNCTION public.decay_episodios(p_decay_per_day numeric, p_threshold_desativar numeric) OWNER TO postgres;

--
-- Name: FUNCTION decay_episodios(p_decay_per_day numeric, p_threshold_desativar numeric); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.decay_episodios(p_decay_per_day numeric, p_threshold_desativar numeric) IS 'Sprint C: aplica decay aos episodic_memory (decay_factor cai com tempo, episódio desativa quando <= threshold). Chamada pelo cron decay-episodios.';


