--
-- Name: definir_buffer_compondo(text, uuid, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.definir_buffer_compondo(p_phone text, p_agent_id uuid, p_composing boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF p_composing THEN
    UPDATE public.buffer_mensagens SET is_composing = true WHERE phone = p_phone AND agente_id = p_agent_id AND processed = false;
  ELSE
    UPDATE public.buffer_mensagens SET is_composing = false, last_activity_at = now() WHERE phone = p_phone AND agente_id = p_agent_id AND processed = false;
  END IF;
  RETURN jsonb_build_object('updated', FOUND);
END;
$$;


ALTER FUNCTION public.definir_buffer_compondo(p_phone text, p_agent_id uuid, p_composing boolean) OWNER TO postgres;

--
-- Name: definir_campo_customizado(uuid, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.definir_campo_customizado(p_lead_id uuid, p_chave text, p_valor text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF NOT public._lead_pertence_caller(p_lead_id) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;
  IF p_chave IS NULL OR length(trim(p_chave)) = 0 THEN
    RAISE EXCEPTION 'chave_invalida';
  END IF;

  UPDATE public.leads
     SET custom_fields = COALESCE(custom_fields, '{}'::jsonb) || jsonb_build_object(p_chave, p_valor),
         updated_at = now()
   WHERE id = p_lead_id;
END;
$$;


ALTER FUNCTION public.definir_campo_customizado(p_lead_id uuid, p_chave text, p_valor text) OWNER TO postgres;

--
-- Name: definir_contrato_pdf_url_publico(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.definir_contrato_pdf_url_publico(p_token uuid, p_pdf_url text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_contract_id uuid; v_status text;
BEGIN
  IF p_token IS NULL OR p_pdf_url IS NULL OR btrim(p_pdf_url) = '' THEN RAISE EXCEPTION 'token e pdf_url obrigatorios' USING ERRCODE = '22023'; END IF;
  SELECT id, status INTO v_contract_id, v_status FROM public.contratos WHERE chave_publica = p_token LIMIT 1;
  IF v_contract_id IS NULL THEN RAISE EXCEPTION 'contrato nao encontrado' USING ERRCODE = 'P0002'; END IF;
  IF v_status NOT IN ('awaiting_validation', 'signed', 'aguardando_validacao', 'assinado') THEN RAISE EXCEPTION 'status invalido para pdf_url' USING ERRCODE = '42501'; END IF;
  PERFORM public.verificar_limite_taxa_publico(p_token::text, 'set_contract_pdf_url_public', 3);
  UPDATE public.contratos SET pdf_url = p_pdf_url WHERE id = v_contract_id;
END;
$$;


ALTER FUNCTION public.definir_contrato_pdf_url_publico(p_token uuid, p_pdf_url text) OWNER TO postgres;

