--
-- Name: definir_segredo_consulta(text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.definir_segredo_consulta(p_nome text, p_valor text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_id uuid;
BEGIN
  IF NOT public.eh_admin_plataforma() THEN
    RETURN jsonb_build_object('ok', false, 'erro', 'nao_autorizado');
  END IF;
  IF p_nome IS NULL OR length(trim(p_nome)) = 0 THEN
    RETURN jsonb_build_object('ok', false, 'erro', 'nome_vazio');
  END IF;

  SELECT id INTO v_id FROM vault.secrets WHERE name = p_nome;
  IF v_id IS NULL THEN
    PERFORM vault.create_secret(p_valor, p_nome, 'Credencial API de consulta');
  ELSE
    PERFORM vault.update_secret(v_id, p_valor);
  END IF;

  RETURN jsonb_build_object('ok', true);
END;
$$;


ALTER FUNCTION public.definir_segredo_consulta(p_nome text, p_valor text) OWNER TO postgres;

--
-- Name: definir_tag_curadoria_intervalo(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.definir_tag_curadoria_intervalo(p_horas integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_cron_expr text;
BEGIN
  IF p_horas < 1 OR p_horas > 24 THEN
    RAISE EXCEPTION 'intervalo deve ser entre 1 e 24 horas';
  END IF;

  -- Verifica se é admin
  IF NOT EXISTS (
    SELECT 1 FROM public.profiles p
    WHERE p.id = (select auth.uid()) AND p.system_role = 'platform_admin'
  ) THEN
    RAISE EXCEPTION 'apenas platform_admin pode alterar';
  END IF;

  UPDATE public.config_curadoria_tag
  SET intervalo_horas = p_horas, updated_at = now()
  WHERE id = 1;

  -- Reagenda o cron job (formato: '0 */N * * *' a cada N horas)
  v_cron_expr := format('0 */%s * * *', p_horas);

  PERFORM cron.alter_job(
    job_id := (SELECT jobid FROM cron.job WHERE jobname = 'tag_curadoria_run'),
    schedule := v_cron_expr
  );
END;
$$;


ALTER FUNCTION public.definir_tag_curadoria_intervalo(p_horas integer) OWNER TO postgres;

--
-- Name: derivar_tags_para_lead(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.derivar_tags_para_lead(p_lead_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
DECLARE
  v_dados jsonb;
  v_tags_atual text[];
  v_tags_derivadas text[] := '{}';
  v_tags_outras text[];
  v_data_nasc date;
  v_meses_pt text[] := ARRAY[
    'janeiro','fevereiro','marco','abril','maio','junho',
    'julho','agosto','setembro','outubro','novembro','dezembro'
  ];
  v_idade integer;
  v_estado text;
  v_cidade text;
  v_email text;
  v_dominio text;
  v_telefone text;
  v_ddd text;
  v_renda numeric;
  v_score integer;
  v_qtd_filhos integer;
  v_divida_total numeric;
  v_qtd_dividas integer;
  v_inst text;
BEGIN
  SELECT dados_ficha, COALESCE(tags, '{}')
    INTO v_dados, v_tags_atual
  FROM public.leads
  WHERE id = p_lead_id;

  IF v_dados IS NULL THEN
    RETURN 0;
  END IF;

  IF v_dados ? 'data_nascimento' AND (v_dados->>'data_nascimento') ~ '^\d{4}-\d{2}-\d{2}' THEN
    v_data_nasc := (v_dados->>'data_nascimento')::date;
    v_tags_derivadas := array_append(v_tags_derivadas,
      'aniversariante:' || v_meses_pt[EXTRACT(MONTH FROM v_data_nasc)::int]);
    v_idade := EXTRACT(YEAR FROM age(v_data_nasc))::int;
    v_tags_derivadas := array_append(v_tags_derivadas,
      'faixa_idade:' || CASE
        WHEN v_idade < 25 THEN '18_24'
        WHEN v_idade < 35 THEN '25_34'
        WHEN v_idade < 45 THEN '35_44'
        WHEN v_idade < 55 THEN '45_54'
        WHEN v_idade < 65 THEN '55_64'
        ELSE '65_mais'
      END);
  END IF;

  v_estado := lower(coalesce(v_dados->'endereco'->>'estado', ''));
  IF v_estado <> '' THEN
    v_tags_derivadas := array_append(v_tags_derivadas, 'estado:' || regexp_replace(v_estado, '[^a-z0-9]+', '_', 'g'));
  END IF;
  v_cidade := lower(coalesce(v_dados->'endereco'->>'cidade', ''));
  IF v_cidade <> '' THEN
    v_tags_derivadas := array_append(v_tags_derivadas, 'cidade:' || regexp_replace(v_cidade, '[^a-z0-9]+', '_', 'g'));
  END IF;

  v_email := lower(coalesce(v_dados->>'email', ''));
  IF v_email <> '' AND position('@' in v_email) > 0 THEN
    v_dominio := split_part(v_email, '@', 2);
    v_dominio := regexp_replace(v_dominio, '\..*$', '', 'g');
    IF v_dominio <> '' THEN
      v_tags_derivadas := array_append(v_tags_derivadas, 'email_provider:' || v_dominio);
    END IF;
  END IF;

  v_telefone := regexp_replace(coalesce(v_dados->>'telefone', ''), '[^0-9]', '', 'g');
  IF length(v_telefone) >= 12 THEN
    v_ddd := substring(v_telefone, 3, 2);
    v_tags_derivadas := array_append(v_tags_derivadas, 'ddd:' || v_ddd);
  END IF;

  IF v_dados ? 'renda_mensal' THEN
    v_renda := (v_dados->>'renda_mensal')::numeric;
    v_tags_derivadas := array_append(v_tags_derivadas,
      'renda_faixa:' || CASE
        WHEN v_renda < 1500 THEN 'ate_1500'
        WHEN v_renda < 3000 THEN '1500_3000'
        WHEN v_renda < 5000 THEN '3000_5000'
        WHEN v_renda < 10000 THEN '5000_10k'
        WHEN v_renda < 20000 THEN '10k_20k'
        ELSE '20k_mais'
      END);
  END IF;

  IF v_dados ? 'score_credito' THEN
    v_score := (v_dados->>'score_credito')::int;
    v_tags_derivadas := array_append(v_tags_derivadas,
      'score_faixa:' || CASE
        WHEN v_score < 300 THEN 'muito_baixo'
        WHEN v_score < 500 THEN 'baixo'
        WHEN v_score < 700 THEN 'medio'
        WHEN v_score < 850 THEN 'bom'
        ELSE 'otimo'
      END);
  END IF;

  IF v_dados ? 'filhos' AND jsonb_typeof(v_dados->'filhos') = 'array' THEN
    v_qtd_filhos := jsonb_array_length(v_dados->'filhos');
    IF v_qtd_filhos > 0 THEN
      v_tags_derivadas := array_append(v_tags_derivadas, 'tem_filhos:sim');
      v_tags_derivadas := array_append(v_tags_derivadas, 'qtd_filhos:' || v_qtd_filhos::text);
    END IF;
  END IF;

  IF v_dados ? 'dividas' AND jsonb_typeof(v_dados->'dividas') = 'array' THEN
    v_qtd_dividas := jsonb_array_length(v_dados->'dividas');
    IF v_qtd_dividas > 0 THEN
      v_tags_derivadas := array_append(v_tags_derivadas, 'qtd_dividas:' || v_qtd_dividas::text);
      -- FIX: lower ANTES do regex pra preservar letra inicial
      FOR v_inst IN
        SELECT DISTINCT regexp_replace(lower(coalesce(d->>'instituicao', '')), '[^a-z0-9]+', '_', 'g')
        FROM jsonb_array_elements(v_dados->'dividas') d
        WHERE d->>'instituicao' IS NOT NULL AND d->>'instituicao' <> ''
      LOOP
        IF v_inst <> '' THEN
          v_tags_derivadas := array_append(v_tags_derivadas, 'tem_divida:' || v_inst);
        END IF;
      END LOOP;
      SELECT COALESCE(SUM((d->>'valor')::numeric), 0)
        INTO v_divida_total
      FROM jsonb_array_elements(v_dados->'dividas') d
      WHERE d->>'valor' IS NOT NULL;
      IF v_divida_total > 0 THEN
        v_tags_derivadas := array_append(v_tags_derivadas,
          'valor_divida_total:' || CASE
            WHEN v_divida_total < 1000 THEN 'ate_1k'
            WHEN v_divida_total < 5000 THEN '1k_5k'
            WHEN v_divida_total < 10000 THEN '5k_10k'
            WHEN v_divida_total < 50000 THEN '10k_50k'
            ELSE '50k_mais'
          END);
      END IF;
    END IF;
  END IF;

  WITH chaves_derivadas AS (
    SELECT split_part(t, ':', 1) AS k
    FROM unnest(ARRAY[
      'aniversariante','faixa_idade','estado','cidade',
      'email_provider','ddd','renda_faixa','score_faixa',
      'tem_filhos','qtd_filhos','tem_divida','qtd_dividas','valor_divida_total'
    ]) AS t
  )
  SELECT array_agg(t)
    INTO v_tags_outras
  FROM unnest(coalesce(v_tags_atual, '{}')) AS t
  WHERE split_part(t, ':', 1) NOT IN (SELECT k FROM chaves_derivadas);

  UPDATE public.leads
  SET tags = (
    SELECT COALESCE(array_agg(DISTINCT x), '{}')
    FROM unnest(coalesce(v_tags_outras, '{}') || v_tags_derivadas) AS x
  )
  WHERE id = p_lead_id;

  RETURN array_length(v_tags_derivadas, 1);
END;
$_$;


ALTER FUNCTION public.derivar_tags_para_lead(p_lead_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION derivar_tags_para_lead(p_lead_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.derivar_tags_para_lead(p_lead_id uuid) IS 'Gera tags derivadas (aniversariante, faixa_idade, estado, etc) a partir de leads.dados_ficha. Preserva tags existentes não-derivadas. Idempotente.';


--
-- Name: derivar_template_v2(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.derivar_template_v2(p_template_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_tpl public.contratos_template%ROWTYPE;
  v_conteudo_comum text;
  v_campos_cliente jsonb;
  v_produtos_aceitos jsonb;
  v_tem_curadoria boolean;  -- Δ 2026-09-08
  v_pagamento jsonb;
  v_provas jsonb;
  v_jornada text[];
  v_campos_array jsonb;
  v_campo jsonb;
  v_tipo text;
  v_slugs_texto text[];
  v_slugs_obrigatorios text[];
  v_todos_slugs text[];
  v_slug_item text;
  v_campos_obrigatorios_arr text[];
BEGIN
  SELECT * INTO v_tpl FROM public.contratos_template WHERE id = p_template_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Template % não encontrado', p_template_id;
  END IF;

  -- 3a. conteudo_comum: na FASE 1 espelha o legado SEM transformar
  -- (converter {SE_A_VISTA} aqui vazaria delimitadores crus no contrato —
  --  página pública atual só hidrata {{minúsculo}}, Fase 3 ainda não existe).
  v_conteudo_comum := coalesce(v_tpl.conteudo, '');

  -- 3b. campos_cliente: união dos {{slug}} do texto + campos_obrigatorios legado
  v_slugs_texto := ARRAY(
    SELECT DISTINCT lower(m[1])
    FROM regexp_matches(v_conteudo_comum, '\{\{([a-zA-Z_][a-zA-Z0-9_]*)\}\}', 'g') AS m
    WHERE lower(m[1]) NOT IN (
      'cond_pag_ini','var_avista','var_parcelado','/var_avista','/var_parcelado','cond_pag_fim',
      'itens_contratados','clausulas_por_produto','total_avista','assinaturas',
      'numero_parcelas','valor_parcela','total_parcelado',
      'produto_nome','produto_qtd','produto_preco_avista','cond_pagamento'
    )
    ORDER BY 1
  );
  v_campos_obrigatorios_arr := coalesce(v_tpl.campos_obrigatorios, ARRAY[]::text[]);
  v_slugs_obrigatorios := ARRAY(
    SELECT lower(f) FROM unnest(v_campos_obrigatorios_arr) AS f
    WHERE lower(f) NOT IN ('selfie','documento','assinatura_manuscrita','testemunha')
    ORDER BY 1
  );
  v_todos_slugs := ARRAY(
    SELECT DISTINCT slug FROM (
      SELECT unnest(v_slugs_texto) AS slug
      UNION SELECT unnest(v_slugs_obrigatorios) AS slug
    ) t WHERE slug IS NOT NULL AND slug <> '' ORDER BY 1
  );
  v_campos_array := '[]'::jsonb;
  FOREACH v_slug_item IN ARRAY v_todos_slugs LOOP
    IF v_slug_item IN ('cpf','cnpj') THEN v_tipo := v_slug_item;
    ELSIF v_slug_item IN ('email') THEN v_tipo := 'email';
    ELSIF v_slug_item IN ('telefone','celular','fone','whatsapp') THEN v_tipo := 'telefone';
    ELSIF v_slug_item IN ('data','data_nascimento','nascimento') THEN v_tipo := 'data';
    ELSE v_tipo := 'texto';
    END IF;
    v_campo := jsonb_build_object(
      'slug', v_slug_item,
      'rotulo', initcap(replace(v_slug_item, '_', ' ')),
      'tipo', v_tipo,
      'obrigatorio', (v_slug_item = ANY(v_slugs_obrigatorios)),
      'icone', null
    );
    v_campos_array := v_campos_array || jsonb_build_array(v_campo);
  END LOOP;
  v_campos_cliente := v_campos_array;

  -- 3c. produtos_aceitos
  -- Δ 2026-09-08 — esta derivação rodava a cada save que tocasse QUALQUER coluna
  -- legada (inclusive `conteudo`, ou seja: a cada tecla no editor) e reconstruía a
  -- lista do zero — repondo produtos removidos e zerando o parcelamento configurado
  -- pelo dono (entrada:0, max_parcelas:12, total:0). Agora só deriva na PRIMEIRA
  -- CARGA, que era o propósito original; havendo curadoria, preserva.
  v_tem_curadoria := jsonb_typeof(v_tpl.produtos_aceitos) = 'array'
                     AND jsonb_array_length(v_tpl.produtos_aceitos) > 0;

  IF v_tem_curadoria THEN
    v_produtos_aceitos := v_tpl.produtos_aceitos;
  ELSE
    v_produtos_aceitos := (
      SELECT coalesce(jsonb_agg(
        jsonb_build_object(
          'produto_id', p.id,
          'nome', p.nome,
          'preco_avista', coalesce(
            CASE WHEN v_tpl.produto_id = p.id THEN v_tpl.valor_a_vista ELSE NULL END,
            (SELECT ct2.valor_a_vista FROM public.contratos_template ct2
             WHERE ct2.user_id = v_tpl.user_id AND ct2.produto_id = p.id
               AND ct2.ativo = true AND ct2.valor_a_vista IS NOT NULL
             ORDER BY ct2.updated_at DESC LIMIT 1),
            0
          ),
          'parcelamento', jsonb_build_object('entrada', 0, 'max_parcelas', 12, 'total_parcelado', 0),
          'preco_pendente', NOT EXISTS (
            SELECT 1 FROM public.contratos_template ct3
            WHERE ct3.user_id = v_tpl.user_id AND ct3.produto_id = p.id
              AND ct3.ativo = true AND ct3.valor_a_vista IS NOT NULL AND ct3.valor_a_vista > 0
          )
        )
      ), '[]'::jsonb)
      FROM public.produtos p
      WHERE p.user_id = v_tpl.user_id AND p.ativo = true
    );

  END IF;

  -- 3d. pagamento
  v_pagamento := jsonb_build_object(
    'modo', 'unico',
    'chave_pix', v_tpl.chave_pix,
    'link_parcelamento', v_tpl.link_parcelamento,
    'posicao_pagamento', coalesce(v_tpl.posicao_pagamento, 'before_sign')
  );

  -- 3e. provas
  v_provas := jsonb_build_object(
    'selfie', 'selfie' = ANY(v_campos_obrigatorios_arr),
    'documento', 'documento' = ANY(v_campos_obrigatorios_arr),
    'assinatura_manuscrita', 'assinatura_manuscrita' = ANY(v_campos_obrigatorios_arr),
    'testemunha', 'testemunha' = ANY(v_campos_obrigatorios_arr),
    'num_testemunhas', coalesce(v_tpl.num_testemunhas, 1),
    'instrucao_selfie', v_tpl.instrucao_selfie
  );

  -- 3f. jornada_ordem (default; tenant customiza na Fase 2)
  v_jornada := ARRAY['dados','pagamento','contrato','comprovante','selfie','documento','assinatura','testemunha']::text[];

  -- Gravar SÓ as colunas v2 (não toca legadas — garante anti-recursão do trigger)
  UPDATE public.contratos_template SET
    conteudo_comum = v_conteudo_comum,
    campos_cliente = v_campos_cliente,
    produtos_aceitos = v_produtos_aceitos,
    pagamento = v_pagamento,
    provas = v_provas,
    jornada_ordem = v_jornada
  WHERE id = p_template_id;
END;
$$;


ALTER FUNCTION public.derivar_template_v2(p_template_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION derivar_template_v2(p_template_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.derivar_template_v2(p_template_id uuid) IS 'Deriva colunas v2 do template. produtos_aceitos SÓ é derivado na primeira carga (coluna vazia); havendo curadoria do dono, preserva — antes o trigger apagava a cada save os preços configurados na tela. Δ 2026-09-08.';


