--
-- Name: descartar_pergunta_mentor(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.descartar_pergunta_mentor(p_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_tenant   uuid;
  v_uid      uuid := (SELECT auth.uid());
  v_lead     uuid;
  v_conv     uuid;
  v_pergunta text;
  v_status   text;
BEGIN
  SELECT tenant_id, lead_id, conversation_id, pergunta, status_loop
    INTO v_tenant, v_lead, v_conv, v_pergunta, v_status
    FROM public.perguntas_sem_resposta
    WHERE id = p_id;

  IF v_tenant IS NULL OR v_tenant <> v_uid THEN
    RETURN jsonb_build_object('ok', false, 'erro', 'sem permissao');
  END IF;

  -- Idempotente: já descartada não regrava memória (evita duplicar fato na ficha).
  IF v_status = 'descartada' THEN
    RETURN jsonb_build_object('ok', true, 'ja_descartada', true);
  END IF;

  UPDATE public.perguntas_sem_resposta
    SET status_loop  = 'descartada',
        resolvido    = true,
        resolvido_em = now()
    WHERE id = p_id;

  -- Memória na ficha do lead (dossiê). Prefixo legível e detectável pelo motor,
  -- que filtra estes fatos e instrui o Gate B1 a NÃO re-escalar o tema descartado.
  IF v_lead IS NOT NULL THEN
    INSERT INTO public.memoria_lead (
      lead_id, tenant_id, conversation_id, fato,
      categoria, relevancia, fonte, escopo, created_by, confianca
    ) VALUES (
      v_lead, v_tenant, v_conv,
      'Pergunta descartada pelo dono — o contato perguntou: "'
        || left(coalesce(v_pergunta, ''), 300)
        || '". O dono decidiu não responder isso. Se o contato perguntar de novo sobre este assunto, '
        || 'contorne com naturalidade e siga a conversa — não prometa verificar com ninguém nem escale de novo.',
      'historico_negociacao', 'alta', 'manual', 'longo', v_uid, 0.9
    );
  END IF;

  RETURN jsonb_build_object('ok', true);
END;
$$;


ALTER FUNCTION public.descartar_pergunta_mentor(p_id uuid) OWNER TO postgres;

--
-- Name: descer_lead_pra_base(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.descer_lead_pra_base(p_lead_id uuid, p_motivo text DEFAULT 'manual'::text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_caller_id uuid;
  v_tenant_id uuid;
BEGIN
  v_caller_id := (SELECT auth.uid());

  SELECT l.tenant_id INTO v_tenant_id
  FROM public.leads l
  WHERE l.id = p_lead_id
    AND l.deleted_at IS NULL
    AND (
      l.tenant_id = v_caller_id
      OR EXISTS (
        SELECT 1 FROM public.profiles p
        WHERE p.id = v_caller_id AND p.parent_user_id = l.tenant_id
      )
    );

  IF v_tenant_id IS NULL THEN
    RAISE EXCEPTION 'lead não encontrado ou acesso negado';
  END IF;

  UPDATE public.leads
  SET location = 'base', updated_at = now()
  WHERE id = p_lead_id
    AND location != 'base'
    AND deleted_at IS NULL;

  RETURN FOUND;
END;
$$;


ALTER FUNCTION public.descer_lead_pra_base(p_lead_id uuid, p_motivo text) OWNER TO postgres;

--
-- Name: descrever_opcao_pagamento(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.descrever_opcao_pagamento(p_opcao jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $_$
  -- Texto da cláusula de pagamento para uma opção nomeada (produtos.opcoes_pagamento).
  -- Espelhado em frontend/src/pages/public/contrato/helpers.ts (descreverOpcaoNomeada) — manter iguais.
  WITH v AS (
    SELECT
      COALESCE(p_opcao->>'rotulo', 'Opção escolhida') AS rotulo,
      COALESCE((p_opcao->>'total_centavos')::numeric, 0) / 100 AS total,
      COALESCE((p_opcao->>'entrada_centavos')::numeric, 0) / 100 AS entrada,
      GREATEST(1, COALESCE((p_opcao->>'parcelas')::int, 1)) AS parcelas,
      COALESCE((p_opcao->>'valor_parcela_centavos')::numeric, 0) / 100 AS parcela,
      NULLIF(btrim(p_opcao->>'observacao'), '') AS obs
  )
  SELECT
    'Forma de pagamento escolhida: ' || rotulo
    || '. Valor total de R$ ' || replace(to_char(round(total, 2), 'FM999999990.00'), '.', ',')
    || CASE
         WHEN parcelas > 1 AND entrada > 0 THEN
           ', sendo entrada de R$ ' || replace(to_char(round(entrada, 2), 'FM999999990.00'), '.', ',')
           || ' + ' || parcelas || ' parcelas de R$ ' || replace(to_char(round(parcela, 2), 'FM999999990.00'), '.', ',')
         WHEN parcelas > 1 THEN
           ', em ' || parcelas || ' parcelas de R$ ' || replace(to_char(round(parcela, 2), 'FM999999990.00'), '.', ',')
         ELSE ', em pagamento único'
       END
    || '.'
    || COALESCE(' ' || obs, '')
  FROM v;
$_$;


ALTER FUNCTION public.descrever_opcao_pagamento(p_opcao jsonb) OWNER TO postgres;

--
-- Name: FUNCTION descrever_opcao_pagamento(p_opcao jsonb); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.descrever_opcao_pagamento(p_opcao jsonb) IS 'Frase da cláusula de pagamento para uma opção nomeada do produto. Usada por assinar_contrato_publico (modo=opcao). Espelho no front: descreverOpcaoNomeada.';


--
-- Name: desinstalar_kit_pacote(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.desinstalar_kit_pacote(p_pacote_id uuid, p_agente_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_tenant uuid;
begin
  select user_id into v_tenant from public.agentes_usuario where id = p_agente_id;
  if v_tenant is null then return jsonb_build_object('ok', false); end if;
  -- Outro agente do mesmo tenant ainda com o pacote ligado → itens do tenant ficam.
  update public.cargos set ativo = false where agente_id = p_agente_id and pacote_origem_id = p_pacote_id;
  -- Identidade: remove só o que ainda é exatamente o texto do kit (o tom fica: não dá pra saber se era do kit).
  update public.agentes_usuario a
     set identidade = a.identidade - (select coalesce(array_agg(f), '{}'::text[]) from unnest(array['personalidade', 'persona']) f
                                        where a.identidade->>f is not null
                                          and a.identidade->>f = (select k.kit->'identidade'->>f from public.pacotes_conhecimento_kit k where k.pacote_id = p_pacote_id))
   where a.id = p_agente_id;
  if not exists (select 1 from public.pacotes_conhecimento_ativacao a where a.pacote_id = p_pacote_id and a.tenant_id = v_tenant and a.ligado and a.agente_id <> p_agente_id) then
    update public.produtos set ativo = false where user_id = v_tenant and pacote_origem_id = p_pacote_id;
    update public.blocos_gatilho set ativo = false where tenant_id = v_tenant and pacote_origem_id = p_pacote_id;
    update public.anti_padroes set ativo = false where tenant_id = v_tenant and pacote_origem_id = p_pacote_id;
    update public.blocos_humanizacao set ativo = false where tenant_id = v_tenant and pacote_origem_id = p_pacote_id;
    update public.blocos_procedurais set ativo = false where tenant_id = v_tenant and pacote_origem_id = p_pacote_id;
  end if;
  return jsonb_build_object('ok', true);
end;
$$;


ALTER FUNCTION public.desinstalar_kit_pacote(p_pacote_id uuid, p_agente_id uuid) OWNER TO postgres;

--
-- Name: destilar_perfil_empresa(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.destilar_perfil_empresa(p_tenant_id uuid DEFAULT NULL::uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_destilados int := 0;
  v_eh_admin boolean;
  v_uid uuid;
BEGIN
  v_uid := (select auth.uid());

  IF v_uid IS NOT NULL THEN
    SELECT EXISTS (
      SELECT 1 FROM public.user_roles
      WHERE user_id = v_uid AND role IN ('admin','platform_admin')
    ) INTO v_eh_admin;

    IF NOT v_eh_admin THEN
      RAISE EXCEPTION 'apenas admin/platform_admin pode destilar perfil_empresa';
    END IF;
  END IF;

  WITH tenants_alvo AS (
    SELECT DISTINCT l.tenant_id AS tid
    FROM public.leads l
    WHERE l.deleted_at IS NULL
      AND (p_tenant_id IS NULL OR l.tenant_id = p_tenant_id)
  ),
  metricas AS (
    SELECT
      t.tid,
      count(*) FILTER (WHERE l.desfecho = 'convertido') AS convertidos,
      count(*) FILTER (WHERE l.desfecho IN ('convertido','sumido','recusado','desqualificado')) AS fechados,
      count(*) AS total_leads,
      (SELECT n.nome_exibicao FROM public.profiles p
        JOIN public.nichos n ON n.id = p.nicho_id
        WHERE p.id = t.tid LIMIT 1) AS segmento
    FROM tenants_alvo t
    LEFT JOIN public.leads l ON l.tenant_id = t.tid AND l.deleted_at IS NULL
    GROUP BY t.tid
  ),
  upserts AS (
    INSERT INTO public.perfil_empresa AS pe (
      tenant_id, segmento, taxa_conversao_estimada, conversas_destiladas,
      destilacao_ultima_em
    )
    SELECT
      tid,
      segmento,
      CASE WHEN fechados > 0 THEN round(convertidos::numeric / fechados, 4) ELSE NULL END,
      total_leads,
      now()
    FROM metricas
    WHERE tid IS NOT NULL
    ON CONFLICT (tenant_id) DO UPDATE SET
      segmento = excluded.segmento,
      taxa_conversao_estimada = excluded.taxa_conversao_estimada,
      conversas_destiladas = excluded.conversas_destiladas,
      destilacao_ultima_em = now(),
      versao = pe.versao + 1,
      atualizado_em = now()
    RETURNING pe.tenant_id
  )
  SELECT count(*)::int INTO v_destilados FROM upserts;

  RETURN v_destilados;
END;
$$;


ALTER FUNCTION public.destilar_perfil_empresa(p_tenant_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION destilar_perfil_empresa(p_tenant_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.destilar_perfil_empresa(p_tenant_id uuid) IS 'Trilho B3-fase-2 V1 — destila metricas quantitativas em perfil_empresa. Retorna numero de tenants destilados.';


--
-- Name: detectar_comprovantes_lead(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.detectar_comprovantes_lead(p_janela_horas integer DEFAULT 24) RETURNS TABLE(criados integer, atualizados integer, sem_valor integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
  r RECORD;
  v_valor_txt text;
  v_valor numeric;
  v_cobranca_id uuid;
  v_criados int := 0;
  v_atualizados int := 0;
  v_sem_valor int := 0;
BEGIN
  FOR r IN
    SELECT m.id AS msg_id, m.created_at AS msg_em,
           m.carga->>'media_descricao' AS descr, m.carga->>'media_url' AS url,
           cv.lead_id, cv.tenant_id
    FROM public.mensagens m
    JOIN public.conversas cv ON cv.id = m.conversation_id
    WHERE m.role = 'user'
      AND m.deleted_at IS NULL
      AND cv.lead_id IS NOT NULL
      AND m.created_at > now() - (p_janela_horas || ' hours')::interval
      AND coalesce(m.carga->>'media_descricao','') ILIKE '%comprovante%'
      AND NOT EXISTS (
        SELECT 1 FROM public.pagamentos_cliente pc WHERE pc.origem_mensagem_id = m.id
      )
  LOOP
    -- valor no formato brasileiro (R$ 1.234,56) ou simples (R$ 117)
    v_valor_txt := substring(r.descr from 'R\$\s*([0-9][0-9\.]*(?:,[0-9]{2})?)');
    IF v_valor_txt IS NULL THEN
      v_sem_valor := v_sem_valor + 1;
      CONTINUE;
    END IF;
    v_valor := replace(replace(v_valor_txt, '.', ''), ',', '.')::numeric;
    IF v_valor <= 0 OR v_valor > 1000000 THEN
      v_sem_valor := v_sem_valor + 1;
      CONTINUE;
    END IF;

    -- cobrança pendente do mesmo lead com o mesmo valor → anexa o comprovante nela
    SELECT pc.id INTO v_cobranca_id
    FROM public.pagamentos_cliente pc
    WHERE pc.tenant_id = r.tenant_id AND pc.lead_id = r.lead_id
      AND pc.status = 'pendente' AND pc.origem_mensagem_id IS NULL
      AND pc.valor BETWEEN v_valor - 0.01 AND v_valor + 0.01
    ORDER BY pc.created_at DESC LIMIT 1;

    IF v_cobranca_id IS NOT NULL THEN
      UPDATE public.pagamentos_cliente
      SET observacao = coalesce(observacao || ' · ', '')
            || 'comprovante recebido na conversa em '
            || to_char(r.msg_em AT TIME ZONE 'America/Sao_Paulo', 'DD/MM HH24:MI')
            || ' (detector automático — validar e baixar)',
          origem_mensagem_id = r.msg_id
      WHERE id = v_cobranca_id;
      v_atualizados := v_atualizados + 1;
    ELSE
      INSERT INTO public.pagamentos_cliente (
        tenant_id, lead_id, descricao, valor, data_vencimento, status,
        observacao, origem_mensagem_id
      ) VALUES (
        r.tenant_id, r.lead_id,
        'Comprovante de ' || to_char(v_valor, 'FM999G999G990D00') || ' recebido do cliente na conversa — validar e baixar',
        v_valor, (r.msg_em AT TIME ZONE 'America/Sao_Paulo')::date, 'pendente',
        'Detector automático · ' || coalesce('comprovante: ' || r.url, 'sem URL'),
        r.msg_id
      );
      v_criados := v_criados + 1;
    END IF;
    v_cobranca_id := NULL;
  END LOOP;

  RETURN QUERY SELECT v_criados, v_atualizados, v_sem_valor;
END;
$_$;


ALTER FUNCTION public.detectar_comprovantes_lead(p_janela_horas integer) OWNER TO postgres;

--
-- Name: detectar_intent_categoria(extensions.halfvec, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.detectar_intent_categoria(p_query_embedding extensions.halfvec, p_top_k integer DEFAULT 2) RETURNS TABLE(intent text, frase_pivo text, categorias_alvo text[], similaridade numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    p.intent,
    p.frase_pivo,
    p.categorias_alvo,
    (1 - (p.vetor_semantico <=> p_query_embedding))::numeric AS similaridade
  FROM public.pivots_categoria_intent p
  WHERE p.ativo = true
    AND p.vetor_semantico IS NOT NULL
    AND p.embedding_status = 'ready'
  ORDER BY p.vetor_semantico <=> p_query_embedding
  LIMIT p_top_k;
END;
$$;


ALTER FUNCTION public.detectar_intent_categoria(p_query_embedding extensions.halfvec, p_top_k integer) OWNER TO postgres;

--
-- Name: FUNCTION detectar_intent_categoria(p_query_embedding extensions.halfvec, p_top_k integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.detectar_intent_categoria(p_query_embedding extensions.halfvec, p_top_k integer) IS 'D39 fix Luiz. Compara embedding da mensagem do lead com frases-pivô HNSW. Retorna top-k (intent, frase_pivo, categorias_alvo, similaridade). Usado pelo retrieve-router para boost pós-rerank.';


--
-- Name: detectar_leads_duplicados(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.detectar_leads_duplicados(p_tenant_id uuid) RETURNS TABLE(lead_a uuid, lead_b uuid, motivo text, score numeric)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
  SELECT 
    a.id AS lead_a,
    b.id AS lead_b,
    CASE 
      WHEN public.normalizar_telefone(a.phone) = public.normalizar_telefone(b.phone) 
        AND public.normalizar_telefone(a.phone) <> '' THEN 'telefone_identico'
      WHEN extensions.similarity(coalesce(a.name,''), coalesce(b.name,'')) > 0.7 THEN 'nome_similar'
      ELSE 'outros'
    END AS motivo,
    GREATEST(
      CASE WHEN public.normalizar_telefone(a.phone) = public.normalizar_telefone(b.phone) 
              AND public.normalizar_telefone(a.phone) <> '' THEN 1.0 ELSE 0 END,
      extensions.similarity(coalesce(a.name,''), coalesce(b.name,''))::numeric
    )::numeric AS score
  FROM public.leads a
  JOIN public.leads b ON a.id < b.id
  WHERE a.tenant_id = p_tenant_id AND b.tenant_id = p_tenant_id
    AND a.deleted_at IS NULL AND b.deleted_at IS NULL
    AND a.mesclado_em IS NULL AND b.mesclado_em IS NULL
    AND (
      (public.normalizar_telefone(a.phone) = public.normalizar_telefone(b.phone) AND public.normalizar_telefone(a.phone) <> '')
      OR extensions.similarity(coalesce(a.name,''), coalesce(b.name,'')) > 0.7
    )
  ORDER BY score DESC LIMIT 100;
$$;


ALTER FUNCTION public.detectar_leads_duplicados(p_tenant_id uuid) OWNER TO postgres;

--
-- Name: devolver_lead_babel(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.devolver_lead_babel(p_entrega_id uuid, p_motivo text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_lead uuid;
begin
  update public.entregas_lead_babel
     set devolvido_em = now(), devolvido_motivo = coalesce(p_motivo, 'sem motivo')
   where id = p_entrega_id and devolvido_em is null and deleted_at is null
   returning lead_babel_id into v_lead;
  if v_lead is null then
    return jsonb_build_object('ok', false, 'erro', 'entrega_nao_encontrada_ou_ja_devolvida');
  end if;
  update public.leads_babel set status = 'pronto', atualizado_em = now() where id = v_lead;
  return jsonb_build_object('ok', true, 'lead_babel_id', v_lead);
end;
$$;


ALTER FUNCTION public.devolver_lead_babel(p_entrega_id uuid, p_motivo text) OWNER TO postgres;

--
-- Name: dia_util_do_mes(date, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.dia_util_do_mes(p_data_ref date, p_n integer) RETURNS date
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_ref date := COALESCE(p_data_ref, current_date);
  v_data date := date_trunc('month', v_ref)::date;
  v_fim_mes date := (date_trunc('month', v_ref) + interval '1 month - 1 day')::date;
  v_count int := 0;
BEGIN
  IF p_n IS NULL OR p_n <= 0 THEN
    RETURN NULL;
  END IF;
  WHILE v_data <= v_fim_mes LOOP
    IF public.eh_dia_util(v_data) THEN
      v_count := v_count + 1;
      IF v_count = p_n THEN
        RETURN v_data;
      END IF;
    END IF;
    v_data := v_data + 1;
  END LOOP;
  RETURN NULL;
END;
$$;


ALTER FUNCTION public.dia_util_do_mes(p_data_ref date, p_n integer) OWNER TO postgres;

--
-- Name: disparar_vigia_canais_zapi(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.disparar_vigia_canais_zapi(p_canal_id uuid DEFAULT NULL::uuid) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_chave text;
  v_req   bigint;
begin
  select decrypted_secret into v_chave
    from vault.decrypted_secrets
   where name = 'service_role_key'
   limit 1;

  if v_chave is null then
    raise warning 'disparar_vigia_canais_zapi: service_role_key ausente no vault — vigia não disparado';
    return null;
  end if;

  select net.http_post(
    url := 'https://pdamarjxcmkzbhqxtapl.supabase.co/functions/v1/vigia-canais-zapi',
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'Authorization', 'Bearer ' || v_chave
    ),
    body := case
              when p_canal_id is null then '{}'::jsonb
              else jsonb_build_object('canal_id', p_canal_id)
            end,
    timeout_milliseconds := 300000
  ) into v_req;

  return v_req;
end $$;


ALTER FUNCTION public.disparar_vigia_canais_zapi(p_canal_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION disparar_vigia_canais_zapi(p_canal_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.disparar_vigia_canais_zapi(p_canal_id uuid) IS 'Chama a edge vigia-canais-zapi via pg_net. Sem argumento = varredura completa (cron); com canal_id = confere só aquele canal (trigger de canais).';


--
-- Name: editar_resposta_pergunta_mentor(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.editar_resposta_pergunta_mentor(p_id uuid, p_resposta text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_tenant uuid;
  v_uid    uuid := (SELECT auth.uid());
  v_status text;
  v_bloco  uuid;
  v_gaveta text;
BEGIN
  SELECT tenant_id, status_loop, bloco_criado_id, gaveta_proposta
    INTO v_tenant, v_status, v_bloco, v_gaveta
    FROM public.perguntas_sem_resposta
    WHERE id = p_id;

  IF v_tenant IS NULL OR v_tenant <> v_uid THEN
    RETURN jsonb_build_object('ok', false, 'erro', 'sem permissão');
  END IF;

  IF v_status NOT IN ('dono_respondeu', 'entregue_lead', 'virou_bloco') THEN
    RETURN jsonb_build_object('ok', false, 'erro', 'pergunta ainda não foi respondida');
  END IF;

  IF coalesce(trim(p_resposta), '') = '' THEN
    RETURN jsonb_build_object('ok', false, 'erro', 'resposta vazia');
  END IF;

  UPDATE public.perguntas_sem_resposta
    SET resposta_do_dono = trim(p_resposta),
        respondida_em    = now(),
        respondida_por   = v_uid
    WHERE id = p_id;

  -- Bloco vinculado acompanha (apenas gaveta blocos_conhecimento — demais gavetas têm schemas próprios)
  IF v_bloco IS NOT NULL AND coalesce(v_gaveta, 'blocos_conhecimento') = 'blocos_conhecimento' THEN
    UPDATE public.blocos_conhecimento
      SET content = trim(p_resposta)
      WHERE id = v_bloco AND deleted_at IS NULL;
  END IF;

  RETURN jsonb_build_object('ok', true, 'bloco_atualizado', v_bloco IS NOT NULL);
END;
$$;


ALTER FUNCTION public.editar_resposta_pergunta_mentor(p_id uuid, p_resposta text) OWNER TO postgres;

--
