--

CREATE FUNCTION public.eh_admin_plataforma() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.profiles
    WHERE id = (select auth.uid()) AND system_role = 'platform_admin'
  );
$$;


ALTER FUNCTION public.eh_admin_plataforma() OWNER TO postgres;

--
-- Name: eh_dia_util(date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.eh_dia_util(p_data date) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  SELECT
    extract(dow FROM p_data)::int NOT IN (0, 6)
    AND NOT EXISTS (
      SELECT 1 FROM public.feriados_brasil
      WHERE data = p_data AND ativo = true AND escopo = 'nacional'
    );
$$;


ALTER FUNCTION public.eh_dia_util(p_data date) OWNER TO postgres;

