--
-- Name: enfileirar_acao_agendada(uuid, uuid, uuid, uuid, text, timestamp with time zone, jsonb, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.enfileirar_acao_agendada(p_conversation_id uuid, p_lead_id uuid, p_agente_id uuid, p_tenant_id uuid, p_action_type text, p_scheduled_at timestamp with time zone, p_carga jsonb DEFAULT '{}'::jsonb, p_node_name text DEFAULT NULL::text, p_template text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_id uuid;
BEGIN
  INSERT INTO public.acoes_agendadas (
    conversation_id,
    lead_id,
    agente_id,
    tenant_id,
    action_type,
    scheduled_at,
    status,
    carga,
    node_name,
    template,
    created_at
  )
  VALUES (
    p_conversation_id,
    p_lead_id,
    p_agente_id,
    p_tenant_id,
    p_action_type,
    p_scheduled_at,
    'pendente',
    COALESCE(p_carga, '{}'::jsonb),
    p_node_name,
    p_template,
    now()
  )
  ON CONFLICT (conversation_id, action_type, scheduled_at)
  WHERE status IN ('pendente','processando')
  DO NOTHING
  RETURNING id INTO v_id;

  IF v_id IS NULL THEN
    SELECT id INTO v_id
    FROM public.acoes_agendadas
    WHERE conversation_id = p_conversation_id
      AND action_type     = p_action_type
      AND scheduled_at    = p_scheduled_at
      AND status IN ('pendente','processando')
    LIMIT 1;
  END IF;

  RETURN v_id;
END;
$$;


ALTER FUNCTION public.enfileirar_acao_agendada(p_conversation_id uuid, p_lead_id uuid, p_agente_id uuid, p_tenant_id uuid, p_action_type text, p_scheduled_at timestamp with time zone, p_carga jsonb, p_node_name text, p_template text) OWNER TO postgres;

--
-- Name: enfileirar_tarefa_embedding(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.enfileirar_tarefa_embedding() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_text text;
BEGIN
  CASE TG_TABLE_NAME
    WHEN 'blocos_conhecimento' THEN v_text := coalesce(NEW.title, '') || ' ' || coalesce(NEW.content, '');
    WHEN 'blocos_comportamento' THEN v_text := coalesce(NEW.situacao_descricao, '') || ' ' || coalesce(NEW.instrucao, '');
    WHEN 'blocos_humanizacao' THEN v_text := coalesce(NEW.categoria, '') || ' ' || coalesce(NEW.regra, '');
    WHEN 'blocos_gatilho' THEN v_text := coalesce(NEW.nome_trigger, '') || ' ' || coalesce(NEW.exemplo_frase, '');
    WHEN 'blocos_variacao' THEN v_text := coalesce(NEW.nome_variation, '') || ' ' || coalesce(NEW.instrucao, '');
    WHEN 'blocos_meta' THEN v_text := coalesce(NEW.corpo, '');
    WHEN 'emocao_blocos' THEN v_text := coalesce(NEW.emocao, '') || ' ' || coalesce(NEW.corpo, '');
    WHEN 'prova_social_blocos' THEN v_text := coalesce(NEW.depoimento, '') || ' ' || coalesce(NEW.autor, '');
    WHEN 'memoria_episodica' THEN v_text := coalesce(NEW.episodio_resumo, '') || ' ' || coalesce(NEW.emocao, '');
    WHEN 'blocos_procedurais' THEN v_text := coalesce(NEW.nome_procedimento, '') || ' ' || coalesce(NEW.passos::text, '');
    WHEN 'anti_padroes' THEN v_text := coalesce(NEW.situacao, '') || ' ' || coalesce(NEW.acao_correta, '');
    WHEN 'agente_identidade' THEN v_text := coalesce(NEW.dimensao, '') || ' ' || coalesce(NEW.texto, '');
    WHEN 'memoria_lead' THEN v_text := coalesce(NEW.fato, '') || ' ' || coalesce(NEW.categoria, '');
    WHEN 'manipulacao_blocos' THEN v_text := coalesce(NEW.tipo, '') || ' ' || coalesce(NEW.resposta_padrao, '');
    WHEN 'diretriz_bolha_blocos' THEN v_text := coalesce(NEW.contexto, '') || ' ' || coalesce(NEW.motivo, '');
    WHEN 'regras_operacionais_blocos' THEN v_text := coalesce(NEW.contexto, '') || ' ' || coalesce(NEW.regra, '');
    WHEN 'pivots_categoria_intent' THEN v_text := coalesce(NEW.frase_pivo, '');
    WHEN 'automacao_blocos' THEN v_text := coalesce(NEW.nome, '') || ' ' || coalesce(NEW.descricao, '');
    WHEN 'acao_pausa_blocos' THEN v_text := coalesce(NEW.gatilho_descricao, '') || ' ' || coalesce(NEW.gatilho_falas::text, '') || ' ' || coalesce(NEW.mensagem_retorno, '');
    WHEN 'fase_requisitos' THEN v_text := coalesce(NEW.descricao_curta, '') || ' ' || coalesce(NEW.descricao_semantica, '');
    WHEN 'pacotes_conhecimento_blocos' THEN v_text := coalesce(NEW.titulo, '') || ' ' || coalesce(NEW.conteudo, '');
    ELSE v_text := NULL;
  END CASE;
  IF v_text IS NOT NULL AND trim(v_text) <> '' THEN
    PERFORM pgmq.send('embedding_jobs', jsonb_build_object('table', TG_TABLE_NAME, 'row_id', NEW.id, 'text', trim(v_text)));
    NEW.embedding_status := 'pendente';
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.enfileirar_tarefa_embedding() OWNER TO postgres;

--
-- Name: FUNCTION enfileirar_tarefa_embedding(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.enfileirar_tarefa_embedding() IS 'Trigger function que enfileira embedding_jobs no pgmq pra processamento async via gerar-embedding edge fn. Cobre 9 tabelas: behavior/trigger/human/variation/knowledge/meta/lead_memory/episodic_memory/procedural_chunks.';


--
-- Name: enfileirar_vetor_ferramenta(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.enfileirar_vetor_ferramenta() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_texto text;
begin
  v_texto := trim(coalesce(new.nome_tool, '') || ' ' || coalesce(new.descricao, ''));
  if v_texto <> '' then
    perform pgmq.send(
      'embedding_jobs',
      jsonb_build_object('table', 'ferramentas_dinamicas', 'row_id', new.id, 'text', v_texto)
    );
  end if;
  return null;
end;
$$;


ALTER FUNCTION public.enfileirar_vetor_ferramenta() OWNER TO postgres;

