--
-- Name: entrar_sala_publica(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.entrar_sala_publica(p_chave uuid, p_nome text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_sala public.salas_reuniao%rowtype;
  v_ativos integer;
  v_nome text;
  v_participante_id uuid;
  v_status_entrada text;
begin
  v_nome := nullif(btrim(p_nome), '');
  if v_nome is null then
    raise exception 'nome_obrigatorio';
  end if;

  select * into v_sala from public.salas_reuniao
    where chave_publica = p_chave and deleted_at is null
    for update;
  if not found then
    raise exception 'sala_nao_encontrada';
  end if;
  if v_sala.status not in ('agendada','ao_vivo') then
    raise exception 'sala_indisponivel';
  end if;

  -- lotação conta só quem está aprovado e ativo
  select count(*) into v_ativos from public.salas_reuniao_participantes
    where sala_id = v_sala.id and saiu_em is null and status_entrada = 'aprovado';
  if v_ativos >= v_sala.max_participantes then
    raise exception 'sala_lotada';
  end if;

  v_status_entrada := case when v_sala.exige_aprovacao then 'pendente' else 'aprovado' end;

  insert into public.salas_reuniao_participantes (sala_id, nome_convidado, papel, status_entrada)
    values (v_sala.id, v_nome, 'participante', v_status_entrada)
    returning id into v_participante_id;

  return jsonb_build_object(
    'sala_id', v_sala.id,
    'participante_id', v_participante_id,
    'titulo', v_sala.titulo,
    'modo', v_sala.modo,
    'transporte', v_sala.transporte,
    'max_participantes', v_sala.max_participantes,
    'status', v_sala.status,
    'status_entrada', v_status_entrada,
    'exige_aprovacao', v_sala.exige_aprovacao
  );
end;
$$;


ALTER FUNCTION public.entrar_sala_publica(p_chave uuid, p_nome text) OWNER TO postgres;

--
-- Name: enviar_comprovante_pagamento_publico(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.enviar_comprovante_pagamento_publico(p_token uuid, p_proof_url text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_contract_id uuid;
BEGIN
  IF p_token IS NULL OR p_proof_url IS NULL OR btrim(p_proof_url) = '' THEN RAISE EXCEPTION 'token e url obrigatorios' USING ERRCODE = '22023'; END IF;
  SELECT id INTO v_contract_id FROM public.contratos WHERE chave_publica = p_token LIMIT 1;
  IF v_contract_id IS NULL THEN RAISE EXCEPTION 'contrato nao encontrado' USING ERRCODE = 'P0002'; END IF;
  PERFORM public.verificar_limite_taxa_publico(p_token::text, 'submit_payment_proof_public', 5);
  UPDATE public.contratos SET url_comprovante_pagamento = p_proof_url WHERE id = v_contract_id;
END;
$$;


ALTER FUNCTION public.enviar_comprovante_pagamento_publico(p_token uuid, p_proof_url text) OWNER TO postgres;

--
-- Name: enviar_comprovante_rifa_publico(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.enviar_comprovante_rifa_publico(p_token uuid, p_url text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_p public.pedidos_rifa%rowtype;
begin
  if nullif(btrim(coalesce(p_url, '')), '') is null then
    return jsonb_build_object('ok', false, 'erro', 'url_obrigatoria');
  end if;

  perform public.verificar_limite_taxa_publico(p_token::text, 'rifa_comprovante', 10);

  select * into v_p from public.pedidos_rifa where chave_publica = p_token for update;
  if not found then
    return jsonb_build_object('ok', false, 'erro', 'pedido_nao_encontrado');
  end if;
  if v_p.status not in ('reservado', 'aguardando_validacao', 'rejeitado') then
    return jsonb_build_object('ok', false, 'erro', 'pedido_nao_aceita_comprovante');
  end if;

  -- comprovante anexado tira o pedido da mira do cron de expiração
  update public.pedidos_rifa
  set comprovante_url = p_url, status = 'aguardando_validacao',
      motivo_rejeicao = null, expira_em = null, updated_at = now()
  where id = v_p.id;

  return jsonb_build_object('ok', true, 'status', 'aguardando_validacao');
end;
$$;


ALTER FUNCTION public.enviar_comprovante_rifa_publico(p_token uuid, p_url text) OWNER TO postgres;

