--
-- Name: enviar_reproposta(uuid[], text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.enviar_reproposta(p_campaign_lead_ids uuid[], p_texto text DEFAULT NULL::text) RETURNS TABLE(campaign_lead_id uuid, reproposta_id uuid, scheduled_action_id uuid, status text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_caller uuid := auth.uid(); v_rec record; v_repid uuid; v_actid uuid; v_conv uuid; v_agent uuid; v_idx integer := 0;
BEGIN
  IF v_caller IS NULL THEN RAISE EXCEPTION 'unauthenticated'; END IF;
  FOR v_rec IN
    SELECT cl.id AS cl_id, cl.lead_id AS lead_id, cl.campaign_id AS campaign_id, cl.reproposta_count AS rep_count,
           c.tenant_id AS tenant_id, c.status AS campaign_status, c.deleted_at AS campaign_deleted_at
    FROM public.leads_campanha cl JOIN public.campanhas c ON c.id = cl.campaign_id
    WHERE cl.id = ANY(p_campaign_lead_ids)
      AND (c.tenant_id = v_caller
           OR c.tenant_id IN (SELECT p.parent_user_id FROM public.profiles p WHERE p.id = v_caller AND p.parent_user_id IS NOT NULL)
           OR public.is_platform_admin())
  LOOP
    IF v_rec.campaign_deleted_at IS NOT NULL OR v_rec.campaign_status NOT IN ('active','paused','ativa','pausada') THEN
      campaign_lead_id := v_rec.cl_id; reproposta_id := NULL; scheduled_action_id := NULL; status := 'campanha_inativa';
      RETURN NEXT; CONTINUE;
    END IF;
    IF v_rec.rep_count >= 10 THEN
      campaign_lead_id := v_rec.cl_id; reproposta_id := NULL; scheduled_action_id := NULL; status := 'throttle_atingido';
      RETURN NEXT; CONTINUE;
    END IF;
    IF EXISTS (SELECT 1 FROM public.exclusoes_tenant toov WHERE toov.tenant_id = v_rec.tenant_id AND toov.lead_id = v_rec.lead_id) THEN
      campaign_lead_id := v_rec.cl_id; reproposta_id := NULL; scheduled_action_id := NULL; status := 'opt_out';
      RETURN NEXT; CONTINUE;
    END IF;
    IF EXISTS (SELECT 1 FROM public.leads l WHERE l.id = v_rec.lead_id AND l.opt_out_at IS NOT NULL) THEN
      campaign_lead_id := v_rec.cl_id; reproposta_id := NULL; scheduled_action_id := NULL; status := 'opt_out_lead';
      RETURN NEXT; CONTINUE;
    END IF;
    UPDATE public.acoes_agendadas SET status = 'cancelado'
    WHERE lead_id = v_rec.lead_id AND status IN ('pending','pendente')
      AND action_type IN ('campaign_trigger','campaign_reproposta','retomada_encerramento');
    v_idx := v_idx + 1;
    INSERT INTO public.repropostas_lead_campanha (campaign_lead_id, texto, created_by)
    VALUES (v_rec.cl_id, COALESCE(p_texto,''), v_caller) RETURNING id INTO v_repid;
    SELECT co.id, co.agente_id INTO v_conv, v_agent FROM public.conversas co
    WHERE co.lead_id = v_rec.lead_id AND co.tenant_id = v_rec.tenant_id ORDER BY co.updated_at DESC NULLS LAST LIMIT 1;
    INSERT INTO public.acoes_agendadas (lead_id, conversation_id, agente_id, action_type, scheduled_at, status, carga)
    VALUES (v_rec.lead_id, v_conv, v_agent, 'campaign_reproposta', now() + ((v_idx - 1) * interval '1 minute'), 'pendente',
            jsonb_build_object('campaign_id', v_rec.campaign_id, 'campaign_lead_id', v_rec.cl_id, 'reproposta_id', v_repid, 'texto_personalizado', COALESCE(p_texto,'')))
    RETURNING id INTO v_actid;
    UPDATE public.leads_campanha SET reproposta_count = reproposta_count + 1 WHERE id = v_rec.cl_id;
    campaign_lead_id := v_rec.cl_id; reproposta_id := v_repid; scheduled_action_id := v_actid; status := 'enfileirada';
    RETURN NEXT;
  END LOOP;
  RETURN;
END;
$$;


ALTER FUNCTION public.enviar_reproposta(p_campaign_lead_ids uuid[], p_texto text) OWNER TO postgres;

--
-- Name: FUNCTION enviar_reproposta(p_campaign_lead_ids uuid[], p_texto text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.enviar_reproposta(p_campaign_lead_ids uuid[], p_texto text) IS 'Enfileira reproposta para campaign_leads. Respeita tenant_opt_outs (LGPD), opt_out_at no lead, reproposta_count<10 e campanha ativa.';


--
-- Name: esquema_consulta_dados(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.esquema_consulta_dados() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(
    jsonb_object_agg(
      t.tabela,
      jsonb_build_object('descricao', t.descricao, 'aceita_escrita', t.permite_escrita, 'colunas', t.colunas)
    ),
    '{}'::jsonb
  )
  from (
    select p.tabela,
           p.descricao,
           p.permite_escrita,
           (
             select jsonb_agg(c.column_name || ' ' || c.data_type order by c.ordinal_position)
             from information_schema.columns c
             where c.table_schema = 'public' and c.table_name = p.tabela
           ) as colunas
    from public.tabelas_consulta_permitidas p
    where p.ativo
  ) t;
$$;


ALTER FUNCTION public.esquema_consulta_dados() OWNER TO postgres;

--
-- Name: estado_curadoria_completo(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.estado_curadoria_completo() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_resultado jsonb;
BEGIN
  PERFORM set_config('search_path', 'public', true);
  PERFORM set_config('statement_timeout', '5s', true);

  SELECT jsonb_build_object(
    'gavetas', jsonb_build_object(
      'blocos_conhecimento',     (SELECT COUNT(*) FROM public.blocos_conhecimento WHERE ativo IS NOT FALSE),
      'blocos_comportamento',      (SELECT COUNT(*) FROM public.blocos_comportamento WHERE ativo IS NOT FALSE),
      'blocos_gatilho',       (SELECT COUNT(*) FROM public.blocos_gatilho WHERE ativo IS NOT FALSE),
      'blocos_humanizacao',         (SELECT COUNT(*) FROM public.blocos_humanizacao WHERE ativo IS NOT FALSE),
      'blocos_variacao',     (SELECT COUNT(*) FROM public.blocos_variacao WHERE ativo IS NOT FALSE),
      'blocos_meta',          (SELECT COUNT(*) FROM public.blocos_meta WHERE ativo IS NOT FALSE),
      'blocos_procedurais',    (SELECT COUNT(*) FROM public.blocos_procedurais WHERE ativo IS NOT FALSE),
      'emocao_blocos',        (SELECT COUNT(*) FROM public.emocao_blocos WHERE ativo IS NOT FALSE),
      'prova_social_blocos',  (SELECT COUNT(*) FROM public.prova_social_blocos WHERE ativo IS NOT FALSE),
      'manipulacao_blocos',   (SELECT COUNT(*) FROM public.manipulacao_blocos WHERE ativo IS NOT FALSE),
      'diretriz_bolha_blocos',(SELECT COUNT(*) FROM public.diretriz_bolha_blocos WHERE ativo IS NOT FALSE),
      'automacao_blocos',     (SELECT COUNT(*) FROM public.automacao_blocos WHERE ativo IS NOT FALSE),
      'acao_pausa_blocos',    (SELECT COUNT(*) FROM public.acao_pausa_blocos WHERE ativo IS NOT FALSE),
      'regras_operacionais_blocos', (SELECT COUNT(*) FROM public.regras_operacionais_blocos WHERE ativo IS NOT FALSE)
    ),
    'tenants_ativos', (SELECT COUNT(*) FROM public.profiles WHERE system_role='user' AND deletion_requested_at IS NULL),
    'reflexoes_7d', (SELECT COUNT(*) FROM public.registro_reflexao WHERE criado_em > now() - interval '7 days' AND deleted_at IS NULL),
    'candidates_pendentes', (SELECT COUNT(*) FROM public.candidatos_bloco WHERE status IN ('pendente','pending')),
    'gerado_em', now()
  ) INTO v_resultado;

  RETURN v_resultado;
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('erro', SQLERRM);
END $$;


ALTER FUNCTION public.estado_curadoria_completo() OWNER TO postgres;

--
-- Name: estatisticas_painel(uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.estatisticas_painel(p_tenant_id uuid, p_period_start timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE result jsonb; v_agent_id uuid;
BEGIN
  SELECT id INTO v_agent_id FROM public.agentes_usuario WHERE user_id = p_tenant_id LIMIT 1;
  SELECT jsonb_build_object(
    'leads_ativos', (SELECT count(*) FROM public.leads WHERE tenant_id = p_tenant_id AND phone NOT LIKE 'chat-test%' AND fase_pipeline != 'fechado' AND (p_period_start IS NULL OR created_at >= p_period_start)),
    'clientes_ativos', (SELECT count(*) FROM public.leads WHERE tenant_id = p_tenant_id AND phone NOT LIKE 'chat-test%' AND fase_pipeline = 'fechado' AND (p_period_start IS NULL OR created_at >= p_period_start)),
    'total_leads', (SELECT count(*) FROM public.leads WHERE tenant_id = p_tenant_id AND phone NOT LIKE 'chat-test%' AND (p_period_start IS NULL OR created_at >= p_period_start)),
    'convs_count', (SELECT count(*) FROM public.conversas WHERE tenant_id = p_tenant_id AND phone NOT LIKE 'chat-test%' AND (p_period_start IS NULL OR created_at >= p_period_start)),
    'contracts_count', (SELECT count(*) FROM public.contratos WHERE tenant_id = p_tenant_id),
    'msgs_by_role', (SELECT jsonb_build_object(
        'assistant', coalesce(sum(CASE WHEN m.role = 'assistant' THEN 1 ELSE 0 END), 0),
        'user', coalesce(sum(CASE WHEN m.role = 'user' THEN 1 ELSE 0 END), 0),
        'human', coalesce(sum(CASE WHEN m.role IN ('human','humano') THEN 1 ELSE 0 END), 0)
      ) FROM public.mensagens m JOIN public.conversas c ON c.id = m.conversation_id WHERE c.tenant_id = p_tenant_id AND (p_period_start IS NULL OR m.created_at >= p_period_start)),
    'funnel', (SELECT CASE WHEN v_agent_id IS NOT NULL THEN
        (SELECT jsonb_build_object(
          'Saudação', coalesce(sum(CASE WHEN lower(fase) = 'saudacao' THEN 1 ELSE 0 END), 0),
          'Qualificação', coalesce(sum(CASE WHEN lower(fase) = 'qualificacao' THEN 1 ELSE 0 END), 0),
          'Apresentação', coalesce(sum(CASE WHEN lower(fase) = 'apresentacao' THEN 1 ELSE 0 END), 0),
          'Negociação', coalesce(sum(CASE WHEN lower(fase) = 'negociacao' THEN 1 ELSE 0 END), 0),
          'Fechamento', coalesce(sum(CASE WHEN lower(fase) IN ('fechamento','fechado') THEN 1 ELSE 0 END), 0)
        ) FROM public.fichas_lead WHERE agente_id = v_agent_id)
      ELSE
        (SELECT jsonb_build_object(
          'Saudação', coalesce(sum(CASE WHEN fase_pipeline = 'novo' THEN 1 ELSE 0 END), 0),
          'Qualificação', coalesce(sum(CASE WHEN fase_pipeline = 'qualificando' THEN 1 ELSE 0 END), 0),
          'Apresentação', coalesce(sum(CASE WHEN fase_pipeline = 'apresentando' THEN 1 ELSE 0 END), 0),
          'Negociação', coalesce(sum(CASE WHEN fase_pipeline = 'negociando' THEN 1 ELSE 0 END), 0),
          'Fechamento', coalesce(sum(CASE WHEN fase_pipeline = 'fechado' THEN 1 ELSE 0 END), 0)
        ) FROM public.leads WHERE tenant_id = p_tenant_id AND phone NOT LIKE 'chat-test%' AND (p_period_start IS NULL OR created_at >= p_period_start))
      END),
    'client_phases', (SELECT jsonb_build_object(
        'Documentação', coalesce(sum(CASE WHEN coalesce(fase_cliente,'documentacao') = 'documentacao' THEN 1 ELSE 0 END), 0),
        'Protocolo', coalesce(sum(CASE WHEN fase_cliente = 'protocolo' THEN 1 ELSE 0 END), 0),
        'Em Andamento', coalesce(sum(CASE WHEN fase_cliente = 'andamento' THEN 1 ELSE 0 END), 0),
        'Concluído', coalesce(sum(CASE WHEN fase_cliente = 'concluido' THEN 1 ELSE 0 END), 0)
      ) FROM public.leads WHERE tenant_id = p_tenant_id AND phone NOT LIKE 'chat-test%' AND fase_pipeline = 'fechado'),
    'peak_hours', (SELECT jsonb_build_object(
        '06h', coalesce(sum(CASE WHEN extract(hour FROM m.created_at) BETWEEN 6 AND 7 THEN 1 ELSE 0 END), 0),
        '08h', coalesce(sum(CASE WHEN extract(hour FROM m.created_at) BETWEEN 8 AND 9 THEN 1 ELSE 0 END), 0),
        '10h', coalesce(sum(CASE WHEN extract(hour FROM m.created_at) BETWEEN 10 AND 11 THEN 1 ELSE 0 END), 0),
        '12h', coalesce(sum(CASE WHEN extract(hour FROM m.created_at) BETWEEN 12 AND 13 THEN 1 ELSE 0 END), 0),
        '14h', coalesce(sum(CASE WHEN extract(hour FROM m.created_at) BETWEEN 14 AND 15 THEN 1 ELSE 0 END), 0),
        '16h', coalesce(sum(CASE WHEN extract(hour FROM m.created_at) BETWEEN 16 AND 17 THEN 1 ELSE 0 END), 0),
        '18h', coalesce(sum(CASE WHEN extract(hour FROM m.created_at) BETWEEN 18 AND 19 THEN 1 ELSE 0 END), 0),
        '20h', coalesce(sum(CASE WHEN extract(hour FROM m.created_at) BETWEEN 20 AND 21 THEN 1 ELSE 0 END), 0),
        '22h', coalesce(sum(CASE WHEN extract(hour FROM m.created_at) BETWEEN 22 AND 23 THEN 1 ELSE 0 END), 0)
      ) FROM public.mensagens m JOIN public.conversas c ON c.id = m.conversation_id
      WHERE c.tenant_id = p_tenant_id AND m.role = 'user' AND (p_period_start IS NULL OR m.created_at >= p_period_start)),
    'human_conv_ids', (SELECT coalesce(jsonb_agg(DISTINCT m.conversation_id), '[]'::jsonb)
      FROM public.mensagens m JOIN public.conversas c ON c.id = m.conversation_id
      WHERE c.tenant_id = p_tenant_id AND m.role IN ('human','humano') AND (p_period_start IS NULL OR m.created_at >= p_period_start))
  ) INTO result;
  RETURN result;
END;
$$;


ALTER FUNCTION public.estatisticas_painel(p_tenant_id uuid, p_period_start timestamp with time zone) OWNER TO postgres;

--
-- Name: estornar_carteira_consulta(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.estornar_carteira_consulta(p_consulta_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_tenant uuid;
  v_valor numeric(10,2);
  v_saldo numeric(10,2);
BEGIN
  SELECT tenant_id, valor INTO v_tenant, v_valor
  FROM public.consultas_carteira_mov
  WHERE consulta_id = p_consulta_id AND tipo = 'debito'
  ORDER BY created_at LIMIT 1;

  IF v_tenant IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'erro', 'sem_debito');
  END IF;

  IF EXISTS (SELECT 1 FROM public.consultas_carteira_mov
             WHERE consulta_id = p_consulta_id AND tipo = 'estorno') THEN
    RETURN jsonb_build_object('ok', true, 'erro', 'ja_estornado');
  END IF;

  SELECT saldo INTO v_saldo FROM public.consultas_saldo
    WHERE tenant_id = v_tenant FOR UPDATE;

  UPDATE public.consultas_saldo
    SET saldo = saldo + v_valor, atualizado_em = now()
    WHERE tenant_id = v_tenant;

  INSERT INTO public.consultas_carteira_mov (tenant_id, tipo, valor, saldo_apos, consulta_id)
    VALUES (v_tenant, 'estorno', v_valor, v_saldo + v_valor, p_consulta_id);

  RETURN jsonb_build_object('ok', true, 'saldo_apos', v_saldo + v_valor);
END;
$$;


ALTER FUNCTION public.estornar_carteira_consulta(p_consulta_id uuid) OWNER TO postgres;

--
-- Name: evocar_memoria_dono(uuid[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.evocar_memoria_dono(p_ids uuid[]) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare n integer;
begin
  update public.memoria_dono
     set vezes_evocado = vezes_evocado + 1, ultima_evocacao_em = now()
   where id = any (p_ids);
  get diagnostics n = row_count;
  return n;
end;
$$;


ALTER FUNCTION public.evocar_memoria_dono(p_ids uuid[]) OWNER TO postgres;

--
-- Name: excluir_campanha(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.excluir_campanha(p_campaign_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_caller uuid := auth.uid(); v_tenant uuid; v_is_admin boolean; v_is_team_member boolean;
BEGIN
  IF v_caller IS NULL THEN RAISE EXCEPTION 'unauthenticated'; END IF;
  SELECT tenant_id INTO v_tenant FROM public.campanhas WHERE id = p_campaign_id AND deleted_at IS NULL;
  IF v_tenant IS NULL THEN RAISE EXCEPTION 'not_found'; END IF;
  v_is_admin := public.is_platform_admin();
  SELECT EXISTS (SELECT 1 FROM public.profiles p WHERE p.id = v_caller AND p.parent_user_id = v_tenant) INTO v_is_team_member;
  IF NOT (v_tenant = v_caller OR v_is_admin OR v_is_team_member) THEN RAISE EXCEPTION 'forbidden'; END IF;
  UPDATE public.campanhas SET deleted_at = now(), status = 'pausada', updated_at = now() WHERE id = p_campaign_id;
  UPDATE public.leads_campanha SET state = 'desistente', exit_reason = 'campanha_deletada', closed_at = now()
  WHERE campaign_id = p_campaign_id AND state = 'ativo';
  UPDATE public.acoes_agendadas SET status = 'cancelado'
  WHERE action_type IN ('campaign_trigger','campaign_reproposta') AND status IN ('pending','pendente') AND campaign_id = p_campaign_id;
END;
$$;


ALTER FUNCTION public.excluir_campanha(p_campaign_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION excluir_campanha(p_campaign_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.excluir_campanha(p_campaign_id uuid) IS 'Soft delete de campanha com cascata em campaign_leads e scheduled_actions. Ownership por tenant/team/admin.';


--
-- Name: excluir_campo_personalizado(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.excluir_campo_personalizado(p_lead_id uuid, p_chave text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF NOT public._lead_pertence_caller(p_lead_id) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;

  UPDATE public.leads
     SET custom_fields = COALESCE(custom_fields, '{}'::jsonb) - p_chave,
         updated_at = now()
   WHERE id = p_lead_id;
END;
$$;


ALTER FUNCTION public.excluir_campo_personalizado(p_lead_id uuid, p_chave text) OWNER TO postgres;

--
-- Name: excluir_conversas_profundo_para_atendimento(uuid[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.excluir_conversas_profundo_para_atendimento(p_conversa_ids uuid[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_n_conv integer;
  v_n_leads integer := 0;
  v_uid uuid := (SELECT auth.uid());
  v_ids uuid[];
  v_lead_candidates uuid[];
  v_orphan uuid[];
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'auth obrigatório';
  END IF;

  SELECT coalesce(array_agg(DISTINCT x), ARRAY[]::uuid[])
    INTO v_ids
  FROM unnest(coalesce(p_conversa_ids, ARRAY[]::uuid[])) AS x;

  IF cardinality(v_ids) = 0 THEN
    RETURN jsonb_build_object('deleted_conversa_count', 0, 'deleted_lead_count', 0);
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.conversas c
    WHERE c.id = ANY (v_ids)
      AND NOT (
        c.tenant_id = v_uid
        OR EXISTS (
          SELECT 1 FROM public.profiles p
          WHERE p.id = v_uid AND p.parent_user_id = c.tenant_id
        )
        OR EXISTS (
          SELECT 1 FROM public.profiles padm
          WHERE padm.id = v_uid AND padm.system_role = 'platform_admin'
        )
      )
  ) THEN
    RAISE EXCEPTION 'sem permissão para uma ou mais conversas';
  END IF;

  SELECT cardinality(v_ids) INTO v_n_conv;

  -- ATENCAO: DELETE direto em storage.objects bloqueado pelo Supabase desde 2026-05.
  -- Anexos das conversas excluidas ficam orfaos no bucket anexos-chat.

  SELECT coalesce(array_agg(DISTINCT c.lead_id) FILTER (WHERE c.lead_id IS NOT NULL), ARRAY[]::uuid[])
    INTO v_lead_candidates
  FROM public.conversas AS c
  WHERE c.id = ANY (v_ids);

  -- FASE 1: pagamentos antes de contratos da conversa
  DELETE FROM public.pagamentos_cliente pc
  WHERE pc.contrato_id IN (SELECT id FROM public.contratos WHERE conversa_id = ANY (v_ids));

  -- FASE 2: dependências diretas das conversas
  DELETE FROM public.compromissos WHERE conversation_id = ANY (v_ids);
  DELETE FROM public.travas_conversa WHERE conversation_id = ANY (v_ids);
  DELETE FROM public.tickets_conversa WHERE conversation_id = ANY (v_ids);
  DELETE FROM public.pausa_conversa WHERE conversation_id = ANY (v_ids);
  DELETE FROM public.prompts_mensagem WHERE conversation_id = ANY (v_ids);
  DELETE FROM public.calibracao_padrao
  WHERE conversation_id = ANY (v_ids)
     OR message_id IN (SELECT id FROM public.mensagens WHERE conversation_id = ANY (v_ids));
  DELETE FROM public.mensagens WHERE conversation_id = ANY (v_ids);
  DELETE FROM public.acoes_agendadas WHERE conversation_id = ANY (v_ids);
  DELETE FROM public.auditoria_conversa WHERE conversation_id = ANY (v_ids);
  DELETE FROM public.caixa_saida_mensagens WHERE conversation_id = ANY (v_ids);
  DELETE FROM public.candidatos_bloco WHERE conversation_id = ANY (v_ids);
  DELETE FROM public.contratos WHERE conversa_id = ANY (v_ids);
  DELETE FROM public.crenca_conversa WHERE conversation_id = ANY (v_ids);
  DELETE FROM public.dicas_dono WHERE conversation_id = ANY (v_ids);
  DELETE FROM public.engajamento_turnos WHERE conversation_id = ANY (v_ids);
  DELETE FROM public.estado_digitacao WHERE conversation_id = ANY (v_ids);
  DELETE FROM public.fichas_lead WHERE conversation_id = ANY (v_ids);
  DELETE FROM public.incidentes_seguranca WHERE conversation_id = ANY (v_ids);
  DELETE FROM public.invocacoes_ferramenta WHERE conversation_id = ANY (v_ids);
  DELETE FROM public.manipulacao_log WHERE conversation_id = ANY (v_ids);
  DELETE FROM public.memoria_episodica WHERE conversation_id = ANY (v_ids);
  DELETE FROM public.memoria_lead WHERE conversation_id = ANY (v_ids);
  DELETE FROM public.observacoes_tag WHERE conversation_id = ANY (v_ids);
  DELETE FROM public.perguntas_sem_resposta WHERE conversation_id = ANY (v_ids);
  DELETE FROM public.registro_reflexao WHERE conversation_id = ANY (v_ids);
  DELETE FROM public.registro_uso_api WHERE conversation_id = ANY (v_ids);
  DELETE FROM public.sessoes_chat_publico WHERE conversation_id = ANY (v_ids);

  DELETE FROM public.conversas WHERE id = ANY (v_ids);

  -- FASE 3: leads que não ficaram com conversa
  SELECT coalesce(array_agg(lc), ARRAY[]::uuid[])
    INTO v_orphan
  FROM unnest(v_lead_candidates) AS lc
  WHERE NOT EXISTS (SELECT 1 FROM public.conversas cx WHERE cx.lead_id = lc);

  IF cardinality(v_orphan) > 0 THEN
    v_n_leads := cardinality(v_orphan);

    DELETE FROM public.pagamentos_cliente pc
    WHERE pc.lead_id = ANY (v_orphan)
       OR pc.contrato_id IN (SELECT ct.id FROM public.contratos ct WHERE ct.lead_id = ANY (v_orphan));
    DELETE FROM public.candidatos_bloco WHERE lead_id = ANY (v_orphan);
    DELETE FROM public.cofre_pii_lead WHERE lead_id = ANY (v_orphan);
    DELETE FROM public.comissoes_indicacao_campanha WHERE lead_id = ANY (v_orphan);
    DELETE FROM public.compromissos WHERE lead_id = ANY (v_orphan);
    DELETE FROM public.contratos WHERE lead_id = ANY (v_orphan);
    DELETE FROM public.dicas_dono WHERE lead_id = ANY (v_orphan);
    DELETE FROM public.documentos_cliente WHERE lead_id = ANY (v_orphan);
    DELETE FROM public.engajamento_lead WHERE lead_id = ANY (v_orphan);
    DELETE FROM public.fichas_lead WHERE lead_id = ANY (v_orphan);
    DELETE FROM public.leads_campanha WHERE lead_id = ANY (v_orphan);
    DELETE FROM public.manipulacao_log WHERE lead_id = ANY (v_orphan);
    DELETE FROM public.memoria_lead WHERE lead_id = ANY (v_orphan);
    DELETE FROM public.memoria_episodica WHERE lead_id = ANY (v_orphan);
    DELETE FROM public.observacoes_tag WHERE lead_id = ANY (v_orphan);
    DELETE FROM public.prova_social_blocos WHERE lead_origem = ANY (v_orphan);
    DELETE FROM public.sotaques_observados WHERE lead_id = ANY (v_orphan);
    DELETE FROM public.valores_ficha WHERE lead_id = ANY (v_orphan);
    DELETE FROM public.sessoes_chat_publico WHERE lead_id = ANY (v_orphan);

    DELETE FROM public.leads WHERE id = ANY (v_orphan);
  END IF;

  RETURN jsonb_build_object('deleted_conversa_count', v_n_conv, 'deleted_lead_count', v_n_leads);
END;
$$;


ALTER FUNCTION public.excluir_conversas_profundo_para_atendimento(p_conversa_ids uuid[]) OWNER TO postgres;

--
-- Name: FUNCTION excluir_conversas_profundo_para_atendimento(p_conversa_ids uuid[]); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.excluir_conversas_profundo_para_atendimento(p_conversa_ids uuid[]) IS 'Exclusão em profundidade pelas UUIDs da tabela conversas: mensagens, ficha (fichas_lead), contratos, etc.; remove o lead se não persistir conversa. Permite tenant dono, membro de equipe (parent_user_id) ou platform_admin.';


--
-- Name: excluir_pergunta_mentor(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.excluir_pergunta_mentor(p_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_tenant uuid;
  v_uid    uuid := (SELECT auth.uid());
BEGIN
  SELECT tenant_id INTO v_tenant
    FROM public.perguntas_sem_resposta
    WHERE id = p_id;

  IF v_tenant IS NULL OR v_tenant <> v_uid THEN
    RETURN jsonb_build_object('ok', false, 'erro', 'sem permissão');
  END IF;

  DELETE FROM public.perguntas_sem_resposta WHERE id = p_id;

  RETURN jsonb_build_object('ok', true);
END;
$$;


ALTER FUNCTION public.excluir_pergunta_mentor(p_id uuid) OWNER TO postgres;

--
-- Name: existe_compromisso_ativo(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.existe_compromisso_ativo(p_conversation_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.acoes_agendadas sa
    WHERE sa.conversation_id = p_conversation_id AND sa.status IN ('pending','pendente')
      AND (sa.action_type IN ('agendamento_callback','agendamento_retorno','lembrete_retorno','iniciar_atendimento','retomada_planejada','agendar_compromisso')
           OR (sa.action_type IN ('cobranca_pagamento','cobranca_assinatura') AND sa.carga->>'origem' IN ('trigger_promessa_data','trigger_promessa_assinatura')))
      AND sa.scheduled_at > now()
  );
$$;


ALTER FUNCTION public.existe_compromisso_ativo(p_conversation_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION existe_compromisso_ativo(p_conversation_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.existe_compromisso_ativo(p_conversation_id uuid) IS 'Retorna TRUE se conversation tem scheduled_action pending de compromisso explícito (callback/retorno/cobrança-com-data-prometida) com data futura. Usada por cron-sweep-triggers-temporais e process-followups pra evitar atropelar compromisso já agendado pelo lead.';


--
-- Name: expirar_assinaturas(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.expirar_assinaturas() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
