  WHERE status IN ('active','ativa') AND data_expiracao < now();
END;
$$;


ALTER FUNCTION public.expirar_assinaturas() OWNER TO postgres;

--
-- Name: expirar_reservas_rifa(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.expirar_reservas_rifa() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_qtd integer;
begin
  with vencidos as (
    select id from public.pedidos_rifa
    where status = 'reservado' and expira_em is not null and expira_em < now()
  ), del as (
    delete from public.numeros_rifa
    where pedido_id in (select id from vencidos)
  )
  update public.pedidos_rifa
  set status = 'expirado', updated_at = now()
  where id in (select id from vencidos);
  get diagnostics v_qtd = row_count;
  return v_qtd;
end;
$$;


ALTER FUNCTION public.expirar_reservas_rifa() OWNER TO postgres;

--
-- Name: exportar_meus_dados(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.exportar_meus_dados() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_uid uuid := (SELECT auth.uid());
  v_result jsonb;
BEGIN
  SELECT jsonb_build_object(
    'profile', (
      SELECT row_to_json(p)::jsonb FROM public.profiles p WHERE p.id = v_uid
    ),
    'leads', (
      SELECT COALESCE(jsonb_agg(row_to_json(l)::jsonb), '[]'::jsonb)
      FROM public.leads l WHERE l.tenant_id = v_uid
    ),
    'contratos', (
      SELECT COALESCE(jsonb_agg(row_to_json(c)::jsonb), '[]'::jsonb)
      FROM public.contratos c WHERE c.tenant_id = v_uid
    ),
    'comissoes', (
      SELECT COALESCE(jsonb_agg(row_to_json(mc)::jsonb), '[]'::jsonb)
      FROM public.multinivel_comissoes mc WHERE mc.beneficiario_id = v_uid
    ),
    'saques', (
      SELECT COALESCE(jsonb_agg(row_to_json(ms)::jsonb), '[]'::jsonb)
      FROM public.multinivel_saques ms WHERE ms.user_id = v_uid
    ),
    'pedidos_compra', (
      SELECT COALESCE(jsonb_agg(row_to_json(po)::jsonb), '[]'::jsonb)
      FROM public.pedidos_compra po WHERE po.user_id = v_uid
    ),
    'activity_logs', (
      SELECT COALESCE(jsonb_agg(row_to_json(al)::jsonb), '[]'::jsonb)
      FROM public.activity_logs al WHERE al.user_id = v_uid
    ),
    'exported_at', now()::text
  ) INTO v_result;
  
  -- Log a exportacao
  INSERT INTO public.activity_logs (user_id, action, entity_type, metadata)
  VALUES (v_uid, 'export_data', 'profile', '{"type":"lgpd_export"}'::jsonb);
  
  RETURN v_result;
END;
$$;


ALTER FUNCTION public.exportar_meus_dados() OWNER TO postgres;

--
-- Name: extrair_pii_lead(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.extrair_pii_lead(p_lead_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_tenant_id uuid;
  v_tags      text[];
  v_tag       text;
  v_chave     text;
  v_valor     text;
  v_digitos   text;
  v_cpf       text := NULL;
  v_cnpj      text := NULL;
  v_novas     text[] := '{}';
  v_mascarado text;
BEGIN
  SELECT tenant_id, COALESCE(tags, '{}')
  INTO v_tenant_id, v_tags
  FROM public.leads WHERE id = p_lead_id AND deleted_at IS NULL;

  IF v_tenant_id IS NULL THEN RETURN; END IF;

  FOREACH v_tag IN ARRAY v_tags LOOP
    v_chave := split_part(v_tag, ':', 1);
    v_valor := substring(v_tag from position(':' in v_tag) + 1);
    v_digitos := regexp_replace(v_valor, '\D', '', 'g');

    IF v_chave IN ('cpf', 'documento_pessoal') AND length(v_digitos) = 11 THEN
      v_cpf := COALESCE(v_cpf, v_digitos);
      v_mascarado := public.mascarar_cpf(v_digitos);
      v_novas := array_append(v_novas, v_chave || ':' || v_mascarado);

    ELSIF v_chave = 'cnpj' AND length(v_digitos) = 14 THEN
      v_cnpj := COALESCE(v_cnpj, v_digitos);
      v_mascarado := public.mascarar_cnpj(v_digitos);
      v_novas := array_append(v_novas, v_chave || ':' || v_mascarado);

    ELSIF v_chave = 'documento' AND length(v_digitos) = 11 THEN
      v_cpf := COALESCE(v_cpf, v_digitos);
      v_mascarado := public.mascarar_cpf(v_digitos);
      v_novas := array_append(v_novas, v_chave || ':' || v_mascarado);

    ELSIF v_chave = 'documento' AND length(v_digitos) = 14 THEN
      v_cnpj := COALESCE(v_cnpj, v_digitos);
      v_mascarado := public.mascarar_cnpj(v_digitos);
      v_novas := array_append(v_novas, v_chave || ':' || v_mascarado);

    ELSE
      v_novas := array_append(v_novas, v_tag);
    END IF;
  END LOOP;

  IF v_cpf IS NOT NULL OR v_cnpj IS NOT NULL THEN
    INSERT INTO public.cofre_pii_lead (lead_id, tenant_id, cpf_real, cnpj_real, cpf_masked, cnpj_masked)
    VALUES (
      p_lead_id, v_tenant_id, v_cpf, v_cnpj,
      CASE WHEN v_cpf IS NOT NULL THEN public.mascarar_cpf(v_cpf) END,
      CASE WHEN v_cnpj IS NOT NULL THEN public.mascarar_cnpj(v_cnpj) END
    )
    ON CONFLICT (lead_id) DO UPDATE SET
      cpf_real    = COALESCE(EXCLUDED.cpf_real,   public.cofre_pii_lead.cpf_real),
      cnpj_real   = COALESCE(EXCLUDED.cnpj_real,  public.cofre_pii_lead.cnpj_real),
      cpf_masked  = COALESCE(EXCLUDED.cpf_masked,  public.cofre_pii_lead.cpf_masked),
      cnpj_masked = COALESCE(EXCLUDED.cnpj_masked, public.cofre_pii_lead.cnpj_masked),
      updated_at  = now();

    UPDATE public.leads SET tags = v_novas WHERE id = p_lead_id;
  END IF;
END;
$$;


ALTER FUNCTION public.extrair_pii_lead(p_lead_id uuid) OWNER TO postgres;

--
-- Name: falhas_agrupadas_periodo(integer, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.falhas_agrupadas_periodo(p_dias integer DEFAULT 7, p_tenant_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_resultado jsonb;
BEGIN
  PERFORM set_config('search_path', 'public', true);
  PERFORM set_config('statement_timeout', '5s', true);

  SELECT coalesce(jsonb_agg(t ORDER BY t.total DESC), '[]'::jsonb)
  INTO v_resultado
  FROM (
    SELECT motivo_falha,
           COUNT(*) AS total,
           array_agg(DISTINCT tenant_id) FILTER (WHERE tenant_id IS NOT NULL) AS tenants,
           array_agg(DISTINCT licao_gerada) FILTER (WHERE licao_gerada IS NOT NULL) AS licoes_geradas
    FROM public.registro_reflexao
    WHERE criado_em > now() - (p_dias || ' days')::interval
      AND deleted_at IS NULL
      AND (p_tenant_id IS NULL OR tenant_id = p_tenant_id)
    GROUP BY motivo_falha
    HAVING COUNT(*) >= 3
  ) t;

  RETURN v_resultado;
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('erro', SQLERRM);
END $$;


ALTER FUNCTION public.falhas_agrupadas_periodo(p_dias integer, p_tenant_id uuid) OWNER TO postgres;

