    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  UPDATE public.pilha_objetivos
  SET status = 'fechado', fechado_em = now(), motivo_fechamento = p_motivo
  WHERE id = p_objetivo_id AND status = 'aberto';
  RETURN FOUND;
END;
$$;


