CREATE TABLE public.automacao_blocos (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    nome text NOT NULL,
    descricao text NOT NULL,
    escopo text DEFAULT 'global'::text NOT NULL,
    nicho_id uuid,
    tenant_id uuid,
    cenario text NOT NULL,
    carga jsonb DEFAULT '{}'::jsonb NOT NULL,
    condicao_extra jsonb DEFAULT '{}'::jsonb NOT NULL,
    ativo boolean DEFAULT true NOT NULL,
    vetor_semantico extensions.halfvec(1024),
    embedding_status text DEFAULT 'pendente'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT automacao_blocos_embedding_status_check CHECK ((embedding_status = ANY (ARRAY['pendente'::text, 'processando'::text, 'pronto'::text, 'falhou'::text]))),
    CONSTRAINT automacao_chunks_cenario_check CHECK ((cenario = ANY (ARRAY['silencio_pos_fase'::text, 'nao_assinou_contrato'::text, 'nao_enviou_comprovante'::text, 'nao_respondeu_proposta'::text, 'despedida_sem_data'::text, 'recusa_baixa_intensidade'::text, 'qualquer'::text]))),
    CONSTRAINT automacao_chunks_escopo_check CHECK ((escopo = ANY (ARRAY['global'::text, 'nicho'::text, 'tenant'::text])))
);


ALTER TABLE public.automacao_blocos OWNER TO postgres;

