--
-- Name: blocos_gatilho; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.blocos_gatilho (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    nome_trigger text NOT NULL,
    exemplo_frase text NOT NULL,
    acao_disparada text NOT NULL,
    acao_payload jsonb DEFAULT '{}'::jsonb NOT NULL,
    escopo text DEFAULT 'global'::text NOT NULL,
    nicho_id uuid,
    tenant_id uuid,
    ativo boolean DEFAULT true NOT NULL,
    vetor_semantico extensions.halfvec(1024),
    embedding_status text DEFAULT 'pendente'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    categoria text,
    subcategoria text,
    condicao_tipo text DEFAULT 'frase'::text NOT NULL,
    tempo_aguardar_minutos integer,
    fase_aplicavel text,
    tipo_campanha text,
    objetivo_campanha text,
    cargo_id uuid,
    deleted_at timestamp with time zone,
    pacote_origem_id uuid,
    CONSTRAINT blocos_gatilho_embedding_status_check CHECK ((embedding_status = ANY (ARRAY['pendente'::text, 'processando'::text, 'pronto'::text, 'falhou'::text]))),
    CONSTRAINT trigger_chunks_condicao_tipo_check CHECK ((condicao_tipo = ANY (ARRAY['frase'::text, 'silencio_pos_fase'::text, 'nao_assinou_contrato'::text, 'nao_enviou_comprovante'::text, 'nao_respondeu_proposta'::text]))),
    CONSTRAINT trigger_chunks_escopo_check CHECK (((escopo IS NULL) OR (escopo = ANY (ARRAY['global'::text, 'nicho'::text, 'tenant'::text, 'produto'::text])))),
    CONSTRAINT trigger_chunks_objetivo_campanha_check CHECK ((objetivo_campanha = ANY (ARRAY['gerar_curiosidade'::text, 'educar_mercado'::text, 'coletar_lead'::text, 'apresentar_marca'::text, 'reativar_carrinho'::text, 'converter_lead_morno'::text, 'fechamento_direto'::text, 'upsell'::text, 'confirmar_satisfacao'::text, 'pedir_indicacao'::text, 'coletar_depoimento'::text, 'acompanhar_resultado'::text, 'lembrete_amigavel'::text, 'cobranca_firme'::text, 'renegociacao'::text, 'ultima_chance'::text, 'agendar_callback'::text, 'agendar_visita'::text, 'agendar_consulta'::text, 'confirmar_compromisso'::text, 'reagendar'::text]))),
    CONSTRAINT trigger_chunks_temporal_tempo_ck CHECK (((condicao_tipo = 'frase'::text) OR (tempo_aguardar_minutos IS NOT NULL))),
    CONSTRAINT trigger_chunks_tipo_campanha_check CHECK ((tipo_campanha = ANY (ARRAY['divulgacao'::text, 'venda'::text, 'pos_venda'::text, 'cobranca'::text, 'agendamento'::text])))
);


ALTER TABLE public.blocos_gatilho OWNER TO postgres;

