--
-- Name: vw_gatilhos_reativos; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.vw_gatilhos_reativos WITH (security_invoker='true') AS
 SELECT g.id,
    'gatilhos_reativos'::text AS origem,
    (g.escopo)::text AS escopo,
    g.tenant_id,
    g.nicho_id,
    g.cargo_id,
    g.cenario,
    g.acao_tipo,
    g.acao_carga,
    NULL::text AS exemplo_frase,
    g.ativo,
    g.criado_em
   FROM public.gatilhos_reativos g
  WHERE (g.ativo = true)
UNION ALL
 SELECT b.id,
    'blocos_gatilho'::text AS origem,
    b.escopo,
    b.tenant_id,
    b.nicho_id,
    b.cargo_id,
    COALESCE(b.categoria, b.nome_trigger) AS cenario,
    COALESCE(b.acao_disparada, 'prompt_bloco'::text) AS acao_tipo,
    (COALESCE(b.acao_payload, '{}'::jsonb) || jsonb_build_object('exemplo_frase', b.exemplo_frase, 'nome_trigger', b.nome_trigger, 'subcategoria', b.subcategoria, 'condicao_tipo', b.condicao_tipo, 'tempo_aguardar_minutos', b.tempo_aguardar_minutos)) AS acao_carga,
    b.exemplo_frase,
    b.ativo,
    b.created_at AS criado_em
   FROM public.blocos_gatilho b
  WHERE (b.ativo = true)
UNION ALL
 SELECT a.id,
    'automacao_blocos'::text AS origem,
    a.escopo,
    a.tenant_id,
    a.nicho_id,
    NULL::uuid AS cargo_id,
    a.cenario,
    'automacao'::text AS acao_tipo,
    (COALESCE(a.carga, '{}'::jsonb) || jsonb_build_object('condicao_extra', a.condicao_extra, 'descricao', a.descricao, 'nome', a.nome)) AS acao_carga,
    NULL::text AS exemplo_frase,
    a.ativo,
    a.created_at AS criado_em
   FROM public.automacao_blocos a
  WHERE (a.ativo = true);


ALTER VIEW public.vw_gatilhos_reativos OWNER TO postgres;

--
-- Name: VIEW vw_gatilhos_reativos; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON VIEW public.vw_gatilhos_reativos IS 'Onda 5 fatia 3 — adapter unificado: gatilhos_reativos ∪ blocos_gatilho ∪ automacao_blocos. Uso: workers do loop LLM-OS lêem aqui em vez de varrer 3 tabelas.';


--
-- Name: fn_buscar_gatilhos_reativos(uuid, uuid, text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_buscar_gatilhos_reativos(p_tenant_id uuid, p_cargo_id uuid DEFAULT NULL::uuid, p_cenario text DEFAULT NULL::text, p_limite integer DEFAULT 50) RETURNS SETOF public.vw_gatilhos_reativos
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT *
  FROM public.vw_gatilhos_reativos v
  WHERE
    -- escopo: global (sem tenant) OU pertence ao tenant
    (v.tenant_id IS NULL OR v.tenant_id = p_tenant_id)
    AND (p_cargo_id IS NULL OR v.cargo_id IS NULL OR v.cargo_id = p_cargo_id)
    AND (p_cenario IS NULL OR v.cenario ILIKE p_cenario)
  ORDER BY
    -- prioridade: tenant-específico > nicho > global
    CASE WHEN v.tenant_id = p_tenant_id THEN 0
         WHEN v.nicho_id IS NOT NULL THEN 1
         ELSE 2 END,
    v.criado_em DESC
  LIMIT GREATEST(1, LEAST(p_limite, 200));
$$;


ALTER FUNCTION public.fn_buscar_gatilhos_reativos(p_tenant_id uuid, p_cargo_id uuid, p_cenario text, p_limite integer) OWNER TO postgres;

--
-- Name: FUNCTION fn_buscar_gatilhos_reativos(p_tenant_id uuid, p_cargo_id uuid, p_cenario text, p_limite integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_buscar_gatilhos_reativos(p_tenant_id uuid, p_cargo_id uuid, p_cenario text, p_limite integer) IS 'Onda 5 fatia 3 — busca gatilhos reativos do escopo (tenant>nicho>global), opcionalmente filtrados por cargo e cenário.';


--
-- Name: fn_dossie_lead_consolidado(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_dossie_lead_consolidado(p_lead_id uuid, p_conversa_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE resultado jsonb;
DECLARE conv_efetiva uuid;
BEGIN
  -- Guard de posse: sem isto, qualquer usuário logado lia o lead de outro tenant
  -- passando o id alheio (raio-x 2026-09-04, P1 "residual cross-tenant entre logados").
  IF NOT public._lead_pertence_caller(p_lead_id) THEN
    RAISE EXCEPTION 'sem permissão para este lead' USING ERRCODE = '42501';
  END IF;

  -- p_conversa_id só vale se a conversa for DESTE lead; id alheio cai no fallback
  -- em vez de vazar as mensagens da conversa de outro tenant.
  conv_efetiva := COALESCE(
    (SELECT id FROM public.conversas WHERE id = p_conversa_id AND lead_id = p_lead_id),
    (SELECT id FROM public.conversas
      WHERE lead_id = p_lead_id
      ORDER BY updated_at DESC NULLS LAST, created_at DESC
      LIMIT 1)
  );

  SELECT jsonb_build_object(
    'lead', (
      SELECT jsonb_build_object(
        'id', l.id, 'nome_exibicao', l.nome_exibicao, 'name', l.name,
        'phone', l.phone, 'email', l.email,
        'tags', COALESCE(l.tags, ARRAY[]::text[]),
        'dados_ficha', COALESCE(l.dados_ficha, '{}'::jsonb),
        'fase_pipeline', l.fase_pipeline, 'temperatura_lead', l.temperatura_lead,
        'criado_em', l.created_at,
        'divida_total', l.divida_total, 'produto', l.produto,
        'fase_cliente', l.fase_cliente, 'client_checkpoints', l.client_checkpoints,
        'tarefas_cliente', l.tarefas_cliente, 'perfil_estilo', l.perfil_estilo,
        'custom_fields', l.custom_fields, 'origem_lead', l.origem_lead,
        'pontuacao', l.pontuacao, 'converted_at', l.converted_at,
        'url_foto_perfil', l.url_foto_perfil, 'location', l.location,
        'first_contact_at', (SELECT MIN(created_at) FROM public.mensagens m WHERE m.conversation_id IN (SELECT id FROM public.conversas WHERE lead_id = p_lead_id))
      )
      FROM public.leads l WHERE l.id = p_lead_id
    ),
    'fatos', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'id', id, 'fato', fato, 'categoria', categoria, 'relevancia', relevancia,
        'confianca', confianca, 'valido_desde', valido_desde,
        'criado_em', criado_em, 'escopo', escopo
      ) ORDER BY CASE relevancia WHEN 'alta' THEN 3 WHEN 'media' THEN 2 ELSE 1 END * confianca DESC, criado_em DESC)
      FROM public.memoria_lead WHERE lead_id = p_lead_id AND ativa = true LIMIT 10
    ), '[]'::jsonb),
    'episodios', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'id', id, 'episodio_resumo', episodio_resumo, 'gancho', gancho,
        'emocao', emocao, 'outcome', outcome, 'decay_factor', decay_factor,
        'relevancia', relevancia, 'turno_inicio', turno_inicio, 'turno_fim', turno_fim,
        'criado_em', criado_em
      ) ORDER BY criado_em DESC)
      FROM public.memoria_episodica WHERE lead_id = p_lead_id AND ativa = true AND decay_factor > 0.1 LIMIT 10
    ), '[]'::jsonb),
    'compromissos_ativos', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'id', ca.id, 'tipo', ca.tipo, 'origem', ca.origem, 'origem_tabela', ca.origem_tabela,
        'titulo', ca.titulo, 'executar_em', ca.executar_em, 'status', ca.status,
        'conversa_id', ca.conversa_id
      ) ORDER BY ca.executar_em ASC)
      FROM public.compromissos_ativos ca
      WHERE ca.conversa_id IN (SELECT id FROM public.conversas WHERE lead_id = p_lead_id)
    ), '[]'::jsonb),
    'contratos', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'id', id, 'titulo', titulo, 'chave_publica', chave_publica, 'status', status,
        'assinado_em', assinado_em, 'criado_em', created_at,
        'metodo_pagamento', metodo_pagamento, 'opcoes_pagamento', opcoes_pagamento,
        'url_comprovante_pagamento', url_comprovante_pagamento
      ) ORDER BY created_at DESC)
      FROM public.contratos WHERE lead_id = p_lead_id
    ), '[]'::jsonb),
    'campanhas', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'id', lc.id, 'campanha_id', lc.campaign_id, 'campanha_nome', c.name,
        'fase_atual', lc.phase, 'status', lc.state, 'criado_em', lc.entered_at
      ) ORDER BY lc.entered_at DESC)
      FROM public.leads_campanha lc
      JOIN public.campanhas c ON c.id = lc.campaign_id
      WHERE lc.lead_id = p_lead_id AND lc.archived_at IS NULL
    ), '[]'::jsonb),
    'anexos', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'id', m.id, 'role', m.role, 'tipo', m.carga->>'media_type',
        'media_url', m.carga->>'media_url', 'categoria_anexo', m.categoria_anexo,
        'content', m.content, 'criado_em', m.created_at
      ) ORDER BY m.created_at DESC)
      FROM public.mensagens m
      WHERE m.conversation_id IN (SELECT id FROM public.conversas WHERE lead_id = p_lead_id)
        AND m.categoria_anexo IS NOT NULL AND m.deleted_at IS NULL
      LIMIT 30
    ), '[]'::jsonb),
    'crenca_conversa', (
      SELECT jsonb_build_object(
        'belief', belief, 'resumo_agente', resumo_agente, 'proxima_intencao', proxima_intencao,
        'proximo_passo_previsto', proximo_passo_previsto, 'estilo_lead', estilo_lead,
        'updated_at', updated_at
      )
      FROM public.crenca_conversa
      WHERE conversation_id = conv_efetiva
      ORDER BY updated_at DESC NULLS LAST LIMIT 1
    ),
    'pensamento_atual', (
      SELECT dados FROM public.intencoes_pendentes
      WHERE conversa_id = conv_efetiva
      ORDER BY criado_em DESC LIMIT 1
    ),
    'cargo_ativo', (
      SELECT jsonb_build_object(
        'id', c.id, 'nome', c.nome, 'tipologia', c.tipologia,
        'objetivo_principal', c.objetivo_principal, 'regras_livres', c.regras_livres,
        'campos_rastreio', c.campos_rastreio
      )
      FROM public.cargos c
      WHERE c.id = (SELECT cargo_ativo_id FROM public.conversas WHERE id = conv_efetiva)
    ),
    'engajamento', (
      SELECT jsonb_build_object(
        'nivel', nivel, 'pontuacao', pontuacao, 'velocidade_media_s', velocidade_media_s,
        'comprimento_medio', comprimento_medio, 'conversas_count', conversas_count,
        'tendencia', tendencia, 'ultima_atualizacao', ultima_atualizacao
      )
      FROM public.engajamento_lead WHERE lead_id = p_lead_id LIMIT 1
    ),
    'conversa_ativa_id', conv_efetiva,
    'gerado_em', now()
  ) INTO resultado;

  RETURN resultado;
END;
$$;


ALTER FUNCTION public.fn_dossie_lead_consolidado(p_lead_id uuid, p_conversa_id uuid) OWNER TO postgres;

--
-- Name: fn_notificar_msg_conversa(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_notificar_msg_conversa() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_tenant uuid;
  v_resp uuid;
  v_lead uuid;
  v_status text;
  v_agent_on boolean;
  v_channel text;
  v_precisa_humano boolean;
  v_dest uuid;
  v_tipo text;
  v_titulo text;
  v_msg text;
  v_nome text;
  v_foto text;
  v_midia_url text;
  v_midia_tipo text;
  v_mtipo_raw text;
BEGIN
  IF NEW.role <> 'user' THEN
    RETURN NEW;
  END IF;

  SELECT c.tenant_id, c.responsavel_id, c.lead_id, c.status, c.agent_enabled, c.channel
    INTO v_tenant, v_resp, v_lead, v_status, v_agent_on, v_channel
  FROM public.conversas c
  WHERE c.id = NEW.conversation_id;

  IF v_tenant IS NULL THEN
    RETURN NEW;
  END IF;

  -- Chat-Teste é ambiente isolado: conversas channel='teste' não geram notificação.
  IF v_channel = 'teste' THEN
    RETURN NEW;
  END IF;

  -- v5: identidade do contato (nome no título + foto do WhatsApp).
  SELECT l.precisa_humano,
         coalesce(
           nullif(btrim(l.nome_exibicao), ''),
           nullif(btrim(l.name), ''),
           nullif(btrim(l.nome_provedor), '')
         ),
         nullif(btrim(l.url_foto_perfil), '')
    INTO v_precisa_humano, v_nome, v_foto
  FROM public.leads l
  WHERE l.id = v_lead;

  IF v_precisa_humano IS TRUE THEN
    v_tipo := 'handoff';
  ELSIF v_status = 'humano' OR v_agent_on IS FALSE THEN
    v_tipo := 'conversa_humana';
  ELSE
    v_tipo := 'conversa_mensagem';
  END IF;

  v_titulo := coalesce(v_nome, 'Novo contato');
  v_dest := coalesce(v_resp, v_tenant);

  -- v6: mídia da mensagem. Quando há anexo, a notificação carrega a URL + tipo
  -- normalizado e usa a transcrição/legenda como texto (não o placeholder
  -- [MEDIA_RECEBIDA]). Texto comum segue como trecho de 120 chars.
  IF NEW.carga ? 'media_url' THEN
    v_midia_url := nullif(btrim(NEW.carga->>'media_url'), '');
    v_mtipo_raw := lower(coalesce(NEW.carga->>'media_type', ''));
    v_midia_tipo := CASE
      WHEN v_mtipo_raw LIKE 'image%' THEN 'image'
      WHEN v_mtipo_raw LIKE 'audio%' THEN 'audio'
      WHEN v_mtipo_raw LIKE 'video%' THEN 'video'
      ELSE 'document'
    END;
    v_msg := nullif(btrim(NEW.carga->>'media_descricao'), '');
  ELSE
    v_midia_url := NULL;
    v_midia_tipo := NULL;
    v_msg := left(coalesce(NEW.content, ''), 120);
  END IF;

  INSERT INTO public.notificacoes
    (user_id, tipo, icone, titulo, mensagem, acao, acao_label, lida, foto_url, midia_url, midia_tipo)
  VALUES
    (v_dest, v_tipo, 'whatsapp', v_titulo, v_msg, 'conversas', 'Abrir conversa', false, v_foto, v_midia_url, v_midia_tipo);

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_notificar_msg_conversa() OWNER TO postgres;

--
-- Name: fn_rate_limit_consumir(uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_rate_limit_consumir(_tenant_id uuid, _limite_por_min integer DEFAULT 60) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _janela timestamptz := date_trunc('minute', now());
  _atual integer;
BEGIN
  INSERT INTO public.rate_limit_tenant (tenant_id, janela, contador)
  VALUES (_tenant_id, _janela, 1)
  ON CONFLICT (tenant_id, janela)
  DO UPDATE SET contador = public.rate_limit_tenant.contador + 1
  RETURNING contador INTO _atual;
  RETURN _atual <= _limite_por_min;
END;
$$;


