-- Name: fn_rifa_ativada_aplica_fixos(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_rifa_ativada_aplica_fixos() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if new.status = 'ativa' and (tg_op = 'INSERT' or old.status is distinct from 'ativa') then
    perform public.sincronizar_numeros_fixos_rifa(new.id);
  end if;
  return new;
end;
$$;


