--
-- Name: fn_rifas_gerar_codigo_controle(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_rifas_gerar_codigo_controle() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_prefixo text;
  v_seq int;
BEGIN
  IF NEW.codigo_controle IS NOT NULL THEN
    RETURN NEW;
  END IF;

  v_prefixo := 'R' || to_char(now() AT TIME ZONE 'America/Sao_Paulo', 'DDMMYY');

  SELECT COALESCE(MAX((substring(codigo_controle from 8 for 2))::int), -1) + 1
    INTO v_seq
    FROM public.rifas
    WHERE tenant_id = NEW.tenant_id
      AND codigo_controle LIKE v_prefixo || '%';

  NEW.codigo_controle := v_prefixo || lpad(v_seq::text, 2, '0');
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_rifas_gerar_codigo_controle() OWNER TO postgres;

--
-- Name: fn_sanitizar_resposta_mentor(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_sanitizar_resposta_mentor() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $_$
declare
  v text;
begin
  if new.papel <> 'assistant' or new.conteudo is null or new.conteudo = '' then
    return new;
  end if;
  v := new.conteudo;
  v := regexp_replace(v, '\s*isso responde [àa] pergunta\.?', '', 'gi');
  v := regexp_replace(v, '^.*posso ignorar( silenciosamente)?.*$', '', 'gin');
  v := regexp_replace(v, '^\s*o prompt (de |do )?sistema (diz|pede|manda).*$', '', 'gin');
  v := regexp_replace(v, '^\s*portanto: ["“].*$', '', 'gin');
  v := regexp_replace(v, '^\s*conforme (o prompt|as regras|as instru[cç][oõ]es).*$', '', 'gin');
  v := regexp_replace(v, '^.*obedi[êe]ncia cega.*$', '', 'gin');
  v := regexp_replace(v, '^\s*(o|a) (kpi|tool|ferramenta|consulta) (foi|j[áa] foi) (chamad|execut|realizad).*$', '', 'gin');
  v := regexp_replace(v, '^\s*(devo|vou) (responder|entregar|seguir|passar) (exatamente|s[óo]|apenas|somente).*$', '', 'gin');
  v := regexp_replace(v, E'\n{3,}', E'\n\n', 'g');
  v := btrim(v);
  if v <> '' then
    new.conteudo := v;
  end if;
  return new;
end;
$_$;


ALTER FUNCTION public.fn_sanitizar_resposta_mentor() OWNER TO postgres;

--
-- Name: fn_saude_motor(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_saude_motor() RETURNS TABLE(fila text, pendentes bigint, ultimo_evento timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pgmq'
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    q.queue_name::text,
    coalesce(m.queue_length, 0)::bigint,
    m.newest_msg_age_sec::timestamptz
  FROM pgmq.list_queues() q
  LEFT JOIN LATERAL (SELECT * FROM pgmq.metrics(q.queue_name)) m ON true
  WHERE q.queue_name LIKE 'fila_%';
EXCEPTION WHEN OTHERS THEN RETURN;
END;
$$;


ALTER FUNCTION public.fn_saude_motor() OWNER TO postgres;

--
-- Name: fn_sincronizar_acao_agendada_para_compromisso(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_sincronizar_acao_agendada_para_compromisso() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_descricao text;
  v_tenant_id uuid;
  v_eh_compromisso boolean;
  v_origem text;
  v_assunto text;
  v_angulo text;
BEGIN
  v_origem := NEW.carga->>'origem';
  v_eh_compromisso := NEW.action_type IN (
    'agendamento_callback','agendamento_retorno','lembrete_retorno',
    'iniciar_atendimento','planejar_retomada','retomada_planejada'
  );
  IF NOT v_eh_compromisso AND NEW.action_type IN ('cobranca_pagamento','cobranca_assinatura') THEN
    v_eh_compromisso := v_origem IN ('trigger_promessa_data','trigger_promessa_assinatura');
  END IF;
  IF NOT v_eh_compromisso THEN RETURN NEW; END IF;
  IF NEW.scheduled_at IS NULL THEN RETURN NEW; END IF;

  v_tenant_id := NEW.tenant_id;
  IF v_tenant_id IS NULL AND NEW.conversation_id IS NOT NULL THEN
    SELECT c.tenant_id INTO v_tenant_id FROM public.conversas c WHERE c.id = NEW.conversation_id;
  END IF;
  IF v_tenant_id IS NULL THEN RETURN NEW; END IF;

  v_assunto := NEW.carga->>'assunto';
  v_angulo := NEW.carga->>'angulo';

  v_descricao := CASE NEW.action_type
    WHEN 'agendamento_callback' THEN 'Retorno agendado' || coalesce(' · ' || (NEW.carga->>'data_original'), '')
    WHEN 'agendamento_retorno' THEN 'Retorno agendado' || coalesce(' · ' || (NEW.carga->>'data_original'), '') || coalesce(' · ' || (NEW.carga->>'motivo'), '')
    WHEN 'lembrete_retorno' THEN 'Lembrete antes do callback'
    WHEN 'iniciar_atendimento' THEN 'Iniciar atendimento'
    WHEN 'cobranca_pagamento' THEN 'Pagamento prometido pelo lead' || coalesce(' · ' || (NEW.carga->>'tom'), '')
    WHEN 'cobranca_assinatura' THEN 'Assinatura prometida pelo lead' || coalesce(' · ' || (NEW.carga->>'tom'), '')
    WHEN 'planejar_retomada' THEN 'Avaliando retomada' || coalesce(' · ' || (NEW.carga->>'condicao_tipo'), '')
    WHEN 'retomada_planejada' THEN 'Retomada planejada' || coalesce(' · ' || v_assunto, '') || coalesce(' (' || v_angulo || ')', '')
    ELSE 'Compromisso'
  END;

  IF NEW.carga->>'descricao' IS NOT NULL THEN
    v_descricao := NEW.carga->>'descricao';
  END IF;

  IF TG_OP = 'INSERT' THEN
    INSERT INTO public.compromissos (conversation_id, lead_id, tenant_id, descricao, scheduled_at, origem, status, scheduled_action_id)
    VALUES (NEW.conversation_id, NEW.lead_id, v_tenant_id, v_descricao, NEW.scheduled_at, 'autonomo', 'pendente', NEW.id)
    ON CONFLICT (scheduled_action_id) WHERE scheduled_action_id IS NOT NULL DO NOTHING;
  ELSIF TG_OP = 'UPDATE' THEN
    IF NEW.status IS DISTINCT FROM OLD.status THEN
      IF NEW.status IN ('executed','done','executado') THEN
        UPDATE public.compromissos SET status = 'cumprido', cumprido_em = coalesce(NEW.executed_at, now())
        WHERE scheduled_action_id = NEW.id AND status = 'pendente';
      ELSIF NEW.status IN ('cancelled','cancelado') THEN
        UPDATE public.compromissos SET status = 'cancelado'
        WHERE scheduled_action_id = NEW.id AND status = 'pendente';
      END IF;
    END IF;
    IF NEW.scheduled_at IS DISTINCT FROM OLD.scheduled_at THEN
      UPDATE public.compromissos SET scheduled_at = NEW.scheduled_at, descricao = v_descricao
      WHERE scheduled_action_id = NEW.id AND status = 'pendente';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_sincronizar_acao_agendada_para_compromisso() OWNER TO postgres;

--
-- Name: fn_sou_dono_do_agente(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_sou_dono_do_agente(p_agente uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (
    select 1 from public.agentes a
    where a.id = p_agente and a.user_id = (select auth.uid())
  )
$$;


ALTER FUNCTION public.fn_sou_dono_do_agente(p_agente uuid) OWNER TO postgres;

--
-- Name: fn_sou_gestor_delegado(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_sou_gestor_delegado(p_agente uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (
    select 1 from public.agentes_delegados d
    where d.agente_id = p_agente and d.gestor_user_id = (select auth.uid())
  )
$$;


ALTER FUNCTION public.fn_sou_gestor_delegado(p_agente uuid) OWNER TO postgres;

--
-- Name: fn_tag_mentor_mensagem(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_tag_mentor_mensagem() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  new.tags := public.fn_tags_do_texto(coalesce(new.conteudo, ''));
  return new;
end
$$;


ALTER FUNCTION public.fn_tag_mentor_mensagem() OWNER TO postgres;

--
-- Name: fn_tags_do_texto(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_tags_do_texto(p_texto text) RETURNS text[]
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select coalesce(array_agg(tag order by tag), '{}')
  from public.mentor_tag_regras
  where p_texto ~* padrao
$$;


ALTER FUNCTION public.fn_tags_do_texto(p_texto text) OWNER TO postgres;

--
-- Name: fn_trg_registrar_cruzamento_score_faixa(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_trg_registrar_cruzamento_score_faixa() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_faixa_antiga text; v_faixa_nova text;
BEGIN
  IF NEW.score_lead IS NULL OR NEW.tenant_id IS NULL THEN RETURN NEW; END IF;
  v_faixa_nova := public.score_lead_faixa(NEW.score_lead);
  v_faixa_antiga := CASE WHEN OLD.score_lead IS NULL THEN NULL ELSE public.score_lead_faixa(OLD.score_lead) END;
  IF v_faixa_antiga IS DISTINCT FROM v_faixa_nova THEN
    BEGIN INSERT INTO public.gatilhos_score_lead (conversa_id, lead_id, tenant_id, score, faixa_anterior, faixa_nova)
      VALUES (NEW.id, NEW.lead_id, NEW.tenant_id, NEW.score_lead, v_faixa_antiga, v_faixa_nova);
    EXCEPTION WHEN OTHERS THEN NULL; END;
  END IF;
  RETURN NEW;
END; $$;


ALTER FUNCTION public.fn_trg_registrar_cruzamento_score_faixa() OWNER TO postgres;

--
-- Name: garantir_categorias_padrao(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.garantir_categorias_padrao(p_tenant_id uuid DEFAULT NULL::uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_tenant uuid := COALESCE((SELECT auth.uid()), p_tenant_id);
  v_qtd int := 0;
BEGIN
  -- Tranca de identidade (2026-09-08): não pode viver só no GRANT.
  PERFORM public.tenant_efetivo(p_tenant_id);
  IF v_tenant IS NULL THEN
    RAISE EXCEPTION 'tenant obrigatório';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.categorias_financeiras WHERE tenant_id = v_tenant AND deleted_at IS NULL) THEN
    INSERT INTO public.categorias_financeiras (tenant_id, nome)
    VALUES (v_tenant, 'Casa'), (v_tenant, 'Empresa'), (v_tenant, 'Transporte'),
           (v_tenant, 'Alimentação'), (v_tenant, 'Contas'), (v_tenant, 'Investimento');
    GET DIAGNOSTICS v_qtd = ROW_COUNT;
  END IF;
  RETURN v_qtd;
END;
$$;


ALTER FUNCTION public.garantir_categorias_padrao(p_tenant_id uuid) OWNER TO postgres;

--
-- Name: gatilho_re_atomizar_empresa(); Type: FUNCTION; Schema: public; Owner: postgres
