-- Name: FUNCTION gatilho_re_atomizar_empresa(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.gatilho_re_atomizar_empresa() IS 'Bloco 3.5 — registra em chunk_audit_log quando campos-chave de empresas mudam, sinalizando re-atomização pendente via cron-atomizar-empresa.';


--
-- Name: gerar_contrato_do_template(uuid, uuid, jsonb, uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.gerar_contrato_do_template(p_conversa_id uuid, p_template_id uuid DEFAULT NULL::uuid, p_dados_cliente jsonb DEFAULT '{}'::jsonb, p_tenant_id uuid DEFAULT NULL::uuid, p_lead_id uuid DEFAULT NULL::uuid, p_agente_id uuid DEFAULT NULL::uuid) RETURNS TABLE(contrato_id uuid, chave_publica uuid, nome_template text, total numeric, qtd_itens integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
  v_tenant uuid;
  v_lead uuid;
  v_agente uuid;
  v_tpl public.contratos_template%ROWTYPE;
  v_cfg public.config_contrato%ROWTYPE;
  v_texto text;
  v_tok text;
  v_total numeric := 0;
  v_total_carrinho numeric := 0;
  v_qtd integer := 0;
  v_itens_txt text;
  v_bloco_itens text := '';
  v_parc jsonb;
  v_entrada numeric;
  v_parcelas integer;
  v_valor_parc numeric;
  v_total_parc numeric := 0;
  v_contrato_id uuid;
  v_chave uuid;
  v_cond_full text;
  v_var_avista text;
  v_var_parc text;
  v_inerte text;
  v_clausulas text := '';
  v_dados_pag jsonb;
  v_itens_calc jsonb;
  v_planos jsonb := NULL;
  v_sep jsonb;
  -- F3a:
  v_campos_form jsonb;
  v_exig jsonb;
  v_exig_selfie_prod boolean := false;
  v_exig_test_prod int := 0;
  v_exig_instr_prod text := NULL;
  v_num_testemunhas int;
  v_instrucao_selfie text;
  -- F3c: documento + canvas de assinatura por produto
  v_exig_doc_prod boolean := false;
  v_exig_assin_prod boolean := false;
  v_campos_obrig text[];
  -- 2026-09-17: produto com opções nomeadas (total depende da opção escolhida)
  v_tem_nomeadas boolean := false;
BEGIN
  IF p_conversa_id IS NULL THEN
    RAISE EXCEPTION 'conversa_id obrigatório para gerar contrato';
  END IF;

  SELECT c.tenant_id, c.lead_id, c.agente_id
    INTO v_tenant, v_lead, v_agente
  FROM public.conversas c
  WHERE c.id = p_conversa_id;

  v_tenant := COALESCE(p_tenant_id, v_tenant);
  v_lead   := COALESCE(p_lead_id, v_lead);
  v_agente := COALESCE(p_agente_id, v_agente);

  IF v_tenant IS NULL THEN
    RAISE EXCEPTION 'Conversa % não encontrada ou sem tenant', p_conversa_id;
  END IF;

  SELECT * INTO v_cfg FROM public.config_contrato cc WHERE cc.tenant_id = v_tenant;

  IF p_template_id IS NOT NULL THEN
    SELECT t.* INTO v_tpl
    FROM public.contratos_template t
    WHERE t.id = p_template_id AND t.user_id = v_tenant AND t.ativo = true;
  END IF;

  IF v_tpl.id IS NULL THEN
    SELECT t.* INTO v_tpl
    FROM public.contratos_template t
    WHERE t.user_id = v_tenant AND t.ativo = true
    ORDER BY
      (t.produto_id IN (SELECT cc.produto_id FROM public.carrinho_da_conversa cc WHERE cc.conversa_id = p_conversa_id)) DESC,
      (t.produto_id IS NULL) DESC,
      t.created_at ASC
    LIMIT 1;
  END IF;

  IF v_tpl.id IS NULL THEN
    RAISE EXCEPTION 'Nenhum molde de contrato ativo para este tenant. Configure um template em /agente antes de gerar contrato.';
  END IF;

  SELECT COALESCE(SUM(cc.quantidade * COALESCE(p.preco_centavos::numeric / 100, cc.preco_unitario)), 0), COUNT(*)
    INTO v_total_carrinho, v_qtd
  FROM public.carrinho_da_conversa cc
  LEFT JOIN public.produtos p ON p.id = cc.produto_id
  WHERE cc.conversa_id = p_conversa_id;

  v_total := CASE WHEN v_total_carrinho > 0 THEN v_total_carrinho ELSE COALESCE(v_tpl.valor_a_vista, 0) END;
  IF v_total_carrinho <= 0 THEN
    RAISE LOG 'gerar_contrato_do_template: fallback_molde usado (conversa=%, tenant=%)', p_conversa_id, v_tenant;
  END IF;

  IF v_qtd > 0 THEN
    SELECT string_agg(
      '- ' || to_char(cc.quantidade, 'FM999999990') || 'x ' || COALESCE(p.nome, 'Item')
      || CASE WHEN COALESCE(p.preco_centavos::numeric / 100, cc.preco_unitario) > 0
              THEN ' — R$ ' || replace(to_char(round(COALESCE(p.preco_centavos::numeric / 100, cc.preco_unitario), 2), 'FM999999990.00'), '.', ',')
                   || ' (subtotal R$ ' || replace(to_char(round(cc.quantidade * COALESCE(p.preco_centavos::numeric / 100, cc.preco_unitario), 2), 'FM999999990.00'), '.', ',') || ')'
              ELSE '' END,
      E'\n' ORDER BY cc.adicionado_em)
      INTO v_itens_txt
    FROM public.carrinho_da_conversa cc
    LEFT JOIN public.produtos p ON p.id = cc.produto_id
    WHERE cc.conversa_id = p_conversa_id;

    SELECT (COUNT(*) = 1 AND bool_and(cc.quantidade = 1 AND jsonb_array_length(COALESCE(p.opcoes_pagamento, '[]'::jsonb)) > 0))
      INTO v_tem_nomeadas
    FROM public.carrinho_da_conversa cc
    JOIN public.produtos p ON p.id = cc.produto_id
    WHERE cc.conversa_id = p_conversa_id;

    IF COALESCE(v_tem_nomeadas, false) THEN
      SELECT 'ITENS CONTRATADOS' || E'\n' || '- 1x ' || COALESCE(p.nome, 'Item')
             || E'\n\n' || 'VALOR: conforme a forma de pagamento escolhida, descrita na cláusula de pagamento.'
        INTO v_bloco_itens
      FROM public.carrinho_da_conversa cc
      JOIN public.produtos p ON p.id = cc.produto_id
      WHERE cc.conversa_id = p_conversa_id
      LIMIT 1;
    ELSE
      v_bloco_itens := 'ITENS CONTRATADOS' || E'\n' || COALESCE(v_itens_txt, '')
        || E'\n\n' || 'VALOR TOTAL: R$ ' || replace(to_char(round(v_total, 2), 'FM999999990.00'), '.', ',');
    END IF;
  END IF;

  v_parc := COALESCE(v_tpl.opcoes_parcelamento -> 0, '{}'::jsonb);
  v_entrada    := NULLIF(v_parc ->> 'entrada', '')::numeric;
  v_parcelas   := NULLIF(v_parc ->> 'parcelas', '')::integer;
  v_valor_parc := NULLIF(v_parc ->> 'valor_parcela', '')::numeric;
  v_total_parc := COALESCE(v_entrada, 0) + COALESCE(v_parcelas, 0) * COALESCE(v_valor_parc, 0);

  v_texto := CASE
    WHEN v_tpl.conteudo_comum IS NOT NULL AND left(ltrim(v_tpl.conteudo_comum), 9) = '{"type":"'
      THEN COALESCE(NULLIF(v_tpl.conteudo, ''), '')
    ELSE COALESCE(NULLIF(v_tpl.conteudo_comum, ''), v_tpl.conteudo, '')
  END;

  IF position('{COND_PAGAMENTO}' IN v_texto) > 0 THEN
    v_cond_full := substring(v_texto from '\{COND_PAGAMENTO\}[\s\S]*?\{/COND_PAGAMENTO\}');
    IF v_cond_full IS NOT NULL THEN
      v_var_avista := substring(v_cond_full from '\{SE_A_VISTA\}([\s\S]*?)\{/SE_A_VISTA\}');
      v_var_parc   := substring(v_cond_full from '\{SE_PARCELADO\}([\s\S]*?)\{/SE_PARCELADO\}');
      IF v_var_avista IS NULL AND v_var_parc IS NULL THEN
        v_var_avista := substring(v_cond_full from '\{COND_PAGAMENTO\}([\s\S]*?)\{/COND_PAGAMENTO\}');
        v_var_parc   := v_var_avista;
      END IF;
      v_texto := replace(v_texto, v_cond_full, '@@COND_PAGAMENTO_INERTE@@');
    END IF;
  END IF;

  v_texto := replace(v_texto, '{SE_A_VISTA}', '');
  v_texto := replace(v_texto, '{/SE_A_VISTA}', '');
  v_texto := replace(v_texto, '{SE_PARCELADO}', '');
  v_texto := replace(v_texto, '{/SE_PARCELADO}', '');

  v_texto := replace(v_texto, '{PRODUTO_PRECO}',
    'R$ ' || replace(to_char(round(COALESCE(v_tpl.valor_a_vista, v_total), 2), 'FM999999990.00'), '.', ','));
  v_texto := replace(v_texto, '{CHAVE_PIX}', COALESCE(v_tpl.chave_pix, ''));
  v_texto := replace(v_texto, '{LINK_PAGAMENTO}', COALESCE(v_tpl.link_parcelamento, ''));
  v_texto := replace(v_texto, '{VALOR_ENTRADA}',
    CASE WHEN v_entrada IS NULL THEN '' ELSE 'R$ ' || replace(to_char(round(v_entrada, 2), 'FM999999990.00'), '.', ',') END);
  v_texto := replace(v_texto, '{NUMERO_PARCELAS}', COALESCE(v_parcelas::text, ''));
  v_texto := replace(v_texto, '{VALOR_PARCELA}',
    CASE WHEN v_valor_parc IS NULL THEN '' ELSE 'R$ ' || replace(to_char(round(v_valor_parc, 2), 'FM999999990.00'), '.', ',') END);
  v_texto := replace(v_texto, '{TOTAL_PARCELADO}',
    CASE WHEN v_total_parc = 0 THEN '' ELSE 'R$ ' || replace(to_char(round(v_total_parc, 2), 'FM999999990.00'), '.', ',') END);

  v_texto := replace(v_texto, '{TOTAL_AVISTA}',
    'R$ ' || replace(to_char(round(v_total, 2), 'FM999999990.00'), '.', ','));

  -- F3a: cláusulas — miolo do PRODUTO vence o jsonb do molde; calculadas SEMPRE.
  IF v_qtd > 0 THEN
    SELECT COALESCE(string_agg(
             replace(
               replace(
                 replace(
                   COALESCE(NULLIF(p.clausulas_contrato, ''), v_tpl.clausulas_por_produto ->> cc.produto_id::text, ''),
                   '{PRODUTO_NOME}', COALESCE(p.nome, 'Item')
                 ),
                 '{PRODUTO_QTD}', to_char(cc.quantidade, 'FM999999990')
               ),
               '{PRODUTO_PRECO_AVISTA}',
               'R$ ' || replace(to_char(round(COALESCE(p.preco_centavos::numeric / 100, cc.preco_unitario), 2), 'FM999999990.00'), '.', ',')
             ),
             E'\n\n' ORDER BY cc.adicionado_em
           ), '')
      INTO v_clausulas
    FROM public.carrinho_da_conversa cc
    LEFT JOIN public.produtos p ON p.id = cc.produto_id
    WHERE cc.conversa_id = p_conversa_id;
  END IF;

  IF position('{CLAUSULAS_POR_PRODUTO}' IN v_texto) > 0 THEN
    v_texto := replace(v_texto, '{CLAUSULAS_POR_PRODUTO}', COALESCE(v_clausulas, ''));
  ELSIF COALESCE(v_clausulas, '') <> '' THEN
    -- moldura antiga sem o token: miolos anexados ao fim (antes do bloco de itens)
    v_texto := v_texto || E'\n\n' || 'CLÁUSULAS DOS PRODUTOS CONTRATADOS' || E'\n\n' || v_clausulas;
  END IF;

  IF position('{ITENS_CONTRATADOS}' IN v_texto) > 0 THEN
    v_texto := replace(v_texto, '{ITENS_CONTRATADOS}', v_bloco_itens);
  ELSIF v_bloco_itens <> '' THEN
    v_texto := v_texto || E'\n\n' || v_bloco_itens;
  END IF;

  v_texto := replace(v_texto, '[NOME_COMPLETO]', '{{nome_completo}}');
  v_texto := replace(v_texto, '[NOME]', '{{nome_completo}}');
  v_texto := replace(v_texto, '[CPF]', '{{cpf}}');
  v_texto := replace(v_texto, '[TELEFONE]', '{{telefone}}');
  v_texto := replace(v_texto, '[EMAIL]', '{{email}}');
  FOR v_tok IN
    SELECT DISTINCT (regexp_matches(v_texto, '\[([A-Z0-9_]+)\]', 'g'))[1]
  LOOP
    v_texto := replace(v_texto, '[' || v_tok || ']', '{{' || lower(v_tok) || '}}');
  END LOOP;

  IF v_cond_full IS NOT NULL THEN
    v_inerte := '{{COND_PAG_INI}}{{VAR_AVISTA}}' || COALESCE(v_var_avista, '')
                || '{{/VAR_AVISTA}}{{VAR_PARCELADO}}' || COALESCE(v_var_parc, '')
                || '{{/VAR_PARCELADO}}{{COND_PAG_FIM}}';
    v_inerte := replace(v_inerte, '{TOTAL_AVISTA}',
      'R$ ' || replace(to_char(round(v_total, 2), 'FM999999990.00'), '.', ','));
    v_texto := replace(v_texto, '@@COND_PAGAMENTO_INERTE@@', v_inerte);
  END IF;

  -- F2: planos pela fonte única quando todos os itens têm preço.
  IF v_qtd > 0 THEN
    SELECT jsonb_agg(jsonb_build_object(
             'produto_id', cc.produto_id,
             'nome', COALESCE(p.nome, 'Item'),
             'qtd', cc.quantidade,
             'preco_centavos', p.preco_centavos,
             'entrada_centavos', COALESCE(p.entrada_centavos, 0),
             'max_parcelas', COALESCE(p.max_parcelas, 1),
             'valor_parcela_cravado_centavos', p.valor_parcela_cravado_centavos,
             'parcelas_oferecidas', p.parcelas_oferecidas,
             'opcoes_pagamento', COALESCE(p.opcoes_pagamento, '[]'::jsonb)
           ) ORDER BY cc.adicionado_em)
      INTO v_itens_calc
    FROM public.carrinho_da_conversa cc
    LEFT JOIN public.produtos p ON p.id = cc.produto_id
    WHERE cc.conversa_id = p_conversa_id;

    IF v_itens_calc IS NOT NULL AND NOT EXISTS (
      SELECT 1 FROM jsonb_array_elements(v_itens_calc) i WHERE (i->>'preco_centavos') IS NULL
    ) THEN
      BEGIN
        SELECT jsonb_agg(public.calcular_plano_pagamento(jsonb_build_array(i)))
          INTO v_sep
        FROM jsonb_array_elements(v_itens_calc) i;
        v_planos := jsonb_build_object(
          'junto', public.calcular_plano_pagamento(v_itens_calc),
          'separado', COALESCE(v_sep, '[]'::jsonb)
        );
      EXCEPTION WHEN OTHERS THEN
        v_planos := NULL;
      END;
    END IF;
  END IF;

  -- F3a: formulário = união dedup por slug (molde primeiro, depois produtos).
  WITH todos AS (
    SELECT campo, 0 AS ord, row_number() OVER () AS seq
    FROM jsonb_array_elements(COALESCE(NULLIF(v_tpl.campos_cliente, '[]'::jsonb), '[]'::jsonb)) campo
    UNION ALL
    SELECT campo, 1, 1000 + row_number() OVER ()
    FROM public.carrinho_da_conversa cc
    JOIN public.produtos p ON p.id = cc.produto_id,
    LATERAL jsonb_array_elements(COALESCE(p.campos_cliente, '[]'::jsonb)) campo
    WHERE cc.conversa_id = p_conversa_id
  ), dedup AS (
    SELECT DISTINCT ON (campo->>'slug') campo, seq
    FROM todos
    ORDER BY campo->>'slug', ord, seq
  )
  SELECT COALESCE(jsonb_agg(campo ORDER BY seq), '[]'::jsonb) INTO v_campos_form FROM dedup;

  -- F3a: exigências = união mais exigente (molde ∪ produtos vendidos).
  -- F3c: + documento e assinatura_manuscrita por produto.
  SELECT COALESCE(bool_or(COALESCE((p.exigencias->>'selfie')::boolean, false)), false),
         COALESCE(MAX(COALESCE((p.exigencias->>'num_testemunhas')::int, 0)), 0),
         MAX(NULLIF(p.exigencias->>'instrucao_selfie', '')),
         COALESCE(bool_or(COALESCE((p.exigencias->>'documento')::boolean, false)), false),
         COALESCE(bool_or(COALESCE((p.exigencias->>'assinatura_manuscrita')::boolean, false)), false)
    INTO v_exig_selfie_prod, v_exig_test_prod, v_exig_instr_prod, v_exig_doc_prod, v_exig_assin_prod
  FROM public.carrinho_da_conversa cc
  JOIN public.produtos p ON p.id = cc.produto_id
  WHERE cc.conversa_id = p_conversa_id;

  v_num_testemunhas  := GREATEST(COALESCE(v_tpl.num_testemunhas, 1), v_exig_test_prod);
  v_instrucao_selfie := CASE
    WHEN v_exig_selfie_prod THEN COALESCE(v_exig_instr_prod, v_tpl.instrucao_selfie, 'Envie uma selfie segurando seu documento.')
    ELSE v_tpl.instrucao_selfie
  END;

  -- F3c: campos_obrigatorios do contrato = molde ∪ exigências dos produtos (só adiciona, nunca remove).
  v_campos_obrig := COALESCE(v_tpl.campos_obrigatorios, ARRAY[]::text[]);
  IF v_exig_doc_prod AND NOT ('documento' = ANY(v_campos_obrig)) THEN
    v_campos_obrig := array_append(v_campos_obrig, 'documento');
  END IF;
  IF v_exig_assin_prod AND NOT ('assinatura_manuscrita' = ANY(v_campos_obrig)) THEN
    v_campos_obrig := array_append(v_campos_obrig, 'assinatura_manuscrita');
  END IF;
  IF v_exig_selfie_prod AND NOT ('selfie' = ANY(v_campos_obrig)) THEN
    v_campos_obrig := array_append(v_campos_obrig, 'selfie');
  END IF;

  v_exig := jsonb_build_object(
    'selfie', (v_instrucao_selfie IS NOT NULL),
    'num_testemunhas', v_num_testemunhas,
    'instrucao_selfie', v_instrucao_selfie,
    'documento', ('documento' = ANY(v_campos_obrig)),
    'assinatura_manuscrita', ('assinatura_manuscrita' = ANY(v_campos_obrig))
  );

  SELECT jsonb_build_object(
    'total_avista', v_total,
    'max_parcelas', COALESCE(v_parcelas, 12),
    'entrada', v_entrada,
    'valor_parcela', v_valor_parc,
    'parcelas', v_parcelas,
    'pagamento', COALESCE(v_tpl.pagamento, '{}'::jsonb),
    'planos', v_planos,
    'fallback_molde', (v_total_carrinho <= 0),
    'por_produto', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
               'produto_id', cc.produto_id,
               'nome', COALESCE(p.nome, 'Item'),
               'quantidade', cc.quantidade,
               'preco_unitario', COALESCE(p.preco_centavos::numeric / 100, cc.preco_unitario),
               'subtotal', round(cc.quantidade * COALESCE(p.preco_centavos::numeric / 100, cc.preco_unitario), 2)
             ) ORDER BY cc.adicionado_em)
      FROM public.carrinho_da_conversa cc
      LEFT JOIN public.produtos p ON p.id = cc.produto_id
      WHERE cc.conversa_id = p_conversa_id
    ), '[]'::jsonb)
  ) INTO v_dados_pag;

  INSERT INTO public.contratos
    (tenant_id, lead_id, agente_id, conversa_id, nome_template, titulo, texto_contrato,
     origem, status, dados_cliente, chave_pix, link_parcelamento, posicao_pagamento,
     num_testemunhas, instrucao_selfie, campos_obrigatorios,
     logo_url, nome_empresa, descricao_empresa, cor_pagina, dados_pagamento,
     campos_formulario, exigencias, molde_versao)
  VALUES
    (v_tenant, v_lead, v_agente, p_conversa_id, v_tpl.nome,
     COALESCE(NULLIF(v_tpl.nome, ''), 'Contrato'), v_texto,
     'agente', 'pendente', COALESCE(p_dados_cliente, '{}'::jsonb),
     v_tpl.chave_pix, v_tpl.link_parcelamento, v_tpl.posicao_pagamento,
     v_num_testemunhas, v_instrucao_selfie,
     to_jsonb(v_campos_obrig),
     v_cfg.logo_url, v_cfg.nome_empresa, v_cfg.descricao_empresa, v_cfg.cor_pagina,
     v_dados_pag,
     v_campos_form, v_exig, v_tpl.id::text || '@' || COALESCE(v_tpl.updated_at::text, ''))
  RETURNING id, public.contratos.chave_publica INTO v_contrato_id, v_chave;

  INSERT INTO public.contrato_itens
    (contrato_id, produto_id, nome_snapshot, quantidade, preco_unitario, subtotal, ordem)
  SELECT v_contrato_id, cc.produto_id, COALESCE(p.nome, 'Item'),
         cc.quantidade, COALESCE(p.preco_centavos::numeric / 100, cc.preco_unitario),
         round(cc.quantidade * COALESCE(p.preco_centavos::numeric / 100, cc.preco_unitario), 2),
         (row_number() OVER (ORDER BY cc.adicionado_em))::int - 1
  FROM public.carrinho_da_conversa cc
  LEFT JOIN public.produtos p ON p.id = cc.produto_id
  WHERE cc.conversa_id = p_conversa_id;

  RETURN QUERY SELECT v_contrato_id, v_chave, v_tpl.nome, v_total, v_qtd;
END;
$_$;


ALTER FUNCTION public.gerar_contrato_do_template(p_conversa_id uuid, p_template_id uuid, p_dados_cliente jsonb, p_tenant_id uuid, p_lead_id uuid, p_agente_id uuid) OWNER TO postgres;

--
-- Name: gerar_link_consulta(uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.gerar_link_consulta(p_tenant_id uuid DEFAULT NULL::uuid, p_lead_id uuid DEFAULT NULL::uuid, p_conversa_id uuid DEFAULT NULL::uuid, p_agente_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_uid uuid := (select auth.uid());
  v_role text := (select auth.role());
  v_tenant uuid;
  v_chave uuid;
  v_selfie boolean;
  v_doc boolean;
  v_produto uuid;
  v_validacao jsonb;
  v_preco_cpf numeric(10,2);
  v_preco_cnpj numeric(10,2);
  v_lead uuid := p_lead_id;
  v_conversa uuid := p_conversa_id;
  v_agente uuid := p_agente_id;
BEGIN
  -- Override de tenant só é permitido para o motor (service_role).
  -- Tenant autenticado usa o próprio auth.uid(); anon não pode injetar tenant.
  IF v_uid IS NOT NULL THEN
    v_tenant := v_uid;
  ELSIF v_role = 'service_role' THEN
    v_tenant := p_tenant_id;
  ELSE
    RETURN jsonb_build_object('ok', false, 'erro', 'nao_autorizado');
  END IF;

  IF v_tenant IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'erro', 'sem_tenant');
  END IF;

  -- GATE catraca de venda: app instalado + toggle + saldo. Sem isso, link não nasce.
  IF NOT public.consulta_pode_vender(v_tenant) THEN
    RETURN jsonb_build_object('ok', false, 'erro', 'consulta_indisponivel');
  END IF;

  -- authenticated (botão do tenant): link avulso, sem vínculo de lead/conversa.
  IF v_uid IS NOT NULL THEN
    v_lead := NULL; v_conversa := NULL; v_agente := NULL;
  END IF;

  SELECT selfie_ativo, doc_foto_ativo, produto_oferta_id,
         COALESCE(validacao_comprovante, '{}'::jsonb), preco_venda_cpf, preco_venda_cnpj
    INTO v_selfie, v_doc, v_produto, v_validacao, v_preco_cpf, v_preco_cnpj
  FROM public.consultas_config_tenant
  WHERE tenant_id = v_tenant;

  v_chave := gen_random_uuid();

  INSERT INTO public.consultas (
    tenant_id, lead_id, conversa_id, agente_id, origem, status, chave_publica,
    produto_oferta_id, campos_obrigatorios, validacao_comprovante
  ) VALUES (
    v_tenant, v_lead, v_conversa, v_agente, 'link', 'aguardando_pagamento', v_chave,
    v_produto,
    (CASE WHEN v_selfie THEN jsonb_build_array('selfie') ELSE '[]'::jsonb END)
      || (CASE WHEN v_doc THEN jsonb_build_array('documento') ELSE '[]'::jsonb END),
    COALESCE(v_validacao, '{}'::jsonb)
  );

  RETURN jsonb_build_object(
    'ok', true,
    'chave_publica', v_chave,
    'preco_cpf', v_preco_cpf,
    'preco_cnpj', v_preco_cnpj
  );
END;
$$;


ALTER FUNCTION public.gerar_link_consulta(p_tenant_id uuid, p_lead_id uuid, p_conversa_id uuid, p_agente_id uuid) OWNER TO postgres;

--
-- Name: gerar_recebiveis_do_contrato(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.gerar_recebiveis_do_contrato() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_forma jsonb;
  v_opcoes jsonb;
  v_opcao jsonb;
  v_parcelas integer;
  v_entrada numeric;
  v_valor_parcela numeric;
  v_total numeric;
  v_nome text;
  v_desc_base text;
  i integer;
  -- 2026-09-17: cobrança separada por produto
  v_separado boolean := false;
  v_plano jsonb;
  v_esc jsonb;
  v_prod_nome text;
  -- numeração única no contrato: uq_contas_a_receber_contrato_parcela impede
  -- que dois produtos usem "parcela 1" no mesmo contrato.
  v_seq integer := 0;
  v_primeira numeric;
BEGIN
  -- idempotente: já gerou pra este contrato → nada a fazer
  IF EXISTS (SELECT 1 FROM public.contas_a_receber WHERE contrato_id = NEW.id) THEN
    RETURN NEW;
  END IF;

  BEGIN
    v_nome := COALESCE(
      NEW.dados_signatario->>'nome_completo',
      NEW.dados_cliente->>'nome_completo',
      (SELECT l.name FROM public.leads l WHERE l.id = NEW.lead_id),
      'contato'
    );
    v_desc_base := COALESCE(NULLIF(NEW.titulo, ''), 'Contrato') || ' · ' || v_nome;

    v_forma := NEW.forma_pagamento_escolhida;
    v_opcoes := NEW.dados_pagamento->'planos'->'junto'->'opcoes';
    v_parcelas := COALESCE((v_forma->>'parcelas')::integer, 1);

    IF lower(COALESCE(v_forma->>'modo', '')) = 'opcao' THEN
      -- opção nomeada (produtos.opcoes_pagamento): mesma forma {entrada, parcelas, valor_parcela}
      SELECT o INTO v_opcao
      FROM jsonb_array_elements(COALESCE(NEW.dados_pagamento->'planos'->'junto'->'opcoes_nomeadas', '[]'::jsonb)) o
      WHERE o->>'id' = v_forma->>'opcao_id' LIMIT 1;
      IF v_opcao IS NOT NULL THEN
        v_parcelas := GREATEST(1, COALESCE((v_opcao->>'parcelas')::integer, 1));
      END IF;
    ELSIF lower(COALESCE(v_forma->>'composicao', 'junto')) = 'separado'
          AND jsonb_typeof(NEW.dados_pagamento->'planos'->'separado') = 'array' THEN
      -- 2026-09-17: cobrança separada por produto caía no fallback e virava UMA
      -- parcela com o total à vista. Agora gera as parcelas de cada produto.
      v_separado := true;
    ELSIF v_opcoes IS NOT NULL AND jsonb_typeof(v_opcoes) = 'array' THEN
      SELECT o INTO v_opcao FROM jsonb_array_elements(v_opcoes) o
      WHERE (o->>'parcelas')::integer = v_parcelas LIMIT 1;
    END IF;

    IF v_separado THEN
      FOR v_plano IN SELECT * FROM jsonb_array_elements(NEW.dados_pagamento->'planos'->'separado') LOOP
        v_prod_nome := COALESCE(v_plano->'por_produto'->0->>'nome', 'Item');
        SELECT e INTO v_esc
        FROM jsonb_array_elements(COALESCE(v_forma->'por_produto', '[]'::jsonb)) e
        WHERE e->>'produto_id' = v_plano->'por_produto'->0->>'produto_id' LIMIT 1;

        v_opcao := NULL;
        IF lower(COALESCE(v_esc->>'modo','avista')) = 'parcelado' AND jsonb_typeof(v_plano->'opcoes') = 'array' THEN
          SELECT o INTO v_opcao FROM jsonb_array_elements(v_plano->'opcoes') o
          WHERE (o->>'parcelas')::integer = COALESCE(NULLIF(v_esc->>'parcelas','')::integer, (v_plano->>'max_parcelas')::integer, 1)
          LIMIT 1;
        END IF;

        IF v_opcao IS NOT NULL THEN
          v_entrada := COALESCE((v_opcao->>'entrada_centavos')::numeric, 0) / 100;
          v_parcelas := GREATEST(1, COALESCE((v_opcao->>'parcelas')::integer, 1));
          v_valor_parcela := COALESCE((v_opcao->>'valor_parcela_centavos')::numeric, 0) / 100;
        ELSE
          v_entrada := 0;
          v_parcelas := 1;
          v_valor_parcela := COALESCE((v_plano->>'total_centavos')::numeric, 0) / 100;
        END IF;

        IF v_entrada > 0 THEN
          INSERT INTO public.contas_a_receber (tenant_id, contrato_id, lead_id, numero_parcela, descricao, valor, vencimento)
          VALUES (NEW.tenant_id, NEW.id, NEW.lead_id, v_seq, 'Entrada · ' || v_prod_nome || ' · ' || v_desc_base, v_entrada, CURRENT_DATE);
          v_seq := v_seq + 1;
        END IF;
        IF v_valor_parcela > 0 THEN
          FOR i IN 1..v_parcelas LOOP
            INSERT INTO public.contas_a_receber (tenant_id, contrato_id, lead_id, numero_parcela, descricao, valor, vencimento)
            VALUES (NEW.tenant_id, NEW.id, NEW.lead_id, v_seq,
              'Parcela ' || i || '/' || v_parcelas || ' · ' || v_prod_nome || ' · ' || v_desc_base,
              v_valor_parcela, CURRENT_DATE + (i * 30));
            v_seq := v_seq + 1;
          END LOOP;
        END IF;
      END LOOP;
      RETURN NEW;
    END IF;

    IF v_opcao IS NOT NULL THEN
      v_entrada := COALESCE((v_opcao->>'entrada_centavos')::numeric, 0) / 100;
      v_valor_parcela := COALESCE((v_opcao->>'valor_parcela_centavos')::numeric, 0) / 100;
    ELSE
      -- fallback: total à vista como recebível único
      v_entrada := 0;
      v_parcelas := 1;
      v_valor_parcela := COALESCE(
        (NEW.dados_pagamento->'planos'->'junto'->>'total_centavos')::numeric / 100,
        (NEW.dados_pagamento->>'total_avista')::numeric,
        0
      );
    END IF;

    IF v_entrada > 0 THEN
      INSERT INTO public.contas_a_receber (tenant_id, contrato_id, lead_id, numero_parcela, descricao, valor, vencimento)
      VALUES (NEW.tenant_id, NEW.id, NEW.lead_id, 0, 'Entrada · ' || v_desc_base, v_entrada, CURRENT_DATE);
    END IF;

    IF v_valor_parcela > 0 THEN
      -- 2026-09-17: o plano joga o resto da divisão em `primeira_parcela_centavos`,
      -- mas aqui todas as parcelas saíam iguais — a soma ficava até n-1 centavos
      -- abaixo do total. A 1ª parcela agora usa o valor cheio quando existe.
      v_primeira := COALESCE((v_opcao->>'primeira_parcela_centavos')::numeric / 100, v_valor_parcela);
      FOR i IN 1..v_parcelas LOOP
        INSERT INTO public.contas_a_receber (tenant_id, contrato_id, lead_id, numero_parcela, descricao, valor, vencimento)
        VALUES (
          NEW.tenant_id, NEW.id, NEW.lead_id, i,
          'Parcela ' || i || '/' || v_parcelas || ' · ' || v_desc_base,
          CASE WHEN i = 1 THEN v_primeira ELSE v_valor_parcela END,
          CURRENT_DATE + (i * 30)
        );
      END LOOP;
    END IF;
  EXCEPTION WHEN OTHERS THEN
    -- 2026-09-17: antes só avisava no log do Postgres — o contrato ficava
    -- assinado e SEM cobrança, e ninguém sabia. Agora também cai no painel do
    -- dono. Continua sem re-lançar: falha aqui não pode desfazer a assinatura.
    RAISE WARNING 'gerar_recebiveis_do_contrato falhou pro contrato %: %', NEW.id, SQLERRM;
    BEGIN
      INSERT INTO public.notificacoes (user_id, tipo, icone, titulo, mensagem, acao, acao_label)
      VALUES (NEW.tenant_id, 'recebivel_falhou', 'alert',
              'Contrato assinado sem cobrança gerada',
              'O contrato "' || COALESCE(NULLIF(NEW.titulo, ''), 'Contrato')
                || '" foi assinado, mas as contas a receber não foram geradas. Lance a cobrança à mão no Financeiro. (motivo técnico: '
                || SQLERRM || ')',
              'financeiro', 'Abrir financeiro');
    EXCEPTION WHEN OTHERS THEN NULL;
    END;
  END;

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.gerar_recebiveis_do_contrato() OWNER TO postgres;

--
-- Name: gerar_sugestoes_fusao_tag(uuid, numeric, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.gerar_sugestoes_fusao_tag(p_nicho_id uuid, p_threshold numeric DEFAULT 0.85, p_min_leads integer DEFAULT 1) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE v_count integer := 0;
BEGIN
  IF p_nicho_id IS NULL THEN RAISE EXCEPTION 'nicho_id obrigatorio'; END IF;
  DELETE FROM public.sugestoes_fusao_tag WHERE nicho_id = p_nicho_id AND status IN ('pending','pendente');
  CREATE TEMP TABLE IF NOT EXISTS _pares (tag_a text, tag_b text, sim numeric) ON COMMIT DROP;
  TRUNCATE _pares;
  INSERT INTO _pares
  SELECT a.tag_text, b.tag_text, 1 - (a.vetor_semantico <=> b.vetor_semantico) AS sim
  FROM public.candidatos_tag a JOIN public.candidatos_tag b
    ON a.nicho_id = b.nicho_id AND a.tag_text < b.tag_text AND a.vetor_semantico IS NOT NULL AND b.vetor_semantico IS NOT NULL
  WHERE a.nicho_id = p_nicho_id AND a.num_leads_independentes >= p_min_leads AND b.num_leads_independentes >= p_min_leads
    AND 1 - (a.vetor_semantico <=> b.vetor_semantico) >= p_threshold;
  CREATE TEMP TABLE IF NOT EXISTS _vertices (tag text PRIMARY KEY) ON COMMIT DROP;
  TRUNCATE _vertices;
  INSERT INTO _vertices SELECT DISTINCT tag_a FROM _pares UNION SELECT DISTINCT tag_b FROM _pares;
  CREATE TEMP TABLE IF NOT EXISTS _arestas_bid (a text, b text) ON COMMIT DROP;
  TRUNCATE _arestas_bid;
  INSERT INTO _arestas_bid SELECT tag_a, tag_b FROM _pares
    UNION ALL SELECT tag_b, tag_a FROM _pares
    UNION ALL SELECT tag, tag FROM _vertices;
  CREATE TEMP TABLE IF NOT EXISTS _componentes (tag text PRIMARY KEY, root text) ON COMMIT DROP;
  TRUNCATE _componentes;
  WITH RECURSIVE alcanc AS (
    SELECT tag AS origem, tag AS atual FROM _vertices
    UNION SELECT al.origem, e.b FROM alcanc al JOIN _arestas_bid e ON e.a = al.atual
  )
  INSERT INTO _componentes SELECT origem, MIN(atual) FROM alcanc GROUP BY origem;
  INSERT INTO public.sugestoes_fusao_tag (nicho_id, tags, suggested_canonical, similarity, status, motivo, criado_em, tag_a, tag_b)
  SELECT p_nicho_id, cluster_tags, canonical, avg_sim, 'pendente',
    format('cluster=%s tags leads_canonica=%s', array_length(cluster_tags, 1), max_leads),
    now(), cluster_tags[1],
    CASE WHEN array_length(cluster_tags, 1) >= 2 THEN cluster_tags[2] ELSE cluster_tags[1] END
  FROM (
    SELECT c.root, array_agg(DISTINCT c.tag ORDER BY c.tag) AS cluster_tags,
      (SELECT tc.tag_text FROM public.candidatos_tag tc
       WHERE tc.nicho_id = p_nicho_id AND tc.tag_text = ANY(array_agg(DISTINCT c.tag))
       ORDER BY tc.num_leads_independentes DESC, tc.criado_em ASC LIMIT 1) AS canonical,
      (SELECT MAX(tc.num_leads_independentes) FROM public.candidatos_tag tc
       WHERE tc.nicho_id = p_nicho_id AND tc.tag_text = ANY(array_agg(DISTINCT c.tag))) AS max_leads,
      (SELECT COALESCE(AVG(p.sim), 0) FROM _pares p
       WHERE p.tag_a = ANY(array_agg(DISTINCT c.tag)) AND p.tag_b = ANY(array_agg(DISTINCT c.tag))) AS avg_sim
    FROM _componentes c GROUP BY c.root HAVING count(DISTINCT c.tag) >= 2
  ) clusters;
  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$$;


ALTER FUNCTION public.gerar_sugestoes_fusao_tag(p_nicho_id uuid, p_threshold numeric, p_min_leads integer) OWNER TO postgres;

--
-- Name: gestao_acessos_da_minha_equipe(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.gestao_acessos_da_minha_equipe() RETURNS TABLE(id uuid, papeis text[])
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select a.id, a.papeis
    from public.gestao_acessos a
    join public.profiles m on m.id = a.id and m.deleted_at is null
   where a.deleted_at is null
     and m.parent_user_id = (select auth.uid())
     and public.gestao_eh_admin() $$;


ALTER FUNCTION public.gestao_acessos_da_minha_equipe() OWNER TO postgres;

--
-- Name: gestao_atividade_uso(text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.gestao_atividade_uso(p_de text, p_ate text) RETURNS TABLE(cliente_id uuid, competencia text, tokens_uso bigint, leads_uso integer, tokens_manual bigint, leads_manual integer, tokens_final bigint, leads_final integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare v_ini date; v_fim date;
begin
  if not public.gestao_tem_papel(array['financeiro']::text[]) then raise exception 'gestao: sem permissao para a atividade' using errcode = '42501'; end if;
  if p_de is null or p_ate is null or p_de !~ '^[0-9]{4}-(0[1-9]|1[0-2])$' or p_ate !~ '^[0-9]{4}-(0[1-9]|1[0-2])$' or p_de > p_ate then
    raise exception 'gestao: competencia invalida (use AAAA-MM, de <= ate)' using errcode = '22023'; end if;
  v_ini := (p_de || '-01')::date; v_fim := ((p_ate || '-01')::date + interval '1 month')::date;
  if v_fim - v_ini > 800 then raise exception 'gestao: intervalo maior que 24 meses' using errcode = '22023'; end if;
  return query
  with mm as (select to_char(g, 'YYYY-MM') as comp from generate_series(v_ini::timestamp, (v_fim - 1)::timestamp, interval '1 month') g),
  -- so o cache: nenhuma leitura de traces ou leads aqui (Missao 8)
  u as (select k.tenant_id, k.competencia, k.tokens, k.leads
          from public.gestao_atividade_uso_mes k
         where k.competencia >= p_de and k.competencia <= p_ate)
  select c.id, mm.comp,
         coalesce(u.tokens, 0)::bigint, coalesce(u.leads, 0)::integer,
         a.tokens, a.leads,
         coalesce(a.tokens, u.tokens, 0)::bigint, coalesce(a.leads, u.leads, 0)::integer
    from public.gestao_clientes c
   cross join mm
    left join u on u.tenant_id = c.profile_id and u.competencia = mm.comp
    left join public.gestao_atividade a on a.cliente_id = c.id and a.competencia = mm.comp and a.deleted_at is null
   where c.deleted_at is null and (coalesce(u.tokens, 0) > 0 or coalesce(u.leads, 0) > 0 or a.id is not null)
   order by c.id, mm.comp;
end $_$;


ALTER FUNCTION public.gestao_atividade_uso(p_de text, p_ate text) OWNER TO postgres;

--
-- Name: gestao_atividade_uso_atualizado_em(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.gestao_atividade_uso_atualizado_em() RETURNS timestamp with time zone
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v timestamptz;
begin
  if not public.gestao_tem_papel(array['financeiro']::text[]) then raise exception 'gestao: sem permissao para a atividade' using errcode = '42501'; end if;
  select max(k.atualizado_em) into v from public.gestao_atividade_uso_mes k;
  return v;
end $$;


ALTER FUNCTION public.gestao_atividade_uso_atualizado_em() OWNER TO postgres;

--
-- Name: gestao_atividade_uso_recalcular(text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.gestao_atividade_uso_recalcular(p_de text, p_ate text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare v_ini date; v_fim date; v_tenants uuid[]; v_lim timestamptz[]; v_comp text[]; v_n integer;
begin
  if not (coalesce(current_setting('role', true), 'none') in ('none', 'service_role') or public.gestao_tem_papel(array['financeiro']::text[])) then
    raise exception 'gestao: sem permissao para recalcular a atividade' using errcode = '42501'; end if;
  if p_de is null or p_ate is null or p_de !~ '^[0-9]{4}-(0[1-9]|1[0-2])$' or p_ate !~ '^[0-9]{4}-(0[1-9]|1[0-2])$' or p_de > p_ate then
    raise exception 'gestao: competencia invalida (use AAAA-MM, de <= ate)' using errcode = '22023'; end if;
  v_ini := (p_de || '-01')::date; v_fim := ((p_ate || '-01')::date + interval '1 month')::date;
  if v_fim - v_ini > 800 then raise exception 'gestao: intervalo maior que 24 meses' using errcode = '22023'; end if;
  select array_agg((g::timestamp at time zone 'America/Sao_Paulo') order by g), array_agg(to_char(g, 'YYYY-MM') order by g) into v_lim, v_comp
    from generate_series(v_ini::timestamp, v_fim::timestamp, interval '1 month') g;
  select coalesce(array_agg(distinct c.profile_id), '{}') into v_tenants from public.gestao_clientes c where c.deleted_at is null and c.profile_id is not null;
  insert into public.gestao_atividade_uso_mes (tenant_id, competencia, tokens, leads, atualizado_em)
  select tn.tenant_id, mm.comp, coalesce(t.tokens, 0), coalesce(l.leads, 0), now()
    from unnest(v_tenants) as tn(tenant_id)
   cross join (select to_char(g, 'YYYY-MM') as comp from generate_series(v_ini::timestamp, (v_fim - 1)::timestamp, interval '1 month') g) mm
    left join (select x.tenant_id, v_comp[width_bucket(x.criado_em, v_lim)] as comp, sum(coalesce(x.custo_tokens_in, 0) + coalesce(x.custo_tokens_out, 0))::bigint as tokens
                 from public.traces x
                where x.tenant_id = any (v_tenants) and x.criado_em >= (v_ini::timestamp at time zone 'America/Sao_Paulo') and x.criado_em < (v_fim::timestamp at time zone 'America/Sao_Paulo')
                group by 1, 2) t on t.tenant_id = tn.tenant_id and t.comp = mm.comp
    left join (select y.tenant_id, v_comp[width_bucket(y.created_at, v_lim)] as comp, count(*)::integer as leads
                 from public.leads y
                where y.tenant_id = any (v_tenants) and y.deleted_at is null and y.created_at >= (v_ini::timestamp at time zone 'America/Sao_Paulo') and y.created_at < (v_fim::timestamp at time zone 'America/Sao_Paulo')
                group by 1, 2) l on l.tenant_id = tn.tenant_id and l.comp = mm.comp
  on conflict (tenant_id, competencia) do update set tokens = excluded.tokens, leads = excluded.leads, atualizado_em = excluded.atualizado_em;
  get diagnostics v_n = row_count;
  return v_n;
end $_$;


ALTER FUNCTION public.gestao_atividade_uso_recalcular(p_de text, p_ate text) OWNER TO postgres;

--
-- Name: gestao_atribuir_suporte(uuid, text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.gestao_atribuir_suporte(p_impl_id uuid, p_nome text, p_indice integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_impl record; v_equipe jsonb;
begin
  if not public.gestao_tem_papel(array['implementacao']::text[]) then raise exception 'gestao: sem permissao para atribuir suporte' using errcode = '42501'; end if;
  if p_impl_id is null or p_nome is null or btrim(p_nome) = '' or length(p_nome) > 120 or p_indice is null or p_indice < 0 or p_indice > 1000 then
    raise exception 'gestao: parametros invalidos' using errcode = '22023'; end if;
  select * into v_impl from public.gestao_implementacoes where id = p_impl_id and deleted_at is null;
  if not found or v_impl.status is distinct from 'concluida' or v_impl.suporte_responsavel is distinct from p_nome then
    raise exception 'gestao: a implementacao precisa estar concluida e com este responsavel de suporte' using errcode = '22023'; end if;
  select valor -> 'pessoas' into v_equipe from public.gestao_config where chave = 'equipe' and deleted_at is null;
  if v_equipe is not null and jsonb_typeof(v_equipe) = 'array' and jsonb_array_length(v_equipe) > 0 and not (v_equipe @> to_jsonb(p_nome)) then
    raise exception 'gestao: % nao esta na equipe de suporte', p_nome using errcode = '22023'; end if;
  insert into public.gestao_config (chave, valor) values ('rodizioSuporte', jsonb_build_object('indice', p_indice, 'nome', p_nome, 'em', now()))
    on conflict (chave) do update set valor = excluded.valor, deleted_at = null;
  if v_impl.cliente_id is not null then update public.gestao_clientes set suporte = p_nome where id = v_impl.cliente_id; end if;
end $$;


ALTER FUNCTION public.gestao_atribuir_suporte(p_impl_id uuid, p_nome text, p_indice integer) OWNER TO postgres;

