--
-- Name: gestao_chamado_abrir(uuid, text, text, text, text, text, text, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.gestao_chamado_abrir(p_cliente_id uuid, p_titulo text, p_relato text, p_canal text, p_relatado_por text, p_categoria text, p_prioridade text, p_responsavel text, p_atend_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_nome text; v_id uuid;
begin
  if not public.gestao_tem_papel(array['suporte']::text[]) then
    raise exception 'gestao: sem permissão para abrir chamado' using errcode = '42501';
  end if;
  select c.nome into v_nome from public.gestao_clientes c where c.id = p_cliente_id and c.deleted_at is null;
  if v_nome is null then raise exception 'gestao: cliente não encontrado' using errcode = '22023'; end if;
  if p_atend_id is not null and not exists (select 1 from public.gestao_suporte_atend s
      where s.id = p_atend_id and s.cliente_id = p_cliente_id and s.deleted_at is null) then
    raise exception 'gestao: o acompanhamento não é deste cliente' using errcode = '22023';
  end if;
  insert into public.gestao_chamados (cliente_id, cliente_nome, atend_id, titulo, relato, canal, relatado_por, categoria, prioridade, responsavel)
  values (p_cliente_id, v_nome, p_atend_id, btrim(p_titulo), btrim(p_relato), p_canal, nullif(btrim(coalesce(p_relatado_por, '')), ''),
          p_categoria, coalesce(p_prioridade, 'media'), nullif(btrim(coalesce(p_responsavel, '')), ''))
  returning id into v_id;
  return v_id;
end $$;


ALTER FUNCTION public.gestao_chamado_abrir(p_cliente_id uuid, p_titulo text, p_relato text, p_canal text, p_relatado_por text, p_categoria text, p_prioridade text, p_responsavel text, p_atend_id uuid) OWNER TO postgres;

--
-- Name: gestao_chamado_antes_update(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.gestao_chamado_antes_update() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if new.numero <> old.numero or new.cliente_id <> old.cliente_id or new.aberto_em <> old.aberto_em or new.importado <> old.importado then
    raise exception 'gestao: número, cliente, abertura e origem do chamado não mudam' using errcode = '22023';
  end if;
  new.atualizado_em := now();
  new.passou_pd := old.passou_pd or new.passou_pd;
  if new.status is distinct from old.status then
    new.status_desde := now();
    if new.status = 'aguardando_equipe' then new.passou_pd := true; end if;
    if new.status in ('resolvido', 'nao_resolvido') then new.resolvido_em := now(); else new.resolvido_em := null; end if;
    -- reaberto: causa/solução/resultado antigos saem do chamado (continuam no evento de fechamento); o próximo fechamento pede tudo de novo
    if old.status in ('resolvido', 'nao_resolvido') and new.status not in ('resolvido', 'nao_resolvido') then
      new.causa := null; new.solucao := null; new.resultado := null;
    end if;
  end if;
  return new;
end $$;


ALTER FUNCTION public.gestao_chamado_antes_update() OWNER TO postgres;

--
-- Name: gestao_chamado_apos_insert(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.gestao_chamado_apos_insert() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if not new.importado then
    insert into public.gestao_chamado_eventos (chamado_id, tipo, texto, aconteceu_em) values (new.id, 'criacao', new.relato, new.aberto_em);
  end if;
  return null;
end $$;


ALTER FUNCTION public.gestao_chamado_apos_insert() OWNER TO postgres;

--
-- Name: gestao_chamado_apos_update(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.gestao_chamado_apos_update() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_motivo text := nullif(btrim(coalesce(current_setting('gestao.chamado_motivo', true), '')), '');
  v_tipo text;
  v_texto text;
begin
  if new.status is distinct from old.status then
    v_tipo := case
      when new.status = 'aguardando_equipe' then 'escalonamento'
      when new.status in ('resolvido', 'nao_resolvido') then 'fechamento'
      when old.status in ('resolvido', 'nao_resolvido') then 'reabertura'
      when old.status = 'aguardando_equipe' then 'devolucao'
      else 'status' end;
    v_texto := case
      when new.status = 'resolvido' then concat_ws(E'\n', 'Causa: ' || new.causa, 'Solução: ' || new.solucao, 'Resultado: ' || new.resultado, v_motivo)
      when new.status = 'nao_resolvido' then concat_ws(E'\n', 'Justificativa: ' || new.resultado, v_motivo)
      else v_motivo end;
    insert into public.gestao_chamado_eventos (chamado_id, tipo, valor_antigo, valor_novo, texto) values (new.id, v_tipo, old.status, new.status, v_texto);
  end if;
  if new.responsavel is distinct from old.responsavel then
    insert into public.gestao_chamado_eventos (chamado_id, tipo, valor_antigo, valor_novo, texto) values (new.id, 'responsavel', old.responsavel, new.responsavel, v_motivo);
  end if;
  if new.prioridade is distinct from old.prioridade then
    insert into public.gestao_chamado_eventos (chamado_id, tipo, valor_antigo, valor_novo, texto) values (new.id, 'prioridade', old.prioridade, new.prioridade, v_motivo);
  end if;
  if new.categoria is distinct from old.categoria then
    insert into public.gestao_chamado_eventos (chamado_id, tipo, valor_antigo, valor_novo, texto) values (new.id, 'categoria', old.categoria, new.categoria, v_motivo);
  end if;
  return null;
end $$;


ALTER FUNCTION public.gestao_chamado_apos_update() OWNER TO postgres;

