    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select c.id from public.gestao_chamados c
   where c.deleted_at is null and c.numero::text = regexp_replace(btrim(coalesce(p_codigo, '')), '^(ch-?|#)?0*', '', 'i') $$;


