-- Name: gestao_chamado_ficha(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.gestao_chamado_ficha(p_cliente_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  -- 25/09 (Adrian): implementação e P&D abrem a ficha de qualquer cliente para editar o link do Drive; os chamados dentro
  -- dela continuam filtrados pela RLS (P&D só os escalados, implementação nenhum).
  if not public.gestao_tem_papel(array['suporte','financeiro','comercial','programador','implementacao']::text[]) then
    raise exception 'gestao: sem permissão para ver a ficha deste cliente' using errcode = '42501';
  end if;
  return public.gestao_chamado_ficha_interna(p_cliente_id);
end $$;


ALTER FUNCTION public.gestao_chamado_ficha(p_cliente_id uuid) OWNER TO postgres;

--
-- Name: gestao_chamado_ficha_interna(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.gestao_chamado_ficha_interna(p_cliente_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v jsonb;
begin
  select jsonb_build_object(
    'cliente', jsonb_build_object('id', c.id, 'nome', c.nome, 'email', c.email, 'telefone', c.telefone, 'situacao', c.situacao,
      'fechamento', c.fechamento, 'implantacao', c.implementacao, 'implementador', c.implementador, 'suporte', c.suporte, 'obs', c.obs, 'link_drive', c.link_drive),
    'implementacoes', coalesce((select jsonb_agg(jsonb_build_object('id', i.id, 'status', i.status, 'responsavel', i.responsavel,
        'programador', i.programador, 'enviado_em', i.enviado_em, 'iniciado_em', i.iniciado_em, 'concluido_em', i.concluido_em,
        'validado_em', i.validado_em, 'obs_final', i.obs_final) order by i.criado_em)
      from public.gestao_implementacoes i where i.cliente_id = c.id and i.deleted_at is null), '[]'::jsonb),
    'acompanhamentos', coalesce((select jsonb_agg(jsonb_build_object('id', s.id, 'status', s.status, 'responsavel', s.responsavel,
        'inicio', s.inicio, 'concluido_em', s.concluido_em, 'obs_final', s.obs_final) order by s.criado_em)
      from public.gestao_suporte_atend s where s.cliente_id = c.id and s.deleted_at is null), '[]'::jsonb))
  into v
  from public.gestao_clientes c where c.id = p_cliente_id and c.deleted_at is null;
  if v is null then raise exception 'gestao: cliente não encontrado' using errcode = '22023'; end if;
  return v;
end $$;


ALTER FUNCTION public.gestao_chamado_ficha_interna(p_cliente_id uuid) OWNER TO postgres;

--
-- Name: gestao_chamado_mudar(uuid, jsonb, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.gestao_chamado_mudar(p_chamado uuid, p_mudancas jsonb, p_motivo text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  c public.gestao_chamados;
  v_chaves text[] := array(select jsonb_object_keys(coalesce(p_mudancas, '{}'::jsonb)) order by 1);
  v_motivo text := nullif(btrim(coalesce(p_motivo, '')), '');
  v_status text;
  v_fechado boolean;
  v_suporte boolean := public.gestao_tem_papel(array['suporte']::text[]);
  v_depois public.gestao_chamados;
begin
  select * into c from public.gestao_chamados where id = p_chamado and deleted_at is null for update;
  if c.id is null then raise exception 'gestao: chamado não encontrado' using errcode = '22023'; end if;
  if cardinality(v_chaves) = 0 or exists (select 1 from unnest(v_chaves) k where k not in ('status','responsavel','prioridade','categoria','causa','solucao','resultado')) then
    raise exception 'gestao: campo que não pode ser mudado aqui' using errcode = '22023';
  end if;
  v_status := coalesce(p_mudancas->>'status', c.status);
  v_fechado := c.status in ('resolvido', 'nao_resolvido');
  if not v_suporte and not public.gestao_tem_papel(array['programador']::text[]) then
    raise exception 'gestao: sem permissão para mudar este chamado' using errcode = '42501';
  end if;
  if not v_suporte then
    if not (public.gestao_tem_papel(array['programador']::text[]) and c.passou_pd and c.status = 'aguardando_equipe'
            and v_chaves = array['status'] and v_status = 'andamento') then
      raise exception 'gestao: o P&D só pode devolver o chamado ao Suporte' using errcode = '42501';
    end if;
  end if;
  if v_fechado and not (v_chaves = array['status'] and v_status in ('aberto', 'andamento')) then
    raise exception 'gestao: chamado fechado; use Reabrir' using errcode = '22023';
  end if;
  if v_motivo is null and v_status is distinct from c.status and (v_fechado or v_status = 'aguardando_equipe' or c.status = 'aguardando_equipe')
     and v_status not in ('resolvido', 'nao_resolvido') then
    raise exception 'gestao: informe o motivo' using errcode = '22023';
  end if;
  v_depois := c;
  v_depois.status := v_status;
  if p_mudancas ? 'responsavel' then v_depois.responsavel := nullif(btrim(coalesce(p_mudancas->>'responsavel', '')), ''); end if;
  if p_mudancas ? 'prioridade' then v_depois.prioridade := p_mudancas->>'prioridade'; end if;
  if p_mudancas ? 'categoria' then v_depois.categoria := p_mudancas->>'categoria'; end if;
  if p_mudancas ? 'causa' then v_depois.causa := nullif(btrim(coalesce(p_mudancas->>'causa', '')), ''); end if;
  if p_mudancas ? 'solucao' then v_depois.solucao := nullif(btrim(coalesce(p_mudancas->>'solucao', '')), ''); end if;
  if p_mudancas ? 'resultado' then v_depois.resultado := nullif(btrim(coalesce(p_mudancas->>'resultado', '')), ''); end if;
  if v_status = 'resolvido' and (v_depois.causa is null or v_depois.solucao is null or v_depois.resultado is null) then
    raise exception 'gestao: para resolver, preencha causa, solução e resultado' using errcode = '22023';
  end if;
  if v_status = 'nao_resolvido' and v_depois.resultado is null then
    raise exception 'gestao: para fechar como não resolvido, escreva a justificativa' using errcode = '22023';
  end if;
  if v_depois.status is not distinct from c.status and v_depois.responsavel is not distinct from c.responsavel
     and v_depois.prioridade is not distinct from c.prioridade and v_depois.categoria is not distinct from c.categoria
     and v_depois.causa is not distinct from c.causa and v_depois.solucao is not distinct from c.solucao
     and v_depois.resultado is not distinct from c.resultado then
    raise exception 'gestao: nada mudou' using errcode = '22023';
  end if;
  perform set_config('gestao.chamado_motivo', coalesce(v_motivo, ''), true);
  update public.gestao_chamados set status = v_depois.status, responsavel = v_depois.responsavel, prioridade = v_depois.prioridade,
    categoria = v_depois.categoria, causa = v_depois.causa, solucao = v_depois.solucao, resultado = v_depois.resultado
  where id = c.id;
  perform set_config('gestao.chamado_motivo', '', true);
end $$;


ALTER FUNCTION public.gestao_chamado_mudar(p_chamado uuid, p_mudancas jsonb, p_motivo text) OWNER TO postgres;

--
-- Name: gestao_chamado_registrar(uuid, text, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.gestao_chamado_registrar(p_chamado uuid, p_tipo text, p_texto text, p_aconteceu_em timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare c public.gestao_chamados; v_quando timestamptz := coalesce(p_aconteceu_em, now()); v_id uuid;
begin
  select * into c from public.gestao_chamados where id = p_chamado and deleted_at is null for update;
  if c.id is null then raise exception 'gestao: chamado não encontrado' using errcode = '22023'; end if;
  if public.gestao_tem_papel(array['suporte']::text[]) then
    if p_tipo not in ('nota_interna', 'contato_cliente') then raise exception 'gestao: tipo de registro inválido' using errcode = '22023'; end if;
  -- Serjão B-3: o P&D comenta só enquanto o chamado está com ele (aguardando_equipe); depois de devolver, só lê
  elsif public.gestao_tem_papel(array['programador']::text[]) and c.passou_pd and c.status = 'aguardando_equipe' then
    if p_tipo <> 'nota_interna' then raise exception 'gestao: o P&D registra só nota interna' using errcode = '42501'; end if;
  else
    raise exception 'gestao: sem permissão para registrar neste chamado' using errcode = '42501';
  end if;
  if c.status in ('resolvido', 'nao_resolvido') then raise exception 'gestao: chamado fechado; reabra para registrar' using errcode = '22023'; end if;
  if length(btrim(coalesce(p_texto, ''))) = 0 then raise exception 'gestao: escreva o texto do registro' using errcode = '22023'; end if;
  insert into public.gestao_chamado_eventos (chamado_id, tipo, texto, aconteceu_em) values (c.id, p_tipo, btrim(p_texto), v_quando) returning id into v_id;
  if p_tipo = 'contato_cliente' and (c.primeira_resposta_em is null or v_quando < c.primeira_resposta_em) then
    update public.gestao_chamados set primeira_resposta_em = v_quando where id = c.id;
  end if;
  return v_id;
end $$;


ALTER FUNCTION public.gestao_chamado_registrar(p_chamado uuid, p_tipo text, p_texto text, p_aconteceu_em timestamp with time zone) OWNER TO postgres;

--
-- Name: gestao_chamado_registrar_terminal(text, text, text, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.gestao_chamado_registrar_terminal(p_codigo text, p_tipo text, p_texto text, p_autor text, p_aconteceu_em timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare v_id uuid := public.gestao_chamado_do_codigo(p_codigo); c public.gestao_chamados; v_quando timestamptz := coalesce(p_aconteceu_em, now()); v_ev uuid;
begin
  if coalesce(current_setting('role', true), 'none') in ('authenticated', 'anon') then
    raise exception 'gestao: o registro pelo terminal não pode ser chamado pela tela' using errcode = '42501';
  end if;
  if v_id is null then raise exception 'gestao: chamado % não encontrado', p_codigo using errcode = '22023'; end if;
  select * into c from public.gestao_chamados where id = v_id for update;
  if p_tipo not in ('nota_interna', 'contato_cliente') then raise exception 'gestao: tipo de registro inválido (nota_interna ou contato_cliente)' using errcode = '22023'; end if;
  if c.status in ('resolvido', 'nao_resolvido') then raise exception 'gestao: chamado fechado; reabra pela tela' using errcode = '22023'; end if;
  if length(btrim(coalesce(p_texto, ''))) = 0 then raise exception 'gestao: escreva o texto do registro' using errcode = '22023'; end if;
  if btrim(coalesce(p_autor, '')) !~ '^[^()]{2,60} \(IA\), por [^()]{2,60}$' then
    raise exception 'gestao: autor no formato "Nome (IA), por Pessoa"' using errcode = '22023';
  end if;
  insert into public.gestao_chamado_eventos (chamado_id, tipo, texto, aconteceu_em, autor_nome, origem)
  values (c.id, p_tipo, btrim(p_texto), v_quando, btrim(p_autor), 'terminal') returning id into v_ev;
  if p_tipo = 'contato_cliente' and (c.primeira_resposta_em is null or v_quando < c.primeira_resposta_em) then
    update public.gestao_chamados set primeira_resposta_em = v_quando where id = c.id;
  end if;
  return v_ev;
end $_$;


ALTER FUNCTION public.gestao_chamado_registrar_terminal(p_codigo text, p_tipo text, p_texto text, p_autor text, p_aconteceu_em timestamp with time zone) OWNER TO postgres;

--
-- Name: gestao_cliente_definir_drive(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.gestao_cliente_definir_drive(p_cliente_id uuid, p_link text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare v_link text := nullif(btrim(coalesce(p_link, '')), '');
begin
  if not public.gestao_tem_papel(array['programador','implementacao']::text[]) then
    raise exception 'gestao: sem permissão para editar o link do Drive' using errcode = '42501';
  end if;
  if v_link is not null and (v_link !~ '^https://[^[:space:]]+$' or length(v_link) > 500) then
    raise exception 'gestao: o link precisa começar com https:// (até 500 caracteres, sem espaços)' using errcode = '22023';
  end if;
  update public.gestao_clientes set link_drive = v_link where id = p_cliente_id and deleted_at is null;
  if not found then raise exception 'gestao: cliente não encontrado' using errcode = '22023'; end if;
end $_$;


ALTER FUNCTION public.gestao_cliente_definir_drive(p_cliente_id uuid, p_link text) OWNER TO postgres;

--
-- Name: gestao_definir_acesso_membro(uuid, text[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.gestao_definir_acesso_membro(p_membro uuid, p_papeis text[]) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_eu uuid := (select auth.uid());
  v_m record;
  v_nome text;
  v_papeis text[];
  v_area text;
  v_equipe jsonb;
  v_pessoas jsonb;
  v_membros jsonb;
  v_reg jsonb;
  v_pessoa text;
  v_func uuid;
  v_outro text;
  v_tinha_sup boolean;
  v_ganhou boolean;
  v_perdeu boolean;
  v_mudou boolean;
begin
  if v_eu is null or not public.gestao_eh_admin() then
    raise exception 'gestao: so o administrador da Gestao define as funcoes da equipe' using errcode = '42501'; end if;
  if p_membro is null then raise exception 'gestao: membro obrigatorio' using errcode = '22023'; end if;
  if p_membro = v_eu then raise exception 'gestao: use a aba Acessos para mudar o proprio acesso' using errcode = '22023'; end if;
  select id, full_name, apelido, email, parent_user_id into v_m from public.profiles where id = p_membro and deleted_at is null;
  if not found then raise exception 'gestao: membro nao encontrado' using errcode = '22023'; end if;
  -- só membro da PRÓPRIA equipe (ou o dono da plataforma, que administra tudo)
  if v_m.parent_user_id is distinct from v_eu
     and not exists (select 1 from public.profiles p where p.id = v_eu and p.system_role = 'platform_admin' and p.deleted_at is null) then
    raise exception 'gestao: essa pessoa nao e da sua equipe' using errcode = '42501'; end if;

  v_papeis := array(select distinct x from unnest(coalesce(p_papeis, '{}'::text[])) x where x is not null order by x);
  if not (v_papeis <@ array['admin','financeiro','comercial','implementacao','programador','suporte']::text[]) then
    raise exception 'gestao: funcao desconhecida' using errcode = '22023'; end if;
  v_nome := coalesce(nullif(btrim(v_m.full_name), ''), nullif(btrim(v_m.apelido), ''), v_m.email, 'Membro');
  if length(v_nome) > 120 then v_nome := left(v_nome, 120); end if;
  -- E-1 (Serjão, rodada 3): quem JÁ tem acesso mantém o "no time como" que já tinha (os atendimentos estão gravados com
  -- esse nome). O nome do perfil só vale para quem nunca teve acesso.
  select nullif(btrim(pessoa), '') into v_pessoa from public.gestao_acessos where id = p_membro;
  v_pessoa := coalesce(v_pessoa, v_nome);
  -- E-3 (Serjão, rodada 4): o rodízio só muda quando o papel Suporte MUDA de fato (a tela manda todas as funções
  -- a cada edição). Guardar se ele já tinha Suporte ANTES de gravar.
  select 'suporte' = any (papeis) into v_tinha_sup from public.gestao_acessos where id = p_membro and deleted_at is null;
  v_tinha_sup := coalesce(v_tinha_sup, false);

  -- 1. o acesso
  if cardinality(v_papeis) = 0 then
    update public.gestao_acessos set deleted_at = now() where id = p_membro and deleted_at is null;
  else
    insert into public.gestao_acessos (id, papeis, pessoa, por_id)
    values (p_membro, v_papeis, v_pessoa, v_eu)
    on conflict (id) do update set papeis = excluded.papeis, pessoa = excluded.pessoa, por_id = excluded.por_id, deleted_at = null;
  end if;

  -- 2. a lista da área: Implementação e P&D são funcionários, ligados ao membro por extras.membro_id.
  --    E-1: se já existe um funcionário da área com esse nome e sem ligação, LIGA esse (não cria um segundo).
  --    O nome do funcionário nunca é trocado aqui.
  foreach v_area in array array['implementacao','programador'] loop
    if v_area = any (v_papeis) then
      update public.gestao_funcionarios set ativo = true, deleted_at = null
       where area = v_area and extras ->> 'membro_id' = p_membro::text;
      if not found then
        select id into v_func from public.gestao_funcionarios
         where area = v_area and nome = v_pessoa and coalesce(extras ->> 'membro_id', '') = ''
         order by (deleted_at is null) desc, criado_em limit 1;
        if v_func is not null then
          update public.gestao_funcionarios set ativo = true, deleted_at = null,
                 extras = extras || jsonb_build_object('membro_id', p_membro::text)
           where id = v_func;
        else
          insert into public.gestao_funcionarios (nome, area, ativo, extras)
          values (v_pessoa, v_area, true, jsonb_build_object('membro_id', p_membro::text));
        end if;
        v_func := null;
      end if;
    else
      update public.gestao_funcionarios set ativo = false
       where area = v_area and extras ->> 'membro_id' = p_membro::text and ativo is distinct from false;
    end if;
  end loop;

  -- 3. Suporte: a equipe do rodízio (gestao_config 'equipe' → {"pessoas": [...]}).
  --    E-2 (Serjão, rodada 3): nada por nome solto. Cada membro fica registrado em valor.membros[id] = {nome, adicionado};
  --    "adicionado" = foi esta função que pôs o nome no rodízio. Ao tirar, só sai o nome que ela mesma pôs e que nenhum
  --    outro membro registrado usa. Nome cadastrado à mão nunca é tirado daqui.
  select valor into v_equipe from public.gestao_config where chave = 'equipe' and deleted_at is null;
  v_equipe := coalesce(v_equipe, '{}'::jsonb);
  v_pessoas := case when jsonb_typeof(v_equipe -> 'pessoas') = 'array' then v_equipe -> 'pessoas' else '[]'::jsonb end;
  v_membros := case when jsonb_typeof(v_equipe -> 'membros') = 'object' then v_equipe -> 'membros' else '{}'::jsonb end;
  v_reg := v_membros -> (p_membro::text);
  v_ganhou := ('suporte' = any (v_papeis)) and not v_tinha_sup;
  v_perdeu := v_tinha_sup and not ('suporte' = any (v_papeis));
  v_mudou := false;
  -- SAÍDA: quando PERDEU o Suporte agora, e também quando GANHOU mas havia um registro velho (E-4, Serjão rodada 5:
  -- o Suporte tinha sido tirado pela aba Acessos, sem passar por aqui). O registro velho sai com a regra de sempre.
  if v_reg is not null and (v_perdeu or v_ganhou) then
    if (v_reg ->> 'adicionado')::boolean then
      -- outro membro registrado com o mesmo nome? ele herda o "adicionado" (o nome fica, e sai quando ele sair)
      select m.key into v_outro from jsonb_each(v_membros) m
       where m.key <> p_membro::text and m.value -> 'nome' = v_reg -> 'nome' limit 1;
      if v_outro is not null then
        v_membros := jsonb_set(v_membros, array[v_outro, 'adicionado'], 'true'::jsonb);
      else
        v_pessoas := (select coalesce(jsonb_agg(e), '[]'::jsonb) from jsonb_array_elements(v_pessoas) e where e <> v_reg -> 'nome');
      end if;
    end if;
    v_membros := v_membros - (p_membro::text);
    v_mudou := true;
  end if;
  -- ENTRADA: GANHOU Suporte agora → registra com o "no time como" ATUAL.
  if v_ganhou then
    if v_pessoas @> to_jsonb(v_pessoa) then
      v_membros := v_membros || jsonb_build_object(p_membro::text, jsonb_build_object('nome', v_pessoa, 'adicionado', false));
    else
      v_pessoas := v_pessoas || to_jsonb(v_pessoa);
      v_membros := v_membros || jsonb_build_object(p_membro::text, jsonb_build_object('nome', v_pessoa, 'adicionado', true));
    end if;
    v_mudou := true;
  end if;
  -- continua com Suporte, ou continua sem: o rodízio NÃO é tocado (quem o dono tirou à mão, fica fora)
  if not v_mudou then v_equipe := null; end if;
  if v_equipe is not null then
    insert into public.gestao_config (chave, valor)
    values ('equipe', v_equipe || jsonb_build_object('pessoas', v_pessoas, 'membros', v_membros))
    on conflict (chave) do update set valor = excluded.valor, deleted_at = null;
  end if;
end $$;


ALTER FUNCTION public.gestao_definir_acesso_membro(p_membro uuid, p_papeis text[]) OWNER TO postgres;

--
-- Name: gestao_definir_suporte_cliente(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.gestao_definir_suporte_cliente(p_cliente_id uuid, p_nome text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if not public.gestao_tem_papel(array['suporte','implementacao']::text[]) then
    raise exception 'gestao: sem permissao para definir o suporte do cliente' using errcode = '42501'; end if;
  if p_cliente_id is null or (p_nome is not null and length(p_nome) > 120) then
    raise exception 'gestao: parametros invalidos' using errcode = '22023'; end if;
  update public.gestao_clientes set suporte = nullif(btrim(coalesce(p_nome, '')), '') where id = p_cliente_id and deleted_at is null;
  if not found then raise exception 'gestao: cliente nao encontrado' using errcode = '22023'; end if;
end $$;


ALTER FUNCTION public.gestao_definir_suporte_cliente(p_cliente_id uuid, p_nome text) OWNER TO postgres;

--
-- Name: gestao_eh_admin(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.gestao_eh_admin() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select public.gestao_tem_papel(array['admin']::text[]) $$;


ALTER FUNCTION public.gestao_eh_admin() OWNER TO postgres;

--
-- Name: gestao_eliminar_expirados(boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.gestao_eliminar_expirados(p_executar boolean DEFAULT false) RETURNS TABLE(tabela text, linhas bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare v_anos integer; v_corte timestamptz; t text; n bigint;
begin
  if not public.gestao_eh_admin() then raise exception 'gestao: so o admin elimina dados expirados' using errcode = '42501'; end if;
  select case when (valor ->> 'anos') ~ '^[0-9]{1,2}$' then (valor ->> 'anos')::integer end into v_anos from public.gestao_config where chave = 'retencao' and deleted_at is null;
  v_anos := coalesce(v_anos, 5);
  if v_anos < 1 then raise exception 'gestao: retencao invalida' using errcode = '22023'; end if;
  v_corte := now() - make_interval(years => v_anos);
  foreach t in array array['gestao_vendas', 'gestao_indicacoes'] loop
    if p_executar then execute format('with d as (delete from public.%I where criado_em < $1 returning 1) select count(*) from d', t) into n using v_corte;
    else execute format('select count(*) from public.%I where criado_em < $1', t) into n using v_corte; end if;
    tabela := t; linhas := n; return next;
  end loop;
end $_$;


ALTER FUNCTION public.gestao_eliminar_expirados(p_executar boolean) OWNER TO postgres;

--
-- Name: gestao_enviar_implementacao(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.gestao_enviar_implementacao(p_cliente_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_cli record; v_por text; v_id uuid;
begin
  if not public.gestao_tem_papel(array['financeiro','comercial']::text[]) then
    raise exception 'gestao: sem permissao para enviar cliente a implementacao' using errcode = '42501'; end if;
  if p_cliente_id is null then raise exception 'gestao: cliente obrigatorio' using errcode = '22023'; end if;
  -- um envio por vez para o mesmo cliente (dois cliques ao mesmo tempo não criam duas implementações)
  perform pg_advisory_xact_lock(hashtext('gestao_enviar_implementacao:' || p_cliente_id::text));
  select id, nome, implementador into v_cli from public.gestao_clientes where id = p_cliente_id and deleted_at is null;
  if not found then raise exception 'gestao: cliente nao encontrado' using errcode = '22023'; end if;
  if exists (select 1 from public.gestao_implementacoes
              where cliente_id = p_cliente_id and deleted_at is null and status is distinct from 'concluida') then
    raise exception 'gestao: % ja esta na implementacao', v_cli.nome using errcode = '22023'; end if;
  -- quem enviou: o nome do perfil de quem está logado (o mesmo que o app mostra), nunca um texto vindo do navegador
  select nullif(btrim(p.full_name), '') into v_por from public.profiles p where p.id = (select auth.uid()) and p.deleted_at is null;
  insert into public.gestao_implementacoes (cliente_id, cliente_nome, status, enviado_em, responsavel, tentativas, dias, extras)
  values (v_cli.id, v_cli.nome, 'aguardando', now(), nullif(btrim(coalesce(v_cli.implementador, '')), ''), '[]'::jsonb, '{}'::jsonb,
          jsonb_build_object('encaminhamentos', jsonb_build_array(
            jsonb_build_object('em', now(), 'de', 'clientes', 'para', 'implementacao', 'por', v_por))))
  returning id into v_id;
  return v_id;
end $$;


ALTER FUNCTION public.gestao_enviar_implementacao(p_cliente_id uuid) OWNER TO postgres;

--
-- Name: gestao_excluir_do_suporte(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.gestao_excluir_do_suporte(p_impl_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if not public.gestao_tem_papel(array['suporte','implementacao']::text[]) then
    raise exception 'gestao: sem permissao para excluir do suporte' using errcode = '42501'; end if;
  update public.gestao_implementacoes set suporte_removido = true
   where id = p_impl_id and deleted_at is null and status = 'concluida';
  if not found then raise exception 'gestao: implementacao nao encontrada ou ainda nao concluida' using errcode = '22023'; end if;
end $$;


ALTER FUNCTION public.gestao_excluir_do_suporte(p_impl_id uuid) OWNER TO postgres;

--
-- Name: gestao_implementacao_dos_clientes(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.gestao_implementacao_dos_clientes() RETURNS TABLE(cliente_id uuid, impl_id uuid, status text, enviado_em timestamp with time zone, concluido_em timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  -- artefato impAtivaDoCliente: a implementação aberta; se não houver, a última concluída
  select distinct on (i.cliente_id) i.cliente_id, i.id, i.status, i.enviado_em, i.concluido_em
    from public.gestao_implementacoes i
   where i.deleted_at is null and i.cliente_id is not null
     and public.gestao_tem_papel(array['financeiro','comercial','implementacao','programador','suporte']::text[])
   order by i.cliente_id, (i.status = 'concluida'), i.enviado_em desc nulls last $$;


