--
-- Name: gestao_pessoas_suporte(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.gestao_pessoas_suporte() RETURNS TABLE(nome text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if not public.gestao_tem_algum_papel() then
    raise exception 'gestao: sem permissão para listar a equipe' using errcode = '42501';
  end if;
  return query select distinct btrim(a.pessoa) from public.gestao_acessos a
   where a.deleted_at is null and a.papeis && array['suporte']::text[] and length(btrim(coalesce(a.pessoa, ''))) > 0
   order by 1;
end $$;


ALTER FUNCTION public.gestao_pessoas_suporte() OWNER TO postgres;

--
-- Name: gestao_publico_registrar_indicacao(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.gestao_publico_registrar_indicacao(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare v_sub text := nullif(btrim(p ->> 'submissionId'), ''); v_id uuid; v_ind uuid; v_dia date;
begin
  if p is null or jsonb_typeof(p) <> 'object' then raise exception 'gestao: corpo invalido' using errcode = '22023'; end if;
  if v_sub is null or length(v_sub) > 100 or coalesce(btrim(p ->> 'leadName'), '') = '' or length(p ->> 'leadName') > 200
     or coalesce(btrim(p ->> 'leadWhatsapp'), '') = '' or length(p ->> 'leadWhatsapp') > 40 or coalesce(btrim(p ->> 'consentText'), '') = '' or length(p ->> 'consentText') > 4000
     or (coalesce(p ->> 'localDate', '') <> '' and p ->> 'localDate' !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$') then
    raise exception 'gestao: campos obrigatorios ausentes ou invalidos' using errcode = '22023'; end if;
  select id into v_id from public.gestao_indicacoes where submission_id = v_sub;
  if v_id is not null then return jsonb_build_object('ok', true, 'duplicado', true, 'id', v_id); end if;
  v_dia := coalesce(nullif(p ->> 'localDate', '')::date, (now() at time zone 'America/Sao_Paulo')::date);
  select id into v_ind from public.gestao_indicadores where upper(codigo) = upper(btrim(p ->> 'referrerCode')) and deleted_at is null order by criado_em limit 1;
  insert into public.gestao_indicacoes (indicador_id, referrer_name, referrer_code, lead_nome, lead_whatsapp, nicho, status, origem, data_indicacao, submission_id, consentimento_texto, consentimento_em)
  values (v_ind, left(btrim(p ->> 'referrerName'), 200), upper(left(btrim(p ->> 'referrerCode'), 60)), btrim(p ->> 'leadName'), btrim(p ->> 'leadWhatsapp'), left(p ->> 'niche', 120),
          'novo', 'pagina', v_dia, v_sub, p ->> 'consentText', now())
  returning id into v_id;
  return jsonb_build_object('ok', true, 'duplicado', false, 'id', v_id, 'indicadorEncontrado', v_ind is not null);
exception when unique_violation then
  select id into v_id from public.gestao_indicacoes where submission_id = v_sub;
  return jsonb_build_object('ok', true, 'duplicado', true, 'id', v_id);
end $_$;


ALTER FUNCTION public.gestao_publico_registrar_indicacao(p jsonb) OWNER TO postgres;

--
-- Name: gestao_publico_registrar_venda(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.gestao_publico_registrar_venda(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare v_sub text := nullif(btrim(p ->> 'submissionId'), ''); v_id uuid; v_arq jsonb := p -> 'arquivo'; v_cent numeric;
begin
  if p is null or jsonb_typeof(p) <> 'object' then raise exception 'gestao: corpo invalido' using errcode = '22023'; end if;
  if v_sub is null or length(v_sub) > 100 or coalesce(btrim(p ->> 'clientName'), '') = '' or length(p ->> 'clientName') > 200
     or coalesce(btrim(p ->> 'sellerName'), '') = '' or length(p ->> 'sellerName') > 200 or coalesce(btrim(p ->> 'consentText'), '') = '' or length(p ->> 'consentText') > 4000
     or coalesce(p ->> 'saleDate', '') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' or coalesce(p ->> 'setupCentavos', '') !~ '^[0-9]{1,10}$' then
    raise exception 'gestao: campos obrigatorios ausentes ou invalidos' using errcode = '22023'; end if;
  select id into v_id from public.gestao_vendas where submission_id = v_sub;
  if v_id is not null then return jsonb_build_object('ok', true, 'duplicado', true, 'id', v_id); end if;
  v_cent := (p ->> 'setupCentavos')::numeric / 100;
  if v_arq is not null and jsonb_typeof(v_arq) = 'object' then
    insert into public.gestao_arquivos (id, nome_original, tipo, tamanho, sha256) values ((v_arq ->> 'id')::uuid, v_arq ->> 'nome', v_arq ->> 'tipo', (v_arq ->> 'tamanho')::bigint, v_arq ->> 'sha256')
      on conflict (id) do nothing;
  end if;
  insert into public.gestao_vendas (vendedor_nome, data_venda, plano, setup, cliente_nome, empresa, nicho, whatsapp, email, status, origem, comprovante, submission_id, consentimento_texto, consentimento_em)
  values (btrim(p ->> 'sellerName'), (p ->> 'saleDate')::date, left(p ->> 'plan', 60), v_cent, btrim(p ->> 'clientName'), left(p ->> 'companyName', 200), left(p ->> 'niche', 120),
          left(p ->> 'whatsapp', 40), left(p ->> 'email', 200), 'pendente', 'pagina',
          case when v_arq is not null and jsonb_typeof(v_arq) = 'object' then jsonb_build_object('id', v_arq ->> 'id', 'contentType', v_arq ->> 'tipo', 'sizeBytes', (v_arq ->> 'tamanho')::bigint) end,
          v_sub, p ->> 'consentText', now())
  returning id into v_id;
  return jsonb_build_object('ok', true, 'duplicado', false, 'id', v_id);
exception when unique_violation then
  select id into v_id from public.gestao_vendas where submission_id = v_sub;
  return jsonb_build_object('ok', true, 'duplicado', true, 'id', v_id);
end $_$;


ALTER FUNCTION public.gestao_publico_registrar_venda(p jsonb) OWNER TO postgres;

--
-- Name: gestao_registra_pagamento(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.gestao_registra_pagamento() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if old.pago_em is not null and (to_jsonb(new) - 'atualizado_em') is distinct from (to_jsonb(old) - 'atualizado_em') then
    insert into public.gestao_pagamentos_log (tabela, linha_id, cliente_id, acao, antes, depois, por)
    values (tg_table_name, old.id, old.cliente_id,
            case when new.deleted_at is not null and old.deleted_at is null then 'apagou' when new.pago_em is null then 'desmarcou' else 'alterou' end,
            to_jsonb(old), to_jsonb(new), (select auth.uid()));
  end if;
  return new;
end $$;


ALTER FUNCTION public.gestao_registra_pagamento() OWNER TO postgres;

--
-- Name: gestao_tem_algum_papel(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.gestao_tem_algum_papel() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(
    exists (select 1 from public.profiles p where p.id = (select auth.uid()) and p.system_role = 'platform_admin' and p.deleted_at is null)
    or exists (select 1 from public.gestao_acessos a where a.id = (select auth.uid()) and a.deleted_at is null and cardinality(a.papeis) > 0),
    false) $$;


