--
-- Name: historico_cobranca_lead(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.historico_cobranca_lead(p_lead_id uuid) RETURNS TABLE(tipo text, data timestamp with time zone, valor numeric, status text, campaign_id uuid, campaign_name text, meta jsonb)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
  SELECT
    'pagamento'::text,
    COALESCE(cp.data_pagamento, cp.created_at),
    cp.valor,
    cp.status,
    NULL::uuid,
    NULL::text,
    jsonb_build_object('payment_id', cp.id, 'metodo', cp.metodo_pagamento, 'data_vencimento', cp.data_vencimento, 'descricao', cp.descricao)
  FROM public.pagamentos_cliente cp
  WHERE cp.lead_id = p_lead_id

  UNION ALL

  SELECT
    'campanha_cobranca'::text,
    cl.entered_at,
    NULL::numeric,
    cl.state,
    c.id,
    c.name,
    jsonb_build_object('campaign_lead_id', cl.id, 'phase', cl.phase, 'attempt_count', cl.attempt_count, 'exit_reason', cl.exit_reason)
  FROM public.leads_campanha cl
  JOIN public.campanhas c ON c.id = cl.campaign_id
  WHERE cl.lead_id = p_lead_id
    AND c.type = 'cobranca'
    AND c.deleted_at IS NULL

  ORDER BY 2 DESC NULLS LAST;
$$;


ALTER FUNCTION public.historico_cobranca_lead(p_lead_id uuid) OWNER TO postgres;

--
-- Name: importar_contatos_para_base(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.importar_contatos_para_base(p_tenant_id uuid, p_contatos jsonb) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_caller uuid := auth.uid();
  v_admin boolean := public.is_platform_admin();
  v_team boolean;
  v_count integer := 0;
  v_item jsonb;
BEGIN
  IF v_caller IS NULL THEN RAISE EXCEPTION 'unauthenticated'; END IF;
  SELECT EXISTS (
    SELECT 1 FROM public.profiles
     WHERE id = v_caller AND parent_user_id = p_tenant_id
  ) INTO v_team;
  IF NOT (p_tenant_id = v_caller OR v_admin OR v_team) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;

  FOR v_item IN SELECT * FROM jsonb_array_elements(p_contatos)
  LOOP
    INSERT INTO public.leads (tenant_id, name, nome_exibicao, phone, email, tags, location)
    VALUES (
      p_tenant_id,
      COALESCE(v_item->>'name', v_item->>'phone'),
      v_item->>'name',
      v_item->>'phone',
      v_item->>'email',
      CASE
        WHEN jsonb_typeof(v_item->'tags') = 'array'
          THEN ARRAY(SELECT jsonb_array_elements_text(v_item->'tags'))
        ELSE NULL
      END,
      'base'
    );
    v_count := v_count + 1;
  END LOOP;
  RETURN v_count;
END;
$$;


ALTER FUNCTION public.importar_contatos_para_base(p_tenant_id uuid, p_contatos jsonb) OWNER TO postgres;

