--
-- Name: liberar_zumbis(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.liberar_zumbis(p_max_idade_minutos integer DEFAULT 15) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_count int;
  v_zumbis_outbox int := 0;
BEGIN
  UPDATE public.acoes_agendadas
     SET status = 'falhou',
         tentativas = 999,
         error_message = 'reaper:zumbi_processando_mais_de_' || p_max_idade_minutos || '_min'
   WHERE status = 'processando'
     AND COALESCE(executed_at, created_at) < now() - (p_max_idade_minutos || ' minutes')::interval;

  GET DIAGNOSTICS v_count = ROW_COUNT;

  -- 2026-09-17 (varredura): o reaper só olhava acoes_agendadas. A bolha do
  -- outbox é marcada 'processando' e o envio dorme até 30s; se o worker morre
  -- nesse intervalo (Shutdown/EarlyDrop já aconteceu), ela ficava 'processando'
  -- pra sempre — o lead não recebia e nada acusava. Agora volta pra 'pendente'
  -- pro consumer tentar de novo (respeitando o teto de retries do consumer).
  -- Idade importa: bolha de horas atrás não pode ser despejada no lead agora.
  -- Até 6h → volta pra fila (o consumer respeita o teto de retries).
  -- Mais velha que isso → falhou, pra não mandar conversa fora de contexto.
  UPDATE public.caixa_saida_mensagens
     SET status = CASE
           WHEN COALESCE(updated_at, created_at) < now() - interval '6 hours' THEN 'falhou'
           WHEN COALESCE(retries, 0) >= 3 THEN 'falhou'
           ELSE 'pendente'
         END,
         retries = COALESCE(retries, 0) + 1,
         error_reason = 'reaper:zumbi_processando_mais_de_' || p_max_idade_minutos || '_min'
   WHERE status = 'processando'
     AND COALESCE(updated_at, created_at) < now() - (p_max_idade_minutos || ' minutes')::interval;

  GET DIAGNOSTICS v_zumbis_outbox = ROW_COUNT;
  IF v_zumbis_outbox > 0 THEN
    RAISE WARNING 'liberar_zumbis: % bolha(s) do outbox presas em processando foram liberadas', v_zumbis_outbox;
  END IF;

  RETURN v_count + v_zumbis_outbox;
END;
$$;


ALTER FUNCTION public.liberar_zumbis(p_max_idade_minutos integer) OWNER TO postgres;

--
-- Name: FUNCTION liberar_zumbis(p_max_idade_minutos integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.liberar_zumbis(p_max_idade_minutos integer) IS 'Marca como falhou acoes presas em processando ha mais de N minutos e devolve pra pendente as bolhas do outbox presas do mesmo jeito (2026-09-17). Chamada no inicio de processar-acompanhamentos pra liberar slots travados. Sem trigger separado; SQL barato.';


--
-- Name: limpar_antes_embedar(text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.limpar_antes_embedar(p_text text, p_cap_bytes integer DEFAULT 1500) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
  v_resultado text;
  v_bytes_originais int;
  v_bytes_finais int;
BEGIN
  v_resultado := p_text;
  v_bytes_originais := length(p_text);

  -- Remove linhas com >5 underscores ou hifens consecutivos (separadores)
  v_resultado := regexp_replace(v_resultado, '[_-]{5,}', '', 'g');

  -- Remove placeholders comuns
  v_resultado := regexp_replace(v_resultado, '\[[A-Z_][A-Z0-9_]*\]', '', 'g');  -- [NOME] [CPF]
  v_resultado := regexp_replace(v_resultado, '\{\{[a-z_]+\}\}', '', 'g');       -- {{cliente}}
  v_resultado := regexp_replace(v_resultado, '%s|%d', '', 'g');

  -- Remove cabeçalhos de cláusula repetidos (CLÁUSULA X · § Y)
  v_resultado := regexp_replace(v_resultado, 'CLÁUSULA\s+\d+[º°]?[^\n]*\n', '', 'g');
  v_resultado := regexp_replace(v_resultado, '§\s*\d+[º°]?\s*-', '', 'g');

  -- Normalizar whitespace
  v_resultado := regexp_replace(v_resultado, '\s+', ' ', 'g');
  v_resultado := trim(v_resultado);

  -- Cap em p_cap_bytes (corta em fim de frase mais próximo)
  IF length(v_resultado) > p_cap_bytes THEN
    -- Tenta cortar em '. ' ou '! ' ou '? ' antes do cap
    v_resultado := substring(v_resultado from 1 for p_cap_bytes);
    -- Procura último ponto final · trim
    v_resultado := regexp_replace(v_resultado, '[^.!?]*$', '');
    -- Se ficou vazio · usar cap simples
    IF length(v_resultado) < p_cap_bytes / 2 THEN
      v_resultado := substring(p_text from 1 for p_cap_bytes);
    END IF;
  END IF;

  v_bytes_finais := length(v_resultado);

  RETURN jsonb_build_object(
    'texto_limpo', v_resultado,
    'bytes_originais', v_bytes_originais,
    'bytes_finais', v_bytes_finais,
    'bytes_removidos', v_bytes_originais - v_bytes_finais
  );
END;
$_$;


ALTER FUNCTION public.limpar_antes_embedar(p_text text, p_cap_bytes integer) OWNER TO postgres;

--
-- Name: FUNCTION limpar_antes_embedar(p_text text, p_cap_bytes integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.limpar_antes_embedar(p_text text, p_cap_bytes integer) IS 'D37 fix Luiz. Limpa texto de chunk antes de gerar embedding. Remove separadores, placeholders, cabeçalhos repetidos. Cap configurável.';


--
-- Name: limpar_fluxo_ao_excluir_produto(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.limpar_fluxo_ao_excluir_produto() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_agent record;
  v_quals_validos jsonb;
BEGIN
  FOR v_agent IN
    SELECT au.id, au.fluxo
    FROM public.agentes_usuario au
    WHERE jsonb_typeof(au.fluxo->'qualificacao'->'qualificadores_produto') = 'array'
      AND au.fluxo->'qualificacao'->'qualificadores_produto' @> jsonb_build_array(jsonb_build_object('produto_id', OLD.id::text))
  LOOP
    SELECT COALESCE(
      jsonb_agg(qp ORDER BY ord)
        FILTER (WHERE qp->>'produto_id' <> OLD.id::text),
      '[]'::jsonb
    )
    INTO v_quals_validos
    FROM jsonb_array_elements(v_agent.fluxo->'qualificacao'->'qualificadores_produto') WITH ORDINALITY AS t(qp, ord);

    UPDATE public.agentes_usuario
    SET fluxo = jsonb_set(fluxo, '{qualificacao,qualificadores_produto}', v_quals_validos, false),
        updated_at = now()
    WHERE id = v_agent.id;
  END LOOP;

  RETURN OLD;
END;
$$;


ALTER FUNCTION public.limpar_fluxo_ao_excluir_produto() OWNER TO postgres;

--
-- Name: limpar_fluxo_ao_excluir_produto_midia(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.limpar_fluxo_ao_excluir_produto_midia() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_agent record;
  v_fase text;
  v_midias_validas jsonb;
BEGIN
  FOR v_agent IN
    SELECT au.id, au.fluxo
    FROM public.agentes_usuario au
    WHERE au.fluxo IS NOT NULL
  LOOP
    FOR v_fase IN SELECT unnest(ARRAY['saudacao','qualificacao','apresentacao','negociacao','fechado'])
    LOOP
      IF jsonb_typeof(v_agent.fluxo->v_fase->'midias_envio') = 'array'
         AND v_agent.fluxo->v_fase->'midias_envio' @> jsonb_build_array(jsonb_build_object('produto_midia_id', OLD.id::text)) THEN
        SELECT COALESCE(
          jsonb_agg(m ORDER BY ord)
            FILTER (WHERE m->>'produto_midia_id' <> OLD.id::text),
          '[]'::jsonb
        )
        INTO v_midias_validas
        FROM jsonb_array_elements(v_agent.fluxo->v_fase->'midias_envio') WITH ORDINALITY AS t(m, ord);

        UPDATE public.agentes_usuario
        SET fluxo = jsonb_set(fluxo, ARRAY[v_fase, 'midias_envio'], v_midias_validas, false),
            updated_at = now()
        WHERE id = v_agent.id;
      END IF;
    END LOOP;
  END LOOP;

  RETURN OLD;
END;
$$;


ALTER FUNCTION public.limpar_fluxo_ao_excluir_produto_midia() OWNER TO postgres;

--
-- Name: limpar_intencoes_antigas(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.limpar_intencoes_antigas() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_apagadas int;
BEGIN
  WITH ranqueadas AS (
    SELECT id,
           row_number() OVER (PARTITION BY conversa_id ORDER BY criado_em DESC) AS pos
    FROM public.intencoes_pendentes
  ),
  apagar AS (
    DELETE FROM public.intencoes_pendentes ip
    USING ranqueadas r
    WHERE ip.id = r.id
      AND r.pos > 5
      AND ip.criado_em < now() - interval '30 days'
    RETURNING ip.id
  )
  SELECT count(*)::int INTO v_apagadas FROM apagar;
  RETURN v_apagadas;
END;
$$;


ALTER FUNCTION public.limpar_intencoes_antigas() OWNER TO postgres;

--
-- Name: limpar_prompts_turno_expirados(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.limpar_prompts_turno_expirados() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_dias    integer;
  v_apagados integer;
begin
  select coalesce(max(retencao_prompts_turno_dias), 90) into v_dias
  from public.config_plataforma;

  delete from public.prompts_turno
  where criado_em < now() - (v_dias || ' days')::interval;

  get diagnostics v_apagados = row_count;
  return v_apagados;
end;
$$;


ALTER FUNCTION public.limpar_prompts_turno_expirados() OWNER TO postgres;

--
-- Name: limpar_traces_antigos(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.limpar_traces_antigos() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_apagados int;
BEGIN
  WITH apagar AS (
    DELETE FROM public.traces
    WHERE criado_em < now() - interval '90 days'
    RETURNING id
  )
  SELECT count(*)::int INTO v_apagados FROM apagar;
  RETURN v_apagados;
END;
$$;


ALTER FUNCTION public.limpar_traces_antigos() OWNER TO postgres;

--
-- Name: linha_do_tempo_contato(uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.linha_do_tempo_contato(p_lead_id uuid, p_tenant_id uuid, p_limite integer DEFAULT 12) RETURNS TABLE(quando timestamp with time zone, tipo text, descricao text)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
  WITH eventos AS (
    -- contrato emitido
    SELECT c.created_at AS quando, 'contrato'::text AS tipo,
           ('contrato "' || coalesce(nullif(c.titulo,''),'sem título') || '" emitido'
            || CASE WHEN c.status IS NOT NULL THEN ' (status: ' || c.status || ')' ELSE '' END) AS descricao
    FROM public.contratos c
    WHERE c.lead_id = p_lead_id AND c.tenant_id = p_tenant_id
    UNION ALL
    -- contrato assinado
    SELECT c.assinado_em, 'contrato_assinado'::text,
           ('contrato "' || coalesce(nullif(c.titulo,''),'sem título') || '" ASSINADO pelo cliente')
    FROM public.contratos c
    WHERE c.lead_id = p_lead_id AND c.tenant_id = p_tenant_id AND c.assinado_em IS NOT NULL
    UNION ALL
    -- pagamento recebido (comprovante anexado ao contrato)
    SELECT c.created_at, 'pagamento'::text,
           ('pagamento recebido'
            || CASE WHEN c.metodo_pagamento IS NOT NULL THEN ' via ' || c.metodo_pagamento ELSE '' END
            || ' (comprovante anexado)')
    FROM public.contratos c
    WHERE c.lead_id = p_lead_id AND c.tenant_id = p_tenant_id AND c.url_comprovante_pagamento IS NOT NULL
    UNION ALL
    -- compromissos ativos (promessas/follow-ups com data)
    SELECT coalesce(ca.executar_em, ca.created_at), 'compromisso'::text,
           (coalesce(nullif(ca.titulo,''), ca.tipo, 'compromisso')
            || CASE WHEN ca.status IS NOT NULL THEN ' (' || ca.status || ')' ELSE '' END)
    FROM public.compromissos_ativos ca
    WHERE ca.lead_id = p_lead_id AND ca.tenant_id = p_tenant_id
    UNION ALL
    -- ações agendadas (callbacks)
    SELECT coalesce(aa.executed_at, aa.scheduled_at), 'agendamento'::text,
           (coalesce(aa.action_type, 'ação') || ' agendada'
            || CASE WHEN aa.status IS NOT NULL THEN ' (' || aa.status || ')' ELSE '' END)
    FROM public.acoes_agendadas aa
    WHERE aa.lead_id = p_lead_id AND aa.tenant_id = p_tenant_id
  )
  SELECT quando, tipo, descricao FROM (
    SELECT quando, tipo, descricao FROM eventos WHERE quando IS NOT NULL ORDER BY quando DESC LIMIT p_limite
  ) sub
  ORDER BY quando ASC;
$$;


ALTER FUNCTION public.linha_do_tempo_contato(p_lead_id uuid, p_tenant_id uuid, p_limite integer) OWNER TO postgres;

--
-- Name: listar_jobs_com_historico(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.listar_jobs_com_historico() RETURNS TABLE(nome text, descricao text, categoria text, cron_expr text, ativo boolean, jobid_pg_cron integer, ultima_exec timestamp with time zone, status_ultima text, falhas_7d bigint, sucessos_7d bigint, duracao_media_ms numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM public.user_roles
    WHERE user_id = (SELECT auth.uid())
      AND role IN ('admin','platform_admin')
  ) THEN
    RAISE EXCEPTION 'sem permissao' USING ERRCODE = 'insufficient_privilege';
  END IF;

  RETURN QUERY
    SELECT ac.nome, ac.descricao, ac.categoria, ac.cron_expr, ac.ativo,
           ac.jobid_pg_cron, s.ultima_exec, s.status_ultima,
           COALESCE(s.falhas_7d, 0), COALESCE(s.sucessos_7d, 0), s.duracao_media_ms
    FROM public.agendamentos_config ac
    LEFT JOIN public.vw_cron_saude s ON s.jobid = ac.jobid_pg_cron
    ORDER BY ac.categoria, ac.nome;
END;
$$;


ALTER FUNCTION public.listar_jobs_com_historico() OWNER TO postgres;

--
-- Name: listar_leads_por_dia(uuid, timestamp with time zone, timestamp with time zone, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.listar_leads_por_dia(p_tenant_id uuid, p_inicio timestamp with time zone, p_fim timestamp with time zone, p_limite integer DEFAULT 20) RETURNS TABLE(lead_id uuid, name text, phone text, temperatura_lead text, fase_pipeline text, updated_at timestamp with time zone, total_mensagens bigint, ultima_mensagem_em timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  SELECT l.id,
         l.name,
         l.phone,
         l.temperatura_lead,
         l.fase_pipeline,
         l.updated_at,
         COUNT(m.id) AS total_mensagens,
         MAX(m.created_at) AS ultima_mensagem_em
  FROM public.mensagens m
  JOIN public.conversas c ON c.id = m.conversation_id
  JOIN public.leads l ON l.id = c.lead_id
  WHERE c.tenant_id = p_tenant_id
    AND c.channel <> 'teste'
    AND m.created_at >= p_inicio
    AND m.created_at < p_fim
    AND m.deleted_at IS NULL
  GROUP BY l.id
  ORDER BY MAX(m.created_at) DESC
  LIMIT LEAST(GREATEST(COALESCE(p_limite, 20), 1), 50)
$$;


ALTER FUNCTION public.listar_leads_por_dia(p_tenant_id uuid, p_inicio timestamp with time zone, p_fim timestamp with time zone, p_limite integer) OWNER TO postgres;

--
-- Name: marcar_conversa_lida(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.marcar_conversa_lida(p_conv_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_tenant uuid;
  v_caller uuid := (select auth.uid());
BEGIN
  SELECT tenant_id INTO v_tenant FROM public.conversas WHERE id = p_conv_id;
  IF v_tenant IS NULL THEN RETURN; END IF;

  IF v_tenant != v_caller
     AND NOT public.is_platform_admin()
     AND NOT EXISTS (
       SELECT 1 FROM public.profiles
       WHERE id = v_caller AND parent_user_id = v_tenant
     )
  THEN
    RAISE EXCEPTION 'sem permissao pra marcar conversa lida';
  END IF;

  UPDATE public.conversas
  SET visto_em = now()
  WHERE id = p_conv_id;
END;
$$;


ALTER FUNCTION public.marcar_conversa_lida(p_conv_id uuid) OWNER TO postgres;

--
-- Name: marcar_handoff_atendido(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.marcar_handoff_atendido(p_lead_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_tenant uuid; v_caller uuid := (select auth.uid());
BEGIN
  SELECT tenant_id INTO v_tenant FROM public.leads WHERE id = p_lead_id;
  IF v_tenant IS NULL THEN RETURN; END IF;
  IF v_tenant != v_caller AND NOT public.is_platform_admin()
     AND NOT EXISTS (SELECT 1 FROM public.profiles WHERE id = v_caller AND parent_user_id = v_tenant) THEN
    RAISE EXCEPTION 'sem permissao pra atender handoff';
  END IF;
  UPDATE public.leads SET precisa_humano = false WHERE id = p_lead_id;
  UPDATE public.conversas SET visto_em = now(), status = 'humano', agent_enabled = false WHERE lead_id = p_lead_id;
END;
$$;


ALTER FUNCTION public.marcar_handoff_atendido(p_lead_id uuid) OWNER TO postgres;

--
-- Name: marcar_lead_convertido_por_contrato(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.marcar_lead_convertido_por_contrato() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_valor numeric;
BEGIN
  IF NEW.lead_id IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT COALESCE(SUM(ci.subtotal), 0) INTO v_valor
  FROM public.contrato_itens ci
  WHERE ci.contrato_id = NEW.id;

  UPDATE public.leads l
  SET desfecho = 'convertido',
      desfecho_em = COALESCE(NEW.assinado_em, now()),
      desfecho_motivo = 'contrato assinado',
      valor_conversao = COALESCE(NULLIF(v_valor, 0), l.valor_conversao)
  WHERE l.id = NEW.lead_id
    AND l.desfecho IS DISTINCT FROM 'convertido';

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.marcar_lead_convertido_por_contrato() OWNER TO postgres;

--
-- Name: marcar_lead_recusado(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.marcar_lead_recusado(p_lead_id uuid, p_motivo text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF NOT public._lead_pertence_caller(p_lead_id) THEN
    RAISE EXCEPTION 'sem permissão para este lead';
  END IF;

  UPDATE public.leads
  SET desfecho = 'recusado',
      desfecho_em = now(),
      desfecho_motivo = COALESCE(NULLIF(trim(p_motivo), ''), 'recusado (manual)')
  WHERE id = p_lead_id
    AND deleted_at IS NULL
    AND desfecho IS DISTINCT FROM 'convertido';

  RETURN FOUND;
END;
$$;


ALTER FUNCTION public.marcar_lead_recusado(p_lead_id uuid, p_motivo text) OWNER TO postgres;

--
-- Name: marcar_leads_sumidos(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.marcar_leads_sumidos(p_dias_sem_resposta integer DEFAULT 7) RETURNS TABLE(marcados integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_marcados int;
BEGIN
  WITH atualizados AS (
    UPDATE public.leads l
    SET desfecho = 'sumido',
        desfecho_em = now(),
        desfecho_motivo = 'sem resposta há ' || p_dias_sem_resposta || 'd (cron)'
    WHERE l.desfecho IS NULL
      AND l.deleted_at IS NULL
      -- última mensagem do LEAD (role='user') nessa conversa > X dias atrás
      AND NOT EXISTS (
        SELECT 1 FROM public.mensagens m
        JOIN public.conversas c ON c.id = m.conversation_id
        WHERE c.lead_id = l.id
          AND m.role = 'user'
          AND m.created_at > (now() - (p_dias_sem_resposta || ' days')::interval)
      )
      -- e existe pelo menos 1 conversa antiga (lead conversou em algum momento)
      AND EXISTS (
        SELECT 1 FROM public.conversas c WHERE c.lead_id = l.id
      )
    RETURNING l.id
  )
  SELECT count(*)::int INTO v_marcados FROM atualizados;

  RETURN QUERY SELECT v_marcados;
END;
$$;


ALTER FUNCTION public.marcar_leads_sumidos(p_dias_sem_resposta integer) OWNER TO postgres;

