--
-- Name: memoria_lead_similar(uuid, extensions.halfvec, double precision, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.memoria_lead_similar(p_lead_id uuid, p_embedding extensions.halfvec, p_threshold double precision DEFAULT 0.85, p_top_k integer DEFAULT 5) RETURNS TABLE(id uuid, fato text, similarity double precision)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
  -- Gate anti-duplicado Mem0-style:
  -- Retorna fatos semanticamente similares para o lead especificado.
  -- Se retornar rows: fato já existe semanticamente → NOOP/UPDATE.
  -- Se retornar vazio: fato novo → ADD.
  -- Filtro duplo lead_id + tenant_id garante isolamento por lead E por tenant (anti-LGPD-break).
  -- fonte != 'teste': fixtures de teste não contaminam busca de produção (anti-envenenamento Wave 0).
  SELECT
    lm.id,
    lm.fato,
    1.0 - (lm.vetor_semantico <=> p_embedding) AS similarity
  FROM public.memoria_lead lm
  WHERE lm.lead_id           = p_lead_id
    AND lm.tenant_id         = (select auth.uid())
    AND lm.ativa             = true
    AND lm.embedding_status  = 'ready'
    AND lm.fonte             != 'teste'
    AND (1.0 - (lm.vetor_semantico <=> p_embedding)) >= p_threshold
  ORDER BY lm.vetor_semantico <=> p_embedding ASC
  LIMIT p_top_k;
$$;


ALTER FUNCTION public.memoria_lead_similar(p_lead_id uuid, p_embedding extensions.halfvec, p_threshold double precision, p_top_k integer) OWNER TO postgres;

--
-- Name: FUNCTION memoria_lead_similar(p_lead_id uuid, p_embedding extensions.halfvec, p_threshold double precision, p_top_k integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.memoria_lead_similar(p_lead_id uuid, p_embedding extensions.halfvec, p_threshold double precision, p_top_k integer) IS 'Gate anti-duplicado para lead_memory (R01.4 — Motor Vivo). p_lead_id OBRIGATÓRIO sem default — evita vazamento de memória entre leads (LGPD). Filtro duplo: lead_id = p_lead_id AND tenant_id = auth.uid(). Retorna fatos com similaridade cosine >= p_threshold (default 0.85).';


--
-- Name: mesclar_lead(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.mesclar_lead(p_lead_duplicado_id uuid, p_lead_canonico_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_a uuid; v_b uuid;
BEGIN
  SELECT tenant_id INTO v_a FROM public.leads WHERE id = p_lead_duplicado_id;
  SELECT tenant_id INTO v_b FROM public.leads WHERE id = p_lead_canonico_id;
  IF v_a IS NULL OR v_b IS NULL OR v_a <> v_b THEN
    RAISE EXCEPTION 'leads de tenants diferentes ou inexistentes';
  END IF;
  UPDATE public.leads SET mesclado_em = p_lead_canonico_id, deleted_at = now()
  WHERE id = p_lead_duplicado_id AND mesclado_em IS NULL;
  RETURN FOUND;
END;
$$;


ALTER FUNCTION public.mesclar_lead(p_lead_duplicado_id uuid, p_lead_canonico_id uuid) OWNER TO postgres;

--
-- Name: metricas_base(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.metricas_base(p_tenant_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_caller uuid := auth.uid();
  v_admin boolean := public.is_platform_admin();
  v_team boolean;
  v_total integer;
  v_leads integer;
  v_clientes integer;
  v_top_produto text;
  v_distribuicao_tags jsonb;
  v_distribuicao_meses jsonb;
  v_total_consumido numeric;
BEGIN
  IF v_caller IS NULL THEN RAISE EXCEPTION 'unauthenticated'; END IF;
  SELECT EXISTS (
    SELECT 1 FROM public.profiles
     WHERE id = v_caller AND parent_user_id = p_tenant_id
  ) INTO v_team;
  IF NOT (p_tenant_id = v_caller OR v_admin OR v_team) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;

  SELECT COUNT(*),
         COUNT(*) FILTER (WHERE converted_at IS NULL),
         COUNT(*) FILTER (WHERE converted_at IS NOT NULL)
    INTO v_total, v_leads, v_clientes
    FROM public.leads
   WHERE tenant_id = p_tenant_id
     AND location = 'base'
     AND deleted_at IS NULL;

  SELECT product INTO v_top_produto
    FROM public.leads
   WHERE tenant_id = p_tenant_id
     AND location = 'base'
     AND deleted_at IS NULL
     AND product IS NOT NULL
   GROUP BY product
   ORDER BY COUNT(*) DESC
   LIMIT 1;

  SELECT COALESCE(jsonb_object_agg(tag, qtd), '{}'::jsonb)
    INTO v_distribuicao_tags
  FROM (
    SELECT unnest(tags) AS tag, COUNT(*) AS qtd
      FROM public.leads
     WHERE tenant_id = p_tenant_id
       AND location = 'base'
       AND deleted_at IS NULL
       AND tags IS NOT NULL
     GROUP BY tag
     ORDER BY qtd DESC
     LIMIT 20
  ) t;

  SELECT COALESCE(jsonb_object_agg(mes, qtd), '{}'::jsonb)
    INTO v_distribuicao_meses
  FROM (
    SELECT to_char(date_trunc('month', created_at), 'YYYY-MM') AS mes,
           COUNT(*) AS qtd
      FROM public.leads
     WHERE tenant_id = p_tenant_id
       AND location = 'base'
       AND deleted_at IS NULL
     GROUP BY mes
     ORDER BY mes DESC
     LIMIT 12
  ) m;

  SELECT COALESCE(SUM(cp.valor), 0)
    INTO v_total_consumido
    FROM public.pagamentos_cliente cp
    JOIN public.leads l ON l.id = cp.lead_id
   WHERE l.tenant_id = p_tenant_id
     AND l.location = 'base'
     AND l.converted_at IS NOT NULL
     AND l.deleted_at IS NULL;

  RETURN jsonb_build_object(
    'total', v_total,
    'leads', v_leads,
    'clientes', v_clientes,
    'produto_mais_vendido', v_top_produto,
    'distribuicao_tags', v_distribuicao_tags,
    'distribuicao_temporal_meses', v_distribuicao_meses,
    'total_consumido_clientes', v_total_consumido
  );
END;
$$;


ALTER FUNCTION public.metricas_base(p_tenant_id uuid) OWNER TO postgres;

--
-- Name: metricas_campanha(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.metricas_campanha(p_tenant_id uuid, p_campaign_id uuid) RETURNS TABLE(total_leads integer, leads_por_state jsonb, tempo_medio_minutos_ate_fechamento numeric, taxa_conversao numeric, reproposta_count_total integer, atividade_ultimas_24h integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  -- Valida tenant ownership
  PERFORM 1 FROM public.campanhas
   WHERE id = p_campaign_id AND tenant_id = p_tenant_id AND deleted_at IS NULL;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'campaign % não pertence ao tenant %', p_campaign_id, p_tenant_id
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  RETURN QUERY
  WITH base AS (
    SELECT * FROM public.leads_campanha
     WHERE campaign_id = p_campaign_id
       AND archived_at IS NULL
  )
  SELECT
    (SELECT count(*)::int FROM base) AS total_leads,
    (
      SELECT coalesce(jsonb_object_agg(state, c), '{}'::jsonb)
        FROM (SELECT state, count(*) AS c FROM base GROUP BY state) s
    ) AS leads_por_state,
    (
      SELECT round(avg(EXTRACT(EPOCH FROM (closed_at - entered_at)) / 60)::numeric, 2)
        FROM base WHERE closed_at IS NOT NULL
    ) AS tempo_medio_minutos_ate_fechamento,
    (
      SELECT CASE WHEN count(*) = 0 THEN 0
                  ELSE round((count(*) FILTER (WHERE state = 'fechado'))::numeric / count(*) * 100, 2)
             END
        FROM base
    ) AS taxa_conversao,
    (SELECT coalesce(sum(reproposta_count), 0)::int FROM base) AS reproposta_count_total,
    (SELECT count(*)::int FROM base WHERE last_contact_at > now() - interval '24 hours') AS atividade_ultimas_24h;
END;
$$;


ALTER FUNCTION public.metricas_campanha(p_tenant_id uuid, p_campaign_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION metricas_campanha(p_tenant_id uuid, p_campaign_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.metricas_campanha(p_tenant_id uuid, p_campaign_id uuid) IS 'Item #5 ALTERAÇÕES: agregados de uma campanha pra dashboard Esteira.';


--
-- Name: metricas_unread_humano(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.metricas_unread_humano(p_tenant_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_caller uuid := (select auth.uid()); v_atendimento int; v_clientes int; v_campanha int; v_handoffs int;
BEGIN
  IF p_tenant_id != v_caller AND NOT public.is_platform_admin()
     AND NOT EXISTS (SELECT 1 FROM public.profiles WHERE id = v_caller AND parent_user_id = p_tenant_id) THEN
    RAISE EXCEPTION 'sem permissao pra ver metricas do tenant';
  END IF;
  SELECT count(DISTINCT c.id) INTO v_atendimento FROM public.conversas c JOIN public.leads l ON l.id = c.lead_id
  WHERE c.tenant_id = p_tenant_id AND c.agent_enabled = false AND coalesce(c.status,'ativa') != 'campaign'
    AND l.location = 'atendimento' AND l.deleted_at IS NULL
    AND EXISTS (SELECT 1 FROM public.mensagens m WHERE m.conversation_id = c.id AND m.role = 'user' AND m.deleted_at IS NULL AND m.created_at > coalesce(c.visto_em,'1970-01-01'::timestamptz));
  SELECT count(DISTINCT c.id) INTO v_clientes FROM public.conversas c JOIN public.leads l ON l.id = c.lead_id
  WHERE c.tenant_id = p_tenant_id AND c.agent_enabled = false AND l.location = 'cliente' AND l.deleted_at IS NULL
    AND EXISTS (SELECT 1 FROM public.mensagens m WHERE m.conversation_id = c.id AND m.role = 'user' AND m.deleted_at IS NULL AND m.created_at > coalesce(c.visto_em,'1970-01-01'::timestamptz));
  SELECT count(DISTINCT c.id) INTO v_campanha FROM public.conversas c
  WHERE c.tenant_id = p_tenant_id AND c.agent_enabled = false
    AND (c.status = 'campaign' OR EXISTS (SELECT 1 FROM public.leads_campanha cl WHERE cl.lead_id = c.lead_id AND cl.state = 'ativo'))
    AND EXISTS (SELECT 1 FROM public.mensagens m WHERE m.conversation_id = c.id AND m.role = 'user' AND m.deleted_at IS NULL AND m.created_at > coalesce(c.visto_em,'1970-01-01'::timestamptz));
  SELECT count(DISTINCT l.id) INTO v_handoffs FROM public.leads l
  WHERE l.tenant_id = p_tenant_id AND l.precisa_humano = true AND l.deleted_at IS NULL;
  RETURN jsonb_build_object('atendimento', v_atendimento, 'clientes', v_clientes, 'campanha', v_campanha, 'handoffs_pendentes', v_handoffs, 'total', v_atendimento + v_clientes + v_campanha + v_handoffs);
END;
$$;


ALTER FUNCTION public.metricas_unread_humano(p_tenant_id uuid) OWNER TO postgres;

--
-- Name: migrar_automacoes_para_retornos(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.migrar_automacoes_para_retornos(cfg jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  auto_contrato jsonb;
  agendamento_callback jsonb;
  lemb_assinatura jsonb;
  lemb_pagamento jsonb;
  novo_retornos jsonb;
  assinatura_valor int;
  assinatura_unidade text;
  pagamento_valor int;
  pagamento_unidade text;
BEGIN
  auto_contrato := cfg -> 'automacoes_contrato';
  agendamento_callback := cfg -> 'agendamento_callback';
  lemb_assinatura := auto_contrato -> 'lembrete_assinatura';
  lemb_pagamento := auto_contrato -> 'lembrete_pagamento';

  assinatura_valor := COALESCE((lemb_assinatura #>> '{intervalo,valor}')::int, 1);
  assinatura_unidade := COALESCE(lemb_assinatura #>> '{intervalo,unidade}', 'horas');
  pagamento_valor := COALESCE((lemb_pagamento #>> '{intervalo,valor}')::int, 2);
  pagamento_unidade := COALESCE(lemb_pagamento #>> '{intervalo,unidade}', 'horas');

  novo_retornos := jsonb_build_object(
    'agendamento_retorno', jsonb_build_object(
      'ativo', COALESCE((agendamento_callback ->> 'ativo')::boolean, true),
      'horario_default', '09:00',
      'dias_uteis_apenas', false,
      'janela_horario', jsonb_build_object('inicio', '08:00', 'fim', '20:00'),
      'lembrete_antes', COALESCE(agendamento_callback -> 'lembrete_retorno', jsonb_build_object('ativo', false, 'minutos_antes', 30)),
      'retomada', jsonb_build_object('tom', 'empatico')
    ),

    'cobranca_assinatura', jsonb_build_object(
      'ativo', COALESCE((lemb_assinatura ->> 'ativo')::boolean, true),
      'dias_uteis_apenas', false,
      'janela_horario', jsonb_build_object('inicio', '09:00', 'fim', '19:00'),
      'escalar_humano_apos_ultima', true,
      'tentativas', jsonb_build_array(
        jsonb_build_object(
          'ordem', 1,
          'quando', jsonb_build_object('tipo', 'tempo_relativo', 'valor', assinatura_valor, 'unidade', assinatura_unidade, 'base', 'envio_contrato'),
          'tom', 'empatico'
        ),
        jsonb_build_object(
          'ordem', 2,
          'quando', jsonb_build_object('tipo', 'tempo_relativo', 'valor', 24, 'unidade', 'horas', 'base', 'envio_contrato'),
          'tom', 'direto'
        ),
        jsonb_build_object(
          'ordem', 3,
          'quando', jsonb_build_object('tipo', 'tempo_relativo', 'valor', 72, 'unidade', 'horas', 'base', 'envio_contrato'),
          'tom', 'final'
        )
      )
    ),

    'cobranca_pagamento', jsonb_build_object(
      'ativo', COALESCE((lemb_pagamento ->> 'ativo')::boolean, true),
      'dias_uteis_apenas', false,
      'janela_horario', jsonb_build_object('inicio', '08:00', 'fim', '21:00'),
      'escalar_humano_apos_ultima', true,
      'pos_assinatura_sem_data_prometida', jsonb_build_object(
        'tentativas', jsonb_build_array(
          jsonb_build_object(
            'ordem', 1,
            'quando', jsonb_build_object('tipo', 'tempo_relativo', 'valor', pagamento_valor, 'unidade', pagamento_unidade, 'base', 'assinatura'),
            'tom', 'empatico'
          ),
          jsonb_build_object(
            'ordem', 2,
            'quando', jsonb_build_object('tipo', 'tempo_relativo', 'valor', 24, 'unidade', 'horas', 'base', 'assinatura'),
            'tom', 'direto'
          ),
          jsonb_build_object(
            'ordem', 3,
            'quando', jsonb_build_object('tipo', 'tempo_relativo', 'valor', 72, 'unidade', 'horas', 'base', 'assinatura'),
            'tom', 'final'
          )
        )
      ),
      'quando_lead_promete_data', jsonb_build_object(
        'respeitar_horario_lead', true,
        'tentativas', jsonb_build_array(
          jsonb_build_object(
            'ordem', 1,
            'quando', jsonb_build_object('tipo', 'relativo_a_data_prometida', 'offset_dias', 0, 'horario_padrao', '18:00', 'respeitar_horario_lead', true),
            'tom', 'empatico'
          ),
          jsonb_build_object(
            'ordem', 2,
            'quando', jsonb_build_object('tipo', 'relativo_a_data_prometida', 'offset_dias', 1, 'horario_padrao', '10:00', 'respeitar_horario_lead', false),
            'tom', 'direto'
          ),
          jsonb_build_object(
            'ordem', 3,
            'quando', jsonb_build_object('tipo', 'relativo_a_data_prometida', 'offset_dias', 2, 'horario_padrao', '15:00', 'respeitar_horario_lead', false),
            'tom', 'final'
          )
        )
      )
    )
  );

  RETURN cfg || jsonb_build_object('retornos', novo_retornos);
END;
$$;


ALTER FUNCTION public.migrar_automacoes_para_retornos(cfg jsonb) OWNER TO postgres;

--
-- Name: migrar_filtros_campanha(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.migrar_filtros_campanha(p_campaign_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_filters       jsonb;
  v_tags          text[];
  v_tag           text;
  v_key           text;
  v_val           text;
  v_chave_can     text;
  v_valor_can     text;
  v_alias_chave   text;
  v_alias_valor   text;
  v_map           jsonb := '{}'::jsonb;
  v_criterios     jsonb;
BEGIN
  SELECT filters INTO v_filters FROM public.campanhas WHERE id = p_campaign_id;
  IF v_filters IS NULL THEN RETURN; END IF;

  -- idempotente: já migrado
  IF v_filters ? 'criterios' THEN RETURN; END IF;

  SELECT ARRAY(SELECT jsonb_array_elements_text(v_filters -> 'tags'))
  INTO v_tags;

  IF v_tags IS NULL OR array_length(v_tags, 1) IS NULL THEN
    UPDATE public.campanhas
    SET filters = v_filters
      || jsonb_build_object(
           'criterios',       '[]'::jsonb,
           'operador_global', 'AND',
           'legado_backup',   v_filters)
    WHERE id = p_campaign_id;
    RETURN;
  END IF;

  FOREACH v_tag IN ARRAY v_tags LOOP
    v_key := split_part(v_tag, ':', 1);
    v_val := CASE
               WHEN position(':' IN v_tag) > 0
               THEN substring(v_tag FROM position(':' IN v_tag) + 1)
               ELSE ''
             END;

    -- lookup alias exato (chave:valor)
    SELECT tva.chave_canonica, tva.valor_canonico
    INTO   v_alias_chave, v_alias_valor
    FROM   public.alias_vocabulario_tag tva
    WHERE  tva.alias = v_tag AND tva.escopo = 'plataforma'
    LIMIT  1;

    IF FOUND THEN
      v_chave_can := v_alias_chave;
      v_valor_can := v_alias_valor;
    ELSE
      -- lookup só pela chave
      SELECT tva.chave_canonica, tva.valor_canonico
      INTO   v_alias_chave, v_alias_valor
      FROM   public.alias_vocabulario_tag tva
      WHERE  tva.alias = v_key AND tva.escopo = 'plataforma'
      LIMIT  1;

      IF FOUND THEN
        v_chave_can := v_alias_chave;
        v_valor_can := COALESCE(NULLIF(v_val, ''), v_alias_valor);
      ELSE
        v_chave_can := v_key;
        v_valor_can := COALESCE(NULLIF(v_val, ''), v_key);
      END IF;
    END IF;

    -- agrupar por chave no map
    IF v_map ? v_chave_can THEN
      v_map := jsonb_set(v_map, ARRAY[v_chave_can],
               (v_map -> v_chave_can) || to_jsonb(v_valor_can));
    ELSE
      v_map := v_map || jsonb_build_object(v_chave_can, jsonb_build_array(v_valor_can));
    END IF;
  END LOOP;

  -- map → array de critérios
  SELECT jsonb_agg(
    jsonb_build_object('chave', k.key, 'operador', 'in', 'valores', k.value)
  )
  INTO v_criterios
  FROM jsonb_each(v_map) AS k;

  UPDATE public.campanhas
  SET filters = v_filters
    || jsonb_build_object(
         'criterios',       COALESCE(v_criterios, '[]'::jsonb),
         'operador_global', COALESCE(v_filters ->> 'operator', 'AND'),
         'legado_backup',   v_filters)
  WHERE id = p_campaign_id;
END;
$$;


ALTER FUNCTION public.migrar_filtros_campanha(p_campaign_id uuid) OWNER TO postgres;

--
-- Name: monitor_saude_motor(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.monitor_saude_motor() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_alertas jsonb := '[]'::jsonb;
  v_motor_parado jsonb;
  v_leads_sem_resposta jsonb;
  v_retries_falhando jsonb;
BEGIN
  PERFORM set_config('search_path', 'public', true);
  PERFORM set_config('statement_timeout', '10s', true);

  WITH ultimas AS (
    SELECT 
      c.id AS conversation_id,
      c.tenant_id,
      c.agente_id,
      c.status,
      c.agent_enabled,
      MAX(m.created_at) FILTER (WHERE m.role = 'user') AS ultima_user,
      MAX(m.created_at) FILTER (WHERE m.role IN ('assistant','human')) AS ultima_agente,
      COUNT(*) FILTER (WHERE m.role = 'user' AND m.created_at > now() - interval '48 hours') AS msgs_lead_48h,
      COUNT(*) FILTER (WHERE m.role IN ('assistant','human') AND m.created_at > now() - interval '48 hours') AS msgs_agente_48h
    FROM mensagens m
    JOIN conversas c ON c.id = m.conversation_id
    WHERE c.status IN ('ativa', 'humano')
      AND c.agent_enabled IS NOT FALSE
      AND m.deleted_at IS NULL
      AND m.created_at > now() - interval '48 hours'
    GROUP BY c.id, c.tenant_id, c.agente_id, c.status, c.agent_enabled
  ),
  motor_parado AS (
    SELECT 
      conversation_id,
      tenant_id,
      agente_id,
      ultima_user,
      ultima_agente,
      EXTRACT(EPOCH FROM (now() - ultima_user))/60 AS min_sem_resposta
    FROM ultimas
    WHERE ultima_user > COALESCE(ultima_agente, '1970-01-01'::timestamptz)
      AND ultima_user < now() - interval '30 minutes'
      AND msgs_lead_48h > 0
  )
  SELECT COALESCE(jsonb_agg(to_jsonb(m) ORDER BY m.min_sem_resposta DESC), '[]'::jsonb)
  INTO v_motor_parado
  FROM motor_parado m
  WHERE m.min_sem_resposta > 30
  LIMIT 50;

  IF jsonb_array_length(v_motor_parado) > 0 THEN
    v_alertas := v_alertas || jsonb_build_object(
      'tipo', 'motor_parado',
      'severity', 'vermelho',
      'count', jsonb_array_length(v_motor_parado),
      'detalhes', v_motor_parado
    );
  END IF;

  WITH sem_resposta AS (
    SELECT 
      c.tenant_id,
      COUNT(DISTINCT c.id) AS conversas_afetadas,
      COUNT(*) FILTER (WHERE c.agent_enabled IS NOT FALSE) AS com_agente_ligado
    FROM conversas c
    WHERE c.status IN ('ativa', 'humano')
      AND c.agent_enabled IS NOT FALSE
      AND EXISTS (
        SELECT 1 FROM mensagens m
        WHERE m.conversation_id = c.id
          AND m.role = 'user'
          AND m.deleted_at IS NULL
          AND m.created_at > now() - interval '30 minutes'
      )
      AND NOT EXISTS (
        SELECT 1 FROM mensagens m
        WHERE m.conversation_id = c.id
          AND m.role IN ('assistant','human')
          AND m.deleted_at IS NULL
          AND m.created_at > now() - interval '30 minutes'
      )
    GROUP BY c.tenant_id
    HAVING COUNT(DISTINCT c.id) >= 3
  )
  SELECT COALESCE(jsonb_agg(to_jsonb(s) ORDER BY s.conversas_afetadas DESC), '[]'::jsonb)
  INTO v_leads_sem_resposta
  FROM sem_resposta s;

  IF jsonb_array_length(v_leads_sem_resposta) > 0 THEN
    v_alertas := v_alertas || jsonb_build_object(
      'tipo', 'leads_sem_resposta_30min',
      'severity', 'laranja',
      'tenants_afetados', jsonb_array_length(v_leads_sem_resposta),
      'detalhes', v_leads_sem_resposta
    );
  END IF;

  WITH retries AS (
    SELECT 
      tenant_id,
      COUNT(*) AS falhas,
      MAX(retries) AS max_retries,
      MAX(created_at) AS ultima_tentativa
    FROM caixa_saida_mensagens
    WHERE status IN ('pendente', 'erro', 'agendada')
      AND retries >= 3
      AND created_at > now() - interval '1 hour'
    GROUP BY tenant_id
    HAVING COUNT(*) >= 5
  )
  SELECT COALESCE(jsonb_agg(to_jsonb(r) ORDER BY r.falhas DESC), '[]'::jsonb)
  INTO v_retries_falhando
  FROM retries r;

  IF jsonb_array_length(v_retries_falhando) > 0 THEN
    v_alertas := v_alertas || jsonb_build_object(
      'tipo', 'retentativas_falhando',
      'severity', 'vermelho',
      'tenants_afetados', jsonb_array_length(v_retries_falhando),
      'detalhes', v_retries_falhando
    );
  END IF;

  INSERT INTO public.agendamentos_log (cronjob_nome, iniciou_em, terminou_em, duracao_ms, resultado, payload_resposta)
  VALUES ('monitor_saude_motor', now(), now(), 0, 
    CASE WHEN jsonb_array_length(v_alertas) > 0 THEN 'erro' ELSE 'sucesso' END,
    v_alertas);

  RETURN v_alertas;
END;
$$;


ALTER FUNCTION public.monitor_saude_motor() OWNER TO postgres;

--
-- Name: movimentar_estoque(uuid, text, integer, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.movimentar_estoque(p_item_id uuid, p_tipo text, p_quantidade integer, p_motivo text DEFAULT NULL::text) RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_nova integer;
BEGIN
  IF p_tipo NOT IN ('entrada', 'saida', 'ajuste') THEN
    RAISE EXCEPTION 'tipo de movimentação inválido: %', p_tipo;
  END IF;
  IF p_quantidade IS NULL OR p_quantidade < 0 THEN
    RAISE EXCEPTION 'quantidade inválida';
  END IF;
  UPDATE public.estoque_itens
  SET quantidade = CASE p_tipo
        WHEN 'entrada' THEN quantidade + p_quantidade
        WHEN 'saida' THEN quantidade - p_quantidade
        ELSE p_quantidade
      END,
      updated_at = now()
  WHERE id = p_item_id AND deleted_at IS NULL
  RETURNING quantidade INTO v_nova;
  IF v_nova IS NULL THEN
    RAISE EXCEPTION 'item de estoque não encontrado';
  END IF;
  INSERT INTO public.estoque_movimentacoes (tenant_id, item_id, tipo, quantidade, motivo)
  SELECT tenant_id, id, p_tipo, p_quantidade, p_motivo
  FROM public.estoque_itens WHERE id = p_item_id;
  RETURN v_nova;
END;
$$;


ALTER FUNCTION public.movimentar_estoque(p_item_id uuid, p_tipo text, p_quantidade integer, p_motivo text) OWNER TO postgres;

--
-- Name: normalizar_tag(text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.normalizar_tag(p_tag_text text, p_tenant_id uuid, p_nicho_id uuid DEFAULT NULL::uuid) RETURNS TABLE(chave_canonica text, valor_canonico text, vocabulario_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_chave_raw text;
  v_valor_raw text;
  v_pos int;
BEGIN
  IF p_tag_text IS NULL OR length(trim(p_tag_text)) = 0 THEN
    RETURN;
  END IF;

  v_pos := position(':' IN p_tag_text);
  IF v_pos > 0 THEN
    v_chave_raw := lower(trim(substring(p_tag_text FROM 1 FOR v_pos - 1)));
    v_valor_raw := lower(trim(substring(p_tag_text FROM v_pos + 1)));
  ELSE
    v_chave_raw := lower(trim(p_tag_text));
    v_valor_raw := NULL;
  END IF;

  RETURN QUERY
  SELECT a.chave_canonica, COALESCE(a.valor_canonico, v_valor_raw), v.id
  FROM public.alias_vocabulario_tag a
  LEFT JOIN public.vocabulario_curadoria v
    ON v.chave = a.chave_canonica
    AND (v.escopo = 'plataforma'
         OR (v.escopo = 'nicho' AND v.nicho_id = p_nicho_id)
         OR (v.escopo = 'tenant' AND v.tenant_id = p_tenant_id))
    AND v.ativo
  WHERE lower(a.alias) = v_chave_raw
    AND (a.escopo = 'plataforma'
         OR (a.escopo = 'nicho' AND a.nicho_id = p_nicho_id)
         OR (a.escopo = 'tenant' AND a.tenant_id = p_tenant_id))
  LIMIT 1;

  IF NOT FOUND THEN
    RETURN QUERY
    SELECT v.chave, COALESCE(v_valor_raw, v.valor), v.id
    FROM public.vocabulario_curadoria v
    WHERE lower(v.chave) = v_chave_raw
      AND v.ativo
      AND (v.escopo = 'plataforma'
           OR (v.escopo = 'nicho' AND v.nicho_id = p_nicho_id)
           OR (v.escopo = 'tenant' AND v.tenant_id = p_tenant_id))
    ORDER BY CASE v.escopo WHEN 'tenant' THEN 1 WHEN 'nicho' THEN 2 ELSE 3 END
    LIMIT 1;
  END IF;
END;
$$;


ALTER FUNCTION public.normalizar_tag(p_tag_text text, p_tenant_id uuid, p_nicho_id uuid) OWNER TO postgres;

--
-- Name: normalizar_telefone(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.normalizar_telefone(p_tel text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  SELECT regexp_replace(coalesce(p_tel, ''), '[^0-9]', '', 'g');
$$;


ALTER FUNCTION public.normalizar_telefone(p_tel text) OWNER TO postgres;

--
-- Name: normalizar_telefone_brasil(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.normalizar_telefone_brasil(p_bruto text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v text := regexp_replace(coalesce(p_bruto, ''), '\D', '', 'g');
begin
  v := regexp_replace(v, '^0+', '');
  if v ~ '^55\d{10,11}$' then
    return v;
  end if;
  if v ~ '^\d{10,11}$' then
    return '55' || v;
  end if;
  return null;
end;
$_$;


ALTER FUNCTION public.normalizar_telefone_brasil(p_bruto text) OWNER TO postgres;

--
-- Name: FUNCTION normalizar_telefone_brasil(p_bruto text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.normalizar_telefone_brasil(p_bruto text) IS 'Normaliza telefone BR pro formato internacional (55 + DDD + número). Devolve NULL se não reconhecer.';


--
-- Name: notificar_empresas_incompletas(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.notificar_empresas_incompletas() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_tenant uuid;
  v_pontuacao int;
  v_faltantes text[];
  v_criadas int := 0;
BEGIN
  FOR v_tenant IN SELECT DISTINCT au.user_id FROM public.agentes_usuario au LOOP
    SELECT c.pontuacao, c.faltantes INTO v_pontuacao, v_faltantes
    FROM public.completude_empresa(v_tenant) c;

    CONTINUE WHEN v_pontuacao >= 80;

    CONTINUE WHEN EXISTS (
      SELECT 1 FROM public.notificacoes n
      WHERE n.user_id = v_tenant
        AND n.tipo = 'empresa_incompleta'
        AND (n.lida = false OR n.created_at > now() - interval '6 days')
    );

    INSERT INTO public.notificacoes (user_id, tipo, icone, titulo, mensagem, acao, acao_label)
    VALUES (
      v_tenant,
      'empresa_incompleta',
      'building-2',
      'Cadastro da empresa em ' || v_pontuacao || '%',
      'Seu agente vende melhor quando conhece a empresa. Falta: ' || array_to_string(v_faltantes, ', ') || '.',
      '/empresa',
      'Completar cadastro'
    );
    v_criadas := v_criadas + 1;
  END LOOP;

  RETURN v_criadas;
END;
$$;


ALTER FUNCTION public.notificar_empresas_incompletas() OWNER TO postgres;

--
-- Name: obter_agenda_publica(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.obter_agenda_publica(p_token uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_reg public.agendamentos_link%ROWTYPE;
  v_cfg public.agenda_config_tenant%ROWTYPE;
  v_logo text; v_nome text; v_cor text; v_banner text;
  v_slots jsonb := '[]'::jsonb;
  v_hoje date; v_limite date; v_dia date;
  v_meses integer; v_sala uuid;
BEGIN
  IF p_token IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'erro', 'token_obrigatorio');
  END IF;
  SELECT * INTO v_reg FROM public.agendamentos_link WHERE chave_publica = p_token;
  IF v_reg.id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'erro', 'nao_encontrado');
  END IF;
  SELECT * INTO v_cfg FROM public.agenda_config_tenant WHERE tenant_id = v_reg.tenant_id;

  -- Branding: empresas (ficha viva) manda; config_contrato/consultas_config_tenant = fallback.
  SELECT e.logo_url, e.nome, e.banner_url INTO v_logo, v_nome, v_banner
  FROM public.empresas e WHERE e.user_id = v_reg.tenant_id LIMIT 1;
  SELECT cc.cor_pagina INTO v_cor
  FROM public.config_contrato cc WHERE cc.tenant_id = v_reg.tenant_id;
  IF v_logo IS NULL THEN
    SELECT cc.logo_url INTO v_logo FROM public.config_contrato cc WHERE cc.tenant_id = v_reg.tenant_id;
  END IF;
  IF v_nome IS NULL THEN
    SELECT cc.nome_empresa INTO v_nome FROM public.config_contrato cc WHERE cc.tenant_id = v_reg.tenant_id;
  END IF;
  IF v_banner IS NULL THEN
    SELECT ct.banner_url INTO v_banner FROM public.consultas_config_tenant ct WHERE ct.tenant_id = v_reg.tenant_id;
  END IF;
  v_nome := COALESCE(v_nome, 'Agendamento');

  -- Já agendado: devolve tela de sucesso
  IF v_reg.status = 'agendado' THEN
    SELECT s.chave_publica INTO v_sala FROM public.salas_reuniao s WHERE s.id = v_reg.sala_reuniao_id;
    RETURN jsonb_build_object(
      'ok', true, 'status', 'agendado',
      'scheduled_at', v_reg.scheduled_at,
      'link_sala', '/sala/' || COALESCE(v_sala::text, ''),
      'nome_exibicao', v_nome, 'logo_url', v_logo, 'banner_url', v_banner, 'cor_pagina', v_cor
    );
  END IF;

  IF v_cfg.id IS NULL OR v_cfg.agente_pode_agendar IS DISTINCT FROM true THEN
    RETURN jsonb_build_object('ok', false, 'erro', 'agenda_indisponivel');
  END IF;

  v_meses  := LEAST(GREATEST(COALESCE(v_cfg.meses_a_frente, 1), 1), 12);
  v_hoje   := (now() AT TIME ZONE 'America/Sao_Paulo')::date;
  v_limite := (date_trunc('month', v_hoje) + (v_meses || ' months')::interval - interval '1 day')::date;

  v_dia := v_hoje;
  WHILE v_dia <= v_limite LOOP
    v_slots := v_slots || COALESCE((
      SELECT jsonb_agg(s.slot_inicio ORDER BY s.slot_inicio)
      FROM public.slots_disponiveis(v_reg.tenant_id, v_dia) s
      WHERE s.slot_inicio > now()
    ), '[]'::jsonb);
    v_dia := v_dia + 1;
  END LOOP;

  RETURN jsonb_build_object(
    'ok', true, 'status', 'pendente',
    'slots', v_slots,
    'duracao_min', COALESCE(v_cfg.duracao_padrao_min, 30),
    'meses_a_frente', v_meses,
    'limite', v_limite,
    'nome_exibicao', v_nome, 'logo_url', v_logo, 'banner_url', v_banner, 'cor_pagina', v_cor
  );
END;
$$;


ALTER FUNCTION public.obter_agenda_publica(p_token uuid) OWNER TO postgres;

--
-- Name: config_chamadas_llm; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.config_chamadas_llm (
    chave text NOT NULL,
    nome text NOT NULL,
    descricao text,
    modelo text NOT NULL,
    temperatura numeric(3,2) DEFAULT 0.7 NOT NULL,
    max_tokens integer DEFAULT 1024 NOT NULL,
    prompt_template text DEFAULT ''::text NOT NULL,
    itens_produzidos text[] DEFAULT '{}'::text[] NOT NULL,
    versao integer DEFAULT 1 NOT NULL,
    ativo boolean DEFAULT true NOT NULL,
    criado_em timestamp with time zone DEFAULT now() NOT NULL,
    atualizado_em timestamp with time zone DEFAULT now() NOT NULL,
    atualizado_por uuid,
    escopo text DEFAULT 'global'::text NOT NULL,
    nicho_id uuid,
    tenant_id uuid,
    custo_teto_diario numeric(10,2),
    deleted_at timestamp with time zone,
    notas text,
    posicao text DEFAULT 'turno'::text NOT NULL,
    schedule text,
    json_mode boolean DEFAULT false NOT NULL,
    gavetas_ativas jsonb DEFAULT '{}'::jsonb NOT NULL,
    CONSTRAINT config_chamadas_llm_escopo_check CHECK ((escopo = ANY (ARRAY['global'::text, 'nicho'::text, 'tenant'::text]))),
    CONSTRAINT config_chamadas_llm_escopo_consistente CHECK ((((escopo = 'global'::text) AND (nicho_id IS NULL) AND (tenant_id IS NULL)) OR ((escopo = 'nicho'::text) AND (nicho_id IS NOT NULL) AND (tenant_id IS NULL)) OR ((escopo = 'tenant'::text) AND (tenant_id IS NOT NULL)))),
    CONSTRAINT config_chamadas_llm_max_tokens_check CHECK (((max_tokens > 0) AND (max_tokens <= 32768))),
    CONSTRAINT config_chamadas_llm_posicao_check CHECK ((posicao = ANY (ARRAY['turno'::text, 'cron'::text]))),
    CONSTRAINT config_chamadas_llm_temperatura_check CHECK (((temperatura >= (0)::numeric) AND (temperatura <= (2)::numeric)))
);


ALTER TABLE public.config_chamadas_llm OWNER TO postgres;

