-- Name: TABLE config_chamadas_llm; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.config_chamadas_llm IS 'Onda C1 — control plane: configuração viva por chamada LLM do motor RAG. Editável via Curadoria > Chamadas LLM sem deploy.';


--
-- Name: COLUMN config_chamadas_llm.gavetas_ativas; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.config_chamadas_llm.gavetas_ativas IS 'Mapa de gavetas RAG ativas pra esta chamada. Formato: {"<gaveta>": {"ativo": bool, "piso": numeric, "top_n": int}}. Editável via Curadoria UI; motor lê em runtime.';


--
-- Name: obter_config_chamada_llm(text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.obter_config_chamada_llm(p_chave text, p_tenant_id uuid DEFAULT NULL::uuid, p_nicho_id uuid DEFAULT NULL::uuid) RETURNS public.config_chamadas_llm
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_resultado public.config_chamadas_llm;
BEGIN
  -- 1) tenta override por tenant (escopo mais específico)
  IF p_tenant_id IS NOT NULL THEN
    SELECT * INTO v_resultado FROM public.config_chamadas_llm
    WHERE chave = p_chave 
      AND escopo = 'tenant' 
      AND tenant_id = p_tenant_id
      AND ativo = true 
      AND deleted_at IS NULL
    ORDER BY versao DESC
    LIMIT 1;
    IF FOUND THEN RETURN v_resultado; END IF;
  END IF;

  -- 2) tenta override por nicho
  IF p_nicho_id IS NOT NULL THEN
    SELECT * INTO v_resultado FROM public.config_chamadas_llm
    WHERE chave = p_chave 
      AND escopo = 'nicho' 
      AND nicho_id = p_nicho_id
      AND ativo = true 
      AND deleted_at IS NULL
    ORDER BY versao DESC
    LIMIT 1;
    IF FOUND THEN RETURN v_resultado; END IF;
  END IF;

  -- 3) fallback pra global
  SELECT * INTO v_resultado FROM public.config_chamadas_llm
  WHERE chave = p_chave 
    AND escopo = 'global'
    AND ativo = true 
    AND deleted_at IS NULL
  ORDER BY versao DESC
  LIMIT 1;

  -- pode retornar NULL → motor usa fallback hardcoded
  RETURN v_resultado;
END;
$$;


ALTER FUNCTION public.obter_config_chamada_llm(p_chave text, p_tenant_id uuid, p_nicho_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION obter_config_chamada_llm(p_chave text, p_tenant_id uuid, p_nicho_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.obter_config_chamada_llm(p_chave text, p_tenant_id uuid, p_nicho_id uuid) IS 'Lookup com fallback em cascata tenant→nicho→global. Retorna NULL se nada encontrado (motor usa hardcoded).';


--
-- Name: obter_consulta_por_token(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.obter_consulta_por_token(p_token uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  SELECT jsonb_build_object(
    'chave_publica', c.chave_publica,
    'titulo', c.titulo,
    'nome_empresa', COALESCE(c.nome_empresa, e.nome),
    'logo_url', COALESCE(c.logo_url, e.logo_url),
    'banner_url', COALESCE(c.banner_url, e.banner_url),
    'cor_pagina', c.cor_pagina,
    'tipo_doc', COALESCE(c.tipo_doc, t.tipo_doc),
    'preco', c.preco,
    'preco_venda_cpf', cfg.preco_venda_cpf,
    'preco_venda_cnpj', cfg.preco_venda_cnpj,
    'chave_pix', COALESCE(c.chave_pix, cfg.chave_pix, p.chave_pix),
    -- Config viva: deriva da exigência ligada agora pelo tenant (não mais snapshot).
    'campos_obrigatorios',
      (CASE WHEN COALESCE(cfg.selfie_ativo, false) THEN jsonb_build_array('selfie') ELSE '[]'::jsonb END)
      || (CASE WHEN COALESCE(cfg.doc_foto_ativo, false) THEN jsonb_build_array('documento') ELSE '[]'::jsonb END),
    'campos_formulario', COALESCE(cfg.campos_formulario, '[]'::jsonb),
    'instrucao_selfie', c.instrucao_selfie,
    'aviso_final', c.aviso_final,
    'status', c.status,
    'resultado', CASE WHEN c.status = 'concluida' THEN c.resultado ELSE NULL END,
    'pdf_url', CASE WHEN c.status = 'concluida' THEN c.pdf_url ELSE NULL END
  )
  FROM public.consultas c
  LEFT JOIN public.consultas_tipos t ON t.id = c.tipo_id
  LEFT JOIN public.empresas e ON e.user_id = c.tenant_id
  LEFT JOIN public.consultas_config_tenant cfg ON cfg.tenant_id = c.tenant_id
  LEFT JOIN public.profiles p ON p.id = c.tenant_id
  WHERE c.chave_publica = p_token AND c.deleted_at IS NULL;
$$;


ALTER FUNCTION public.obter_consulta_por_token(p_token uuid) OWNER TO postgres;

--
-- Name: obter_contrato_por_token(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.obter_contrato_por_token(p_token uuid) RETURNS TABLE(id uuid, chave_publica uuid, titulo text, texto_contrato text, logo_url text, descricao_empresa text, nome_empresa text, cor_pagina text, dados_cliente jsonb, status text, assinado_em timestamp with time zone, campos_obrigatorios jsonb, instrucao_selfie text, num_testemunhas integer, campos_cliente text[], opcoes_pagamento jsonb, metodo_pagamento text, posicao_pagamento text, chave_pix text, link_parcelamento text, url_comprovante_pagamento text, pdf_url text, conversa_id uuid, agente_id uuid, origem text, placeholders jsonb, dados_pagamento jsonb, forma_pagamento_escolhida jsonb)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
DECLARE
  v_user_agent text;
  v_ip text;
  v_headers jsonb;
BEGIN
  IF p_token IS NULL THEN
    RAISE EXCEPTION 'token obrigatorio' USING ERRCODE = '22023';
  END IF;

  BEGIN
    v_headers := current_setting('request.headers', true)::jsonb;
    v_user_agent := v_headers->>'user-agent';
    v_ip := COALESCE(split_part(v_headers->>'x-forwarded-for', ',', 1),
                     v_headers->>'cf-connecting-ip');
    INSERT INTO public.log_acesso_contrato (chave_publica, evento, user_agent, ip)
    VALUES (p_token, 'carregamento', v_user_agent, v_ip);
  EXCEPTION WHEN OTHERS THEN NULL;
  END;

  RETURN QUERY
  SELECT
    c.id, c.chave_publica, c.titulo, c.texto_contrato,
    -- Logo viva: empresas manda; snapshot do contrato e fallback.
    COALESCE(e.logo_url, c.logo_url)        AS logo_url,
    c.descricao_empresa, c.nome_empresa, c.cor_pagina,
    c.dados_cliente, c.status, c.assinado_em,
    c.campos_obrigatorios, c.instrucao_selfie, c.num_testemunhas,
    c.campos_cliente, c.opcoes_pagamento, c.metodo_pagamento,
    c.posicao_pagamento, c.chave_pix, c.link_parcelamento,
    c.url_comprovante_pagamento, c.pdf_url, c.conversa_id,
    c.agente_id, c.origem,
    COALESCE(NULLIF(c.campos_formulario, '[]'::jsonb), NULLIF(ct.campos_cliente, '[]'::jsonb), ct.placeholders, '[]'::jsonb) AS placeholders,
    c.dados_pagamento, c.forma_pagamento_escolhida
  FROM public.contratos c
  LEFT JOIN public.contratos_template ct
    ON ct.nome = c.nome_template AND ct.user_id = c.tenant_id
  LEFT JOIN public.empresas e
    ON e.user_id = c.tenant_id
  WHERE c.chave_publica = p_token
  LIMIT 1;
END;
$$;


ALTER FUNCTION public.obter_contrato_por_token(p_token uuid) OWNER TO postgres;

--
-- Name: obter_dados_publicos_empresa(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.obter_dados_publicos_empresa(p_token uuid) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_tenant_id uuid; v_result json;
BEGIN
  SELECT tenant_id INTO v_tenant_id FROM public.leads WHERE chave_rastreamento = p_token LIMIT 1;
  IF v_tenant_id IS NULL THEN RETURN NULL; END IF;
  SELECT json_build_object('nome', e.nome,'cnpj', e.cnpj,'descricao', e.descricao,'logo_url', e.logo_url,'banner_url', e.banner_url,'whatsapp', e.whatsapp,'instagram', e.instagram,'site', e.site,'cidade', e.cidade,'estado', e.estado) INTO v_result
  FROM public.empresas e WHERE e.user_id = v_tenant_id LIMIT 1;
  RETURN v_result;
END;
$$;


