--
-- Name: obter_uso_armazenamento(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.obter_uso_armazenamento(p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_result jsonb;
BEGIN
  SELECT jsonb_build_object(
    'used_bytes', COALESCE(storage_used_bytes, 0),
    'max_bytes', COALESCE(max_storage_bytes, 209715200),
    'used_mb', ROUND(COALESCE(storage_used_bytes, 0) / 1048576.0, 1),
    'max_mb', ROUND(COALESCE(max_storage_bytes, 209715200) / 1048576.0, 0),
    'percent', CASE WHEN max_storage_bytes > 0 THEN ROUND(COALESCE(storage_used_bytes, 0) * 100.0 / max_storage_bytes, 1) ELSE 0 END
  ) INTO v_result FROM public.assinaturas_usuario WHERE user_id = p_user_id AND status IN ('active','ativa') LIMIT 1;
  RETURN COALESCE(v_result, '{"used_bytes":0,"max_bytes":209715200,"used_mb":0,"max_mb":200,"percent":0}'::jsonb);
END;
$$;


ALTER FUNCTION public.obter_uso_armazenamento(p_user_id uuid) OWNER TO postgres;

--
-- Name: pacote_liberado_para_tenant(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pacote_liberado_para_tenant(p_pacote_id uuid, p_tenant_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM public.pacotes_conhecimento pc
    WHERE pc.id = p_pacote_id
      AND pc.ativo = true
      AND pc.deleted_at IS NULL
      AND (
        (pc.origem = 'tenant' AND pc.tenant_id = p_tenant_id)
        OR (
          pc.origem = 'admin'
          AND (pc.nicho_id IS NULL OR pc.nicho_id = (SELECT p.nicho_id FROM public.profiles p WHERE p.id = p_tenant_id))
          AND (
            pc.loja_aplicativo_id IS NULL
            OR EXISTS (
              SELECT 1 FROM public.aplicativos_instalados ai
              WHERE ai.user_id = p_tenant_id AND ai.aplicativo_id = pc.loja_aplicativo_id
            )
          )
        )
      )
  );
$$;


ALTER FUNCTION public.pacote_liberado_para_tenant(p_pacote_id uuid, p_tenant_id uuid) OWNER TO postgres;

