--
-- Name: pacotes_conhecimento_do_agente(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pacotes_conhecimento_do_agente(p_agente_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  WITH ligados AS (
    SELECT pc.id, pc.nome, pc.ordem
    FROM public.pacotes_conhecimento_ativacao pa
    JOIN public.pacotes_conhecimento pc ON pc.id = pa.pacote_id
    WHERE pa.agente_id = p_agente_id
      AND pa.ligado = true
      AND public.pacote_liberado_para_tenant(pc.id, pa.tenant_id)
  )
  SELECT jsonb_build_object(
    'pacotes', coalesce((SELECT jsonb_agg(jsonb_build_object('id', l.id, 'nome', l.nome) ORDER BY l.ordem, l.nome) FROM ligados l), '[]'::jsonb),
    -- o motor só gasta embedding na busca por relevância se houver bloco desse modo
    'tem_relevancia', EXISTS (
      SELECT 1 FROM ligados l JOIN public.pacotes_conhecimento_blocos b ON b.pacote_id = l.id
      WHERE b.modo = 'relevancia' AND b.ativo = true AND b.deleted_at IS NULL
    ),
    'fixos', coalesce((
      SELECT jsonb_agg(jsonb_build_object(
               'id', b.id, 'pacote_id', l.id, 'pacote_nome', l.nome,
               'titulo', b.titulo, 'conteudo', b.conteudo, 'category', b.category)
             ORDER BY l.ordem, l.nome, b.ordem, b.created_at)
      FROM ligados l
      JOIN public.pacotes_conhecimento_blocos b ON b.pacote_id = l.id
      WHERE b.modo = 'sempre' AND b.ativo = true AND b.deleted_at IS NULL
    ), '[]'::jsonb)
  );
$$;


ALTER FUNCTION public.pacotes_conhecimento_do_agente(p_agente_id uuid) OWNER TO postgres;

--
-- Name: parse_tempo_relativo(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.parse_tempo_relativo(p_str text) RETURNS timestamp with time zone
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_str        text;
  v_days       int := 0;
  v_hours      int := 0;
  v_minutes    int := 0;
  v_match      text[];
  v_interval   interval;
BEGIN
  IF p_str IS NULL OR trim(p_str) = '' THEN
    RETURN NULL;
  END IF;

  v_str := trim(p_str);

  -- Tenta ISO 8601 direto (começa com dígito ou contém 'T')
  IF v_str !~ '^\+' THEN
    BEGIN
      RETURN v_str::timestamptz;
    EXCEPTION WHEN others THEN
      RETURN NULL;
    END;
  END IF;

  -- Remove o prefixo '+'
  v_str := substr(v_str, 2);

  -- Extrai dias: Nd ou Ndays
  v_match := regexp_match(v_str, '^(\d+)d');
  IF v_match IS NOT NULL THEN
    v_days := v_match[1]::int;
    v_str  := regexp_replace(v_str, '^\d+d', '');
  END IF;

  -- Extrai horas: Nh ou Nhours
  v_match := regexp_match(v_str, '^(\d+)h');
  IF v_match IS NOT NULL THEN
    v_hours := v_match[1]::int;
    v_str   := regexp_replace(v_str, '^\d+h', '');
  END IF;

  -- Extrai minutos: Nmin ou Nminutes
  v_match := regexp_match(v_str, '^(\d+)min');
  IF v_match IS NOT NULL THEN
    v_minutes := v_match[1]::int;
    v_str     := regexp_replace(v_str, '^\d+min', '');
  END IF;

  -- Se sobrou algo que não é vazio, formato inválido
  IF trim(v_str) <> '' THEN
    RETURN NULL;
  END IF;

  -- Se nenhum componente foi extraído, inválido
  IF v_days = 0 AND v_hours = 0 AND v_minutes = 0 THEN
    RETURN NULL;
  END IF;

  v_interval := make_interval(days => v_days, hours => v_hours, mins => v_minutes);
  RETURN now() + v_interval;
END;
$$;


ALTER FUNCTION public.parse_tempo_relativo(p_str text) OWNER TO postgres;

--
-- Name: FUNCTION parse_tempo_relativo(p_str text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.parse_tempo_relativo(p_str text) IS 'Converte string relativa (+5min, +1h30min, +2d, +1d12h) ou ISO 8601 em timestamptz. Retorna NULL se inválido. Motor agente-vivo v188.';


--
-- Name: pausar_minha_entrada_babel(uuid, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pausar_minha_entrada_babel(p_campanha_babel_id uuid, p_pausado boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  update public.campanhas_babel_participantes
     set pausado = p_pausado, atualizado_em = now()
   where campanha_babel_id = p_campanha_babel_id
     and tenant_id = (select auth.uid())
     and deleted_at is null;
  if not found then
    return jsonb_build_object('ok', false, 'erro', 'nao_participa');
  end if;
  return jsonb_build_object('ok', true, 'pausado', p_pausado);
end;
$$;


ALTER FUNCTION public.pausar_minha_entrada_babel(p_campanha_babel_id uuid, p_pausado boolean) OWNER TO postgres;

--
-- Name: pausar_recurso_curadoria(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pausar_recurso_curadoria(p_chave text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.user_roles WHERE user_id = (SELECT auth.uid()) AND role IN ('admin','platform_admin')) THEN
    RETURN jsonb_build_object('ok', false, 'erro', 'sem permissao');
  END IF;
  UPDATE public.recursos_ativacao_curadoria
  SET status = 'pausado', atualizado_por = (SELECT auth.uid())
  WHERE chave_recurso = p_chave AND status <> 'bloqueado';
  IF NOT FOUND THEN RETURN jsonb_build_object('ok', false, 'erro', 'recurso bloqueado ou inexistente'); END IF;
  RETURN jsonb_build_object('ok', true);
END;
$$;


ALTER FUNCTION public.pausar_recurso_curadoria(p_chave text) OWNER TO postgres;

--
-- Name: acoes_agendadas; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.acoes_agendadas (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    lead_id uuid,
    conversation_id uuid,
    agente_id uuid,
    action_type text NOT NULL,
    scheduled_at timestamp with time zone NOT NULL,
    status text DEFAULT 'pendente'::text,
    node_name text,
    carga jsonb DEFAULT '{}'::jsonb,
    template text,
    created_at timestamp with time zone DEFAULT now(),
    tentativas integer DEFAULT 0 NOT NULL,
    campaign_id uuid,
    tenant_id uuid,
    executed_at timestamp with time zone,
    error_message text,
    CONSTRAINT acoes_agendadas_status_check CHECK ((status = ANY (ARRAY['pendente'::text, 'cancelado'::text, 'executado'::text, 'falhou'::text, 'processando'::text])))
);


ALTER TABLE public.acoes_agendadas OWNER TO postgres;

--
-- Name: pegar_proxima_acao_agendada(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pegar_proxima_acao_agendada(p_limite integer DEFAULT 50) RETURNS SETOF public.acoes_agendadas
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  RETURN QUERY
  WITH
    -- Nivel 1: 1 candidato por conversa (mais antigo primeiro)
    candidatos AS (
      SELECT DISTINCT ON (conversation_id) id
      FROM public.acoes_agendadas
      WHERE status = 'pendente'
        AND scheduled_at <= now()
      ORDER BY conversation_id, scheduled_at ASC, created_at ASC
      LIMIT p_limite
    ),
    -- Nivel 2: lock atomico dos ids candidatos com SKIP LOCKED
    travados AS (
      SELECT id
      FROM public.acoes_agendadas
      WHERE id IN (SELECT id FROM candidatos)
        AND status = 'pendente'
      FOR UPDATE SKIP LOCKED
    )
  UPDATE public.acoes_agendadas a
     SET status = 'processando',
         tentativas = COALESCE(a.tentativas, 0) + 1,
         executed_at = now()  -- início do processamento: reaper conta daqui, não da criação
    FROM travados t
   WHERE a.id = t.id
  RETURNING a.*;
END;
$$;


ALTER FUNCTION public.pegar_proxima_acao_agendada(p_limite integer) OWNER TO postgres;

--
-- Name: FUNCTION pegar_proxima_acao_agendada(p_limite integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.pegar_proxima_acao_agendada(p_limite integer) IS 'Atomic claim de proximas acoes pendentes. DISTINCT ON garante 1 por conversa; SKIP LOCKED elimina race entre instancias do cron. Marca como processando no mesmo statement (sem race entre SELECT e UPDATE).';


--
-- Name: peso_recencia_episodio(timestamp with time zone, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.peso_recencia_episodio(p_criado_em timestamp with time zone, p_half_life_dias numeric DEFAULT 60) RETURNS numeric
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  SELECT POWER(
    2.0,
    -1.0 * (EXTRACT(EPOCH FROM (now() - p_criado_em)) / 86400.0) / GREATEST(p_half_life_dias, 1.0)
  )::numeric;
$$;


ALTER FUNCTION public.peso_recencia_episodio(p_criado_em timestamp with time zone, p_half_life_dias numeric) OWNER TO postgres;

--
-- Name: FUNCTION peso_recencia_episodio(p_criado_em timestamp with time zone, p_half_life_dias numeric); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.peso_recencia_episodio(p_criado_em timestamp with time zone, p_half_life_dias numeric) IS 'Calcula peso de recência (0,1] de um episódio dado seu timestamp. Quanto mais antigo, menor o peso, mas nunca zera. Half-life padrão 60 dias (60d=0.5, 120d=0.25, 1ano≈0.08). RAG do agente multiplica score × relevancia × peso_recencia pra ranquear episódios. Substitui o decay físico antigo (cron-decay-episodios desativado).';


