--
-- Name: pode_gastar_llm(uuid, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pode_gastar_llm(p_tenant_id uuid, p_teto_padrao_usd numeric DEFAULT 5.00) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_teto   numeric := p_teto_padrao_usd;
  v_aviso  smallint := 80;
  v_corte  smallint := 100;
  v_ativo  boolean := true;
  v_gasto  numeric;
  v_pct    numeric;
  v_modo   text;
begin
  select teto_mensal_usd, aviso_pct, corte_pct, ativo
    into v_teto, v_aviso, v_corte, v_ativo
    from public.orcamento_llm_tenant where tenant_id = p_tenant_id;
  if not found then
    v_teto := p_teto_padrao_usd;
  end if;
  v_gasto := public.custo_llm_tenant_mes(p_tenant_id);
  v_pct := case when v_teto > 0 then round((v_gasto / v_teto) * 100, 1) else 0 end;
  v_modo := case
    when not v_ativo or v_teto <= 0 then 'normal'
    when v_pct >= v_corte then 'bloqueado'
    when v_pct >= v_aviso then 'economico'
    else 'normal' end;
  return jsonb_build_object('ok', true, 'modo', v_modo, 'gasto_usd', round(v_gasto, 4),
                            'teto_usd', v_teto, 'pct', v_pct);
end;
$$;


ALTER FUNCTION public.pode_gastar_llm(p_tenant_id uuid, p_teto_padrao_usd numeric) OWNER TO postgres;

--
-- Name: popular_fases_campanha(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.popular_fases_campanha() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
DECLARE
  v_phases jsonb;
BEGIN
  v_phases := CASE NEW.type
    WHEN 'divulgacao' THEN '[
      {"slug":"aguardando","label":"Aguardando","order_index":0,"is_final_positive":false},
      {"slug":"abordado","label":"Abordado","order_index":1,"is_final_positive":false},
      {"slug":"respondeu","label":"Respondeu","order_index":2,"is_final_positive":false},
      {"slug":"pediu_info","label":"Pediu info","order_index":3,"is_final_positive":false},
      {"slug":"engajou","label":"Engajou","order_index":4,"is_final_positive":true}
    ]'::jsonb
    WHEN 'venda' THEN '[
      {"slug":"aguardando","label":"Aguardando","order_index":0,"is_final_positive":false},
      {"slug":"abordado","label":"Abordado","order_index":1,"is_final_positive":false},
      {"slug":"interessado","label":"Interessado","order_index":2,"is_final_positive":false},
      {"slug":"com_objecao","label":"Com objeção","order_index":3,"is_final_positive":false},
      {"slug":"negociando","label":"Negociando","order_index":4,"is_final_positive":false},
      {"slug":"comprou","label":"Comprou","order_index":5,"is_final_positive":true}
    ]'::jsonb
    WHEN 'pos_venda' THEN '[
      {"slug":"aguardando","label":"Aguardando","order_index":0,"is_final_positive":false},
      {"slug":"abordado","label":"Abordado","order_index":1,"is_final_positive":false},
      {"slug":"respondeu","label":"Respondeu","order_index":2,"is_final_positive":false},
      {"slug":"recomprou","label":"Recomprou","order_index":3,"is_final_positive":true}
    ]'::jsonb
    WHEN 'cobranca' THEN '[
      {"slug":"aguardando","label":"Aguardando","order_index":0,"is_final_positive":false},
      {"slug":"tentativa","label":"Tentativa","order_index":1,"is_final_positive":false},
      {"slug":"negociando","label":"Negociando","order_index":2,"is_final_positive":false},
      {"slug":"comprovante_enviado","label":"Comprovante enviado","order_index":3,"is_final_positive":false},
      {"slug":"pagou","label":"Pagou","order_index":4,"is_final_positive":true}
    ]'::jsonb
    WHEN 'agendamento' THEN '[
      {"slug":"aguardando","label":"Aguardando","order_index":0,"is_final_positive":false},
      {"slug":"abordado","label":"Abordado","order_index":1,"is_final_positive":false},
      {"slug":"negociando_horario","label":"Negociando horário","order_index":2,"is_final_positive":false},
      {"slug":"agendado","label":"Agendado","order_index":3,"is_final_positive":false},
      {"slug":"compareceu","label":"Compareceu","order_index":4,"is_final_positive":true}
    ]'::jsonb
    WHEN 'indicacao' THEN '[
      {"slug":"saudacao","label":"Saudação","order_index":0,"is_final_positive":false},
      {"slug":"apresentacao","label":"Apresentação","order_index":1,"is_final_positive":false},
      {"slug":"negociacao","label":"Negociação","order_index":2,"is_final_positive":false},
      {"slug":"fechado","label":"Fechado","order_index":3,"is_final_positive":true}
    ]'::jsonb
  END;

  INSERT INTO public.fases_campanha (campaign_id, slug, label, order_index, is_final_positive)
  SELECT NEW.id, p->>'slug', p->>'label', (p->>'order_index')::int, (p->>'is_final_positive')::bool
  FROM jsonb_array_elements(v_phases) p;

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.popular_fases_campanha() OWNER TO postgres;

--
-- Name: preencher_candidatos_tag(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.preencher_candidatos_tag(p_nicho_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_inseridos integer := 0;
BEGIN
  IF p_nicho_id IS NULL THEN RAISE EXCEPTION 'nicho_id obrigatorio'; END IF;
  WITH agg AS (
    SELECT unnest(l.tags) AS tag_text, count(DISTINCT l.id) AS num_leads, count(*) AS num_obs,
      array_agg(DISTINCT l.id) FILTER (WHERE l.id IS NOT NULL) AS evidence
    FROM public.leads l JOIN public.profiles p ON p.id = l.tenant_id
    WHERE p.nicho_id = p_nicho_id AND l.tags IS NOT NULL AND array_length(l.tags, 1) > 0
    GROUP BY 1
  ),
  ins AS (
    INSERT INTO public.candidatos_tag (nicho_id, tag_text, num_observacoes, num_leads_independentes, evidencia_lead_ids, status, criado_em, atualizado_em)
    SELECT p_nicho_id, a.tag_text, a.num_obs, a.num_leads, (a.evidence)[1:5], 'pendente', now(), now() FROM agg a
    ON CONFLICT (nicho_id, tag_text) DO UPDATE
    SET num_observacoes = EXCLUDED.num_observacoes, num_leads_independentes = EXCLUDED.num_leads_independentes,
        evidencia_lead_ids = EXCLUDED.evidencia_lead_ids, atualizado_em = now()
    RETURNING 1
  )
  SELECT count(*) INTO v_inseridos FROM ins;
  RETURN v_inseridos;
END;
$$;


ALTER FUNCTION public.preencher_candidatos_tag(p_nicho_id uuid) OWNER TO postgres;

--
-- Name: preencher_perfil_empresa_prior(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.preencher_perfil_empresa_prior() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_tem_metricas boolean;
BEGIN
  -- Só dispara se profile tem nicho_id E não já existe perfil_empresa pro tenant
  IF NEW.nicho_id IS NULL THEN RETURN NEW; END IF;
  IF EXISTS (SELECT 1 FROM public.perfil_empresa WHERE tenant_id = NEW.id) THEN
    RETURN NEW;
  END IF;

  -- Verificar se nicho tem ≥1 métrica em comparativo_nicho (k-anon já garante count_tenants≥10)
  SELECT EXISTS (
    SELECT 1 FROM public.comparativo_nicho cn
    WHERE cn.nicho_id = NEW.nicho_id AND (cn.expira_em IS NULL OR cn.expira_em > now())
  ) INTO v_tem_metricas;

  IF NOT v_tem_metricas THEN RETURN NEW; END IF;

  -- Criar perfil_empresa com prior herdado
  INSERT INTO public.perfil_empresa (
    tenant_id,
    ticket_medio_estimado,
    prazo_decisao_medio_dias,
    taxa_conversao_estimada,
    origem_por_campo
  )
  SELECT
    NEW.id,
    (SELECT valor_anonimizado FROM public.comparativo_nicho WHERE nicho_id = NEW.nicho_id AND metrica = 'ticket_medio' LIMIT 1),
    (SELECT (valor_anonimizado * 1)::int FROM public.comparativo_nicho WHERE nicho_id = NEW.nicho_id AND metrica = 'prazo_decisao_dias' LIMIT 1),
    (SELECT valor_anonimizado FROM public.comparativo_nicho WHERE nicho_id = NEW.nicho_id AND metrica = 'taxa_conversao' LIMIT 1),
    '{
      "ticket_medio_estimado": "prior_nicho",
      "prazo_decisao_medio_dias": "prior_nicho",
      "taxa_conversao_estimada": "prior_nicho"
    }'::jsonb
  ON CONFLICT (tenant_id) DO NOTHING;

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.preencher_perfil_empresa_prior() OWNER TO postgres;

--
-- Name: preparar_exclusao_dados(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.preparar_exclusao_dados(p_owner uuid, p_conversa uuid, p_sql text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if exists (
    select 1 from public.profiles pr
    where pr.id = p_owner
      and pr.parent_user_id is not null
      and coalesce(pr.system_role, '') <> 'platform_admin'
  ) then
    return jsonb_build_object('ok', false, 'erro',
      'sem_permissao: excluir dados da conta é privilégio do dono. Peça ao titular.');
  end if;
  return public.preparar_exclusao_dados_nucleo(p_owner, p_conversa, p_sql);
end;
$$;


ALTER FUNCTION public.preparar_exclusao_dados(p_owner uuid, p_conversa uuid, p_sql text) OWNER TO postgres;

--
-- Name: preparar_exclusao_dados_nucleo(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: consultor_dados_ro
--

CREATE FUNCTION public.preparar_exclusao_dados_nucleo(p_owner uuid, p_conversa uuid, p_sql text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_sql text;
  v_tabela text;
  v_where text;
  v_permitida boolean;
  v_amostra jsonb;
  v_total integer;
  v_id uuid;
  v_teto constant integer := 200;
begin
  if p_owner is null or p_conversa is null then
    return jsonb_build_object('ok', false, 'erro', 'dono ou conversa ausente');
  end if;

  v_sql := btrim(coalesce(p_sql, ''));
  v_sql := regexp_replace(v_sql, ';\s*$', '');
  if v_sql = '' then
    return jsonb_build_object('ok', false, 'erro', 'comando vazio');
  end if;
  if position(';' in v_sql) > 0 then
    return jsonb_build_object('ok', false, 'erro', 'apenas um comando por vez');
  end if;
  if v_sql !~* '^delete\s+from\s' then
    return jsonb_build_object('ok', false, 'erro', 'o comando precisa começar com DELETE FROM');
  end if;
  if v_sql !~* '\ywhere\y' then
    return jsonb_build_object('ok', false, 'erro', 'DELETE sem WHERE é proibido');
  end if;
  if v_sql ~* '\y(update|insert|drop|alter|create|grant|revoke|truncate|returning)\y' then
    return jsonb_build_object('ok', false, 'erro', 'comando inválido pra exclusão');
  end if;

  v_tabela := lower((regexp_match(v_sql, '^delete\s+from\s+(?:only\s+)?(?:public\.)?"?([a-z_][a-z0-9_]*)"?', 'i'))[1]);
  v_where := (regexp_match(v_sql, '\ywhere\y(.*)$', 'i'))[1];
  if v_tabela is null or btrim(coalesce(v_where, '')) = '' then
    return jsonb_build_object('ok', false, 'erro', 'não consegui ler a tabela ou o filtro do comando');
  end if;

  select coalesce(bool_or(permite_exclusao and ativo), false) into v_permitida
  from public.tabelas_consulta_permitidas where tabela = v_tabela;
  if not v_permitida then
    return jsonb_build_object('ok', false, 'erro',
      'tabela ''' || v_tabela || ''' não pode ser excluída por aqui. Nesses casos use atualizar_dados pra desativar o registro.');
  end if;

  perform set_config('search_path', 'public', true);
  perform set_config('statement_timeout', '8000', true);
  perform set_config('request.jwt.claims',
    json_build_object('sub', p_owner::text, 'role', 'authenticated')::text, true);

  -- Prévia: conta e amostra o que SERIA apagado (RLS do dono aplicada).
  begin
    execute format('select count(*) from public.%I where %s', v_tabela, v_where) into v_total;
    execute format('select coalesce(jsonb_agg(t), ''[]''::jsonb) from (select * from public.%I where %s limit 5) t',
                   v_tabela, v_where) into v_amostra;
  exception when others then
    return jsonb_build_object('ok', false, 'erro', 'filtro inválido: ' || sqlerrm);
  end;

  if v_total = 0 then
    return jsonb_build_object('ok', false, 'erro', 'nenhum registro casou com esse filtro — nada a excluir');
  end if;
  if v_total > v_teto then
    return jsonb_build_object('ok', false, 'erro',
      'o filtro pegaria ' || v_total || ' registros (teto ' || v_teto || ') — estreite o WHERE');
  end if;

  insert into public.confirmacoes_exclusao (owner_id, conversa_id, tabela, comando, linhas_previstas, resumo)
  values (p_owner, p_conversa, v_tabela, v_sql, v_total, v_amostra)
  returning id into v_id;

  return jsonb_build_object(
    'ok', true, 'etapa', 'preparado', 'bilhete', v_id,
    'tabela', v_tabela, 'linhas_previstas', v_total, 'amostra', v_amostra
  );
end;
$_$;


ALTER FUNCTION public.preparar_exclusao_dados_nucleo(p_owner uuid, p_conversa uuid, p_sql text) OWNER TO consultor_dados_ro;

--
-- Name: prevenir_mudanca_campo_critico(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.prevenir_mudanca_campo_critico() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  -- Bypass explicito via setting de sessao (usado por RPCs admin como remove_team_member)
  IF current_setting('app.bypass_profile_guard', true) = 'true' THEN
    RETURN NEW;
  END IF;
  -- Retrocompat: tambem aceita o setting antigo app.allow_parent_reset
  IF current_setting('app.allow_parent_reset', true) = 'true' THEN
    RETURN NEW;
  END IF;

  -- Bloqueia mudanca de system_role (previne auto-promocao a platform_admin)
  IF OLD.system_role IS DISTINCT FROM NEW.system_role THEN
    RAISE EXCEPTION 'Nao e permitido alterar system_role sem bypass autorizado.'
      USING ERRCODE = '42501';
  END IF;

  -- Bloqueia qualquer mudanca em parent_user_id (promocao/democao entre tenant/team)
  IF OLD.parent_user_id IS DISTINCT FROM NEW.parent_user_id THEN
    RAISE EXCEPTION 'Nao e permitido alterar parent_user_id sem bypass autorizado.'
      USING ERRCODE = '42501';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.prevenir_mudanca_campo_critico() OWNER TO postgres;

--
-- Name: FUNCTION prevenir_mudanca_campo_critico(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.prevenir_mudanca_campo_critico() IS 'Protege system_role e parent_user_id contra alteracao indevida. Supersede trg_prevent_parent_reset.';


--
-- Name: processar_aprovacao_pedido(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.processar_aprovacao_pedido() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_plano public.loja_planos%ROWTYPE;
BEGIN
  IF NEW.status != 'aprovado' THEN RETURN NEW; END IF;
  IF OLD.status = 'aprovado' THEN RETURN NEW; END IF;

  IF NEW.tipo = 'plano' THEN
    SELECT * INTO v_plano FROM public.loja_planos WHERE id = NEW.item_id;
    IF v_plano.id IS NOT NULL THEN
      INSERT INTO public.assinaturas_usuario (
        user_id, plano_id, plano_nome, preco, max_conversas, max_ciclos_por_conversa,
        max_storage_bytes, data_inicio, data_expiracao, conversas_usadas, status
      ) VALUES (
        NEW.user_id, NEW.item_id, NEW.item_nome, NEW.item_preco,
        COALESCE(v_plano.max_conversas, 1000), COALESCE(v_plano.max_ciclos_por_conversa, 50),
        209715200, now(), now() + (COALESCE(v_plano.dias_expiracao, 30) || ' days')::interval, 0, 'ativa'
      )
      ON CONFLICT (user_id) DO UPDATE SET
        plano_id = EXCLUDED.plano_id,
        plano_nome = EXCLUDED.plano_nome,
        preco = EXCLUDED.preco,
        max_conversas = EXCLUDED.max_conversas,
        max_ciclos_por_conversa = EXCLUDED.max_ciclos_por_conversa,
        max_storage_bytes = EXCLUDED.max_storage_bytes,
        data_inicio = EXCLUDED.data_inicio,
        data_expiracao = EXCLUDED.data_expiracao,
        conversas_usadas = 0,
        status = 'ativa',
        updated_at = now();
    END IF;
  END IF;

  IF NEW.tipo = 'plus' THEN
    UPDATE public.profiles SET multinivel_ativo = true WHERE id = NEW.user_id;
  END IF;

  IF NEW.tipo = 'pacote_extra' THEN
    UPDATE public.assinaturas_usuario
    SET max_conversas = max_conversas + COALESCE((SELECT conversas FROM public.loja_pacotes_extra WHERE id = NEW.item_id), 500),
        updated_at = now()
    WHERE user_id = NEW.user_id AND status IN ('active','ativa');
  END IF;

  IF NEW.tipo = 'implantacao' THEN
    UPDATE public.profiles SET is_active = true, account_status = 'ativo' WHERE id = NEW.user_id;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.processar_aprovacao_pedido() OWNER TO postgres;

--
-- Name: processar_comissao_multinivel(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.processar_comissao_multinivel() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_valor numeric;
  v_current_id uuid;
  v_nivel int := 0;
  v_max_nivel int;
  v_nivel_valor numeric;
  v_nivel_tipo_valor text;
  v_comissao numeric;
  v_is_ativo boolean;
  v_tipo_produto text;
BEGIN
  -- So processa quando entra em 'aprovado'
  IF NEW.status != 'aprovado' THEN RETURN NEW; END IF;
  -- Em UPDATE, só na transição para aprovado (evita reprocessar). Em INSERT,
  -- OLD não existe, então não pode ser referenciado.
  IF TG_OP = 'UPDATE' AND OLD.status = 'aprovado' THEN RETURN NEW; END IF;

  v_user_id := NEW.user_id;
  v_valor := NEW.item_preco;
  v_tipo_produto := NEW.tipo;

  SELECT referred_by INTO v_current_id FROM profiles WHERE id = v_user_id;
  SELECT MAX(nivel) INTO v_max_nivel FROM multinivel_niveis WHERE tipo_produto = v_tipo_produto AND is_active = true;

  IF v_max_nivel IS NULL OR v_current_id IS NULL THEN
    RETURN NEW;
  END IF;

  WHILE v_current_id IS NOT NULL AND v_nivel < v_max_nivel LOOP
    v_nivel := v_nivel + 1;
    SELECT multinivel_ativo INTO v_is_ativo FROM profiles WHERE id = v_current_id;
    IF v_is_ativo IS NOT TRUE THEN
      SELECT referred_by INTO v_current_id FROM profiles WHERE id = v_current_id;
      CONTINUE;
    END IF;

    SELECT valor, tipo_valor INTO v_nivel_valor, v_nivel_tipo_valor
    FROM multinivel_niveis
    WHERE tipo_produto = v_tipo_produto AND nivel = v_nivel AND is_active = true;

    IF v_nivel_valor IS NULL THEN EXIT; END IF;

    IF v_nivel_tipo_valor = 'fixo' THEN
      v_comissao := ROUND(v_nivel_valor, 2);
    ELSE
      v_comissao := ROUND(v_valor * v_nivel_valor / 100, 2);
    END IF;

    IF v_comissao > 0 THEN
      INSERT INTO multinivel_comissoes (beneficiario_id, origem_id, purchase_order_id, nivel, percentual, valor_base, valor_comissao, status)
      VALUES (v_current_id, v_user_id, NEW.id, v_nivel, v_nivel_valor, v_valor, v_comissao, 'creditado');
      UPDATE profiles SET saldo_multinivel = COALESCE(saldo_multinivel, 0) + v_comissao WHERE id = v_current_id;
    END IF;

    SELECT referred_by INTO v_current_id FROM profiles WHERE id = v_current_id;
  END LOOP;

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.processar_comissao_multinivel() OWNER TO postgres;

--
-- Name: processar_novo_usuario(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.processar_novo_usuario() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_parent_user_id uuid := NULL;
  v_convidado_por text := new.raw_user_meta_data->>'convidado_por';
BEGIN
  -- Membro de equipe: parent_user_id vem do metadata, validado contra um tenant real.
  IF v_convidado_por IS NOT NULL AND v_convidado_por <> '' THEN
    BEGIN
      SELECT p.id INTO v_parent_user_id
      FROM public.profiles p
      WHERE p.id = v_convidado_por::uuid AND p.parent_user_id IS NULL
      LIMIT 1;
    EXCEPTION WHEN invalid_text_representation THEN
      v_parent_user_id := NULL;
    END;
  END IF;

  INSERT INTO public.profiles (id, full_name, email, parent_user_id)
  VALUES (
    new.id,
    coalesce(new.raw_user_meta_data->>'full_name', ''),
    coalesce(new.email, ''),
    v_parent_user_id
  );

  -- Agente próprio só pra tenant (membro de equipe não tem agente).
  IF v_parent_user_id IS NULL THEN
    INSERT INTO public.agentes (user_id, nome_agente) VALUES (new.id, '');
  END IF;

  RETURN new;
END;
$$;


ALTER FUNCTION public.processar_novo_usuario() OWNER TO postgres;

--
-- Name: processar_tarefas_vetor_semantico(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.processar_tarefas_vetor_semantico(p_batch integer DEFAULT 10) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  msg record;
  v_url text;
  v_key text;
  v_processed int := 0;
BEGIN
  SELECT decrypted_secret INTO v_url FROM vault.decrypted_secrets WHERE name = 'EMBED_FUNCTION_URL' LIMIT 1;
  SELECT decrypted_secret INTO v_key FROM vault.decrypted_secrets WHERE name = 'service_role_key' LIMIT 1;

  IF v_url IS NULL OR v_key IS NULL THEN
    RETURN 0;
  END IF;

  FOR msg IN SELECT * FROM pgmq.read('embedding_jobs', 60, p_batch) LOOP
    PERFORM net.http_post(
      url := v_url,
      headers := jsonb_build_object(
        'Content-Type', 'application/json',
        'Authorization', 'Bearer ' || v_key
      ),
      body := msg.message
    );
    PERFORM pgmq.delete('embedding_jobs', msg.msg_id);
    v_processed := v_processed + 1;
  END LOOP;

  RETURN v_processed;
END;
$$;


ALTER FUNCTION public.processar_tarefas_vetor_semantico(p_batch integer) OWNER TO postgres;

--
-- Name: promover_blocos_cross_nicho(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.promover_blocos_cross_nicho() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_inseridos int := 0;
BEGIN
  -- Pra cada nicho, identifica blocos canônicos em ≥3 tenants do mesmo nicho
  -- e cria candidato escopo='nicho' em candidatos_bloco (se não existir já)
  -- Tabela candidatos_bloco já existe (referência §6.4 do plano)
  -- Schema esperado: id, gaveta, payload jsonb, escopo_proposto, nicho_id, motivo, criado_em, status
  
  IF NOT EXISTS (SELECT 1 FROM information_schema.tables 
                 WHERE table_schema='public' AND table_name='candidatos_bloco') THEN
    -- Tabela ausente — pular (será criada em onda específica)
    RETURN jsonb_build_object('ok', false, 'erro', 'candidatos_bloco ausente');
  END IF;
  
  -- Pra simplicidade desta onda, registramos placeholder (sem implementação concreta agora —
  -- B3 destilação real virá na Onda 12; promoção real virá quando ≥3 tenants tiverem nicho_id).
  
  RETURN jsonb_build_object('ok', true, 'inseridos', v_inseridos, 'nota', 'placeholder — promoção real após Onda 12 + backfill nicho_id');
END;
$$;


ALTER FUNCTION public.promover_blocos_cross_nicho() OWNER TO postgres;

--
-- Name: promover_meta_blocos_estaveis(integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.promover_meta_blocos_estaveis(p_min_usos integer DEFAULT 10, p_janela_dias integer DEFAULT 7) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_promovidos int := 0;
BEGIN
  WITH usos_por_chunk AS (
    SELECT
      jsonb_array_elements_text(coalesce(metadata->'planejador'->'meta_consultados', '[]'::jsonb))::uuid AS meta_id,
      count(*) FILTER (
        WHERE coalesce(metadata->'verificador'->>'ok','true') <> 'false'
      ) AS usos_validos
    FROM public.logs_requisicao_llm
    WHERE created_at > now() - (p_janela_dias || ' days')::interval
      AND metadata ? 'planejador'
    GROUP BY jsonb_array_elements_text(coalesce(metadata->'planejador'->'meta_consultados', '[]'::jsonb))
  ),
  promocoes AS (
    UPDATE public.blocos_meta mc
       SET stability_tier = 'promovido',
           updated_at = now()
      FROM usos_por_chunk u
     WHERE mc.id = u.meta_id
       AND mc.stability_tier = 'experimental'
       AND u.usos_validos >= p_min_usos
    RETURNING mc.id
  )
  SELECT count(*) INTO v_promovidos FROM promocoes;

  RETURN v_promovidos;
END;
$$;


ALTER FUNCTION public.promover_meta_blocos_estaveis(p_min_usos integer, p_janela_dias integer) OWNER TO postgres;

