--
-- Name: propagar_preco_produto_templates(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.propagar_preco_produto_templates() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF COALESCE(NEW.preco_centavos, 0) > 0 AND (
       NEW.preco_centavos IS DISTINCT FROM OLD.preco_centavos OR
       NEW.entrada_centavos IS DISTINCT FROM OLD.entrada_centavos OR
       NEW.max_parcelas IS DISTINCT FROM OLD.max_parcelas OR
       NEW.valor_parcela_cravado_centavos IS DISTINCT FROM OLD.valor_parcela_cravado_centavos
     ) THEN
    UPDATE public.contratos_template SET produto_id = produto_id WHERE produto_id = NEW.id;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.propagar_preco_produto_templates() OWNER TO postgres;

--
-- Name: proximo_dia_util(date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.proximo_dia_util(p_data date) RETURNS date
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_data date := p_data;
  v_max_iter int := 30;
BEGIN
  WHILE NOT public.eh_dia_util(v_data) AND v_max_iter > 0 LOOP
    v_data := v_data + 1;
    v_max_iter := v_max_iter - 1;
  END LOOP;
  RETURN v_data;
END;
$$;


ALTER FUNCTION public.proximo_dia_util(p_data date) OWNER TO postgres;

--
-- Name: proximo_recebimento(text, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.proximo_recebimento(p_padrao text, p_ref date DEFAULT NULL::date) RETURNS date
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_ref date := COALESCE(p_ref, current_date);
  v_n int;
  v_dia int;
  v_data date;
  v_fim_mes date;
BEGIN
  IF p_padrao IS NULL OR length(p_padrao) = 0 THEN
    RETURN NULL;
  END IF;

  IF p_padrao LIKE 'dia_util_n:%' THEN
    v_n := substring(p_padrao FROM 12)::int;
    v_data := public.dia_util_do_mes(v_ref, v_n);
    IF v_data IS NULL OR v_data < v_ref THEN
      v_data := public.dia_util_do_mes((date_trunc('month', v_ref) + interval '1 month')::date, v_n);
    END IF;
    RETURN v_data;
  END IF;

  IF p_padrao LIKE 'dia_%' AND p_padrao NOT LIKE 'dia_util%' THEN
    v_dia := substring(p_padrao FROM 5)::int;
    IF v_dia < 1 OR v_dia > 31 THEN RETURN NULL; END IF;
    v_data := make_date(extract(year FROM v_ref)::int, extract(month FROM v_ref)::int, v_dia);
    IF v_data < v_ref THEN
      v_data := (date_trunc('month', v_ref) + interval '1 month')::date + (v_dia - 1);
    END IF;
    RETURN public.proximo_dia_util(v_data);
  END IF;

  IF p_padrao = 'fim_mes' THEN
    v_fim_mes := (date_trunc('month', v_ref) + interval '1 month - 1 day')::date;
    WHILE NOT public.eh_dia_util(v_fim_mes) LOOP
      v_fim_mes := v_fim_mes - 1;
    END LOOP;
    RETURN v_fim_mes;
  END IF;

  RETURN NULL;
END;
$$;


ALTER FUNCTION public.proximo_recebimento(p_padrao text, p_ref date) OWNER TO postgres;

--
-- Name: publico_depoimento_para_rag(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.publico_depoimento_para_rag() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_agent_id uuid;
  v_chunk_id uuid;
  v_content text;
BEGIN
  IF NEW.aprovado = true
     AND (TG_OP = 'INSERT' OR OLD.aprovado = false)
     AND NEW.rag_bloco_id IS NULL
  THEN
    SELECT id INTO v_agent_id
    FROM public.agentes_usuario
    WHERE user_id = NEW.user_id AND is_active = true
    ORDER BY created_at DESC LIMIT 1;

    IF v_agent_id IS NOT NULL THEN
      v_content := NEW.autor_nome
        || CASE WHEN NEW.nota IS NOT NULL THEN ' (' || NEW.nota || '★)' ELSE '' END
        || ': ' || NEW.texto;

      INSERT INTO public.blocos_conhecimento (agente_id, title, content, category, escopo, tipo, ativo)
      VALUES (
        v_agent_id,
        'Depoimento de ' || NEW.autor_nome,
        v_content,
        'prova_social',
        'tenant',
        'resposta',
        true
      ) RETURNING id INTO v_chunk_id;

      NEW.rag_bloco_id := v_chunk_id;
      NEW.aprovado_at := now();
    END IF;
  END IF;

  IF TG_OP = 'UPDATE'
     AND NEW.aprovado = false
     AND OLD.aprovado = true
     AND OLD.rag_bloco_id IS NOT NULL
  THEN
    DELETE FROM public.blocos_conhecimento WHERE id = OLD.rag_bloco_id;
    NEW.rag_bloco_id := NULL;
    NEW.aprovado_at := NULL;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.publico_depoimento_para_rag() OWNER TO postgres;

