--
-- Name: publico_obter_perfil(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.publico_obter_perfil(p_slug text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
DECLARE
  v_user_id uuid;
  v_profile jsonb;
  v_empresa jsonb;
  v_services jsonb;
  v_gallery jsonb;
  v_testimonials jsonb;
BEGIN
  SELECT pp.user_id INTO v_user_id
  FROM perfil_publico pp
  WHERE pp.slug = p_slug AND pp.is_active = true;

  IF v_user_id IS NULL THEN
    RETURN NULL;
  END IF;

  SELECT to_jsonb(pp) INTO v_profile
  FROM perfil_publico pp WHERE pp.user_id = v_user_id;

  SELECT jsonb_build_object(
    'nome', e.nome,
    'descricao', e.descricao,
    'endereco', e.endereco,
    'bairro', e.bairro,
    'cidade', e.cidade,
    'estado', e.estado,
    'cep', e.cep,
    'instagram', e.instagram,
    'facebook', e.facebook,
    'tiktok', e.tiktok,
    'whatsapp', e.whatsapp,
    'youtube', e.youtube,
    'site', e.site,
    'logo_url', e.logo_url,
    'banner_url', e.banner_url
  ) INTO v_empresa
  FROM empresas e WHERE e.user_id = v_user_id LIMIT 1;

  SELECT coalesce(jsonb_agg(
    jsonb_build_object(
      'id', s.id, 'nome', s.nome, 'descricao', s.descricao,
      'foto_url', s.foto_url, 'preco_text', s.preco_text, 'ordem', s.ordem
    ) ORDER BY s.ordem
  ), '[]'::jsonb) INTO v_services
  FROM servicos_publicos s WHERE s.user_id = v_user_id;

  SELECT coalesce(jsonb_agg(
    jsonb_build_object(
      'id', g.id, 'titulo', g.titulo, 'descricao', g.descricao,
      'foto_url', g.foto_url, 'ordem', g.ordem
    ) ORDER BY g.ordem
  ), '[]'::jsonb) INTO v_gallery
  FROM galeria_publica g WHERE g.user_id = v_user_id;

  SELECT coalesce(jsonb_agg(
    jsonb_build_object(
      'id', t.id, 'autor_nome', t.autor_nome, 'autor_foto_url', t.autor_foto_url,
      'texto', t.texto, 'nota', t.nota, 'created_at', t.created_at
    ) ORDER BY t.created_at DESC
  ), '[]'::jsonb) INTO v_testimonials
  FROM depoimentos_publicos t
  WHERE t.user_id = v_user_id AND t.aprovado = true;

  RETURN jsonb_build_object(
    'profile', v_profile,
    'empresa', v_empresa,
    'services', v_services,
    'gallery', v_gallery,
    'testimonials', v_testimonials,
    'user_id', v_user_id
  );
END;
$$;


ALTER FUNCTION public.publico_obter_perfil(p_slug text) OWNER TO postgres;

--
-- Name: purgar_soft_delete_expirado(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.purgar_soft_delete_expirado() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  alvo record;
  n integer;
  total jsonb := '[]'::jsonb;
  alvos constant jsonb := '[
    {"t":"acao_pausa_blocos","d":90},{"t":"anti_padroes","d":90},
    {"t":"blocos_comportamento","d":90},{"t":"blocos_conhecimento","d":90},
    {"t":"blocos_gatilho","d":90},{"t":"blocos_humanizacao","d":90},
    {"t":"blocos_meta","d":90},{"t":"blocos_padrao","d":90},
    {"t":"blocos_procedurais","d":90},{"t":"blocos_variacao","d":90},
    {"t":"diretriz_bolha_blocos","d":90},{"t":"emocao_blocos","d":90},
    {"t":"manipulacao_blocos","d":90},{"t":"prova_social_blocos","d":90},
    {"t":"regras_operacionais_blocos","d":90},{"t":"avisos_curadoria","d":90},
    {"t":"config_chamadas_llm","d":90},{"t":"campos_ficha","d":90},
    {"t":"rollouts_canario","d":90},{"t":"registro_reflexao","d":90},
    {"t":"pilha_objetivos","d":90},{"t":"invocacoes_ferramenta","d":90},
    {"t":"notas_app","d":180},{"t":"arquivos_textos","d":180},
    {"t":"pastas_base","d":180},{"t":"eventos_agenda","d":180},
    {"t":"salas_reuniao","d":180},{"t":"consultas_pacotes","d":180},
    {"t":"consultas_tipos","d":180},{"t":"metas_financeiras","d":180}
  ]'::jsonb;
BEGIN
  FOR alvo IN SELECT (e->>'t') AS tabela, (e->>'d')::int AS dias FROM jsonb_array_elements(alvos) e
  LOOP
    BEGIN
      EXECUTE format(
        'DELETE FROM public.%I WHERE deleted_at IS NOT NULL AND deleted_at < now() - make_interval(days => %s)',
        alvo.tabela, alvo.dias);
      GET DIAGNOSTICS n = ROW_COUNT;
      INSERT INTO public.registro_purge (tabela, linhas_apagadas) VALUES (alvo.tabela, n);
      total := total || jsonb_build_object('tabela', alvo.tabela, 'apagadas', n);
    EXCEPTION WHEN foreign_key_violation THEN
      -- FK RESTRICT segurando linha: pula a tabela nesta rodada e registra; nunca aborta o lote
      INSERT INTO public.registro_purge (tabela, linhas_apagadas, erro)
      VALUES (alvo.tabela, 0, SQLERRM);
    END;
  END LOOP;
  RETURN total;
END;
$$;


ALTER FUNCTION public.purgar_soft_delete_expirado() OWNER TO postgres;

--
-- Name: rebufferar_mensagens(text, uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rebufferar_mensagens(p_phone text, p_agent_id uuid, p_texto text, p_media_url text DEFAULT NULL::text, p_media_type text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_aberto record; v_channel uuid; v_msg jsonb;
BEGIN
  v_msg := jsonb_build_object('text', COALESCE(p_texto,''), 'media_url', p_media_url,
                              'media_type', p_media_type, 'received_at', now());
  SELECT * INTO v_aberto FROM public.buffer_mensagens
   WHERE phone = p_phone AND agente_id = p_agent_id AND processed = false
   FOR UPDATE;
  IF v_aberto IS NOT NULL THEN
    UPDATE public.buffer_mensagens
       SET mensagens = jsonb_build_array(v_msg) || mensagens,
           first_at = LEAST(first_at, now())
     WHERE id = v_aberto.id;
    RETURN;
  END IF;

  SELECT channel_id INTO v_channel FROM public.buffer_mensagens
   WHERE phone = p_phone AND agente_id = p_agent_id
   ORDER BY created_at DESC LIMIT 1;
  IF v_channel IS NULL THEN
    SELECT c.id INTO v_channel FROM public.canais c
      JOIN public.agentes_usuario a ON a.user_id = c.user_id
     WHERE a.id = p_agent_id
     ORDER BY c.created_at DESC LIMIT 1;
  END IF;

  BEGIN
    INSERT INTO public.buffer_mensagens (phone, agente_id, channel_id, mensagens, is_composing, first_at, last_activity_at, processed)
    VALUES (p_phone, p_agent_id, v_channel, jsonb_build_array(v_msg), false, now(), now(), false);
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'rebufferar_mensagens: insert falhou (phone=%, agente=%): %', p_phone, p_agent_id, SQLERRM;
  END;
END;
$$;


ALTER FUNCTION public.rebufferar_mensagens(p_phone text, p_agent_id uuid, p_texto text, p_media_url text, p_media_type text) OWNER TO postgres;

