--
-- Name: recomputar_humor_relacao(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.recomputar_humor_relacao(p_dias integer DEFAULT 30) RETURNS integer
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
  WITH base AS (
    SELECT
      me.lead_id,
      c.agente_id,
      me.tenant_id,
      me.criado_em,
      COALESCE(me.decay_factor, 1.0) * COALESCE(me.relevancia, 0.5) AS peso,
      COALESCE(m.valencia, 0.0) AS valencia,
      COALESCE(m.ativacao, 0.3) AS ativacao
    FROM public.memoria_episodica me
    JOIN public.conversas c ON c.id = me.conversation_id
    LEFT JOIN public.mapa_emocao_afeto m ON m.emocao = me.emocao
    WHERE me.ativa = true
      AND me.lead_id IS NOT NULL
      AND c.agente_id IS NOT NULL
      AND me.criado_em >= now() - make_interval(days => p_dias)
  ),
  agreg AS (
    SELECT
      lead_id,
      agente_id,
      tenant_id,
      sum(valencia * peso) / NULLIF(sum(peso), 0) AS valencia,
      sum(ativacao * peso) / NULLIF(sum(peso), 0) AS ativacao,
      max(criado_em) FILTER (WHERE valencia < -0.4) AS ultima_ruptura_em
    FROM base
    GROUP BY lead_id, agente_id, tenant_id
  ),
  calc AS (
    SELECT
      lead_id, agente_id, tenant_id,
      round(GREATEST(-1, LEAST(1, COALESCE(valencia, 0)))::numeric, 3)             AS valencia,
      round(GREATEST(0,  LEAST(1, COALESCE(ativacao, 0.3)))::numeric, 3)           AS ativacao,
      round(GREATEST(0,  LEAST(1, 0.5 + 0.5 * COALESCE(valencia, 0)))::numeric, 3) AS confianca,
      ultima_ruptura_em
    FROM agreg
  ),
  up AS (
    INSERT INTO public.estado_afetivo_lead
      (lead_id, agente_id, tenant_id, valencia, ativacao, confianca, ultima_ruptura_em, resumo_humor, atualizado_em)
    SELECT
      lead_id, agente_id, tenant_id, valencia, ativacao, confianca, ultima_ruptura_em,
      CASE
        WHEN valencia >= 0.5  THEN 'relação calorosa, lead engajado'
        WHEN valencia >= 0.15 THEN 'relação positiva, lead receptivo'
        WHEN valencia > -0.15 THEN 'relação morna, lead neutro'
        WHEN valencia > -0.5  THEN 'relação fria, lead cético ou resistente'
        ELSE 'relação tensa, houve atrito — priorizar reparação'
      END,
      now()
    FROM calc
    ON CONFLICT (lead_id, agente_id) DO UPDATE SET
      tenant_id         = excluded.tenant_id,
      valencia          = excluded.valencia,
      ativacao          = excluded.ativacao,
      confianca         = excluded.confianca,
      ultima_ruptura_em = excluded.ultima_ruptura_em,
      resumo_humor      = excluded.resumo_humor,
      atualizado_em     = now()
    RETURNING 1
  )
  SELECT count(*)::int FROM up;
$$;


ALTER FUNCTION public.recomputar_humor_relacao(p_dias integer) OWNER TO postgres;

--
-- Name: reconsolidar_episodios(uuid[], numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.reconsolidar_episodios(p_ids uuid[], p_boost numeric DEFAULT 0.08) RETURNS integer
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
  WITH upd AS (
    UPDATE public.memoria_episodica
       SET decay_factor  = LEAST(1.0, COALESCE(decay_factor, 1.0) + p_boost),
           relevancia    = LEAST(1.0, COALESCE(relevancia, 0.5) + p_boost),
           atualizado_em = now()
     WHERE id = ANY(p_ids)
       AND ativa = true
    RETURNING id
  )
  SELECT count(*)::int FROM upd;
$$;


ALTER FUNCTION public.reconsolidar_episodios(p_ids uuid[], p_boost numeric) OWNER TO postgres;

--
-- Name: reconsolidar_fatos(uuid[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.reconsolidar_fatos(p_ids uuid[]) RETURNS integer
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
  WITH upd AS (
    UPDATE public.memoria_lead
       SET vezes_evocado      = COALESCE(vezes_evocado, 0) + 1,
           ultima_evocacao_em = now(),
           atualizado_em      = now()
     WHERE id = ANY(p_ids)
       AND ativa = true
    RETURNING id
  )
  SELECT count(*)::int FROM upd;
$$;


ALTER FUNCTION public.reconsolidar_fatos(p_ids uuid[]) OWNER TO postgres;

--
-- Name: recusar_saque(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.recusar_saque(p_saque_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_user uuid;
  v_valor numeric;
  v_status text;
BEGIN
  IF NOT public.eh_admin_plataforma() THEN
    RAISE EXCEPTION 'Apenas admin da plataforma pode recusar saque';
  END IF;

  SELECT user_id, valor, status
    INTO v_user, v_valor, v_status
  FROM public.multinivel_saques
  WHERE id = p_saque_id
  FOR UPDATE;

  IF v_user IS NULL THEN
    RAISE EXCEPTION 'Saque nao encontrado';
  END IF;

  -- Idempotência: estorno só do saque pendente (evita devolver saldo duas vezes).
  IF v_status <> 'pendente' THEN
    RETURN;
  END IF;

  UPDATE public.multinivel_saques
  SET status = 'recusado', updated_at = now()
  WHERE id = p_saque_id;

  UPDATE public.profiles
  SET saldo_multinivel = COALESCE(saldo_multinivel, 0) + v_valor
  WHERE id = v_user;
END;
$$;


ALTER FUNCTION public.recusar_saque(p_saque_id uuid) OWNER TO postgres;

--
-- Name: registrar_evento_contrato(uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.registrar_evento_contrato(p_token uuid, p_evento text, p_meta jsonb DEFAULT NULL::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_user_agent text;
  v_ip text;
  v_headers jsonb;
BEGIN
  IF p_token IS NULL THEN
    RAISE EXCEPTION 'token obrigatorio' USING ERRCODE = '22023';
  END IF;
  IF p_evento IS NULL OR btrim(p_evento) = '' THEN
    RAISE EXCEPTION 'evento obrigatorio' USING ERRCODE = '22023';
  END IF;

  PERFORM public.verificar_limite_taxa_publico(p_token::text, 'registrar_evento_contrato', 60);

  BEGIN
    v_headers := current_setting('request.headers', true)::jsonb;
    v_user_agent := v_headers->>'user-agent';
    v_ip := COALESCE(split_part(v_headers->>'x-forwarded-for', ',', 1),
                     v_headers->>'cf-connecting-ip');
  EXCEPTION WHEN OTHERS THEN
    v_user_agent := NULL;
    v_ip := NULL;
  END;

  INSERT INTO public.log_acesso_contrato (chave_publica, evento, user_agent, ip, meta)
  VALUES (p_token, p_evento, v_user_agent, v_ip, p_meta);
END;
$$;


ALTER FUNCTION public.registrar_evento_contrato(p_token uuid, p_evento text, p_meta jsonb) OWNER TO postgres;

--
-- Name: registrar_ticket_conversa(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.registrar_ticket_conversa() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_tenant_id uuid; v_phone text; v_agent_count integer; v_ciclos integer; v_origem text; v_campaign_lead_id uuid; v_ciclo_bucket integer; v_inserted integer;
BEGIN
  IF NEW.role != 'assistant' THEN RETURN NEW; END IF;
  SELECT c.tenant_id, c.phone INTO v_tenant_id, v_phone FROM public.conversas c WHERE c.id = NEW.conversation_id;
  IF v_tenant_id IS NULL THEN RETURN NEW; END IF;
  IF v_phone IS NOT NULL AND v_phone LIKE 'chat-test%' THEN RETURN NEW; END IF;
  SELECT COALESCE(us.max_ciclos_por_conversa, 30) INTO v_ciclos FROM public.assinaturas_usuario us
  WHERE us.user_id = v_tenant_id AND us.status IN ('active','ativa') AND us.data_expiracao >= now() LIMIT 1;
  IF v_ciclos IS NULL THEN RETURN NEW; END IF;
  IF NEW.campaign_lead_id IS NOT NULL THEN
    v_origem := 'campanha'; v_campaign_lead_id := NEW.campaign_lead_id;
    SELECT COUNT(*) INTO v_agent_count FROM public.mensagens m
    WHERE m.conversation_id = NEW.conversation_id AND m.role='assistant' AND m.campaign_lead_id = v_campaign_lead_id AND m.created_at <= NEW.created_at;
  ELSE
    v_origem := 'espontaneo'; v_campaign_lead_id := NULL;
    SELECT COUNT(*) INTO v_agent_count FROM public.mensagens m
    WHERE m.conversation_id = NEW.conversation_id AND m.role='assistant' AND m.campaign_lead_id IS NULL AND m.created_at <= NEW.created_at;
  END IF;
  IF (v_agent_count - 1) % v_ciclos = 0 THEN
    v_ciclo_bucket := floor((v_agent_count - 1)::numeric / v_ciclos::numeric)::int;
    INSERT INTO public.tickets_conversa (tenant_id, conversation_id, origem, campaign_lead_id, ciclo_bucket, created_at)
    VALUES (v_tenant_id, NEW.conversation_id, v_origem, v_campaign_lead_id, v_ciclo_bucket, NEW.created_at) ON CONFLICT DO NOTHING;
    GET DIAGNOSTICS v_inserted = ROW_COUNT;
    IF v_inserted > 0 THEN
      UPDATE public.assinaturas_usuario SET conversas_usadas = COALESCE(conversas_usadas, 0) + 1, updated_at = now()
      WHERE user_id = v_tenant_id AND status IN ('active','ativa');
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.registrar_ticket_conversa() OWNER TO postgres;

--
-- Name: reivindicar_buffer_mensagem(text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.reivindicar_buffer_mensagem(p_phone text, p_agent_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_buffer record;
BEGIN
  UPDATE public.buffer_mensagens SET processed = true WHERE phone = p_phone AND agente_id = p_agent_id AND processed = false RETURNING * INTO v_buffer;
  IF v_buffer IS NULL THEN RETURN jsonb_build_object('mensagens', '[]'::jsonb, 'count', 0); END IF;
  RETURN jsonb_build_object('mensagens', v_buffer.mensagens, 'count', jsonb_array_length(v_buffer.mensagens),
    'first_at', v_buffer.first_at, 'last_at', v_buffer.last_activity_at, 'channel_id', v_buffer.channel_id);
END;
$$;


ALTER FUNCTION public.reivindicar_buffer_mensagem(p_phone text, p_agent_id uuid) OWNER TO postgres;

--
-- Name: remover_membro_equipe(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.remover_membro_equipe(member_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  -- Apenas o owner pode remover seus proprios team members
  IF NOT EXISTS (
    SELECT 1 FROM public.profiles
    WHERE id = member_id AND parent_user_id = (SELECT auth.uid())
  ) THEN
    RAISE EXCEPTION 'Membro nao pertence a sua equipe';
  END IF;

  -- Deleta o usuario em auth.users (CASCADE: profiles, agentes_usuario, assinaturas_usuario)
  -- Isso elimina qualquer chance de tenant-fantasma pos-remocao.
  DELETE FROM auth.users WHERE id = member_id;
END;
$$;


ALTER FUNCTION public.remover_membro_equipe(member_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION remover_membro_equipe(member_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.remover_membro_equipe(member_id uuid) IS 'Remove team member deletando o usuario completamente (auth.users CASCADE). Impede criacao de tenant-fantasma.';


--
-- Name: reservar_numeros_rifa_publico(uuid, text, text, integer, integer[], uuid, uuid, text, jsonb, boolean, boolean, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.reservar_numeros_rifa_publico(p_token uuid, p_nome text, p_phone text, p_qtd integer DEFAULT NULL::integer, p_numeros integer[] DEFAULT NULL::integer[], p_lead_id uuid DEFAULT NULL::uuid, p_conversa_id uuid DEFAULT NULL::uuid, p_origem text DEFAULT 'link'::text, p_utm jsonb DEFAULT NULL::jsonb, p_sem_expiracao boolean DEFAULT false, p_fiado boolean DEFAULT false, p_pedido_token uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_r public.rifas%rowtype;
  v_nome text := nullif(btrim(coalesce(p_nome, '')), '');
  v_phone text := public.normalizar_telefone_brasil(p_phone);
  v_fixo boolean := false;
  v_min integer;
  v_max integer;
  v_qtd integer;
  v_numeros integer[];
  v_pedido public.pedidos_rifa%rowtype;
  v_pedido_existente public.pedidos_rifa%rowtype;
  v_juntando boolean := false;
  v_qtd_existente integer := 0;
  v_valor integer := 0;
  v_restante integer;
  v_promo record;
  v_faltam integer;
  v_inseridos integer;
  v_livres integer;
  v_ocupados integer[];
  v_pix text;
  v_reservados integer[];
  v_expira timestamptz;
begin
  if v_nome is null then
    return jsonb_build_object('ok', false, 'erro', 'nome_obrigatorio');
  end if;
  if v_phone is null then
    return jsonb_build_object('ok', false, 'erro', 'phone_invalido');
  end if;

  perform public.verificar_limite_taxa_publico(v_phone, 'rifa_reserva', 30);

  select * into v_r from public.rifas
  where chave_publica = p_token and deleted_at is null;
  if not found then
    return jsonb_build_object('ok', false, 'erro', 'rifa_nao_encontrada');
  end if;
  if v_r.status <> 'ativa' then
    return jsonb_build_object('ok', false, 'erro', 'rifa_nao_esta_ativa');
  end if;

  -- Pedido aberto pra juntar (Δ 2026-08-28): comprador já reservado
  -- (06,15...) pega mais números — soma no MESMO pedido em vez de criar
  -- outro token/PIX separado. Token é o segredo; rifa+status batendo evita
  -- juntar num pedido fechado/de outra rifa.
  if p_pedido_token is not null then
    select * into v_pedido_existente from public.pedidos_rifa
    where chave_publica = p_pedido_token
      and rifa_id = v_r.id
      and status in ('reservado', 'aguardando_validacao');
    if found then
      v_juntando := true;
      v_qtd_existente := coalesce(v_pedido_existente.qtd_numeros, 0);
    end if;
  end if;

  -- faixa da cartela: 0..total-1 (desde zero) ou 1..total (legado)
  v_min := case when v_r.numeracao_desde_zero then 0 else 1 end;
  v_max := v_min + v_r.total_numeros - 1;

  -- Reserva sem prazo: número fixo do dono OU fiado liberado pelo dono na rifa.
  v_fixo := (coalesce(p_sem_expiracao, false) and (select auth.uid()) = v_r.tenant_id)
         or (coalesce(p_fiado, false) and v_r.aceita_fiado);
  if coalesce(p_fiado, false) and not v_r.aceita_fiado then
    return jsonb_build_object('ok', false, 'erro', 'rifa_nao_aceita_fiado');
  end if;

  -- números escolhidos a dedo: valida faixa e duplicata; qtd vem do array
  if p_numeros is not null and array_length(p_numeros, 1) > 0 then
    select array_agg(distinct n) into v_numeros from unnest(p_numeros) n;
    if exists (select 1 from unnest(v_numeros) n where n < v_min or n > v_max) then
      return jsonb_build_object('ok', false, 'erro', 'numero_fora_da_faixa');
    end if;
    v_qtd := array_length(v_numeros, 1);
  else
    v_qtd := coalesce(p_qtd, 0);
  end if;

  if v_qtd < 1 or (v_qtd_existente + v_qtd) > v_r.max_numeros_por_pedido then
    return jsonb_build_object('ok', false, 'erro',
      'quantidade_invalida (mín 1, máx ' || v_r.max_numeros_por_pedido ||
      case when v_juntando then ' no total do pedido' else '' end || ')');
  end if;

  if v_juntando then
    v_pedido := v_pedido_existente;
  else
    -- valor: pacotes promocionais gulosos (maior primeiro) + resto no preço unitário
    v_restante := v_qtd;
    for v_promo in
      select (c->>'qtd')::int as q, (c->>'preco_total_centavos')::int as p
      from jsonb_array_elements(v_r.promocoes) c
      where (c->>'qtd')::int > 0 and (c->>'preco_total_centavos')::int > 0
      order by (c->>'qtd')::int desc
    loop
      while v_restante >= v_promo.q loop
        v_valor := v_valor + v_promo.p;
        v_restante := v_restante - v_promo.q;
      end loop;
    end loop;
    v_valor := v_valor + v_restante * v_r.preco_numero_centavos;

    insert into public.pedidos_rifa (
      rifa_id, tenant_id, nome, phone, lead_id, conversa_id, origem,
      qtd_numeros, numeros, valor_centavos, status, expira_em, utm
    ) values (
      v_r.id, v_r.tenant_id, v_nome, v_phone, p_lead_id, p_conversa_id,
      case when p_origem in ('link','agente','manual') then p_origem else 'link' end,
      v_qtd, '{}', v_valor, 'reservado',
      case when v_fixo then null else coalesce(public.rifa_prazo_pagamento(v_r.id), now() + make_interval(mins => v_r.minutos_reserva)) end,
      p_utm
    ) returning * into v_pedido;
  end if;

  if v_numeros is not null then
    -- manual: tudo-ou-nada
    insert into public.numeros_rifa (rifa_id, tenant_id, pedido_id, numero, status)
    select v_r.id, v_r.tenant_id, v_pedido.id, n, 'reservado' from unnest(v_numeros) n
    on conflict (rifa_id, numero) do nothing;
    get diagnostics v_inseridos = row_count;
    if v_inseridos < v_qtd then
      select array_agg(n order by n) into v_ocupados
      from unnest(v_numeros) n
      where not exists (
        select 1 from public.numeros_rifa nr
        where nr.rifa_id = v_r.id and nr.numero = n and nr.pedido_id = v_pedido.id
      );
      raise exception 'NUMEROS_OCUPADOS:%', array_to_string(v_ocupados, ',');
    end if;
  else
    -- aleatório: loop curto com re-sorteio dos que colidirem
    v_faltam := v_qtd;
    for i in 1..6 loop
      exit when v_faltam <= 0;
      with candidatos as (
        select gs as numero
        from generate_series(v_min, v_max) gs
        where not exists (
          select 1 from public.numeros_rifa nr
          where nr.rifa_id = v_r.id and nr.numero = gs
        )
        order by random()
        limit v_faltam
      ), ins as (
        insert into public.numeros_rifa (rifa_id, tenant_id, pedido_id, numero, status)
        select v_r.id, v_r.tenant_id, v_pedido.id, numero, 'reservado' from candidatos
        on conflict (rifa_id, numero) do nothing
        returning numero
      )
      select count(*) into v_inseridos from ins;
      v_faltam := v_faltam - v_inseridos;
      if v_inseridos = 0 then
        select count(*) into v_livres
        from generate_series(v_min, v_max) gs
        where not exists (
          select 1 from public.numeros_rifa nr
          where nr.rifa_id = v_r.id and nr.numero = gs
        );
        exit when v_livres = 0;
      end if;
    end loop;
    if v_faltam > 0 then
      raise exception 'NUMEROS_INSUFICIENTES: só restam % números disponíveis',
        (select count(*) from generate_series(v_min, v_max) gs
         where not exists (select 1 from public.numeros_rifa nr
                           where nr.rifa_id = v_r.id and nr.numero = gs));
    end if;
  end if;

  select array_agg(numero order by numero) into v_reservados
  from public.numeros_rifa where pedido_id = v_pedido.id;

  if v_juntando then
    -- repreça o pedido INTEIRO (existente + novos) — pacotes promocionais
    -- são por quantidade total, não por lote isolado.
    v_valor := 0;
    v_restante := array_length(v_reservados, 1);
    for v_promo in
      select (c->>'qtd')::int as q, (c->>'preco_total_centavos')::int as p
      from jsonb_array_elements(v_r.promocoes) c
      where (c->>'qtd')::int > 0 and (c->>'preco_total_centavos')::int > 0
      order by (c->>'qtd')::int desc
    loop
      while v_restante >= v_promo.q loop
        v_valor := v_valor + v_promo.p;
        v_restante := v_restante - v_promo.q;
      end loop;
    end loop;
    v_valor := v_valor + v_restante * v_r.preco_numero_centavos;

    update public.pedidos_rifa set
      numeros = v_reservados,
      qtd_numeros = array_length(v_reservados, 1),
      valor_centavos = v_valor,
      -- pedido fixo (sem prazo) continua sem prazo; senão dá fôlego novo
      -- pro comprador pagar TUDO junto, não só o lote que acabou de somar.
      expira_em = case when v_pedido.expira_em is null then null
                        else coalesce(public.rifa_prazo_pagamento(v_r.id), now() + make_interval(mins => v_r.minutos_reserva)) end,
      updated_at = now()
    where id = v_pedido.id
    -- Δ 2026-09-08: sem isto o retorno levava o prazo ANTIGO (v_pedido foi lido antes do
    -- UPDATE) e o agente anunciava uma hora que às vezes já tinha passado.
    returning expira_em into v_expira;
  else
    update public.pedidos_rifa set numeros = v_reservados, updated_at = now()
    where id = v_pedido.id
    returning expira_em into v_expira;
  end if;

  select coalesce(rc.chave_pix, p.chave_pix) into v_pix
  from public.profiles p
  left join public.rifas_config_tenant rc on rc.tenant_id = p.id
  where p.id = v_r.tenant_id;

  return jsonb_build_object(
    'ok', true,
    'pedido_token', v_pedido.chave_publica,
    'numeros', to_jsonb(v_reservados),
    'qtd', array_length(v_reservados, 1),
    'valor_centavos', v_valor,
    'chave_pix', v_pix,
    'expira_em', v_expira,
    'numero_fixo', v_fixo,
    'rifa_titulo', v_r.titulo,
    'juntou_pedido', v_juntando
  );
end;
$$;


ALTER FUNCTION public.reservar_numeros_rifa_publico(p_token uuid, p_nome text, p_phone text, p_qtd integer, p_numeros integer[], p_lead_id uuid, p_conversa_id uuid, p_origem text, p_utm jsonb, p_sem_expiracao boolean, p_fiado boolean, p_pedido_token uuid) OWNER TO postgres;

--
-- Name: reservar_orcamento_porteiro(text, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.reservar_orcamento_porteiro(p_ip text, p_custo_centesimos integer DEFAULT 1, p_cap_ip integer DEFAULT 500, p_cap_global integer DEFAULT 200000) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_data date := (now() AT TIME ZONE 'America/Sao_Paulo')::date;
  v_gasto_ip integer;
  v_gasto_global integer;
BEGIN
  INSERT INTO public.orcamento_porteiro_diario (data, escopo, identificador, gasto_centesimos, tentativas)
  VALUES (v_data, 'ip', p_ip, p_custo_centesimos, 1)
  ON CONFLICT (data, escopo, identificador) DO UPDATE
    SET gasto_centesimos = public.orcamento_porteiro_diario.gasto_centesimos + EXCLUDED.gasto_centesimos,
        tentativas = public.orcamento_porteiro_diario.tentativas + 1,
        atualizado_em = now()
  RETURNING gasto_centesimos INTO v_gasto_ip;

  INSERT INTO public.orcamento_porteiro_diario (data, escopo, identificador, gasto_centesimos, tentativas)
  VALUES (v_data, 'global', 'global', p_custo_centesimos, 1)
  ON CONFLICT (data, escopo, identificador) DO UPDATE
    SET gasto_centesimos = public.orcamento_porteiro_diario.gasto_centesimos + EXCLUDED.gasto_centesimos,
        tentativas = public.orcamento_porteiro_diario.tentativas + 1,
        atualizado_em = now()
  RETURNING gasto_centesimos INTO v_gasto_global;

  RETURN v_gasto_ip <= p_cap_ip AND v_gasto_global <= p_cap_global;
END;
$$;


ALTER FUNCTION public.reservar_orcamento_porteiro(p_ip text, p_custo_centesimos integer, p_cap_ip integer, p_cap_global integer) OWNER TO postgres;

--
-- Name: resetar_ciclo_assinatura(uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.resetar_ciclo_assinatura(p_user_id uuid, p_dias integer DEFAULT 30) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  UPDATE public.assinaturas_usuario SET conversas_usadas = 0, data_inicio = now(),
    data_expiracao = now() + (p_dias || ' days')::interval, updated_at = now()
  WHERE user_id = p_user_id AND status IN ('active','ativa');
END;
$$;


ALTER FUNCTION public.resetar_ciclo_assinatura(p_user_id uuid, p_dias integer) OWNER TO postgres;

--
-- Name: resolver_codigo_indicacao(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.resolver_codigo_indicacao(p_code text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_user_id uuid;
BEGIN
  SELECT id INTO v_user_id
  FROM public.profiles
  WHERE referral_code = p_code
  LIMIT 1;

  RETURN v_user_id;
END;
$$;


ALTER FUNCTION public.resolver_codigo_indicacao(p_code text) OWNER TO postgres;

--
-- Name: resolver_cupom_ativo(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.resolver_cupom_ativo(p_tenant_id uuid, p_codigo text) RETURNS TABLE(campaign_id uuid, comissao_tipo text, comissao_valor numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
BEGIN
  RETURN QUERY SELECT m.campaign_id, m.comissao_tipo, m.comissao_valor FROM public.meta_indicacao_campanha m
  JOIN public.campanhas c ON c.id = m.campaign_id
  WHERE m.tenant_id = p_tenant_id AND lower(m.cupom) = lower(p_codigo)
    AND c.status IN ('active','ativa') AND c.deleted_at IS NULL
    AND (c.ends_at IS NULL OR c.ends_at > now()) AND (c.starts_at <= now()) LIMIT 1;
END;
$$;


ALTER FUNCTION public.resolver_cupom_ativo(p_tenant_id uuid, p_codigo text) OWNER TO postgres;

--
-- Name: responder_entrada_sala(uuid, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.responder_entrada_sala(p_participante_id uuid, p_aprovar boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid uuid := (select auth.uid());
  v_sala public.salas_reuniao%rowtype;
  v_participante public.salas_reuniao_participantes%rowtype;
begin
  if v_uid is null then
    raise exception 'nao_autenticado';
  end if;

  select * into v_participante from public.salas_reuniao_participantes
    where id = p_participante_id
    for update;
  if not found then
    raise exception 'participante_nao_encontrado';
  end if;

  select * into v_sala from public.salas_reuniao where id = v_participante.sala_id;

  -- só o criador da sala ou alguém do tenant dela pode responder
  if v_sala.criada_por <> v_uid
     and v_sala.tenant_id <> (select coalesce(p.parent_user_id, p.id) from public.profiles p where p.id = v_uid) then
    raise exception 'sem_permissao';
  end if;

  update public.salas_reuniao_participantes
    set status_entrada = case when p_aprovar then 'aprovado' else 'negado' end,
        saiu_em = case when p_aprovar then saiu_em else now() end
    where id = p_participante_id;

  return jsonb_build_object('participante_id', p_participante_id, 'aprovado', p_aprovar);
end;
$$;


ALTER FUNCTION public.responder_entrada_sala(p_participante_id uuid, p_aprovar boolean) OWNER TO postgres;

--
-- Name: responder_pergunta_mentor(uuid, text, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.responder_pergunta_mentor(p_id uuid, p_resposta text, p_aprovar_direto boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_tenant uuid;
  v_uid    uuid := (SELECT auth.uid());
BEGIN
  SELECT tenant_id INTO v_tenant
    FROM public.perguntas_sem_resposta WHERE id = p_id;

  IF v_tenant IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'erro', 'pergunta não encontrada');
  END IF;
  IF v_tenant <> v_uid THEN
    RETURN jsonb_build_object('ok', false, 'erro', 'sem permissão');
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.perguntas_sem_resposta
    WHERE id = p_id AND status_loop = 'aguardando_dono'
  ) THEN
    RETURN jsonb_build_object('ok', false, 'erro', 'pergunta não está aguardando resposta');
  END IF;

  UPDATE public.perguntas_sem_resposta
    SET resposta_do_dono = p_resposta,
        respondida_em    = now(),
        respondida_por   = v_uid,
        status_loop      = 'dono_respondeu',
        resolvido        = true,
        resolvido_em     = now(),
        aprovar_direto   = p_aprovar_direto   -- Δ 2026-09-08
    WHERE id = p_id;

  RETURN jsonb_build_object('ok', true, 'aprovar_direto', p_aprovar_direto);
END;
$$;


ALTER FUNCTION public.responder_pergunta_mentor(p_id uuid, p_resposta text, p_aprovar_direto boolean) OWNER TO postgres;

--
-- Name: resumo_ausencia(timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.resumo_ausencia(p_desde timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_uid       uuid := (SELECT auth.uid());
  v_tenant    uuid;
  v_global    boolean := false;
  v_mensagens integer := 0;
  v_contratos integer := 0;
  v_pix       integer := 0;
  v_pix_valor numeric := 0;
  v_creditos  numeric;
BEGIN
  IF v_uid IS NULL OR p_desde IS NULL THEN
    RETURN jsonb_build_object('mensagens', 0, 'contratos', 0, 'pix', 0, 'pix_valor', 0, 'creditos', 0);
  END IF;

  -- Membro de equipe enxerga o movimento do tenant dono da conta.
  SELECT COALESCE(p.parent_user_id, p.id), (p.system_role = 'platform_admin')
    INTO v_tenant, v_global
  FROM public.profiles p
  WHERE p.id = v_uid;

  IF v_tenant IS NULL THEN
    RETURN jsonb_build_object('mensagens', 0, 'contratos', 0, 'pix', 0, 'pix_valor', 0, 'creditos', 0);
  END IF;

  -- Mensagens que o lead mandou. O filtro por conversa recém-atualizada corta o
  -- escaneamento: conversa sem updated_at novo não pode ter mensagem nova.
  SELECT count(*) INTO v_mensagens
  FROM public.conversas c
  JOIN public.mensagens m ON m.conversation_id = c.id
  WHERE (v_global OR c.tenant_id = v_tenant)
    AND c.updated_at > p_desde
    AND m.created_at > p_desde
    AND m.role = 'user'
    AND m.deleted_at IS NULL;

  SELECT count(*) INTO v_contratos
  FROM public.contratos ct
  WHERE (v_global OR ct.tenant_id = v_tenant)
    AND ct.assinado_em > p_desde;

  SELECT count(*), COALESCE(sum(pc.valor), 0) INTO v_pix, v_pix_valor
  FROM public.pagamentos_cliente pc
  WHERE (v_global OR pc.tenant_id = v_tenant)
    AND pc.status = 'pago'
    AND COALESCE(pc.data_pagamento::timestamptz, pc.updated_at, pc.created_at) > p_desde;

  IF v_global THEN
    SELECT COALESCE(sum(cs.saldo), 0) INTO v_creditos FROM public.consultas_saldo cs;
  ELSE
    SELECT cs.saldo INTO v_creditos
    FROM public.consultas_saldo cs
    WHERE cs.tenant_id = v_tenant;
  END IF;

  RETURN jsonb_build_object(
    'mensagens', v_mensagens,
    'contratos', v_contratos,
    'pix',       v_pix,
    'pix_valor', v_pix_valor,
    'creditos',  COALESCE(v_creditos, 0),
    'global',    v_global
  );
END;
$$;


ALTER FUNCTION public.resumo_ausencia(p_desde timestamp with time zone) OWNER TO postgres;

--
-- Name: resumo_cliente(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.resumo_cliente(p_lead_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_contratos jsonb;
  v_total_consumido numeric;
  v_total_pago numeric;
  v_total_pendente numeric;
  v_proxima_parcela jsonb;
BEGIN
  IF NOT public._lead_pertence_caller(p_lead_id) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;

  SELECT COALESCE(jsonb_agg(c ORDER BY assinado_em DESC NULLS LAST), '[]'::jsonb)
    INTO v_contratos
  FROM (
    SELECT id, titulo, status, assinado_em,
           COALESCE((opcoes_pagamento->>'valor_a_vista')::numeric, 0) AS valor
      FROM public.contratos
     WHERE lead_id = p_lead_id
       AND assinado_em IS NOT NULL
  ) c;

  SELECT COALESCE(SUM(valor), 0)
    INTO v_total_consumido
    FROM public.pagamentos_cliente
   WHERE lead_id = p_lead_id;

  SELECT COALESCE(SUM(valor) FILTER (WHERE status = 'pago'), 0),
         COALESCE(SUM(valor) FILTER (WHERE status = 'pendente'), 0)
    INTO v_total_pago, v_total_pendente
    FROM public.pagamentos_cliente
   WHERE lead_id = p_lead_id;

  SELECT to_jsonb(p)
    INTO v_proxima_parcela
  FROM (
    SELECT id, descricao, valor, data_vencimento
      FROM public.pagamentos_cliente
     WHERE lead_id = p_lead_id
       AND status = 'pendente'
     ORDER BY data_vencimento NULLS LAST
     LIMIT 1
  ) p;

  RETURN jsonb_build_object(
    'contratos', v_contratos,
    'total_consumido', v_total_consumido,
    'total_pago', v_total_pago,
    'total_pendente', v_total_pendente,
    'proxima_parcela', v_proxima_parcela
  );
END;
$$;


ALTER FUNCTION public.resumo_cliente(p_lead_id uuid) OWNER TO postgres;

--
-- Name: retentar_acoes_agendadas_falhas(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.retentar_acoes_agendadas_falhas() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF NEW.status IN ('failed','falhou') AND COALESCE(NEW.tentativas, 0) < 3 THEN
    NEW.scheduled_at := now() + interval '5 minutes';
    NEW.status := 'pendente';
    NEW.tentativas := COALESCE(OLD.tentativas, 0) + 1;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.retentar_acoes_agendadas_falhas() OWNER TO postgres;

--
-- Name: revert_tag_merge(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.revert_tag_merge(p_log_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_log public.registro_fusao_tag%ROWTYPE; v_revert integer := 0;
BEGIN
  SELECT * INTO v_log FROM public.registro_fusao_tag WHERE id = p_log_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'log nao encontrado'; END IF;
  IF v_log.applied_at < now() - interval '90 days' THEN RAISE EXCEPTION 'janela de 90 dias expirou'; END IF;
  WITH afetados AS (
    UPDATE public.leads SET tags = (SELECT array_agg(DISTINCT t) FROM (SELECT unnest(tags) AS t UNION SELECT v_log.tag_origem) z)
    FROM public.profiles p
    WHERE p.id = public.leads.tenant_id AND p.nicho_id = v_log.nicho_id AND public.leads.tags @> ARRAY[v_log.tag_destino]
    RETURNING public.leads.id
  )
  SELECT count(*) INTO v_revert FROM afetados;
  INSERT INTO public.candidatos_tag (nicho_id, tag_text, num_observacoes, num_leads_independentes, evidencia_lead_ids, status, criado_em, atualizado_em)
  VALUES (v_log.nicho_id, v_log.tag_origem, v_log.num_observacoes_movidas, v_log.num_observacoes_movidas, ARRAY[]::uuid[], 'pendente', now(), now())
  ON CONFLICT (nicho_id, tag_text) DO UPDATE
  SET num_leads_independentes = EXCLUDED.num_leads_independentes, atualizado_em = now();
  UPDATE public.sugestoes_fusao_tag SET status = 'rejeitado', decided_at = now() WHERE id = v_log.origem_suggestion_id;
  DELETE FROM public.registro_fusao_tag WHERE id = p_log_id;
  RETURN v_revert;
END;
$$;


ALTER FUNCTION public.revert_tag_merge(p_log_id uuid) OWNER TO postgres;

--
-- Name: rifa_app_instalado(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rifa_app_instalado(p_tenant_id uuid DEFAULT NULL::uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_tenant uuid := public.tenant_efetivo(p_tenant_id);
  v_exige_instalacao boolean;
  v_instalado boolean;
begin
  if v_tenant is null then return false; end if;

  select exists (
    select 1 from public.loja_aplicativos where slug = 'rifas' and is_active = true
  ) into v_exige_instalacao;

  -- App fora da loja (desligado globalmente) = ninguém precisa instalar pra ter.
  -- Mesmo comportamento de `rifa_pode_vender`, de propósito.
  if not v_exige_instalacao then return true; end if;

  select exists (
    select 1 from public.aplicativos_instalados
    where user_id = v_tenant and aplicativo_slug = 'rifas'
  ) into v_instalado;

  return v_instalado;
end;
$$;


ALTER FUNCTION public.rifa_app_instalado(p_tenant_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION rifa_app_instalado(p_tenant_id uuid); Type: COMMENT; Schema: public; Owner: postgres
