-- Name: rifa_confirmar_pagamento_agente(uuid, uuid, boolean, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rifa_confirmar_pagamento_agente(p_tenant_id uuid, p_pedido uuid, p_aprovar boolean, p_motivo text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select public.rifa_confirmar_pagamento_core(p_tenant_id, p_pedido, p_aprovar, p_motivo);
$$;


ALTER FUNCTION public.rifa_confirmar_pagamento_agente(p_tenant_id uuid, p_pedido uuid, p_aprovar boolean, p_motivo text) OWNER TO postgres;

--
-- Name: rifa_confirmar_pagamento_core(uuid, uuid, boolean, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rifa_confirmar_pagamento_core(p_tenant uuid, p_pedido uuid, p_aprovar boolean, p_motivo text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_p public.pedidos_rifa%rowtype;
  v_cotas_ganhas jsonb := '[]'::jsonb;
begin
  -- Tranca de identidade (2026-09-08): não pode viver só no GRANT.
  PERFORM public.tenant_efetivo(p_tenant);
  if p_tenant is null then
    return jsonb_build_object('ok', false, 'erro', 'nao_autenticado');
  end if;

  select * into v_p from public.pedidos_rifa
  where id = p_pedido and tenant_id = p_tenant
  for update;
  if not found then
    return jsonb_build_object('ok', false, 'erro', 'pedido_nao_encontrado');
  end if;
  if v_p.status in ('pago', 'expirado', 'cancelado') then
    return jsonb_build_object('ok', false, 'erro', 'pedido_ja_finalizado (' || v_p.status || ')');
  end if;

  if p_aprovar then
    update public.numeros_rifa set status = 'pago' where pedido_id = v_p.id;
    update public.pedidos_rifa
    set status = 'pago', pago_em = now(), expira_em = null, updated_at = now()
    where id = v_p.id;

    with novas as (
      select jsonb_agg(
        case when (c->>'pedido_ganhador') is null and (c->>'numero')::int = any(v_p.numeros)
          then c || jsonb_build_object('pedido_ganhador', v_p.id::text, 'ganhador_nome', v_p.nome)
          else c end) as cotas,
        coalesce(jsonb_agg(c || jsonb_build_object('ganhador_nome', v_p.nome))
          filter (where (c->>'pedido_ganhador') is null and (c->>'numero')::int = any(v_p.numeros)),
          '[]'::jsonb) as ganhas
      from jsonb_array_elements((select cotas_premiadas from public.rifas where id = v_p.rifa_id)) c
    )
    update public.rifas r
    set cotas_premiadas = coalesce(novas.cotas, r.cotas_premiadas), updated_at = now()
    from novas
    where r.id = v_p.rifa_id
    returning novas.ganhas into v_cotas_ganhas;

    return jsonb_build_object('ok', true, 'status', 'pago',
      'cotas_premiadas_ganhas', coalesce(v_cotas_ganhas, '[]'::jsonb));
  else
    delete from public.numeros_rifa where pedido_id = v_p.id;
    update public.pedidos_rifa
    set status = 'rejeitado', motivo_rejeicao = coalesce(p_motivo, 'comprovante rejeitado'),
        expira_em = null, updated_at = now()
    where id = v_p.id;
    return jsonb_build_object('ok', true, 'status', 'rejeitado');
  end if;
end;
$$;


ALTER FUNCTION public.rifa_confirmar_pagamento_core(p_tenant uuid, p_pedido uuid, p_aprovar boolean, p_motivo text) OWNER TO postgres;

--
-- Name: rifa_decidir_reserva_vencida(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rifa_decidir_reserva_vencida(p_pedido uuid, p_decisao text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_p public.pedidos_rifa%rowtype;
  v_valor_unit integer;
  v_qtd integer := 0;
begin
  if p_decisao not in ('divida', 'sem_divida') then
    return jsonb_build_object('ok', false, 'erro', 'decisao_invalida');
  end if;

  select * into v_p from public.pedidos_rifa where id = p_pedido;
  if not found then
    return jsonb_build_object('ok', false, 'erro', 'pedido_nao_encontrado');
  end if;
  if v_p.tenant_id is distinct from (select auth.uid()) then
    return jsonb_build_object('ok', false, 'erro', 'sem_permissao');
  end if;
  if v_p.status <> 'reservado' then
    return jsonb_build_object('ok', false, 'erro', 'pedido_nao_esta_reservado');
  end if;

  if p_decisao = 'divida' then
    -- Rateia o valor do pedido pelos números pra respeitar promoção (mesma conta da cron antiga).
    v_valor_unit := greatest(1, round(v_p.valor_centavos::numeric / greatest(1, coalesce(v_p.qtd_numeros, 1)))::int);
    insert into public.rifa_dividas (tenant_id, rifa_id, numero, nome, phone, valor_centavos, origem, sorteio_em)
    select v_p.tenant_id, v_p.rifa_id, n, coalesce(v_p.nome, 'Sem nome'), v_p.phone, v_valor_unit, 'reserva',
           coalesce(public.rifa_sorteio_em(v_p.rifa_id), now())
    from unnest(coalesce(v_p.numeros, '{}')) n
    on conflict (rifa_id, numero) do nothing;
    get diagnostics v_qtd = row_count;
    update public.pedidos_rifa
    set divida_gerada_em = now(), divida_dispensada_em = null, updated_at = now()
    where id = p_pedido;
  else
    update public.pedidos_rifa
    set divida_dispensada_em = now(), updated_at = now()
    where id = p_pedido;
  end if;

  return jsonb_build_object('ok', true, 'decisao', p_decisao, 'dividas_criadas', v_qtd);
end;
$$;


ALTER FUNCTION public.rifa_decidir_reserva_vencida(p_pedido uuid, p_decisao text) OWNER TO postgres;

--
-- Name: rifa_dossie_agente(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rifa_dossie_agente(p_tenant_id uuid, p_phone text DEFAULT NULL::text, p_lead_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_phone text := nullif(regexp_replace(coalesce(p_phone, ''), '\D', '', 'g'), '');
  v_pedidos jsonb;
  v_fixos jsonb;
  v_dividas jsonb;
  v_gasto bigint;
  v_numeros integer;
  v_rifas integer;
  v_divida_total bigint;
begin
  -- Tranca de identidade (2026-09-08): não pode viver só no GRANT.
  PERFORM public.tenant_efetivo(p_tenant_id);
  if p_tenant_id is null or (v_phone is null and p_lead_id is null) then
    return jsonb_build_object('ok', false, 'erro', 'informe_phone_ou_lead');
  end if;

  select coalesce(jsonb_agg(jsonb_build_object(
           'pedido_id', p.id, 'rifa_id', p.rifa_id, 'rifa_titulo', r.titulo,
           'rifa_codigo', r.codigo_controle, 'rifa_status', r.status,
           'nome', p.nome, 'numeros', p.numeros, 'qtd', p.qtd_numeros,
           'valor_centavos', p.valor_centavos, 'status', p.status, 'origem', p.origem,
           'comprovante_url', p.comprovante_url, 'expira_em', p.expira_em,
           'criado_em', p.created_at, 'pago_em', p.pago_em,
           'ganhou', (r.numero_sorteado is not null and r.numero_sorteado = any(p.numeros))
         ) order by p.created_at desc), '[]'::jsonb),
         coalesce(sum(p.valor_centavos) filter (where p.status = 'pago'), 0),
         coalesce(sum(p.qtd_numeros) filter (where p.status in ('pago', 'reservado', 'aguardando_validacao')), 0),
         count(distinct p.rifa_id)
    into v_pedidos, v_gasto, v_numeros, v_rifas
  from public.pedidos_rifa p
  join public.rifas r on r.id = p.rifa_id
  where p.tenant_id = p_tenant_id
    and (
      (p_lead_id is not null and p.lead_id = p_lead_id)
      or (v_phone is not null and regexp_replace(coalesce(p.phone, ''), '\D', '', 'g') = v_phone)
    );

  select coalesce(jsonb_agg(jsonb_build_object(
           'metodo_sorteio', metodo_sorteio, 'numero', numero, 'nome', nome) order by numero), '[]'::jsonb)
    into v_fixos
  from public.rifa_numeros_fixos
  where tenant_id = p_tenant_id
    and status = 'ativo'
    and v_phone is not null
    and regexp_replace(coalesce(phone, ''), '\D', '', 'g') = v_phone;

  select coalesce(jsonb_agg(jsonb_build_object(
           'divida_id', d.id, 'rifa_titulo', r.titulo, 'numero', d.numero,
           'valor_centavos', d.valor_centavos, 'origem', d.origem, 'pago', d.pago,
           'sorteio_em', d.sorteio_em) order by d.sorteio_em desc), '[]'::jsonb),
         coalesce(sum(d.valor_centavos) filter (where d.pago = false), 0)
    into v_dividas, v_divida_total
  from public.rifa_dividas d
  join public.rifas r on r.id = d.rifa_id
  where d.tenant_id = p_tenant_id
    and v_phone is not null
    and regexp_replace(coalesce(d.phone, ''), '\D', '', 'g') = v_phone;

  return jsonb_build_object(
    'ok', true,
    'phone', v_phone,
    'pedidos', v_pedidos,
    'numeros_fixos', v_fixos,
    'dividas', v_dividas,
    'resumo', jsonb_build_object(
      'total_gasto_centavos', v_gasto,
      'numeros_ativos', v_numeros,
      'rifas_participadas', v_rifas,
      'divida_aberta_centavos', v_divida_total)
  );
end;
$$;


ALTER FUNCTION public.rifa_dossie_agente(p_tenant_id uuid, p_phone text, p_lead_id uuid) OWNER TO postgres;

--
-- Name: rifa_hora_padrao_metodo(text, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rifa_hora_padrao_metodo(p_metodo text, p_data date) RETURNS time without time zone
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select case
    when p_metodo = 'loteria_federal' then
      case extract(isodow from p_data)::int when 7 then time '11:00' when 3 then time '20:00' end
    when extract(isodow from p_data)::int between 1 and 6 then
      case p_metodo
        when 'ppt' then time '09:20'
        when 'ptm' then time '11:20'
        when 'pt_rio' then time '14:20'
        when 'ptv' then time '16:20'
        when 'ptn' then time '18:20'
        when 'corujinha' then time '21:20'
      end
  end
$$;


ALTER FUNCTION public.rifa_hora_padrao_metodo(p_metodo text, p_data date) OWNER TO postgres;

--
-- Name: rifa_normalizar_hora(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rifa_normalizar_hora(p_txt text) RETURNS time without time zone
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
declare
  m text[];
  h integer;
  mi integer;
begin
  if p_txt is null then return null; end if;
  m := regexp_match(btrim(p_txt), '^(\d{1,2})\s*[:hH]?\s*(\d{2})?');
  if m is null then return null; end if;
  h := m[1]::int;
  mi := coalesce(m[2], '0')::int;
  if h > 23 or mi > 59 then return null; end if;
  return make_time(h, mi, 0);
end;
$$;


ALTER FUNCTION public.rifa_normalizar_hora(p_txt text) OWNER TO postgres;

--
-- Name: rifa_painel_agente(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rifa_painel_agente(p_tenant_id uuid, p_rifa uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_r public.rifas%rowtype;
  v_min integer;
  v_pagos integer;
  v_reservados integer;
  v_arrecadado bigint;
  v_a_receber bigint;
  v_aguardando integer;
  v_participantes integer;
  v_top jsonb;
  v_fila jsonb;
  v_expirando jsonb;
  v_dividas_qtd integer;
  v_dividas_total bigint;
begin
  -- Tranca de identidade (2026-09-08): não pode viver só no GRANT.
  PERFORM public.tenant_efetivo(p_tenant_id);
  if p_tenant_id is null then
    return jsonb_build_object('ok', false, 'erro', 'sem_tenant');
  end if;

  if p_rifa is not null then
    select * into v_r from public.rifas
    where id = p_rifa and tenant_id = p_tenant_id and deleted_at is null;
  else
    select * into v_r from public.rifas
    where tenant_id = p_tenant_id and status = 'ativa' and deleted_at is null
    order by created_at desc limit 1;
  end if;
  if not found then
    return jsonb_build_object('ok', false, 'erro', 'rifa_nao_encontrada');
  end if;

  v_min := case when v_r.numeracao_desde_zero then 0 else 1 end;

  select count(*) filter (where status = 'pago'),
         count(*) filter (where status = 'reservado')
    into v_pagos, v_reservados
  from public.numeros_rifa where rifa_id = v_r.id;

  select coalesce(sum(valor_centavos) filter (where status = 'pago'), 0),
         coalesce(sum(valor_centavos) filter (where status in ('reservado', 'aguardando_validacao')), 0),
         count(*) filter (where status = 'aguardando_validacao'),
         count(distinct coalesce(phone, 'nome:' || nome)) filter (where status = 'pago')
    into v_arrecadado, v_a_receber, v_aguardando, v_participantes
  from public.pedidos_rifa where rifa_id = v_r.id;

  select coalesce(jsonb_agg(jsonb_build_object(
           'pedido_id', id, 'nome', nome, 'phone', phone, 'numeros', numeros,
           'valor_centavos', valor_centavos, 'comprovante_url', comprovante_url,
           'criado_em', created_at) order by created_at), '[]'::jsonb)
    into v_fila
  from (select * from public.pedidos_rifa
        where rifa_id = v_r.id and status = 'aguardando_validacao'
        order by created_at limit 20) q;

  select coalesce(jsonb_agg(jsonb_build_object(
           'pedido_id', id, 'nome', nome, 'phone', phone, 'numeros', numeros,
           'valor_centavos', valor_centavos, 'expira_em', expira_em) order by expira_em), '[]'::jsonb)
    into v_expirando
  from (select * from public.pedidos_rifa
        where rifa_id = v_r.id and status = 'reservado' and expira_em is not null
          and expira_em <= now() + interval '2 hours'
        order by expira_em limit 20) e;

  select coalesce(jsonb_agg(t), '[]'::jsonb) into v_top from (
    -- Δ 2026-09-11 (Fabrício): o mesmo telefone é o mesmo comprador — agrupa por phone (o nome
    -- exibido é o mais recente não-genérico); sem telefone, cai no nome.
    select
      coalesce(
        (select p2.nome from public.pedidos_rifa p2
          where p2.rifa_id = v_r.id and p2.status = 'pago'
            and coalesce(p2.phone, 'nome:' || p2.nome) = coalesce(p.phone, 'nome:' || p.nome)
            and p2.nome !~* '^(lead|cliente whatsapp|cliente|contato)?$' and p2.nome !~ '^[0-9]{8,}$'
          order by p2.created_at desc limit 1),
        max(p.nome)) as nome,
      p.phone,
      sum(p.qtd_numeros) as numeros,
      sum(p.valor_centavos) as gasto_centavos
    from public.pedidos_rifa p
    where p.rifa_id = v_r.id and p.status = 'pago'
    group by coalesce(p.phone, 'nome:' || p.nome), p.phone
    order by sum(p.qtd_numeros) desc
    limit 5
  ) t;

  select count(*), coalesce(sum(valor_centavos), 0)
    into v_dividas_qtd, v_dividas_total
  from public.rifa_dividas where tenant_id = p_tenant_id and pago = false;

  return jsonb_build_object(
    'ok', true,
    'rifa', jsonb_build_object(
      'id', v_r.id, 'codigo_controle', v_r.codigo_controle, 'titulo', v_r.titulo,
      'premio_principal', v_r.premio_principal, 'premios_extras', v_r.premios_extras,
      'status', v_r.status, 'preco_numero_centavos', v_r.preco_numero_centavos,
      'total_numeros', v_r.total_numeros, 'numero_inicial', v_min,
      'metodo_sorteio', v_r.metodo_sorteio, 'data_sorteio_prevista', v_r.data_sorteio_prevista,
      'aceita_fiado', v_r.aceita_fiado, 'minutos_reserva', v_r.minutos_reserva,
      'max_numeros_por_pedido', v_r.max_numeros_por_pedido,
      'promocoes', v_r.promocoes, 'cotas_premiadas', v_r.cotas_premiadas,
      'chave_publica', v_r.chave_publica,
      'numero_sorteado', v_r.numero_sorteado, 'ganhador_nome', v_r.ganhador_nome,
      'resultado_sorteio', v_r.resultado_sorteio, 'sorteada_em', v_r.sorteada_em),
    'progresso', jsonb_build_object(
      'pagos', v_pagos, 'reservados', v_reservados,
      'disponiveis', v_r.total_numeros - v_pagos - v_reservados,
      'total', v_r.total_numeros,
      'pct_vendido', round(((v_pagos + v_reservados)::numeric / nullif(v_r.total_numeros, 0)) * 100, 1)),
    'financeiro', jsonb_build_object(
      'arrecadado_centavos', v_arrecadado,
      'a_receber_centavos', v_a_receber,
      'participantes_pagantes', v_participantes,
      'ticket_medio_centavos', case when v_participantes > 0 then round(v_arrecadado::numeric / v_participantes) else 0 end),
    'aguardando_validacao', jsonb_build_object('qtd', v_aguardando, 'pedidos', v_fila),
    'reservas_expirando_2h', v_expirando,
    'top_compradores', v_top,
    'dividas_abertas', jsonb_build_object('qtd', v_dividas_qtd, 'total_centavos', v_dividas_total)
  );
end;
$_$;


ALTER FUNCTION public.rifa_painel_agente(p_tenant_id uuid, p_rifa uuid) OWNER TO postgres;

--
-- Name: rifa_pode_vender(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rifa_pode_vender(p_tenant_id uuid DEFAULT NULL::uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_tenant uuid := public.tenant_efetivo(p_tenant_id);
  v_exige_instalacao boolean;
  v_instalado boolean;
  v_toggle boolean;
begin
  if v_tenant is null then return false; end if;

  select exists (
    select 1 from public.loja_aplicativos where slug = 'rifas' and is_active = true
  ) into v_exige_instalacao;

  if v_exige_instalacao then
    select exists (
      select 1 from public.aplicativos_instalados
      where user_id = v_tenant and aplicativo_slug = 'rifas'
    ) into v_instalado;
    if not v_instalado then return false; end if;
  end if;

  select agente_pode_vender into v_toggle
  from public.rifas_config_tenant where tenant_id = v_tenant;

  return coalesce(v_toggle, true);
end;
$$;


ALTER FUNCTION public.rifa_pode_vender(p_tenant_id uuid) OWNER TO postgres;

