--
-- Name: rifa_reembolsar_pedido(uuid, integer[], text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rifa_reembolsar_pedido(p_pedido uuid, p_numeros integer[] DEFAULT NULL::integer[], p_motivo text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_p public.pedidos_rifa%rowtype;
  v_r public.rifas%rowtype;
  v_alvo integer[];
  v_resto integer[];
  v_reembolso integer;
  v_motivo text := coalesce(nullif(btrim(p_motivo), ''), 'Desistência com reembolso');
begin
  select * into v_p from public.pedidos_rifa where id = p_pedido for update;
  if not found then
    return jsonb_build_object('ok', false, 'erro', 'pedido_nao_encontrado');
  end if;
  if v_p.tenant_id is distinct from (select auth.uid()) then
    return jsonb_build_object('ok', false, 'erro', 'sem_permissao');
  end if;
  if v_p.status <> 'pago' then
    return jsonb_build_object('ok', false, 'erro', 'so_pedido_pago (' || v_p.status || ')');
  end if;

  select * into v_r from public.rifas where id = v_p.rifa_id for update;
  if v_r.status = 'sorteada' or v_r.numero_sorteado is not null or v_r.sorteada_em is not null then
    return jsonb_build_object('ok', false, 'erro', 'rifa_ja_sorteada');
  end if;

  -- Sem lista = pedido inteiro. Número que não é deste pedido invalida a chamada toda.
  v_alvo := coalesce(p_numeros, v_p.numeros);
  select coalesce(array_agg(distinct n order by n), '{}') into v_alvo from unnest(v_alvo) n;
  if cardinality(v_alvo) = 0 then
    return jsonb_build_object('ok', false, 'erro', 'nenhum_numero');
  end if;
  if not (v_alvo <@ v_p.numeros) then
    return jsonb_build_object('ok', false, 'erro', 'numero_fora_do_pedido');
  end if;
  select coalesce(array_agg(n order by n), '{}') into v_resto from unnest(v_p.numeros) n where n <> all(v_alvo);

  -- Rateio pelo que o comprador pagou (respeita promoção); pedido inteiro devolve o valor cheio.
  v_reembolso := case when cardinality(v_resto) = 0 then v_p.valor_centavos
    else round(v_p.valor_centavos::numeric * cardinality(v_alvo) / greatest(1, cardinality(v_p.numeros)))::int end;

  delete from public.numeros_rifa where pedido_id = v_p.id and numero = any(v_alvo);

  -- Status do WhatsApp (Fabrício 10/09): número devolvido tem que aparecer na cartela. O
  -- cron-status-rifa (a cada 2 min) só posta quando a CONTAGEM de ocupados muda — um reembolso
  -- e uma reserva no mesmo intervalo empatam e nada sai. Snapshot nulo = "mudou": o próximo giro
  -- regera a cartela e posta, mesmo se a rifa ficou sem nenhum número ocupado.
  update public.rifas set vendidos_no_ultimo_status = null where id = v_r.id;

  update public.rifas
  set cotas_premiadas = (
        select jsonb_agg(case
          when c->>'pedido_ganhador' = v_p.id::text and (c->>'numero')::int = any(v_alvo)
            then c - 'pedido_ganhador' - 'ganhador_nome'
          else c end)
        from jsonb_array_elements(cotas_premiadas) c),
      updated_at = now()
  where id = v_r.id and jsonb_typeof(cotas_premiadas) = 'array' and jsonb_array_length(cotas_premiadas) > 0;

  if cardinality(v_resto) = 0 then
    update public.pedidos_rifa
    set status = 'cancelado', expira_em = null,
        reembolsado_em = now(), reembolso_centavos = reembolso_centavos + v_reembolso,
        numeros_reembolsados = numeros_reembolsados || v_alvo, motivo_reembolso = v_motivo,
        updated_at = now()
    where id = v_p.id;
  else
    update public.pedidos_rifa
    set numeros = v_resto, qtd_numeros = cardinality(v_resto), valor_centavos = valor_centavos - v_reembolso,
        reembolsado_em = now(), reembolso_centavos = reembolso_centavos + v_reembolso,
        numeros_reembolsados = numeros_reembolsados || v_alvo, motivo_reembolso = v_motivo,
        updated_at = now()
    where id = v_p.id;
  end if;

  return jsonb_build_object('ok', true,
    'status', case when cardinality(v_resto) = 0 then 'cancelado' else 'pago' end,
    'numeros_liberados', to_jsonb(v_alvo), 'numeros_restantes', to_jsonb(v_resto),
    'reembolso_centavos', v_reembolso);
end;
$$;


ALTER FUNCTION public.rifa_reembolsar_pedido(p_pedido uuid, p_numeros integer[], p_motivo text) OWNER TO postgres;

--
-- Name: rifa_reservas_viram_divida(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rifa_reservas_viram_divida() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_qtd integer := 0;
  v_p record;
  v_valor_unit integer;
begin
  for v_p in
    select pr.id, pr.tenant_id, pr.rifa_id, pr.nome, pr.phone, pr.numeros,
           pr.valor_centavos, pr.qtd_numeros,
           (r.data_sorteio_prevista + coalesce(r.hora_sorteio, '20:00'::time))
             at time zone 'America/Sao_Paulo' as sorteio_em
    from public.pedidos_rifa pr
    join public.rifas r on r.id = pr.rifa_id
    where pr.status = 'reservado'
      and pr.divida_gerada_em is null
      and r.status = 'ativa'
      and r.deleted_at is null
      -- Sem data cadastrada não existe "uma hora antes" — a dívida desse caso continua
      -- nascendo no sorteio, como sempre foi.
      and r.data_sorteio_prevista is not null
      and (r.data_sorteio_prevista + coalesce(r.hora_sorteio, '20:00'::time))
            at time zone 'America/Sao_Paulo' <= now() + interval '1 hour'
    limit 200
  loop
    -- Rateia o valor do pedido pelos números pra respeitar promoção ("10 por R$ 80" não pode
    -- virar dívida de preço cheio).
    v_valor_unit := greatest(1, round(v_p.valor_centavos::numeric / greatest(1, coalesce(v_p.qtd_numeros, 1)))::int);

    insert into public.rifa_dividas (tenant_id, rifa_id, numero, nome, phone, valor_centavos, origem, sorteio_em)
    select v_p.tenant_id, v_p.rifa_id, n, v_p.nome, v_p.phone, v_valor_unit, 'reserva', v_p.sorteio_em
    from unnest(coalesce(v_p.numeros, '{}')) n
    on conflict (rifa_id, numero) do nothing;

    -- O número CONTINUA reservado no nome da pessoa: nada é apagado de `numeros_rifa`.
    -- `expira_em` zerado só pra tirar o pedido de qualquer varredura de expiração.
    update public.pedidos_rifa
    set divida_gerada_em = now(), expira_em = null, updated_at = now()
    where id = v_p.id;

    v_qtd := v_qtd + 1;
  end loop;
  return v_qtd;
end;
$_$;


ALTER FUNCTION public.rifa_reservas_viram_divida() OWNER TO postgres;

--
-- Name: FUNCTION rifa_reservas_viram_divida(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.rifa_reservas_viram_divida() IS 'Uma hora antes do sorteio, toda reserva não paga vira dívida (1 linha por número). O número NÃO volta pro pote — só sai se o dono rejeitar o pedido. Cron rifa_reservas_viram_divida, */10min.';


--
-- Name: rifa_sortear_agente(uuid, uuid, integer, integer[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rifa_sortear_agente(p_tenant_id uuid, p_rifa uuid, p_numero_manual integer DEFAULT NULL::integer, p_numeros_manuais integer[] DEFAULT NULL::integer[]) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select public.rifa_sortear_core(p_tenant_id, p_rifa, p_numero_manual, p_numeros_manuais);
$$;


ALTER FUNCTION public.rifa_sortear_agente(p_tenant_id uuid, p_rifa uuid, p_numero_manual integer, p_numeros_manuais integer[]) OWNER TO postgres;

--
-- Name: rifa_sortear_core(uuid, uuid, integer, integer[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rifa_sortear_core(p_tenant uuid, p_rifa uuid, p_numero_manual integer, p_numeros_manuais integer[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_r public.rifas%rowtype;
  v_min integer;
  v_max integer;
  v_premios text[];
  v_numeros integer[];
  v_qtd integer;
  v_numero integer;
  v_ped public.pedidos_rifa%rowtype;
  v_resultado jsonb := '[]'::jsonb;
  v_item jsonb;
  v_dividas integer := 0;
  i integer;
begin
  -- Tranca de identidade (2026-09-08): não pode viver só no GRANT.
  PERFORM public.tenant_efetivo(p_tenant);
  if p_tenant is null then
    return jsonb_build_object('ok', false, 'erro', 'nao_autenticado');
  end if;

  select * into v_r from public.rifas
  where id = p_rifa and tenant_id = p_tenant and deleted_at is null
  for update;
  if not found then
    return jsonb_build_object('ok', false, 'erro', 'rifa_nao_encontrada');
  end if;
  if v_r.status = 'sorteada' then
    return jsonb_build_object('ok', false, 'erro', 'rifa_ja_sorteada');
  end if;

  v_min := case when v_r.numeracao_desde_zero then 0 else 1 end;
  v_max := v_min + v_r.total_numeros - 1;

  select array[v_r.premio_principal] || coalesce(array_agg(e.value #>> '{}' order by e.ordinality), '{}')
    into v_premios
  from jsonb_array_elements(coalesce(v_r.premios_extras, '[]'::jsonb)) with ordinality e;
  v_qtd := coalesce(array_length(v_premios, 1), 1);

  if p_numeros_manuais is not null and array_length(p_numeros_manuais, 1) > 0 then
    if array_length(p_numeros_manuais, 1) <> v_qtd then
      return jsonb_build_object('ok', false, 'erro',
        'informar_um_numero_por_premio (' || v_qtd || ' prêmios)');
    end if;
    if exists (select 1 from unnest(p_numeros_manuais) n where n < v_min or n > v_max) then
      return jsonb_build_object('ok', false, 'erro', 'numero_fora_da_faixa');
    end if;
    if (select count(distinct n) from unnest(p_numeros_manuais) n) <> v_qtd then
      return jsonb_build_object('ok', false, 'erro', 'numeros_repetidos');
    end if;
    v_numeros := p_numeros_manuais;
  elsif p_numero_manual is not null then
    if v_qtd > 1 then
      return jsonb_build_object('ok', false, 'erro',
        'informar_um_numero_por_premio (' || v_qtd || ' prêmios)');
    end if;
    if p_numero_manual < v_min or p_numero_manual > v_max then
      return jsonb_build_object('ok', false, 'erro', 'numero_fora_da_faixa');
    end if;
    v_numeros := array[p_numero_manual];
  else
    select array_agg(numero) into v_numeros
    from (
      select numero from public.numeros_rifa
      where rifa_id = v_r.id and status = 'pago'
      order by random() limit v_qtd
    ) s;
    if v_numeros is null then
      return jsonb_build_object('ok', false, 'erro', 'sem_numeros_pagos');
    end if;
    if array_length(v_numeros, 1) < v_qtd then
      return jsonb_build_object('ok', false, 'erro',
        'pagos_insuficientes (' || array_length(v_numeros, 1) || ' pagos pra ' || v_qtd || ' prêmios)');
    end if;
  end if;

  for i in 1..v_qtd loop
    v_numero := v_numeros[i];
    v_ped := null;
    select p.* into v_ped
    from public.numeros_rifa nr
    join public.pedidos_rifa p on p.id = nr.pedido_id
    where nr.rifa_id = v_r.id and nr.numero = v_numero and nr.status = 'pago';

    v_item := jsonb_build_object(
      'ordem', i, 'premio', v_premios[i], 'numero', v_numero,
      'ganhador_nome', v_ped.nome, 'ganhador_phone', v_ped.phone,
      'sem_ganhador', v_ped.id is null
    );
    v_resultado := v_resultado || jsonb_build_array(v_item);
  end loop;

  with nao_pagos as (
    select nr.numero, p.nome, p.phone,
           case when p.origem = 'manual' and p.expira_em is null then 'fixo' else 'reserva' end as origem
    from public.numeros_rifa nr
    join public.pedidos_rifa p on p.id = nr.pedido_id
    where nr.rifa_id = v_r.id and nr.status = 'reservado'
      and p.divida_dispensada_em is null  -- dono decidiu não cobrar (10/09)
  ), ins as (
    insert into public.rifa_dividas (tenant_id, rifa_id, numero, nome, phone, valor_centavos, origem, sorteio_em)
    select v_r.tenant_id, v_r.id, np.numero, coalesce(np.nome, 'Sem nome'), np.phone,
           v_r.preco_numero_centavos, np.origem, now()
    from nao_pagos np
    on conflict (rifa_id, numero) do nothing
    returning 1
  )
  select count(*) into v_dividas from ins;

  update public.rifas
  set status = 'sorteada',
      numero_sorteado = v_numeros[1],
      ganhador_nome = v_resultado->0->>'ganhador_nome',
      ganhador_phone = v_resultado->0->>'ganhador_phone',
      resultado_sorteio = v_resultado,
      sorteada_em = now(), updated_at = now()
  where id = v_r.id;

  return jsonb_build_object(
    'ok', true,
    'numero_sorteado', v_numeros[1],
    'ganhador_nome', v_resultado->0->>'ganhador_nome',
    'ganhador_phone', v_resultado->0->>'ganhador_phone',
    'sem_ganhador', (v_resultado->0->>'sem_ganhador')::boolean,
    'dividas_geradas', v_dividas,
    'resultado', v_resultado
  );
end;
$$;


ALTER FUNCTION public.rifa_sortear_core(p_tenant uuid, p_rifa uuid, p_numero_manual integer, p_numeros_manuais integer[]) OWNER TO postgres;

--
-- Name: rifa_sorteio_em(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rifa_sorteio_em(p_rifa uuid) RETURNS timestamp with time zone
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select case when r.data_sorteio_prevista is null then null else
    (r.data_sorteio_prevista + coalesce(
      r.hora_sorteio,
      (select public.rifa_normalizar_hora(ri.hora_sorteio)
         from public.rifa_imagens ri
        where ri.rifa_id = r.id and ri.deleted_at is null and ri.hora_sorteio is not null
        order by ri.created_at desc
        limit 1),
      public.rifa_hora_padrao_metodo(r.metodo_sorteio, r.data_sorteio_prevista),
      time '20:00'
    )) at time zone 'America/Sao_Paulo'
  end
  from public.rifas r
  where r.id = p_rifa
$$;


ALTER FUNCTION public.rifa_sorteio_em(p_rifa uuid) OWNER TO postgres;

--
-- Name: rotear_lead_babel(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rotear_lead_babel(p_lead_babel_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_lead      public.leads_babel%rowtype;
  v_hoje      date := (now() at time zone 'America/Sao_Paulo')::date;
  v_escolhido record;
  v_entrega   uuid;
begin
  select * into v_lead from public.leads_babel where id = p_lead_babel_id and deleted_at is null for update;
  if not found then
    return jsonb_build_object('ok', false, 'erro', 'lead_nao_encontrado');
  end if;
  if v_lead.campanha_babel_id is null then
    return jsonb_build_object('ok', false, 'erro', 'lead_sem_campanha');
  end if;
  if v_lead.status <> 'pronto' then
    return jsonb_build_object('ok', false, 'erro', 'lead_nao_esta_pronto', 'status', v_lead.status);
  end if;
  perform pg_advisory_xact_lock(hashtext(v_lead.campanha_babel_id::text));
  with elegiveis as (
    select p.tenant_id, p.peso, p.criado_em as entrou_em,
           (select count(*) from public.entregas_lead_babel e
             where e.campanha_babel_id = p.campanha_babel_id and e.tenant_id = p.tenant_id
               and e.devolvido_em is null and e.deleted_at is null) as entregues,
           (select count(*) from public.entregas_lead_babel e
             where e.campanha_babel_id = p.campanha_babel_id and e.tenant_id = p.tenant_id
               and e.devolvido_em is null and e.deleted_at is null
               and (e.entregue_em at time zone 'America/Sao_Paulo')::date = v_hoje) as entregues_hoje,
           (select count(*) from public.entregas_lead_babel e
             where e.campanha_babel_id = p.campanha_babel_id
               and e.devolvido_em is null and e.deleted_at is null
               and e.entregue_em >= p.criado_em) as total_desde_que_entrou,
           p.teto_total, p.limite_dia
      from public.campanhas_babel_participantes p
      join public.campanhas_babel c on c.id = p.campanha_babel_id
                                   and c.status = 'ativa' and c.deleted_at is null
     where p.campanha_babel_id = v_lead.campanha_babel_id
       and p.pausado = false and p.deleted_at is null
  ),
  aptos as (
    select * from elegiveis
     where (teto_total is null or entregues < teto_total)
       and (limite_dia is null or entregues_hoje < limite_dia)
  ),
  soma as (select sum(peso) as soma_peso from aptos),
  ranqueado as (
    select a.tenant_id, a.entregues,
           (a.peso / s.soma_peso) * a.total_desde_que_entrou as alvo,
           ((a.peso / s.soma_peso) * a.total_desde_que_entrou) - a.entregues as atraso,
           a.peso
      from aptos a cross join soma s
  )
  select tenant_id, entregues, alvo, atraso
    into v_escolhido
    from ranqueado
   order by atraso desc, peso desc, entregues asc, tenant_id
   limit 1;
  if v_escolhido.tenant_id is null then
    return jsonb_build_object('ok', false, 'erro', 'ninguem_elegivel');
  end if;
  insert into public.entregas_lead_babel (lead_babel_id, campanha_babel_id, tenant_id, motivo_escolha)
  values (p_lead_babel_id, v_lead.campanha_babel_id, v_escolhido.tenant_id,
          format('%s lead(s) atrás do alvo (alvo %s, entregues %s)',
                 round(v_escolhido.atraso::numeric, 2), round(v_escolhido.alvo::numeric, 2), v_escolhido.entregues))
  returning id into v_entrega;
  update public.leads_babel
     set status = 'entregue', atualizado_em = now()
   where id = p_lead_babel_id;
  return jsonb_build_object('ok', true, 'entrega_id', v_entrega, 'tenant_id', v_escolhido.tenant_id,
                            'motivo', format('%s lead(s) atrás do alvo', round(v_escolhido.atraso::numeric, 2)));
end;
$$;


ALTER FUNCTION public.rotear_lead_babel(p_lead_babel_id uuid) OWNER TO postgres;

--
-- Name: rpc_metricas_motor(uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_metricas_motor(_tenant_id uuid DEFAULT NULL::uuid, _dias integer DEFAULT 7) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE _resultado jsonb;
BEGIN
  SELECT jsonb_build_object(
    'periodo_dias', _dias,
    'tenant_id', _tenant_id,
    'gerado_em', now(),
    'totais_traces', (
      SELECT jsonb_build_object(
        'eventos', count(*),
        'tokens_in', coalesce(sum(custo_tokens_in), 0),
        'tokens_out', coalesce(sum(custo_tokens_out), 0),
        'p95_latencia_ms', percentile_cont(0.95) WITHIN GROUP (ORDER BY latencia_ms)::integer
      )
      FROM public.traces
      WHERE criado_em >= now() - (_dias || ' days')::interval
        AND (_tenant_id IS NULL OR tenant_id = _tenant_id)
    ),
    'ferramentas', (
      SELECT jsonb_agg(jsonb_build_object(
        'nome', tool_name,
        'sucessos', sucessos,
        'falhas', falhas
      ))
      FROM (
        SELECT tool_name,
          count(*) FILTER (WHERE status = 'sucesso') AS sucessos,
          count(*) FILTER (WHERE status <> 'sucesso') AS falhas
        FROM public.invocacoes_ferramenta
        WHERE criado_em >= now() - (_dias || ' days')::interval
          AND (_tenant_id IS NULL OR tenant_id = _tenant_id)
        GROUP BY tool_name ORDER BY count(*) DESC LIMIT 20
      ) t
    ),
    'saude_filas', (SELECT jsonb_agg(to_jsonb(s)) FROM public.fn_saude_motor() s)
  ) INTO _resultado;
  RETURN _resultado;
END;
$$;


ALTER FUNCTION public.rpc_metricas_motor(_tenant_id uuid, _dias integer) OWNER TO postgres;

