--
-- Name: sincronizar_config_cronjob(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sincronizar_config_cronjob() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'cron', 'vault', 'extensions'
    AS $_$
DECLARE
  v_url text;
  v_jobid bigint;
BEGIN
  -- Caso 1: desativando → UNSCHEDULE
  IF NEW.ativo = false AND NEW.jobid_pg_cron IS NOT NULL THEN
    BEGIN
      PERFORM cron.unschedule(NEW.jobid_pg_cron::int);
    EXCEPTION WHEN OTHERS THEN
      NULL;
    END;
    NEW.jobid_pg_cron := NULL;
    NEW.atualizado_em := now();
    RETURN NEW;
  END IF;

  -- Caso 2: modo semantico → não cria cron.job · trigger separado processa
  IF NEW.modo = 'semantico' THEN
    IF NEW.jobid_pg_cron IS NOT NULL THEN
      BEGIN
        PERFORM cron.unschedule(NEW.jobid_pg_cron::int);
      EXCEPTION WHEN OTHERS THEN
        NULL;
      END;
      NEW.jobid_pg_cron := NULL;
    END IF;
    NEW.atualizado_em := now();
    RETURN NEW;
  END IF;

  -- Caso 3: modo horario + ativo + edge_function → UPSERT cron.job via net.http_post
  IF NEW.modo = 'horario' AND NEW.ativo = true AND NEW.cron_expr IS NOT NULL AND NEW.edge_function IS NOT NULL THEN
    v_url := 'https://pdamarjxcmkzbhqxtapl.supabase.co/functions/v1/' || NEW.edge_function;

    -- Se já tinha jobid → UNSCHEDULE primeiro (reagendar com novo cron_expr)
    IF NEW.jobid_pg_cron IS NOT NULL THEN
      BEGIN
        PERFORM cron.unschedule(NEW.jobid_pg_cron::int);
      EXCEPTION WHEN OTHERS THEN
        NULL;
      END;
    END IF;

    -- Schedule novo invocando edge fn via net.http_post
    SELECT cron.schedule(
      NEW.nome,
      NEW.cron_expr,
      format(
        $cron$
        SELECT net.http_post(
          url := %L,
          headers := jsonb_build_object(
            'Content-Type', 'application/json',
            'Authorization', 'Bearer ' || (SELECT decrypted_secret FROM vault.decrypted_secrets WHERE name = 'service_role_key' LIMIT 1)
          ),
          body := %L::jsonb
        ) AS request_id;
        $cron$,
        v_url,
        coalesce(NEW.parametros::text, '{}')
      )
    ) INTO v_jobid;

    NEW.jobid_pg_cron := v_jobid::int;
  END IF;

  -- Caso 4: modo horario + ativo + sql_inline → schedule SQL direto
  IF NEW.modo = 'horario' AND NEW.ativo = true AND NEW.cron_expr IS NOT NULL AND NEW.sql_inline IS NOT NULL AND NEW.edge_function IS NULL THEN
    IF NEW.jobid_pg_cron IS NOT NULL THEN
      BEGIN
        PERFORM cron.unschedule(NEW.jobid_pg_cron::int);
      EXCEPTION WHEN OTHERS THEN
        NULL;
      END;
    END IF;

    SELECT cron.schedule(
      NEW.nome,
      NEW.cron_expr,
      NEW.sql_inline
    ) INTO v_jobid;

    NEW.jobid_pg_cron := v_jobid::int;
  END IF;

  NEW.atualizado_em := now();
  RETURN NEW;
END;
$_$;


ALTER FUNCTION public.sincronizar_config_cronjob() OWNER TO postgres;

--
-- Name: sincronizar_config_cronjob_excluir(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sincronizar_config_cronjob_excluir() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'cron'
    AS $$
BEGIN
  IF OLD.jobid_pg_cron IS NOT NULL THEN
    BEGIN
      PERFORM cron.unschedule(OLD.jobid_pg_cron::int);
    EXCEPTION WHEN OTHERS THEN
      NULL;
    END;
  END IF;
  RETURN OLD;
END;
$$;


ALTER FUNCTION public.sincronizar_config_cronjob_excluir() OWNER TO postgres;

--
-- Name: sincronizar_fase_pipeline_de_ficha_lead(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sincronizar_fase_pipeline_de_ficha_lead() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_lead_id uuid;
  v_new_stage text;
BEGIN
  IF OLD.fase IS NOT DISTINCT FROM NEW.fase THEN
    RETURN NEW;
  END IF;

  SELECT lead_id INTO v_lead_id
  FROM public.conversas
  WHERE id = NEW.conversation_id
  LIMIT 1;

  IF v_lead_id IS NULL THEN
    RETURN NEW;
  END IF;

  CASE NEW.fase
    WHEN 'saudacao' THEN v_new_stage := 'novo';
    WHEN 'qualificacao' THEN v_new_stage := 'qualificando';
    WHEN 'apresentacao' THEN v_new_stage := 'apresentando';
    WHEN 'negociacao' THEN v_new_stage := 'negociando';
    WHEN 'fechado' THEN v_new_stage := NULL;
    ELSE v_new_stage := NULL;
  END CASE;

  IF v_new_stage IS NOT NULL THEN
    UPDATE public.leads
    SET fase_pipeline = v_new_stage
    WHERE id = v_lead_id;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.sincronizar_fase_pipeline_de_ficha_lead() OWNER TO postgres;

--
-- Name: sincronizar_fichas_lead_ao_assinar_contrato(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sincronizar_fichas_lead_ao_assinar_contrato() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF NEW.assinado_em IS NOT NULL
     AND (OLD.assinado_em IS NULL OR OLD.assinado_em IS DISTINCT FROM NEW.assinado_em)
     AND NEW.conversa_id IS NOT NULL
  THEN
    UPDATE public.fichas_lead
    SET dados_capturados = jsonb_set(
          COALESCE(dados_capturados, '{}'::jsonb),
          '{contrato_assinado}',
          '"sim"'::jsonb,
          true
        ),
        updated_at = now()
    WHERE conversation_id = NEW.conversa_id;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.sincronizar_fichas_lead_ao_assinar_contrato() OWNER TO postgres;

--
-- Name: sincronizar_foto_preco_template(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sincronizar_foto_preco_template() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_p RECORD;
BEGIN
  IF NEW.produto_id IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT p.preco_centavos, p.entrada_centavos, p.max_parcelas, p.valor_parcela_cravado_centavos
    INTO v_p
  FROM public.produtos p
  WHERE p.id = NEW.produto_id AND COALESCE(p.preco_centavos, 0) > 0;

  IF NOT FOUND THEN
    RETURN NEW; -- produto sem preço cravado: foto do template continua valendo
  END IF;

  NEW.valor_a_vista := round(v_p.preco_centavos::numeric / 100, 2);

  IF COALESCE(v_p.max_parcelas, 0) > 0 AND COALESCE(v_p.valor_parcela_cravado_centavos, 0) > 0 THEN
    NEW.opcoes_parcelamento := jsonb_build_array(jsonb_build_object(
      'parcelas',      v_p.max_parcelas,
      'entrada',       round(COALESCE(v_p.entrada_centavos, 0)::numeric / 100, 2),
      'valor_parcela', round(v_p.valor_parcela_cravado_centavos::numeric / 100, 2),
      'valor_total',   round((COALESCE(v_p.entrada_centavos, 0)
                        + v_p.max_parcelas * v_p.valor_parcela_cravado_centavos)::numeric / 100, 2)
    ));
  END IF;

  -- Construtor coerente: elementos de produtos_aceitos do mesmo produto
  -- ganham o preço vivo também.
  IF NEW.produtos_aceitos IS NOT NULL AND jsonb_typeof(NEW.produtos_aceitos) = 'array' THEN
    SELECT jsonb_agg(
      CASE WHEN (e ->> 'produto_id') = NEW.produto_id::text THEN
        e || jsonb_build_object(
          'preco_avista', round(v_p.preco_centavos::numeric / 100, 2),
          'preco_pendente', false,
          'parcelamento', jsonb_build_object(
            'entrada',               round(COALESCE(v_p.entrada_centavos, 0)::numeric / 100, 2),
            'max_parcelas',          COALESCE(v_p.max_parcelas, 0),
            'total_parcelado',       0,
            'valor_parcelado_total', round((COALESCE(v_p.entrada_centavos, 0)
                                      + COALESCE(v_p.max_parcelas, 0) * COALESCE(v_p.valor_parcela_cravado_centavos, 0))::numeric / 100, 2)
          )
        )
      ELSE e END
      ORDER BY ord)
      INTO NEW.produtos_aceitos
    FROM jsonb_array_elements(NEW.produtos_aceitos) WITH ORDINALITY AS t(e, ord);
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.sincronizar_foto_preco_template() OWNER TO postgres;

--
-- Name: sincronizar_numeros_fixos_rifa(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sincronizar_numeros_fixos_rifa(p_rifa uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid uuid := (select auth.uid());
  v_r public.rifas%rowtype;
  v_min integer;
  v_max integer;
  v_pessoa record;
  v_pedido_id uuid;
  v_reservados integer := 0;
  v_liberados integer := 0;
  v_nums integer[];
begin
  -- Tranca de identidade (2026-09-08): não pode viver só no GRANT.
  PERFORM public.tenant_efetivo();
  select * into v_r from public.rifas
  where id = p_rifa and deleted_at is null
    and (v_uid is null or tenant_id = v_uid);
  if not found then
    return jsonb_build_object('ok', false, 'erro', 'rifa_nao_encontrada');
  end if;
  if v_r.status not in ('ativa') then
    return jsonb_build_object('ok', true, 'obs', 'rifa_nao_ativa_nada_a_fazer');
  end if;

  v_min := case when v_r.numeracao_desde_zero then 0 else 1 end;
  v_max := v_min + v_r.total_numeros - 1;

  with alvo as (
    select nr.id, nr.pedido_id
    from public.numeros_rifa nr
    join public.pedidos_rifa p on p.id = nr.pedido_id
    where nr.rifa_id = v_r.id
      and nr.status = 'reservado'
      and p.origem = 'manual' and p.expira_em is null
      and not exists (
        select 1 from public.rifa_numeros_fixos f
        where f.tenant_id = v_r.tenant_id
          and f.metodo_sorteio = v_r.metodo_sorteio
          and f.numero = nr.numero
          and f.status = 'ativo'
      )
  ), del as (
    delete from public.numeros_rifa nr using alvo
    where nr.id = alvo.id
    returning nr.pedido_id
  )
  select count(*) into v_liberados from del;

  for v_pessoa in
    select coalesce(f.phone, '') as phone, f.nome,
           array_agg(f.numero order by f.numero) as numeros
    from public.rifa_numeros_fixos f
    where f.tenant_id = v_r.tenant_id
      and f.metodo_sorteio = v_r.metodo_sorteio
      and f.status = 'ativo'
      and f.numero between v_min and v_max
      and not exists (
        select 1 from public.numeros_rifa nr
        where nr.rifa_id = v_r.id and nr.numero = f.numero
      )
    group by coalesce(f.phone, ''), f.nome
  loop
    insert into public.pedidos_rifa (
      rifa_id, tenant_id, nome, phone, origem,
      qtd_numeros, numeros, valor_centavos, status, expira_em
    ) values (
      v_r.id, v_r.tenant_id, v_pessoa.nome, nullif(v_pessoa.phone, ''), 'manual',
      array_length(v_pessoa.numeros, 1), '{}',
      array_length(v_pessoa.numeros, 1) * v_r.preco_numero_centavos,
      'reservado', null
    ) returning id into v_pedido_id;

    insert into public.numeros_rifa (rifa_id, tenant_id, pedido_id, numero, status)
    select v_r.id, v_r.tenant_id, v_pedido_id, n, 'reservado'
    from unnest(v_pessoa.numeros) n
    on conflict (rifa_id, numero) do nothing;

    select array_agg(numero order by numero) into v_nums
    from public.numeros_rifa where pedido_id = v_pedido_id;

    update public.pedidos_rifa
    set numeros = coalesce(v_nums, '{}'),
        qtd_numeros = coalesce(array_length(v_nums, 1), 0),
        valor_centavos = coalesce(array_length(v_nums, 1), 0) * v_r.preco_numero_centavos,
        updated_at = now()
    where id = v_pedido_id;

    v_reservados := v_reservados + coalesce(array_length(v_nums, 1), 0);
  end loop;

  return jsonb_build_object('ok', true, 'reservados', v_reservados, 'liberados', v_liberados);
end;
$$;


ALTER FUNCTION public.sincronizar_numeros_fixos_rifa(p_rifa uuid) OWNER TO postgres;

--
-- Name: sincronizar_status_conversa_de_lead_campanha(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sincronizar_status_conversa_de_lead_campanha() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_lead_id uuid; v_has_ativo boolean;
BEGIN
  v_lead_id := COALESCE(NEW.lead_id, OLD.lead_id);
  IF v_lead_id IS NULL THEN RETURN COALESCE(NEW, OLD); END IF;
  SELECT EXISTS (SELECT 1 FROM public.leads_campanha WHERE lead_id = v_lead_id AND state = 'ativo') INTO v_has_ativo;
  IF v_has_ativo THEN
    UPDATE public.conversas SET status = 'campaign', agent_enabled = false
    WHERE lead_id = v_lead_id AND status NOT IN ('campaign','closed','encerrada');
  ELSE
    UPDATE public.conversas SET status = 'ativa', agent_enabled = true
    WHERE lead_id = v_lead_id AND status = 'campaign';
  END IF;
  RETURN COALESCE(NEW, OLD);
END;
$$;


ALTER FUNCTION public.sincronizar_status_conversa_de_lead_campanha() OWNER TO postgres;

--
-- Name: sincronizar_tags_lead_de_dados_capturados(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sincronizar_tags_lead_de_dados_capturados() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
  v_lead_id   uuid;
  v_tenant_id uuid;
  v_tags_manuais text[];
  v_tags_sync    text[] := '{}';
  v_key   text;
  v_value text;
  v_tag   text;
  v_chave_canon text;
  v_valor_canon text;
  v_pii_keys text[] := ARRAY[
    'nome', 'nome_cliente', 'nome_lead', 'nome_completo',
    'cpf', 'rg',
    'email', 'contrato_email',
    'telefone', 'contrato_telefone',
    'contrato_token', 'contrato_nome', 'contrato_cpf',
    'contrato_endereco', 'contrato_data_assinatura',
    'agendamento_callback_at', 'agendamento_callback_motivo'
  ];
BEGIN
  IF TG_OP = 'UPDATE' AND OLD.dados_capturados IS NOT DISTINCT FROM NEW.dados_capturados THEN
    RETURN NEW;
  END IF;

  SELECT c.lead_id, l.tenant_id
  INTO v_lead_id, v_tenant_id
  FROM public.conversas c
  JOIN public.leads l ON l.id = c.lead_id
  WHERE c.id = NEW.conversation_id
  LIMIT 1;

  IF v_lead_id IS NULL THEN
    RETURN NEW;
  END IF;

  -- Tags manuais: sem chave:valor e sem has_ prefix (preservar intactas)
  SELECT COALESCE(
    array_agg(t) FILTER (WHERE t NOT LIKE '%:%' AND t NOT LIKE 'has\_%' ESCAPE '\'),
    '{}'
  )
  INTO v_tags_manuais
  FROM unnest(COALESCE((SELECT tags FROM public.leads WHERE id = v_lead_id), '{}')) AS t;

  FOR v_key, v_value IN
    SELECT key, value::text
    FROM jsonb_each_text(COALESCE(NEW.dados_capturados, '{}'::jsonb))
  LOOP
    CONTINUE WHEN v_key LIKE '\_%' ESCAPE '\';
    CONTINUE WHEN v_key = ANY(v_pii_keys);
    CONTINUE WHEN v_value IS NULL OR v_value = '' OR v_value IN ('null', 'undefined', 'none', 'nao_capturado');
    CONTINUE WHEN length(v_value) > 40;

    v_value := lower(regexp_replace(v_value, '[^a-zA-Z0-9áéíóúâêôãõç]+', '_', 'g'));
    v_value := regexp_replace(v_value, '^_+|_+$', '', 'g');
    CONTINUE WHEN v_value = '';

    -- Fase 3: alias lookup → chave + valor canônicos
    -- Tenta match exato "chave:valor" primeiro; fallback em "chave" sem valor.
    v_chave_canon := NULL;
    v_valor_canon := NULL;
    SELECT tva.chave_canonica, tva.valor_canonico
    INTO v_chave_canon, v_valor_canon
    FROM public.alias_vocabulario_tag tva
    WHERE tva.alias IN (v_key || ':' || v_value, v_key)
      AND (
        tva.escopo = 'plataforma'
        OR (tva.escopo = 'nicho' AND tva.nicho_id IS NOT NULL)
        OR (tva.escopo = 'tenant' AND tva.tenant_id = v_tenant_id)
      )
    ORDER BY
      -- preferência: match exato chave:valor > só chave; tenant > nicho > plataforma
      (tva.alias = v_key || ':' || v_value) DESC,
      CASE tva.escopo WHEN 'tenant' THEN 0 WHEN 'nicho' THEN 1 ELSE 2 END
    LIMIT 1;

    IF v_chave_canon IS NOT NULL THEN
      v_key   := v_chave_canon;
      v_value := v_valor_canon;
    END IF;

    IF v_value IN ('sim', 'true', '1') THEN
      v_tag := 'has_' || v_key;
    ELSE
      v_tag := v_key || ':' || v_value;
    END IF;

    IF NOT (v_tag = ANY(v_tags_sync)) THEN
      v_tags_sync := array_append(v_tags_sync, v_tag);
    END IF;
  END LOOP;

  UPDATE public.leads
  SET tags = (
    SELECT COALESCE(array_agg(DISTINCT t), '{}')
    FROM unnest(COALESCE(v_tags_manuais, '{}') || v_tags_sync) AS t
  )
  WHERE id = v_lead_id;

  -- Fase 3: aciona cofre PII somente se alguma tag nova contém sequência de dígitos
  -- (11 ou 14 dígitos = possível CPF/CNPJ injetado via Gemma antes do mascaramento)
  IF EXISTS (
    SELECT 1 FROM unnest(v_tags_sync) AS t
    WHERE t ~ '\d{11}|\d{14}'
  ) THEN
    PERFORM public.extrair_pii_lead(v_lead_id);
  END IF;

  RETURN NEW;
END;
$_$;


ALTER FUNCTION public.sincronizar_tags_lead_de_dados_capturados() OWNER TO postgres;

--
-- Name: FUNCTION sincronizar_tags_lead_de_dados_capturados(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.sincronizar_tags_lead_de_dados_capturados() IS 'Sync leads.tags a partir de lead_cards.dados_capturados. PII (nome/cpf/email/etc) bloqueada — vai pra ficha, não vira tag.';


--
-- Name: sincronizar_template_contrato_para_rag(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sincronizar_template_contrato_para_rag(p_contrato_id uuid) RETURNS TABLE(chunks_inseridos integer, chunks_atualizados integer, chunks_total integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_contrato record;
  v_agent_id uuid;
  v_conteudo text;
  v_partes text[];
  v_parte text;
  v_title text;
  v_inserted int := 0;
  v_updated int := 0;
  v_num int;
  v_prefix text;
BEGIN
  SELECT ct.id, ct.nome, ct.conteudo, ct.produto_id, ct.user_id, p.nome AS produto_nome
  INTO v_contrato
  FROM public.contratos_template ct
  LEFT JOIN public.produtos p ON p.id = ct.produto_id
  WHERE ct.id = p_contrato_id AND ct.ativo = true;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Contrato nao encontrado ou inativo: %', p_contrato_id;
  END IF;

  SELECT ua.id INTO v_agent_id
  FROM public.agentes_usuario ua
  WHERE ua.user_id = v_contrato.user_id
  LIMIT 1;

  IF v_agent_id IS NULL THEN
    RAISE EXCEPTION 'Tenant sem agente: %', v_contrato.user_id;
  END IF;

  v_conteudo := COALESCE(v_contrato.conteudo, '');
  IF v_conteudo = '' THEN
    RAISE EXCEPTION 'Contrato sem conteudo: %', p_contrato_id;
  END IF;

  v_conteudo := regexp_replace(v_conteudo, '\[NOME_COMPLETO\]|\[NOME\]|\{NOME\}', '[NOME DO CLIENTE]', 'gi');
  v_conteudo := regexp_replace(v_conteudo, '\[CPF\]|\{CPF\}', '[CPF DO CLIENTE]', 'gi');
  v_conteudo := regexp_replace(v_conteudo, '\[EMAIL\]|\{EMAIL\}', '[EMAIL DO CLIENTE]', 'gi');
  v_conteudo := regexp_replace(v_conteudo, '\[TELEFONE\]|\{TELEFONE\}', '[TELEFONE DO CLIENTE]', 'gi');
  v_conteudo := regexp_replace(v_conteudo, '\[RG\]|\{RG\}', '[RG DO CLIENTE]', 'gi');
  v_conteudo := regexp_replace(v_conteudo, '\[CEP\]|\{CEP\}', '[CEP DO CLIENTE]', 'gi');
  v_conteudo := regexp_replace(v_conteudo, '\{NOME_EMPRESA\}|\[NOME_EMPRESA\]', '[EMPRESA]', 'gi');
  v_conteudo := regexp_replace(v_conteudo, '\{CNPJ\}|\[CNPJ\]', '[CNPJ DA EMPRESA]', 'gi');

  v_prefix := COALESCE(v_contrato.produto_nome, 'contrato') || ' — ';

  v_partes := regexp_split_to_array(
    v_conteudo,
    '(?=CLÁUSULA\s+\d+|CLAUSULA\s+\d+|Cláusula\s+\d+|Clausula\s+\d+)'
  );

  IF array_length(v_partes, 1) < 2 THEN
    v_partes := regexp_split_to_array(v_conteudo, '\n\s*\n');
  END IF;

  v_num := 0;
  FOREACH v_parte IN ARRAY v_partes LOOP
    v_parte := btrim(v_parte);
    IF length(v_parte) < 40 OR length(v_parte) > 2000 THEN
      CONTINUE;
    END IF;

    v_num := v_num + 1;

    v_title := v_prefix || substring(split_part(v_parte, E'\n', 1) FROM 1 FOR 100);

    INSERT INTO public.blocos_conhecimento
      (agente_id, title, content, category, tags, tipo, escopo, ativo)
    VALUES (
      v_agent_id,
      v_title,
      v_parte,
      'contrato',
      ARRAY['contrato', 'clausula', COALESCE(v_contrato.produto_nome, 'geral')],
      'clausula_contrato',
      'tenant',
      true
    )
    ON CONFLICT DO NOTHING;

    IF FOUND THEN
      v_inserted := v_inserted + 1;
    ELSE
      UPDATE public.blocos_conhecimento
      SET content = v_parte,
          tags = ARRAY['contrato', 'clausula', COALESCE(v_contrato.produto_nome, 'geral')]
      WHERE agente_id = v_agent_id AND title = v_title;
      IF FOUND THEN v_updated := v_updated + 1; END IF;
    END IF;
  END LOOP;

  chunks_inseridos := v_inserted;
  chunks_atualizados := v_updated;
  chunks_total := v_num;
  RETURN NEXT;
END;
$$;


ALTER FUNCTION public.sincronizar_template_contrato_para_rag(p_contrato_id uuid) OWNER TO postgres;

--
-- Name: sincronizar_user_role(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sincronizar_user_role() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF NEW.system_role = 'platform_admin' THEN
    INSERT INTO public.user_roles (user_id, role) VALUES (NEW.id, 'admin')
    ON CONFLICT (user_id, role) DO NOTHING;
  ELSE
    DELETE FROM public.user_roles WHERE user_id = NEW.id AND role = 'admin';
    INSERT INTO public.user_roles (user_id, role) VALUES (NEW.id, 'user')
    ON CONFLICT (user_id, role) DO NOTHING;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.sincronizar_user_role() OWNER TO postgres;

--
-- Name: slots_disponiveis(uuid, date, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.slots_disponiveis(p_tenant_id uuid, p_dia date, p_pessoa_id uuid DEFAULT NULL::uuid) RETURNS TABLE(slot_inicio timestamp with time zone, pessoa_id uuid)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_weekday   integer := EXTRACT(DOW FROM p_dia)::integer;
  v_timezone  text    := 'America/Sao_Paulo';
  v_disp      record;
  v_slot      timestamptz;
  v_slot_fim  timestamptz;
  v_fim_janela timestamptz;
  v_busy      boolean;
BEGIN
  FOR v_disp IN
    SELECT d.id, d.pessoa_id, d.hora_inicio, d.hora_fim,
           d.duracao_slot_min, d.buffer_min
    FROM   public.disponibilidade d
    WHERE  d.tenant_id = p_tenant_id
      AND  d.weekday   = v_weekday
      AND  d.ativo     = true
      AND  (p_pessoa_id IS NULL OR d.pessoa_id = p_pessoa_id)
  LOOP
    v_slot       := (p_dia || ' ' || v_disp.hora_inicio)::timestamp AT TIME ZONE v_timezone;
    v_fim_janela := (p_dia || ' ' || v_disp.hora_fim)::timestamp   AT TIME ZONE v_timezone;

    LOOP
      v_slot_fim := v_slot + (v_disp.duracao_slot_min || ' minutes')::interval;

      EXIT WHEN v_slot_fim > v_fim_janela;

      -- verificar conflito com compromissos existentes
      SELECT EXISTS (
        SELECT 1
        FROM   public.compromissos c
        WHERE  c.tenant_id  = p_tenant_id
          AND  c.status     = 'pendente'
          AND  (p_pessoa_id IS NULL OR c.pessoa_responsavel_id = v_disp.pessoa_id)
          AND  c.scheduled_at >= v_slot
          AND  c.scheduled_at <  v_slot_fim
      ) INTO v_busy;

      IF NOT v_busy THEN
        slot_inicio := v_slot;
        pessoa_id   := v_disp.pessoa_id;
        RETURN NEXT;
      END IF;

      v_slot := v_slot_fim + (v_disp.buffer_min || ' minutes')::interval;
    END LOOP;
  END LOOP;
END;
$$;


ALTER FUNCTION public.slots_disponiveis(p_tenant_id uuid, p_dia date, p_pessoa_id uuid) OWNER TO postgres;

--
-- Name: solicitar_exclusao_conta(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.solicitar_exclusao_conta() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_uid uuid := (SELECT auth.uid());
BEGIN
  UPDATE public.profiles 
  SET deletion_requested_at = now()
  WHERE id = v_uid;
  
  INSERT INTO public.activity_logs (user_id, action, entity_type, metadata)
  VALUES (v_uid, 'request_deletion', 'profile', '{"type":"lgpd_deletion_request"}'::jsonb);
END;
$$;


ALTER FUNCTION public.solicitar_exclusao_conta() OWNER TO postgres;

--
-- Name: solicitar_saque(numeric, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.solicitar_saque(p_valor numeric, p_chave_pix text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_saldo numeric;
  v_saque_id uuid;
BEGIN
  IF p_valor <= 0 THEN
    RAISE EXCEPTION 'Valor do saque deve ser positivo';
  END IF;

  SELECT saldo_multinivel INTO v_saldo
  FROM profiles
  WHERE id = auth.uid()
  FOR UPDATE;

  IF v_saldo IS NULL OR v_saldo < p_valor THEN
    RAISE EXCEPTION 'Saldo insuficiente';
  END IF;

  UPDATE profiles
  SET saldo_multinivel = saldo_multinivel - p_valor
  WHERE id = auth.uid();

  INSERT INTO multinivel_saques (user_id, valor, chave_pix, status)
  VALUES (auth.uid(), p_valor, p_chave_pix, 'pendente')
  RETURNING id INTO v_saque_id;

  RETURN v_saque_id;
END;
$$;


ALTER FUNCTION public.solicitar_saque(p_valor numeric, p_chave_pix text) OWNER TO postgres;

--
-- Name: sortear_rifa(uuid, integer, integer[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sortear_rifa(p_rifa uuid, p_numero_manual integer DEFAULT NULL::integer, p_numeros_manuais integer[] DEFAULT NULL::integer[]) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
