$$;


ALTER FUNCTION public.sortear_rifa(p_rifa uuid, p_numero_manual integer, p_numeros_manuais integer[]) OWNER TO postgres;

--
-- Name: submeter_consulta_publica(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.submeter_consulta_publica(p_token uuid, p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_id uuid;
  v_status text;
  v_origem text;
  v_tenant uuid;
  v_tipo_id uuid;
  v_doc_tipo text;
  v_tipo_resolvido uuid;
  v_preco numeric(10,2);
BEGIN
  SELECT id, status, origem, tenant_id, tipo_id
    INTO v_id, v_status, v_origem, v_tenant, v_tipo_id
  FROM public.consultas
  WHERE chave_publica = p_token AND deleted_at IS NULL
  FOR UPDATE;

  IF v_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'erro', 'consulta_nao_encontrada');
  END IF;
  IF v_origem <> 'link' THEN
    RETURN jsonb_build_object('ok', false, 'erro', 'consulta_nao_e_link');
  END IF;
  IF v_status IN ('consultando', 'concluida') THEN
    RETURN jsonb_build_object('ok', false, 'erro', 'consulta_ja_processada');
  END IF;

  v_doc_tipo := p_payload->>'tipo_doc';

  -- Link universal: resolve o tipo pelo documento (só se ainda não fixado).
  IF v_tipo_id IS NULL AND v_doc_tipo IS NOT NULL THEN
    SELECT id INTO v_tipo_resolvido
    FROM public.consultas_tipos
    WHERE ativo AND deleted_at IS NULL
      AND (tipo_doc = v_doc_tipo OR tipo_doc = 'ambos')
    ORDER BY (tipo_doc = v_doc_tipo) DESC, ordem ASC
    LIMIT 1;
  END IF;

  -- Preço cobrado: pelo tipo de documento (config do tenant), fallback no preço único legado.
  IF v_doc_tipo = 'cpf' THEN
    SELECT COALESCE(preco_venda_cpf, preco_venda_padrao) INTO v_preco
    FROM public.consultas_config_tenant WHERE tenant_id = v_tenant;
  ELSIF v_doc_tipo = 'cnpj' THEN
    SELECT COALESCE(preco_venda_cnpj, preco_venda_padrao) INTO v_preco
    FROM public.consultas_config_tenant WHERE tenant_id = v_tenant;
  END IF;

  UPDATE public.consultas SET
    documento = COALESCE(p_payload->>'documento', documento),
    tipo_doc = COALESCE(p_payload->>'tipo_doc', tipo_doc),
    tipo_id = COALESCE(tipo_id, v_tipo_resolvido),
    preco = COALESCE(preco, v_preco),
    dados_cliente = COALESCE(p_payload->'dados_cliente', dados_cliente),
    url_selfie = COALESCE(p_payload->>'url_selfie', url_selfie),
    url_documento = COALESCE(p_payload->>'url_documento', url_documento),
    url_comprovante_pagamento = COALESCE(p_payload->>'url_comprovante', url_comprovante_pagamento),
    status = 'comprovante_enviado'
  WHERE id = v_id;

  RETURN jsonb_build_object('ok', true);
END;
$$;


ALTER FUNCTION public.submeter_consulta_publica(p_token uuid, p_payload jsonb) OWNER TO postgres;

--
-- Name: substituir_caixa_saida_pendentes(uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.substituir_caixa_saida_pendentes(p_conversation_id uuid, p_since timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_count integer;
BEGIN
  UPDATE public.caixa_saida_mensagens SET status = 'substituida', updated_at = now()
  WHERE conversation_id = p_conversation_id
    AND status IN ('pending','pendente')
    AND (p_since IS NULL OR created_at < p_since)
    AND COALESCE(carga->>'inviolavel','') <> 'true';
  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$$;


ALTER FUNCTION public.substituir_caixa_saida_pendentes(p_conversation_id uuid, p_since timestamp with time zone) OWNER TO postgres;

--
-- Name: FUNCTION substituir_caixa_saida_pendentes(p_conversation_id uuid, p_since timestamp with time zone); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.substituir_caixa_saida_pendentes(p_conversation_id uuid, p_since timestamp with time zone) IS 'Marca bolhas pending como superseded quando lead envia nova mensagem (R01.2 Motor Vivo). Chamada pelo edge function chat/index.ts ao detectar nova mensagem do lead. p_since: timestamp da mensagem do lead — cancela apenas bolhas criadas ANTES. NULL = cancela todas as pending da conversa. Retorna count de rows afetadas.';


--
-- Name: tags_disponiveis_base(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.tags_disponiveis_base(p_tenant_id uuid) RETURNS text[]
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_caller uuid := auth.uid();
  v_admin boolean := public.is_platform_admin();
  v_team boolean;
  v_tags text[];
BEGIN
  IF v_caller IS NULL THEN RAISE EXCEPTION 'unauthenticated'; END IF;
  SELECT EXISTS (
    SELECT 1 FROM public.profiles
     WHERE id = v_caller AND parent_user_id = p_tenant_id
  ) INTO v_team;
  IF NOT (p_tenant_id = v_caller OR v_admin OR v_team) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;

  SELECT COALESCE(array_agg(DISTINCT tag ORDER BY tag), ARRAY[]::text[])
    INTO v_tags
  FROM (
    SELECT unnest(tags) AS tag
      FROM public.leads
     WHERE tenant_id = p_tenant_id
       AND deleted_at IS NULL
       AND tags IS NOT NULL
  ) t;
  RETURN v_tags;
END;
$$;


ALTER FUNCTION public.tags_disponiveis_base(p_tenant_id uuid) OWNER TO postgres;

--
-- Name: telefones_equivalentes(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.telefones_equivalentes(p_phone text) RETURNS text[]
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $_$
declare
  v_bruto text := coalesce(p_phone, '');
  v_dig   text := regexp_replace(v_bruto, '\D', '', 'g');
  v_ddd   text;
  v_local text;
  v_out   text[] := ARRAY[]::text[];
begin
  -- Mesma regra de `supabase/functions/_shared/telefone.ts` (variantesTelefone):
  -- número BR com e sem o 9º dígito. O WhatsApp devolve o JID antigo (sem o 9)
  -- para muitos celulares; o app grava com o 9. As duas formas são o MESMO lead.
  if v_bruto <> '' then v_out := array_append(v_out, v_bruto); end if;
  if v_dig <> '' and v_dig <> v_bruto then v_out := array_append(v_out, v_dig); end if;
  if v_dig ~ '^55\d{10}$' then
    v_ddd := substr(v_dig, 3, 2);
    v_local := substr(v_dig, 5);
    if v_local ~ '^[6-9]' then v_out := array_append(v_out, '55' || v_ddd || '9' || v_local); end if;
  elsif v_dig ~ '^55\d{11}$' then
    v_ddd := substr(v_dig, 3, 2);
    v_local := substr(v_dig, 5);
    if v_local ~ '^9[6-9]' then v_out := array_append(v_out, '55' || v_ddd || substr(v_local, 2)); end if;
  end if;
  return v_out;
end;
$_$;


ALTER FUNCTION public.telefones_equivalentes(p_phone text) OWNER TO postgres;

--
-- Name: FUNCTION telefones_equivalentes(p_phone text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.telefones_equivalentes(p_phone text) IS 'Variantes do mesmo telefone BR (com e sem o 9º dígito). Usar em toda busca de conversa/lead por telefone: phone = ANY(telefones_equivalentes(x)). Caso Otmar 2026-09-12.';


