--
-- Name: tenant_efetivo(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.tenant_efetivo(p_tenant_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_uid    uuid := (SELECT auth.uid());
  v_tenant uuid;
BEGIN
  -- A chave pública nunca resolve tenant nenhum.
  IF (SELECT auth.role()) = 'anon' THEN
    RAISE EXCEPTION 'autenticacao obrigatoria' USING ERRCODE = '42501';
  END IF;

  -- Sem usuário no JWT: service_role (edge) ou chamada interna. O tenant é o que veio.
  IF v_uid IS NULL THEN
    RETURN p_tenant_id;
  END IF;

  -- Logado: o tenant é o do JWT. Membro de equipe responde pelo tenant do dono.
  SELECT COALESCE(p.parent_user_id, p.id) INTO v_tenant
  FROM public.profiles p
  WHERE p.id = v_uid;

  v_tenant := COALESCE(v_tenant, v_uid);

  IF p_tenant_id IS NOT NULL AND p_tenant_id IS DISTINCT FROM v_tenant THEN
    RAISE EXCEPTION 'tenant informado nao pertence a quem chama' USING ERRCODE = '42501';
  END IF;

  RETURN v_tenant;
END;
$$;


ALTER FUNCTION public.tenant_efetivo(p_tenant_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION tenant_efetivo(p_tenant_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.tenant_efetivo(p_tenant_id uuid) IS 'Resolve o tenant de quem chama e barra a chave pública. Usar no lugar de COALESCE(auth.uid(), p_tenant_id).';


--
-- Name: tentar_trava_conversa(uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.tentar_trava_conversa(p_conversation_id uuid, p_ttl_seconds integer DEFAULT 30) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  INSERT INTO public.travas_conversa (conversation_id, locked_at, expires_at)
  VALUES (p_conversation_id, now(), now() + (p_ttl_seconds || ' seconds')::interval)
  ON CONFLICT (conversation_id)
  DO UPDATE SET locked_at = now(), expires_at = now() + (p_ttl_seconds || ' seconds')::interval
  WHERE public.travas_conversa.expires_at < now();
  RETURN FOUND;
END;
$$;


ALTER FUNCTION public.tentar_trava_conversa(p_conversation_id uuid, p_ttl_seconds integer) OWNER TO postgres;

