--
-- Name: tg_rifas_limpar_referencias_ao_deletar(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.tg_rifas_limpar_referencias_ao_deletar() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF NEW.deleted_at IS NOT NULL AND OLD.deleted_at IS NULL THEN
    -- Config do tenant: volta pra "automática" (ativa mais recente) em vez
    -- de apontar pra rifa morta.
    UPDATE public.rifas_config_tenant
    SET rifa_disparo_id = NULL, updated_at = now()
    WHERE rifa_disparo_id = NEW.id;

    -- Agendamentos automáticos: desliga (não deleta — histórico/config
    -- preservados) pra ficar visível na UI que precisa de atenção, em vez
    -- de continuar "ativo" sendo pulado pelo cron pra sempre em silêncio.
    UPDATE public.rifa_agendamentos_disparo
    SET ativo = false, atualizado_em = now()
    WHERE rifa_id = NEW.id AND ativo = true;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.tg_rifas_limpar_referencias_ao_deletar() OWNER TO postgres;

--
-- Name: tg_soft_delete_desativa(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.tg_soft_delete_desativa() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  -- Deletado => inativo, sempre. Restaurar (deleted_at = NULL) NÃO reativa automaticamente:
  -- religar é decisão explícita de quem restaura.
  IF NEW.deleted_at IS NOT NULL THEN
    NEW.ativo := false;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.tg_soft_delete_desativa() OWNER TO postgres;

--
-- Name: FUNCTION tg_soft_delete_desativa(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.tg_soft_delete_desativa() IS 'Força ativo=false quando deleted_at é preenchido. Impede bloco soft-deletado de continuar sendo recuperado pelo RAG (as busca_hibrida_* filtram ativo, não deleted_at).';


--
-- Name: tg_tag_candidates_normalizar(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.tg_tag_candidates_normalizar() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  r record;
BEGIN
  IF NEW.tag_text IS NULL OR length(trim(NEW.tag_text)) = 0 THEN
    RETURN NEW;
  END IF;

  SELECT * INTO r FROM public.normalizar_tag(NEW.tag_text, NEW.tenant_id, NEW.nicho_id) LIMIT 1;

  IF FOUND THEN
    NEW.chave_canonica := r.chave_canonica;
    NEW.valor_canonico := r.valor_canonico;
    NEW.vocabulario_id := r.vocabulario_id;
    NEW.normalizado_em := now();
  END IF;

  RETURN NEW;
END;
$$;


