--
-- Name: acao_pausa_blocos; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.acao_pausa_blocos (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    escopo text DEFAULT 'global'::text NOT NULL,
    nicho_id uuid,
    tenant_id uuid,
    gatilho_descricao text NOT NULL,
    gatilho_falas jsonb DEFAULT '[]'::jsonb NOT NULL,
    duracao_min integer DEFAULT 5 NOT NULL,
    mensagem_retorno text NOT NULL,
    ativo boolean DEFAULT true NOT NULL,
    vetor_semantico extensions.halfvec(1024),
    embedding_status text DEFAULT 'pendente'::text NOT NULL,
    vezes_usado integer DEFAULT 0 NOT NULL,
    prioridade integer DEFAULT 0 NOT NULL,
    versao integer DEFAULT 1 NOT NULL,
    criado_em timestamp with time zone DEFAULT now() NOT NULL,
    tipo_campanha text,
    criado_por uuid,
    updated_at timestamp with time zone DEFAULT now(),
    deleted_at timestamp with time zone,
    CONSTRAINT acao_pausa_blocos_embedding_status_check CHECK ((embedding_status = ANY (ARRAY['pendente'::text, 'processando'::text, 'pronto'::text, 'falhou'::text]))),
    CONSTRAINT acao_pausa_chunks_duracao_min_check CHECK (((duracao_min > 0) AND (duracao_min <= 1440))),
    CONSTRAINT acao_pausa_chunks_escopo_check CHECK ((escopo = ANY (ARRAY['global'::text, 'nicho'::text, 'tenant'::text]))),
    CONSTRAINT acao_pausa_escopo_consistente CHECK ((((escopo = 'global'::text) AND (nicho_id IS NULL) AND (tenant_id IS NULL)) OR ((escopo = 'nicho'::text) AND (nicho_id IS NOT NULL) AND (tenant_id IS NULL)) OR ((escopo = 'tenant'::text) AND (tenant_id IS NOT NULL))))
);


ALTER TABLE public.acao_pausa_blocos OWNER TO postgres;

--
-- Name: TABLE acao_pausa_blocos; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.acao_pausa_blocos IS 'Gaveta semântica de pausas genéricas (café · banheiro · checar com equipe). Hybrid search pra LLM emitir tag e handler agendar cron-retomar-agente.';


