CREATE TABLE public.agendamentos_config (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    nome text NOT NULL,
    descricao text,
    categoria text,
    modo text NOT NULL,
    cron_expr text,
    condicao_sql text,
    edge_function text,
    sql_inline text,
    parametros jsonb DEFAULT '{}'::jsonb,
    ativo boolean DEFAULT true NOT NULL,
    ultima_execucao timestamp with time zone,
    proxima_execucao timestamp with time zone,
    jobid_pg_cron integer,
    criado_em timestamp with time zone DEFAULT now() NOT NULL,
    atualizado_em timestamp with time zone,
    criado_por uuid,
    motivo_criacao text,
    CONSTRAINT cronjobs_config_categoria_check CHECK ((categoria = ANY (ARRAY['curadoria'::text, 'agente_runtime'::text, 'analytics'::text, 'meta_criativo'::text, 'campanha'::text, 'manutencao'::text, 'custom'::text]))),
    CONSTRAINT cronjobs_config_modo_check CHECK ((modo = ANY (ARRAY['horario'::text, 'semantico'::text])))
);


ALTER TABLE public.agendamentos_config OWNER TO postgres;

--
-- Name: TABLE agendamentos_config; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.agendamentos_config IS 'Cronjobs editáveis (D55) · ON/OFF + schedule + parâmetros via painel curadoria.
   Modo horario: usa cron_expr clássico. Modo semantico (D9): dispara quando condicao_sql retorna true.
   Sync com pg_cron via trigger UPSERT em cron.job ao salvar.';


