    CONSTRAINT avisos_curadoria_embedding_status_check CHECK ((embedding_status = ANY (ARRAY['pendente'::text, 'pronto'::text, 'falhou'::text]))),
    CONSTRAINT avisos_curadoria_escopo_check CHECK ((escopo = ANY (ARRAY['global'::text, 'nicho'::text, 'tenant'::text]))),
    CONSTRAINT avisos_curadoria_severidade_check CHECK ((severidade = ANY (ARRAY['info'::text, 'atencao'::text, 'critico'::text, 'sugestao'::text]))),
    CONSTRAINT escopo_consistente CHECK ((((escopo = 'global'::text) AND (nicho_id IS NULL) AND (tenant_id IS NULL)) OR ((escopo = 'nicho'::text) AND (nicho_id IS NOT NULL) AND (tenant_id IS NULL)) OR ((escopo = 'tenant'::text) AND (tenant_id IS NOT NULL))))
);


