    CONSTRAINT meta_chunks_no_self_supersede CHECK (((superseded_by IS NULL) OR (superseded_by <> id))),
    CONSTRAINT meta_chunks_objetivo_campanha_check CHECK ((objetivo_campanha = ANY (ARRAY['gerar_curiosidade'::text, 'educar_mercado'::text, 'coletar_lead'::text, 'apresentar_marca'::text, 'reativar_carrinho'::text, 'converter_lead_morno'::text, 'fechamento_direto'::text, 'upsell'::text, 'confirmar_satisfacao'::text, 'pedir_indicacao'::text, 'coletar_depoimento'::text, 'acompanhar_resultado'::text, 'lembrete_amigavel'::text, 'cobranca_firme'::text, 'renegociacao'::text, 'ultima_chance'::text, 'agendar_callback'::text, 'agendar_visita'::text, 'agendar_consulta'::text, 'confirmar_compromisso'::text, 'reagendar'::text]))),
    CONSTRAINT meta_chunks_stability_tier_check CHECK ((stability_tier = ANY (ARRAY['experimental'::text, 'promovido'::text, 'canonico'::text]))),
    CONSTRAINT meta_chunks_tag_check CHECK ((tag = ANY (ARRAY['planejar_turno'::text, 'verificar_saida'::text, 'escolher_ferramenta'::text, 'antecipar_objecao'::text, 'reflexao_runtime'::text]))),
