--
-- Name: blocos_procedurais; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.blocos_procedurais (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    escopo text NOT NULL,
    nicho_id uuid,
    tenant_id uuid,
    nome_procedimento text NOT NULL,
    passos jsonb DEFAULT '[]'::jsonb NOT NULL,
    citacao_kb text,
    imutavel boolean DEFAULT false NOT NULL,
    ativo boolean DEFAULT true NOT NULL,
    prioridade integer DEFAULT 500 NOT NULL,
    vezes_usado integer DEFAULT 0 NOT NULL,
    versao integer DEFAULT 1 NOT NULL,
    vetor_semantico extensions.halfvec(1024),
    embedding_status text DEFAULT 'pendente'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    deleted_at timestamp with time zone,
    cargo_id uuid,
    pacote_origem_id uuid,
    CONSTRAINT blocos_procedurais_embedding_status_check CHECK ((embedding_status = ANY (ARRAY['pendente'::text, 'processando'::text, 'pronto'::text, 'falhou'::text]))),
    CONSTRAINT procedural_chunks_check CHECK ((((escopo = 'global'::text) AND (nicho_id IS NULL) AND (tenant_id IS NULL)) OR ((escopo = 'nicho'::text) AND (nicho_id IS NOT NULL) AND (tenant_id IS NULL)) OR ((escopo = 'tenant'::text) AND (tenant_id IS NOT NULL)))),
    CONSTRAINT procedural_chunks_escopo_check CHECK ((escopo = ANY (ARRAY['global'::text, 'nicho'::text, 'tenant'::text])))
);


ALTER TABLE public.blocos_procedurais OWNER TO postgres;

--
-- Name: TABLE blocos_procedurais; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.blocos_procedurais IS 'CoALA 5ª camada — Procedural memory. Scripts COMO fazer (fechar contrato em 3 passos, recuperar lead frio, etc). passos jsonb array de objetos {ordem, acao, condicao}.';


--
-- Name: blocos_variacao; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.blocos_variacao (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    nome_variation text NOT NULL,
    instrucao text NOT NULL,
    ativo boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    escopo text DEFAULT 'global'::text NOT NULL,
    nicho_id uuid,
    tenant_id uuid,
    vetor_semantico extensions.halfvec(1024),
    embedding_status text DEFAULT 'pendente'::text NOT NULL,
    categoria text,
    subcategoria text,
    prioridade integer DEFAULT 500,
    tipo_campanha text,
    objetivo_campanha text,
    cargo_id uuid,
    deleted_at timestamp with time zone,
    CONSTRAINT blocos_variacao_embedding_status_check CHECK ((embedding_status = ANY (ARRAY['pendente'::text, 'processando'::text, 'pronto'::text, 'falhou'::text]))),
    CONSTRAINT variation_chunks_escopo_check CHECK ((escopo = ANY (ARRAY['global'::text, 'nicho'::text, 'tenant'::text, 'produto'::text]))),
    CONSTRAINT variation_chunks_escopo_consistente CHECK ((((escopo = 'global'::text) AND (nicho_id IS NULL) AND (tenant_id IS NULL)) OR ((escopo = 'nicho'::text) AND (nicho_id IS NOT NULL) AND (tenant_id IS NULL)) OR ((escopo = 'tenant'::text) AND (tenant_id IS NOT NULL)) OR ((escopo = 'produto'::text) AND (tenant_id IS NOT NULL)))),
    CONSTRAINT variation_chunks_objetivo_campanha_check CHECK ((objetivo_campanha = ANY (ARRAY['gerar_curiosidade'::text, 'educar_mercado'::text, 'coletar_lead'::text, 'apresentar_marca'::text, 'reativar_carrinho'::text, 'converter_lead_morno'::text, 'fechamento_direto'::text, 'upsell'::text, 'confirmar_satisfacao'::text, 'pedir_indicacao'::text, 'coletar_depoimento'::text, 'acompanhar_resultado'::text, 'lembrete_amigavel'::text, 'cobranca_firme'::text, 'renegociacao'::text, 'ultima_chance'::text, 'agendar_callback'::text, 'agendar_visita'::text, 'agendar_consulta'::text, 'confirmar_compromisso'::text, 'reagendar'::text]))),
    CONSTRAINT variation_chunks_tipo_campanha_check CHECK ((tipo_campanha = ANY (ARRAY['divulgacao'::text, 'venda'::text, 'pos_venda'::text, 'cobranca'::text, 'agendamento'::text])))
);


ALTER TABLE public.blocos_variacao OWNER TO postgres;

--
-- Name: COLUMN blocos_variacao.objetivo_campanha; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.blocos_variacao.objetivo_campanha IS 'Objetivo específico dentro do tipo de campanha. Cruza com tipo_campanha (D58 brainstorming + insight Theus 2026-04-25).
   21 valores: divulgacao(4) | venda(4) | pos_venda(4) | cobranca(4) | agendamento(5).';


