--
-- Name: campanhas; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.campanhas (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    name text NOT NULL,
    description text DEFAULT ''::text NOT NULL,
    type text NOT NULL,
    objective text NOT NULL,
    product_id uuid,
    status text DEFAULT 'rascunho'::text NOT NULL,
    filters jsonb DEFAULT '{}'::jsonb NOT NULL,
    duration_mode text NOT NULL,
    starts_at timestamp with time zone DEFAULT now() NOT NULL,
    ends_at timestamp with time zone,
    recurrence jsonb,
    throttle_per_day integer,
    throttle_per_hour integer,
    window_start time without time zone DEFAULT '09:00:00'::time without time zone NOT NULL,
    window_end time without time zone DEFAULT '20:00:00'::time without time zone NOT NULL,
    weekdays integer[] DEFAULT '{1,2,3,4,5}'::integer[] NOT NULL,
    skip_holidays boolean DEFAULT true NOT NULL,
    desistance_silence_days integer DEFAULT 7 NOT NULL,
    desistance_phrases text[] DEFAULT ARRAY['não quero'::text, 'chega'::text, 'para'::text, 'pare'::text, 'remova'::text, 'não manda mais'::text] NOT NULL,
    response_actions text[] DEFAULT '{}'::text[] NOT NULL,
    attempt_thresholds jsonb,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    pos_venda_dias_apos_compra integer,
    deleted_at timestamp with time zone,
    ab_test_config jsonb,
    mensagem_inicial text,
    midia_url text,
    tipo_conteudo text DEFAULT 'texto'::text NOT NULL,
    CONSTRAINT campaigns_duration_mode_check CHECK ((duration_mode = ANY (ARRAY['prazo'::text, 'periodica'::text, 'vitalicia'::text]))),
    CONSTRAINT campaigns_pos_venda_dias_apos_compra_check CHECK (((pos_venda_dias_apos_compra IS NULL) OR (pos_venda_dias_apos_compra >= 0))),
    CONSTRAINT campaigns_type_check CHECK ((type = ANY (ARRAY['divulgacao'::text, 'venda'::text, 'pos_venda'::text, 'cobranca'::text, 'agendamento'::text, 'indicacao'::text]))),
    CONSTRAINT campanhas_midia_exige_url_check CHECK (((tipo_conteudo = 'texto'::text) OR (midia_url IS NOT NULL))),
    CONSTRAINT campanhas_status_check CHECK ((status = ANY (ARRAY['rascunho'::text, 'ativa'::text, 'pausada'::text, 'finalizada'::text]))),
    CONSTRAINT campanhas_tipo_conteudo_check CHECK ((tipo_conteudo = ANY (ARRAY['texto'::text, 'foto'::text, 'foto_texto'::text, 'video'::text])))
);


ALTER TABLE public.campanhas OWNER TO postgres;

