    CONSTRAINT channels_max_msg_hour_check CHECK (((max_messages_per_hour_override IS NULL) OR ((max_messages_per_hour_override >= 10) AND (max_messages_per_hour_override <= 800))))
);


ALTER TABLE public.canais OWNER TO postgres;

