--
-- Name: compromissos_ativos; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.compromissos_ativos WITH (security_invoker='true') AS
 SELECT aa.id,
    'retorno'::text AS tipo,
    'iniciativa_do_agente'::text AS origem,
    'acoes_agendadas'::text AS origem_tabela,
    aa.conversation_id AS conversa_id,
    aa.tenant_id,
    aa.lead_id,
    aa.agente_id,
    COALESCE((aa.carga ->> 'titulo'::text), aa.action_type) AS titulo,
    aa.scheduled_at AS executar_em,
    aa.carga,
    aa.status,
    aa.created_at
   FROM public.acoes_agendadas aa
  WHERE ((aa.status = 'pendente'::text) AND (aa.action_type = ANY (ARRAY['agendamento_retorno'::text, 'agendar_retorno'::text, 'retomada_planejada'::text, 'agendar_compromisso'::text, 'agendar_callback'::text, 'cobranca_pagamento'::text, 'cobranca_assinatura'::text])))
UNION ALL
 SELECT cdl.id,
    'reuniao'::text AS tipo,
    'promessa_explicita'::text AS origem,
    'compromissos_do_lead'::text AS origem_tabela,
    cdl.conversa_id,
    c.tenant_id,
    c.lead_id,
    c.agente_id,
    cdl.titulo,
    cdl.quando AS executar_em,
    cdl.carga,
    cdl.status,
    cdl.criado_em AS created_at
   FROM (public.compromissos_do_lead cdl
     JOIN public.conversas c ON ((c.id = cdl.conversa_id)))
  WHERE (cdl.status = 'agendado'::text)
UNION ALL
 SELECT ct.id,
    'contrato'::text AS tipo,
    'promessa_explicita'::text AS origem,
    'contratos'::text AS origem_tabela,
    ct.conversa_id,
    ct.tenant_id,
    ct.lead_id,
    ct.agente_id,
    COALESCE(ct.titulo, 'Contrato pendente'::text) AS titulo,
    ct.created_at AS executar_em,
    jsonb_build_object('chave_publica', ct.chave_publica) AS carga,
    ct.status,
    ct.created_at
   FROM public.contratos ct
  WHERE (ct.status = ANY (ARRAY['emitido'::text, 'enviado'::text, 'assinado_pendente_pagto'::text]));


ALTER VIEW public.compromissos_ativos OWNER TO postgres;

--
-- Name: VIEW compromissos_ativos; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON VIEW public.compromissos_ativos IS 'EMA (Estado do Mundo do Agente). Unifica compromissos pendentes de 3 origens — acoes_agendadas, compromissos_do_lead, contratos. Consumida pelo motor ragentic-processar-inline antes da síntese para injetar bloco <compromissos_ativos_do_lead> no system prompt e impedir re-promessa/re-saudação. Companion (12), 2026-05-12.';


