-- Name: contratos_legacy_en; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.contratos_legacy_en WITH (security_invoker='on') AS
 SELECT id,
    chave_publica,
    conversa_id AS conversation_id,
    lead_id,
    agente_id,
    tenant_id,
    nome_template AS template_name,
    texto_contrato AS contract_text,
    dados_cliente AS client_data,
    status,
    assinado_em AS signed_at,
    ip_assinatura AS signature_ip,
    created_at,
    titulo AS title,
    logo_url,
    descricao_empresa AS company_description,
    campos_obrigatorios AS required_fields,
    dados_signatario AS signer_data,
    url_selfie AS selfie_url,
    url_documento AS document_url,
    hash_contrato AS contract_hash,
    cor_pagina AS page_color,
    nome_empresa AS company_name,
    url_assinatura AS signature_url,
    instrucao_selfie AS selfie_instruction,
    dados_testemunha AS witness_data,
    url_selfie_testemunha AS witness_selfie_url,
    url_documento_testemunha AS witness_document_url,
    url_assinatura_testemunha AS witness_signature_url,
    testemunha_assinada_em AS witness_signed_at,
    ip_testemunha AS witness_ip,
    num_testemunhas,
    campos_cliente AS client_fields,
    opcoes_pagamento AS payment_options,
    metodo_pagamento AS payment_method,
    detalhes_pagamento AS payment_details,
    posicao_pagamento AS payment_position,
    chave_pix AS pix_key,
    link_parcelamento AS installment_link,
    url_comprovante_pagamento AS payment_proof_url,
    origem,
    pdf_url
   FROM public.contratos;


