--
-- Name: prancheta; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.prancheta (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    conversation_id uuid NOT NULL,
    tenant_id uuid NOT NULL,
    belief jsonb DEFAULT '{}'::jsonb NOT NULL,
    resumo_agente text,
    belief_historico jsonb DEFAULT '[]'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    proxima_intencao jsonb DEFAULT '{}'::jsonb,
    proximo_passo_previsto text,
    estilo_lead text,
    origem_planejamento text
);

ALTER TABLE ONLY public.prancheta REPLICA IDENTITY FULL;


ALTER TABLE public.prancheta OWNER TO postgres;

--
-- Name: TABLE prancheta; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.prancheta IS 'Prancheta de raciocínio do agente (renomeado de crenca_conversa na Onda 7). View public.crenca_conversa mantém compat até remoção do código legado.';


--
-- Name: COLUMN prancheta.tenant_id; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.prancheta.tenant_id IS 'Desnormalizado de conversations.tenant_id para RLS eficiente. Evita JOIN com conversations a cada leitura — UNIQUE index em conversation_id torna leitura <1ms.';


--
-- Name: COLUMN prancheta.belief; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.prancheta.belief IS 'JSONB estruturado — contrato: {  "sintoma_observado": "string — o que o lead expressou",  "causa_inferida": "string — o que o lead provavelmente quis dizer",  "confianca": 0.7,  "objecao_detectada": "string|null",  "proxima_intencao": "string — o que o agente pretende fazer",  "compromissos": [    {"tipo": "preco_dito", "valor": "R$ 997 à vista", "turno": 3, "timestamp": "2026-04-20T10:00:00Z"},    {"tipo": "prazo_dito", "valor": "15 a 45 dias úteis", "turno": 3, "timestamp": "..."}  ]}. compromissos[] é o auto-log do agente: registra o que ele disse/fez neste turno (preço citado, prazo dito, garantia mencionada). Máximo recomendado: últimos 10 compromissos. Escrito por post-llm.ts após cada turno via UPSERT ON CONFLICT DO UPDATE.';


--
-- Name: COLUMN prancheta.resumo_agente; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.prancheta.resumo_agente IS 'Narrativa em pt-BR em 1ª pessoa do agente sobre o que fez nesta conversa. Exemplo: "Cumprimentei o lead, apresentei o Limpa Nome, disse garantia 6 meses e preço R$ 997 à vista. Aguardo decisão." Destinado ao vendedor na FichaPensamentoAgente.tsx. Escrito pelo LLM, não derivado de compromissos[].';


--
-- Name: COLUMN prancheta.belief_historico; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.prancheta.belief_historico IS 'Array rolling de até 5 snapshots do belief. Cada snapshot: {"turno": N, "belief": {...}, "ts": "ISO8601"}. Ao gravar o turno 6, post-llm.ts remove o turno 1 (responsabilidade do código, não do banco). Usado por FichaPensamentoAgente.tsx para mostrar evolução do raciocínio do agente nos últimos 5 turnos.';


--
-- Name: COLUMN prancheta.proxima_intencao; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.prancheta.proxima_intencao IS 'Predição da próxima intenção do lead (objecao_preco|objecao_prazo|objecao_confianca|fechamento|sumir). Alimenta A3 Predictive pre-objection do planejador.';


--
-- Name: COLUMN prancheta.proximo_passo_previsto; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.prancheta.proximo_passo_previsto IS 'Texto livre — o que o agente PLANEJA fazer no próximo turno. Aparece na Ficha Transparente do admin (Sprint D).';


--
-- Name: COLUMN prancheta.estilo_lead; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.prancheta.estilo_lead IS 'formal|informal|misto — detectado por LSM e usado no Ajuste 4 espelhamento_sutil.';


--
-- Name: COLUMN prancheta.origem_planejamento; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.prancheta.origem_planejamento IS 'Marca turnos de belief autônomos (sem fala do lead). NULL = turno normal de
   conversa. ''trigger_temporal'' = belief atualizado por planejar-retomada quando
   cron acordou conversa em silêncio (DEC-017).';


--
-- Name: crenca_conversa; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.crenca_conversa WITH (security_invoker='true') AS
 SELECT id,
    conversation_id,
    tenant_id,
    belief,
    resumo_agente,
    belief_historico,
    created_at,
    updated_at,
    proxima_intencao,
    proximo_passo_previsto,
    estilo_lead,
    origem_planejamento
   FROM public.prancheta;


ALTER VIEW public.crenca_conversa OWNER TO postgres;

--
-- Name: VIEW crenca_conversa; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON VIEW public.crenca_conversa IS 'DEPRECATED: usar public.prancheta. View de compat da Onda 7.';


