--
-- Name: fase_requisitos; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.fase_requisitos (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    fase text NOT NULL,
    ordem integer DEFAULT 0 NOT NULL,
    descricao_curta text NOT NULL,
    descricao_semantica text NOT NULL,
    obrigatorio boolean DEFAULT false NOT NULL,
    evidencias jsonb DEFAULT '[]'::jsonb NOT NULL,
    escopo text DEFAULT 'global'::text NOT NULL,
    nicho_id uuid,
    tenant_id uuid,
    produto_id uuid,
    agente_id uuid,
    ativo boolean DEFAULT true NOT NULL,
    vetor_semantico extensions.halfvec(1024),
    embedding_status text DEFAULT 'pendente'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    threshold double precision DEFAULT 0.5,
    combinacao_evidencias text DEFAULT 'max'::text,
    CONSTRAINT fase_requisitos_combinacao_evidencias_check CHECK ((combinacao_evidencias = ANY (ARRAY['max'::text, 'mean'::text, 'rrf'::text]))),
    CONSTRAINT fase_requisitos_embedding_status_check CHECK ((embedding_status = ANY (ARRAY['pendente'::text, 'processando'::text, 'pronto'::text, 'falhou'::text]))),
    CONSTRAINT fase_requisitos_escopo_check CHECK ((escopo = ANY (ARRAY['global'::text, 'nicho'::text, 'tenant'::text, 'produto'::text, 'agente'::text]))),
    CONSTRAINT fase_requisitos_fase_check CHECK ((fase = ANY (ARRAY['saudacao'::text, 'qualificacao'::text, 'apresentacao'::text, 'negociacao'::text, 'fechado'::text])))
);


ALTER TABLE public.fase_requisitos OWNER TO postgres;

--
-- Name: TABLE fase_requisitos; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.fase_requisitos IS 'Requisitos declarativos por fase do agente. Substituem o guard de slots textuais. Avaliados com evidencias compostas em OR. Embedding via Cohere embed-v4.0 para evidencia sinal_semantico.';


--
-- Name: COLUMN fase_requisitos.fase; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.fase_requisitos.fase IS 'Fase da conversa: saudacao | qualificacao | apresentacao | negociacao | fechado';


--
-- Name: COLUMN fase_requisitos.descricao_semantica; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.fase_requisitos.descricao_semantica IS 'Texto embedado pelo gerar-embedding via Cohere. Usado na evidencia sinal_semantico para medir similaridade com as ultimas mensagens da conversa.';


--
-- Name: COLUMN fase_requisitos.obrigatorio; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.fase_requisitos.obrigatorio IS 'Se true: trava avanco de fase ate cumprido. Se false: gera hint para o agente sem bloquear.';


--
-- Name: COLUMN fase_requisitos.evidencias; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.fase_requisitos.evidencias IS 'Array de evidencias em OR. Tipos: captura (dadosMerged[alvo] preenchido), flag (dadosMerged[alvo]=sim), trigger (acao disparada na conversa), sinal_semantico (similaridade Cohere com descricao_semantica).';


--
-- Name: COLUMN fase_requisitos.ativo; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.fase_requisitos.ativo IS 'Soft delete: false = inativo. Nunca deletar fisicamente — preservar para auditoria.';


--
-- Name: COLUMN fase_requisitos.embedding_status; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.fase_requisitos.embedding_status IS 'Status do pipeline Cohere: pending (aguardando) | processing (em andamento) | ready (pronto) | failed (erro).';


--
-- Name: COLUMN fase_requisitos.threshold; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.fase_requisitos.threshold IS 'Score mínimo (0.0-1.0) pra requisito ser considerado cumprido. Default 0.5 conservador. Curador pode override por requisito. Onda 2 redesign-fluxo-fase-rag-first.';


--
-- Name: COLUMN fase_requisitos.combinacao_evidencias; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.fase_requisitos.combinacao_evidencias IS 'Como combinar scores das evidências em OR. max=primeira melhor, mean=média ponderada (futuro), rrf=fusão recíproca (futuro). Default max (KISS v1). Onda 2.';


