    CONSTRAINT eventos_autor CHECK (((origem <> 'app'::text) OR (autor_uid IS NOT NULL))),
    CONSTRAINT eventos_autor_nome CHECK ((length(btrim(autor_nome)) > 0)),
    CONSTRAINT eventos_origem CHECK ((origem = ANY (ARRAY['app'::text, 'importado'::text, 'sql'::text, 'terminal'::text]))),
    CONSTRAINT eventos_tipo CHECK ((tipo = ANY (ARRAY['criacao'::text, 'nota_interna'::text, 'contato_cliente'::text, 'status'::text, 'responsavel'::text, 'prioridade'::text, 'categoria'::text, 'escalonamento'::text, 'devolucao'::text, 'fechamento'::text, 'reabertura'::text])))
);

