--
-- Name: gestao_chamados; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.gestao_chamados (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    numero integer NOT NULL,
    cliente_id uuid NOT NULL,
    cliente_nome text NOT NULL,
    atend_id uuid,
    titulo text NOT NULL,
    relato text NOT NULL,
    canal text NOT NULL,
    relatado_por text,
    categoria text NOT NULL,
    prioridade text DEFAULT 'media'::text NOT NULL,
    status text DEFAULT 'aberto'::text NOT NULL,
    responsavel text,
    passou_pd boolean DEFAULT false NOT NULL,
    aberto_em timestamp with time zone DEFAULT now() NOT NULL,
    primeira_resposta_em timestamp with time zone,
    status_desde timestamp with time zone DEFAULT now() NOT NULL,
    resolvido_em timestamp with time zone,
    causa text,
    solucao text,
    resultado text,
    importado boolean DEFAULT false NOT NULL,
    criado_em timestamp with time zone DEFAULT now() NOT NULL,
    atualizado_em timestamp with time zone DEFAULT now() NOT NULL,
    deleted_at timestamp with time zone,
    CONSTRAINT chamados_aberto_sem_data CHECK (((status = ANY (ARRAY['resolvido'::text, 'nao_resolvido'::text])) OR (resolvido_em IS NULL))),
    CONSTRAINT chamados_canal CHECK ((canal = ANY (ARRAY['whatsapp'::text, 'chat'::text, 'telefone'::text, 'email'::text, 'terminal'::text, 'reuniao'::text, 'outro'::text]))),
    CONSTRAINT chamados_categoria CHECK ((categoria = ANY (ARRAY['agente'::text, 'whatsapp'::text, 'acesso'::text, 'erro'::text, 'integracao'::text, 'dados'::text, 'duvida'::text, 'melhoria'::text, 'seguranca'::text, 'outro'::text]))),
    CONSTRAINT chamados_nao_resolvido CHECK (((status <> 'nao_resolvido'::text) OR ((resolvido_em IS NOT NULL) AND (length(btrim(COALESCE(resultado, ''::text))) > 0)))),
    CONSTRAINT chamados_prioridade CHECK ((prioridade = ANY (ARRAY['alta'::text, 'media'::text, 'baixa'::text]))),
    CONSTRAINT chamados_relato CHECK ((length(btrim(relato)) > 0)),
    CONSTRAINT chamados_resolvido CHECK (((status <> 'resolvido'::text) OR ((resolvido_em IS NOT NULL) AND (length(btrim(COALESCE(causa, ''::text))) > 0) AND (length(btrim(COALESCE(solucao, ''::text))) > 0) AND (length(btrim(COALESCE(resultado, ''::text))) > 0)))),
    CONSTRAINT chamados_status CHECK ((status = ANY (ARRAY['aberto'::text, 'andamento'::text, 'aguardando_cliente'::text, 'aguardando_equipe'::text, 'resolvido'::text, 'nao_resolvido'::text]))),
    CONSTRAINT chamados_titulo CHECK (((length(btrim(titulo)) >= 3) AND (length(btrim(titulo)) <= 200)))
);

ALTER TABLE ONLY public.gestao_chamados FORCE ROW LEVEL SECURITY;


ALTER TABLE public.gestao_chamados OWNER TO postgres;

