--
-- Name: leads; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.leads (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    phone text,
    tenant_id uuid,
    created_at timestamp with time zone DEFAULT now(),
    name text,
    email text,
    fase_pipeline text DEFAULT 'novo'::text,
    temperatura_lead text DEFAULT 'frio'::text,
    origem_lead text,
    divida_total numeric,
    produto text,
    tags text[],
    precisa_humano boolean DEFAULT false,
    total_mensagens integer DEFAULT 0,
    pontuacao integer DEFAULT 0,
    updated_at timestamp with time zone DEFAULT now(),
    nome_exibicao text,
    url_foto_perfil text,
    canal_externo text DEFAULT 'whatsapp'::text,
    id_externo text,
    agente_id uuid,
    fase_cliente text,
    converted_at timestamp with time zone,
    chave_rastreamento uuid DEFAULT gen_random_uuid(),
    client_checkpoints jsonb DEFAULT '{}'::jsonb,
    tarefas_cliente jsonb DEFAULT '[]'::jsonb,
    nome_provedor text,
    is_hot boolean DEFAULT false NOT NULL,
    assigned_to uuid,
    opt_out_at timestamp with time zone,
    deleted_at timestamp with time zone,
    dados_ficha jsonb DEFAULT '{}'::jsonb NOT NULL,
    perfil_estilo jsonb DEFAULT '{}'::jsonb,
    location text DEFAULT 'atendimento'::text NOT NULL,
    custom_fields jsonb DEFAULT '{}'::jsonb NOT NULL,
    desfecho text,
    desfecho_em timestamp with time zone,
    desfecho_motivo text,
    valor_conversao numeric(12,2),
    mesclado_em uuid,
    pasta_base_id uuid,
    ultima_resposta_lead_em timestamp with time zone,
    CONSTRAINT leads_desfecho_check CHECK ((desfecho = ANY (ARRAY['convertido'::text, 'recusado'::text, 'sumido'::text, 'desqualificado'::text, 'outro'::text]))),
    CONSTRAINT leads_lead_temperature_check CHECK (((temperatura_lead IS NULL) OR (temperatura_lead = ANY (ARRAY['frio'::text, 'morno'::text, 'quente'::text])))),
    CONSTRAINT leads_location_check CHECK ((location = ANY (ARRAY['atendimento'::text, 'base'::text, 'cliente'::text])))
);


ALTER TABLE public.leads OWNER TO postgres;

--
-- Name: COLUMN leads.fase_cliente; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.leads.fase_cliente IS 'Estagio pos-venda: documentacao, protocolo, andamento, concluido';


--
-- Name: COLUMN leads.converted_at; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.leads.converted_at IS 'Data em que o lead foi convertido em cliente';


--
-- Name: COLUMN leads.opt_out_at; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.leads.opt_out_at IS 'LGPD opt-out timestamp. Quando setado, agente nao mais responde/contata o lead. Set via trigger recusa_alta/opt_out_total.';


--
-- Name: COLUMN leads.deleted_at; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.leads.deleted_at IS 'Soft delete — populado pelo botão Deletar da Ficha. NULL = ativo.';


--
-- Name: COLUMN leads.dados_ficha; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.leads.dados_ficha IS 'Dados estruturados do indivíduo (alta cardinalidade, não segmenta). Estrutura sugerida: data_nascimento, endereco{estado,cidade,cep}, email, telefone, renda_mensal, filhos[], dividas[], score_credito, profissao, estado_civil, genero. Tags derivadas (aniversariante, faixa_idade, estado, ...) são geradas automaticamente via derive_tags_for_lead.';


--
-- Name: COLUMN leads.perfil_estilo; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.leads.perfil_estilo IS 'Estilo linguístico do lead computado por cron horário. Campos esperados:
   {registro: formal|informal|misto, comprimento_medio: int, ritmo_mensagens: text,
    pontuacao: baixa|media|alta, capitalizacao: minuscula|normal|caps,
    usa_emoji: bool, conectores_frequentes: text[], amostras_recentes: text[]}.
   D48+D49 brainstorming-prompt.md';


--
-- Name: COLUMN leads.location; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.leads.location IS 'Localização do contato: atendimento (em atendimento ativo), base (refinamento/standby), cliente (pós-venda em andamento). Campanha não é location — é estado paralelo via campaign_leads.';


--
-- Name: COLUMN leads.custom_fields; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.leads.custom_fields IS 'Campos personalizados livres do tenant (chave→valor string). Diferente de lead_cards.dados_capturados (do agente).';


--
-- Name: COLUMN leads.desfecho; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.leads.desfecho IS 'Trilho B1 — fechamento de ciclo do lead. NULL = ainda ativo. convertido = virou cliente. sumido = >7d sem responder. recusado = explicitamente não quer. desqualificado = fora do ICP.';


--
-- Name: COLUMN leads.desfecho_em; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.leads.desfecho_em IS 'Quando o desfecho foi cravado (manual ou via cron-leads-sumidos).';


--
-- Name: COLUMN leads.desfecho_motivo; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.leads.desfecho_motivo IS 'Texto curto livre do motivo. Cron-leads-sumidos preenche "sem resposta há Xd".';


--
-- Name: COLUMN leads.valor_conversao; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.leads.valor_conversao IS 'Valor financeiro da conversão (R$). Populado quando desfecho=convertido (via tool marcar_contrato_assinado ou UI manual em /atendimento).';


--
-- Name: COLUMN leads.pasta_base_id; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.leads.pasta_base_id IS 'Pasta do app Base onde o contato vive (1 só). Persiste quando ele volta pro Conversas.';


