    categoria text DEFAULT 'geral'::text NOT NULL,
    origem_conversa_id uuid,
    ativa boolean DEFAULT true NOT NULL,
    criado_em timestamp with time zone DEFAULT now() NOT NULL,
    atualizado_em timestamp with time zone DEFAULT now() NOT NULL,
    vetor_semantico extensions.halfvec(1024),
    embedding_status text DEFAULT 'pendente'::text NOT NULL,
    relevancia text DEFAULT 'media'::text NOT NULL,
    vezes_evocado integer DEFAULT 0 NOT NULL,
    ultima_evocacao_em timestamp with time zone,
    valido_ate timestamp with time zone
);


ALTER TABLE public.memoria_dono OWNER TO postgres;

--
-- Name: memoria_episodica; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.memoria_episodica (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    conversation_id uuid NOT NULL,
    lead_id uuid,
    episodio_resumo text NOT NULL,
    gancho text,
    emocao text,
    turno_inicio integer NOT NULL,
    turno_fim integer NOT NULL,
    duracao_turnos integer GENERATED ALWAYS AS (((turno_fim - turno_inicio) + 1)) STORED,
    relevancia numeric(3,2) DEFAULT 0.50 NOT NULL,
    decay_factor numeric(3,2) DEFAULT 1.00 NOT NULL,
    vetor_semantico extensions.halfvec(1024),
    embedding_status text DEFAULT 'pendente'::text NOT NULL,
    criado_em timestamp with time zone DEFAULT now() NOT NULL,
    atualizado_em timestamp with time zone DEFAULT now() NOT NULL,
    ativa boolean DEFAULT true NOT NULL,
    outcome text,
    CONSTRAINT episodic_memory_decay_factor_check CHECK (((decay_factor >= (0)::numeric) AND (decay_factor <= (1)::numeric))),
    CONSTRAINT episodic_memory_outcome_check CHECK ((outcome = ANY (ARRAY['fechado'::text, 'retomado'::text, 'desistiu'::text, 'perdido'::text, 'encerrado_natural'::text, 'sem_resultado'::text]))),
    CONSTRAINT episodic_memory_relevancia_check CHECK (((relevancia >= (0)::numeric) AND (relevancia <= (1)::numeric))),
    CONSTRAINT memoria_episodica_embedding_status_check CHECK ((embedding_status = ANY (ARRAY['pendente'::text, 'processando'::text, 'pronto'::text, 'falhou'::text])))
);


ALTER TABLE public.memoria_episodica OWNER TO postgres;

--
-- Name: TABLE memoria_episodica; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.memoria_episodica IS 'Memória episódica do agente — momentos da conversa que viraram lembrança consultável. Decay via cron decay-episodios.';


--
-- Name: COLUMN memoria_episodica.gancho; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.memoria_episodica.gancho IS 'Frase-chave evocativa que o agente pode usar pra puxar a lembrança ("lembra quando você me disse...").';


--
-- Name: COLUMN memoria_episodica.decay_factor; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.memoria_episodica.decay_factor IS 'DEPRECATED 2026-04-30. Não use. O peso de recência é calculado em runtime via public.peso_recencia_episodio(criado_em). Coluna mantida por retrocompatibilidade — sempre 1.0.';


--
-- Name: COLUMN memoria_episodica.outcome; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.memoria_episodica.outcome IS 'Desfecho do episódio. Alimentado por cron-decay-episodios após análise da conversa completa.';


--
-- Name: memoria_lead; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.memoria_lead (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    lead_id uuid NOT NULL,
    tenant_id uuid NOT NULL,
    fato text NOT NULL,
    categoria text DEFAULT 'outro'::text NOT NULL,
    relevancia text DEFAULT 'media'::text NOT NULL,
    fonte text DEFAULT 'auto'::text NOT NULL,
    conversation_id uuid,
    vetor_semantico extensions.halfvec(1024),
    embedding_status text DEFAULT 'pendente'::text NOT NULL,
    criado_em timestamp with time zone DEFAULT now() NOT NULL,
    atualizado_em timestamp with time zone DEFAULT now() NOT NULL,
    ativa boolean DEFAULT true NOT NULL,
    created_by uuid,
    confianca numeric(3,2) DEFAULT 0.8 NOT NULL,
    sistema_expirou_em timestamp with time zone,
    valido_desde timestamp with time zone,
    valido_ate timestamp with time zone,
    fonte_turno integer,
    escopo text DEFAULT 'longo'::text NOT NULL,
    modulo text,
    destilado_em timestamp with time zone,
    origem_curto_ids uuid[],
    confirmado_pelo_lead boolean DEFAULT false NOT NULL,
    confirmado_em timestamp with time zone,
    confirmado_por uuid,
    vezes_evocado integer DEFAULT 0 NOT NULL,
    ultima_evocacao_em timestamp with time zone,
    valencia_emocional numeric DEFAULT 0.0 NOT NULL,
    CONSTRAINT lead_memory_categoria_check CHECK ((categoria = ANY (ARRAY['fato_biografico'::text, 'fato_financeiro'::text, 'objecao'::text, 'interesse'::text, 'historico_negociacao'::text]))),
    CONSTRAINT lead_memory_confianca_check CHECK (((confianca >= (0)::numeric) AND (confianca <= (1)::numeric))),
    CONSTRAINT lead_memory_escopo_check CHECK ((escopo = ANY (ARRAY['curto'::text, 'longo'::text]))),
    CONSTRAINT lead_memory_fonte_check CHECK ((fonte = ANY (ARRAY['auto'::text, 'manual'::text, 'teste'::text, 'producao'::text]))),
    CONSTRAINT lead_memory_modulo_check CHECK (((modulo IS NULL) OR (modulo = ANY (ARRAY['atendimento'::text, 'base'::text, 'campanha'::text, 'clientes'::text, 'agente'::text])))),
    CONSTRAINT lead_memory_relevancia_check CHECK ((relevancia = ANY (ARRAY['alta'::text, 'media'::text, 'baixa'::text]))),
    CONSTRAINT memoria_lead_embedding_status_check CHECK ((embedding_status = ANY (ARRAY['pendente'::text, 'processando'::text, 'pronto'::text, 'falhou'::text])))
);


ALTER TABLE public.memoria_lead OWNER TO postgres;

--
-- Name: COLUMN memoria_lead.categoria; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.memoria_lead.categoria IS 'Classificação white-label do fato memorizado (sem referência a nicho específico). demografico — idade, gênero, cidade, estado civil, profissão declarada. familia — filhos, cônjuge, dependentes, situação familiar. financeiro — renda, patrimônio, dívidas, investimentos, restrições no nome. trabalho — empresa, cargo, tempo de experiência, histórico de desemprego. saude — condições de saúde, histórico médico, medicamentos em uso. interesse — hobbies, desejos, planos de vida, compras pretendidas. objecao — barreiras declaradas, preocupações, resistências ao produto/serviço. historico_relacionamento — já contratou/pagou/reclamou/cancelou, status atual do relacionamento. outro — fallback quando não encaixa nos 8 acima. Padrão do sistema.';


--
-- Name: COLUMN memoria_lead.fonte; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.memoria_lead.fonte IS 'Origem do fato. auto = extract-lead-facts (produção); manual = operador humano; producao = explicitamente marcado como produção; teste = fixture de teste — NUNCA aparece em buscas semânticas/híbridas.';


--
-- Name: COLUMN memoria_lead.confianca; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.memoria_lead.confianca IS 'Confiança do extrator (0..1) na classificação do fato. Gravado pelo extract-lead-facts. Default 0.8 para rows legadas ou fontes manuais.';


--
-- Name: COLUMN memoria_lead.sistema_expirou_em; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.memoria_lead.sistema_expirou_em IS 'Quando o sistema marcou esse fato como expirado/substituido por bloco mais recente. NULL = ainda vivo no sistema.';


--
-- Name: COLUMN memoria_lead.valido_desde; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.memoria_lead.valido_desde IS 'Início da validade desse fato no mundo real (pode ser passada). NULL = não rastreado.';


--
-- Name: COLUMN memoria_lead.valido_ate; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.memoria_lead.valido_ate IS 'Fim da validade desse fato no mundo real. NULL = ainda vale.';


--
-- Name: COLUMN memoria_lead.fonte_turno; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.memoria_lead.fonte_turno IS 'Número do turno (cicloFase) onde esse fato foi extraído pelo agente. NULL = origem manual ou cron (não-turno).';


--
-- Name: COLUMN memoria_lead.escopo; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.memoria_lead.escopo IS 'curto = volátil por módulo, destilada pra longo via cron. longo = fato consolidado permanente, cruza módulos. Backfill: todas as rows pré-existentes ficam como longo.';


--
-- Name: COLUMN memoria_lead.modulo; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.memoria_lead.modulo IS 'Quando escopo=curto, qual módulo gerou. NULL pra longo.';


--
-- Name: COLUMN memoria_lead.vezes_evocado; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.memoria_lead.vezes_evocado IS 'A5 memória viva: reforço hebbiano — nº de vezes que o fato foi recuperado no recall.';


--
-- Name: COLUMN memoria_lead.ultima_evocacao_em; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.memoria_lead.ultima_evocacao_em IS 'A5 memória viva: relógio do esquecimento (Ebbinghaus) — última evocação.';


--
-- Name: COLUMN memoria_lead.valencia_emocional; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.memoria_lead.valencia_emocional IS 'A5 memória viva: carga emocional 0..1 (preenchida pela destilação A6); modula saliência.';


--
-- Name: CONSTRAINT lead_memory_categoria_check ON memoria_lead; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON CONSTRAINT lead_memory_categoria_check ON public.memoria_lead IS 'Alinhado com ExtractLeadFactsOutputSchema.CategoriasLeadMemory em supabase/functions/extract-lead-facts/schema.ts';


