    CONSTRAINT pacotes_conhecimento_nome_check CHECK (((length(TRIM(BOTH FROM nome)) >= 1) AND (length(TRIM(BOTH FROM nome)) <= 120))),
    CONSTRAINT pacotes_conhecimento_origem_check CHECK ((origem = ANY (ARRAY['admin'::text, 'tenant'::text])))
);


