    titulo text NOT NULL,
    conteudo text NOT NULL,
    modo text DEFAULT 'relevancia'::text NOT NULL,
    category text,
    tags text[] DEFAULT '{}'::text[] NOT NULL,
    ordem integer DEFAULT 0 NOT NULL,
    ativo boolean DEFAULT true NOT NULL,
    vetor_semantico extensions.halfvec(1024),
    fts tsvector,
    embedding_status text DEFAULT 'pronto'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    deleted_at timestamp with time zone,
    CONSTRAINT pacotes_blocos_embedding_status_check CHECK ((embedding_status = ANY (ARRAY['pendente'::text, 'pronto'::text, 'erro'::text]))),
    CONSTRAINT pacotes_blocos_modo_check CHECK ((modo = ANY (ARRAY['sempre'::text, 'relevancia'::text]))),
    CONSTRAINT pacotes_blocos_tamanho_check CHECK (((length(conteudo) >= 1) AND (length(conteudo) <=
CASE
    WHEN (modo = 'sempre'::text) THEN 1500
    ELSE 8000
END))),
    CONSTRAINT pacotes_blocos_titulo_check CHECK (((length(TRIM(BOTH FROM titulo)) >= 1) AND (length(TRIM(BOTH FROM titulo)) <= 200)))
);


