    CONSTRAINT regras_operacionais_chunks_categoria_check CHECK ((categoria = ANY (ARRAY['rag_threshold'::text, 'rerank'::text, 'delay_bolha'::text, 'limite_bolha'::text, 'pausa'::text, 'modelo_llm'::text, 'embed'::text, 'fluxo_fase_threshold'::text]))),
    CONSTRAINT regras_operacionais_chunks_escopo_check CHECK ((escopo = ANY (ARRAY['global'::text, 'nicho'::text, 'tenant'::text])))
);


ALTER TABLE public.regras_operacionais_blocos OWNER TO postgres;

--
-- Name: TABLE regras_operacionais_blocos; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.regras_operacionais_blocos IS 'Regras operacionais por escopo (global/nicho/tenant). Override de configs vindas de trigger_thresholds, etc. Precedência efetiva: tenant > nicho > global. Resolução via tool admin_ia.threshold_resolver_efetivo.';


--
-- Name: COLUMN regras_operacionais_blocos.parametros; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.regras_operacionais_blocos.parametros IS 'Schema fixo por categoria (precedência: tenant > nicho > global):
- threshold: {acao: text, threshold: numeric (0..1)}
- rerank: {top_k: int, mmr: numeric (0..1), decay: numeric (0..1)}
- delay: {ms: int, jitter: int}
- limite: {max: int, janela: text}
- pausa: {horas: int, motivo: text}
- modelo: {slug: text, temperatura: numeric}
- embed: {modelo: text, dim: int}';


