    CONSTRAINT rifas_preco_numero_centavos_check CHECK ((preco_numero_centavos > 0)),
    CONSTRAINT rifas_status_check CHECK ((status = ANY (ARRAY['rascunho'::text, 'ativa'::text, 'pausada'::text, 'encerrada'::text, 'sorteada'::text]))),
    CONSTRAINT rifas_total_numeros_check CHECK (((total_numeros >= 1) AND (total_numeros <= 100000)))
);


