--
-- Name: v_gargalos_campanha_tenant; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.v_gargalos_campanha_tenant WITH (security_invoker='true') AS
 SELECT c.tenant_id,
    c.id AS campaign_id,
    c.name AS campaign_name,
    cl.phase AS fase,
    count(*) AS leads_na_fase,
    avg((EXTRACT(epoch FROM (now() - cl.entered_at)) / (3600)::numeric)) AS horas_medias_na_fase
   FROM (public.leads_campanha cl
     JOIN public.campanhas c ON ((c.id = cl.campaign_id)))
  WHERE (cl.entered_at > (now() - '30 days'::interval))
  GROUP BY c.tenant_id, c.id, c.name, cl.phase
 HAVING (count(*) >= 3);


ALTER VIEW public.v_gargalos_campanha_tenant OWNER TO postgres;

--
-- Name: v_leads_por_fase_tenant; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.v_leads_por_fase_tenant WITH (security_invoker='true') AS
 SELECT tenant_id,
    fase_pipeline AS fase,
    count(*) AS total,
    count(*) FILTER (WHERE (updated_at > (now() - '7 days'::interval))) AS ultimos_7d
   FROM public.leads
  WHERE (deleted_at IS NULL)
  GROUP BY tenant_id, fase_pipeline;


ALTER VIEW public.v_leads_por_fase_tenant OWNER TO postgres;

--
-- Name: valores_ficha; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.valores_ficha (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    lead_id uuid NOT NULL,
    tenant_id uuid NOT NULL,
    campo_id uuid NOT NULL,
    valor jsonb NOT NULL,
    valor_texto text GENERATED ALWAYS AS (
CASE jsonb_typeof(valor)
    WHEN 'string'::text THEN (valor #>> '{}'::text[])
    WHEN 'number'::text THEN (valor)::text
    WHEN 'boolean'::text THEN (valor)::text
    ELSE (valor)::text
END) STORED,
    real_world_valid_from timestamp with time zone,
    real_world_valid_to timestamp with time zone,
    valid_from timestamp with time zone DEFAULT now() NOT NULL,
    valid_to timestamp with time zone,
    substituido_por_id uuid,
    recorded_by text DEFAULT 'agente'::text NOT NULL,
    recorded_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT ficha_form_valores_recorded_by_check CHECK ((recorded_by = ANY (ARRAY['agente'::text, 'atendente'::text, 'tenant'::text, 'destilacao_cron'::text])))
);


ALTER TABLE public.valores_ficha OWNER TO postgres;

--
-- Name: TABLE valores_ficha; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.valores_ficha IS 'Valores preenchidos da ficha do contato (Curadoria v2 · F3). Bitemporal: real_world_valid_from/to (quando o fato é/era verdade no mundo) + valid_from/to (quando foi registrado no sistema). Histórico nunca apagado. UNIQUE partial garante só 1 versão atual por (lead, campo). Source: agente|atendente|tenant|destilacao_cron.';


