--
-- Name: vw_bolhas_barradas; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.vw_bolhas_barradas WITH (security_invoker='on') AS
 SELECT (date_trunc('day'::text, c.created_at))::date AS dia,
    c.error_reason,
    c.tenant_id,
    p.full_name AS tenant,
    count(*) AS bolhas,
    max(c.created_at) AS ultima,
    (array_agg("left"(c.content, 160) ORDER BY c.created_at DESC))[1] AS exemplo
   FROM (public.caixa_saida_mensagens c
     LEFT JOIN public.profiles p ON ((p.id = c.tenant_id)))
  WHERE ((c.error_reason = ANY (ARRAY['link_contrato_fantasma'::text, 'placeholder_nao_resolvido'::text])) AND (c.created_at > (now() - '7 days'::interval)))
  GROUP BY ((date_trunc('day'::text, c.created_at))::date), c.error_reason, c.tenant_id, p.full_name
  ORDER BY ((date_trunc('day'::text, c.created_at))::date) DESC, (count(*)) DESC;


ALTER VIEW public.vw_bolhas_barradas OWNER TO postgres;

--
-- Name: VIEW vw_bolhas_barradas; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON VIEW public.vw_bolhas_barradas IS 'Bolhas barradas por guard nos últimos 7 dias, agrupadas por dia/motivo/tenant. security_invoker=on e sem grant pra anon/authenticated: é diagnóstico de operação, consultada com service_role. Ver migration 20260905_fecha_vazamento_vw_bolhas_barradas.';


--
-- Name: vw_cerebro_kpis_1h; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.vw_cerebro_kpis_1h WITH (security_invoker='true') AS
 WITH base AS (
         SELECT t.latencia_ms,
            t.modelo_llm,
                CASE
                    WHEN (t.modelo_llm ~~* '%gemini-2.5-pro%'::text) THEN (((COALESCE(t.custo_tokens_in, 0))::numeric * 0.00000125) + ((COALESCE(t.custo_tokens_out, 0))::numeric * 0.000005))
                    WHEN (t.modelo_llm ~~* '%gemini%'::text) THEN (((COALESCE(t.custo_tokens_in, 0))::numeric * 0.000000075) + ((COALESCE(t.custo_tokens_out, 0))::numeric * 0.0000003))
                    WHEN (t.modelo_llm ~~* '%gpt-4o-mini%'::text) THEN (((COALESCE(t.custo_tokens_in, 0))::numeric * 0.00000015) + ((COALESCE(t.custo_tokens_out, 0))::numeric * 0.0000006))
                    WHEN (t.modelo_llm ~~* '%gpt-4o%'::text) THEN (((COALESCE(t.custo_tokens_in, 0))::numeric * 0.0000025) + ((COALESCE(t.custo_tokens_out, 0))::numeric * 0.00001))
                    ELSE (((COALESCE(t.custo_tokens_in, 0))::numeric * 0.0000005) + ((COALESCE(t.custo_tokens_out, 0))::numeric * 0.0000015))
                END AS custo_usd
           FROM public.traces t
          WHERE (t.criado_em >= (now() - '01:00:00'::interval))
        )
 SELECT (count(*))::integer AS turnos_hora,
    COALESCE(percentile_disc((0.5)::double precision) WITHIN GROUP (ORDER BY latencia_ms), 0) AS latencia_p50_ms,
    COALESCE(percentile_disc((0.95)::double precision) WITHIN GROUP (ORDER BY latencia_ms), 0) AS latencia_p95_ms,
    (COALESCE(sum(custo_usd), (0)::numeric))::numeric(12,4) AS custo_hora_usd,
    now() AS calculado_em
   FROM base;


ALTER VIEW public.vw_cerebro_kpis_1h OWNER TO postgres;

--
-- Name: VIEW vw_cerebro_kpis_1h; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON VIEW public.vw_cerebro_kpis_1h IS 'KPIs do motor última hora: turnos, p50/p95 latência, custo total USD estimado.';


--
-- Name: vw_cerebro_turnos_recentes; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.vw_cerebro_turnos_recentes WITH (security_invoker='true') AS
 SELECT t.id,
    t.criado_em,
    t.lead_id,
    t.tenant_id,
    t.modelo_llm,
    (t.tipo)::text AS tipo,
    t.latencia_ms,
    t.custo_tokens_in,
    t.custo_tokens_out,
    t.confianca,
    c.nome AS cargo_nome,
    l.name AS lead_nome,
        CASE
            WHEN (t.modelo_llm ~~* '%gemini-2.5-pro%'::text) THEN (((COALESCE(t.custo_tokens_in, 0))::numeric * 0.00000125) + ((COALESCE(t.custo_tokens_out, 0))::numeric * 0.000005))
            WHEN (t.modelo_llm ~~* '%gemini-2.5-flash-lite%'::text) THEN (((COALESCE(t.custo_tokens_in, 0))::numeric * 0.000000075) + ((COALESCE(t.custo_tokens_out, 0))::numeric * 0.0000003))
            WHEN (t.modelo_llm ~~* '%gemini%flash%'::text) THEN (((COALESCE(t.custo_tokens_in, 0))::numeric * 0.000000075) + ((COALESCE(t.custo_tokens_out, 0))::numeric * 0.0000003))
            WHEN (t.modelo_llm ~~* '%gpt-4o-mini%'::text) THEN (((COALESCE(t.custo_tokens_in, 0))::numeric * 0.00000015) + ((COALESCE(t.custo_tokens_out, 0))::numeric * 0.0000006))
            WHEN (t.modelo_llm ~~* '%gpt-4o%'::text) THEN (((COALESCE(t.custo_tokens_in, 0))::numeric * 0.0000025) + ((COALESCE(t.custo_tokens_out, 0))::numeric * 0.00001))
            ELSE (((COALESCE(t.custo_tokens_in, 0))::numeric * 0.0000005) + ((COALESCE(t.custo_tokens_out, 0))::numeric * 0.0000015))
        END AS custo_usd_estimado
   FROM ((public.traces t
     LEFT JOIN public.cargos c ON ((c.id = t.cargo_id)))
     LEFT JOIN public.leads l ON ((l.id = t.lead_id)))
  WHERE ((t.criado_em >= (now() - '24:00:00'::interval)) AND ((EXISTS ( SELECT 1
           FROM public.user_roles ur
          WHERE ((ur.user_id = ( SELECT auth.uid() AS uid)) AND (ur.role = ANY (ARRAY['admin'::text, 'platform_admin'::text]))))) OR (t.tenant_id = ( SELECT auth.uid() AS uid))))
  ORDER BY t.criado_em DESC
 LIMIT 100;


ALTER VIEW public.vw_cerebro_turnos_recentes OWNER TO postgres;

--
-- Name: vw_cron_saude; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.vw_cron_saude WITH (security_invoker='true') AS
 WITH stats AS (
         SELECT d.jobid,
            max(d.start_time) AS ultima_exec,
            count(*) FILTER (WHERE (d.status = 'failed'::text)) AS falhas_7d,
            count(*) FILTER (WHERE (d.status = 'succeeded'::text)) AS sucessos_7d,
            round(avg((EXTRACT(epoch FROM (d.end_time - d.start_time)) * (1000)::numeric)) FILTER (WHERE (d.end_time IS NOT NULL)), 0) AS duracao_media_ms
           FROM cron.job_run_details d
          WHERE (d.start_time > (now() - '7 days'::interval))
          GROUP BY d.jobid
        ), ultima AS (
         SELECT DISTINCT ON (job_run_details.jobid) job_run_details.jobid,
            job_run_details.status AS status_ultima
           FROM cron.job_run_details
          WHERE (job_run_details.start_time > (now() - '7 days'::interval))
          ORDER BY job_run_details.jobid, job_run_details.start_time DESC
        )
 SELECT j.jobid,
    j.jobname,
    j.schedule,
    j.active,
    s.ultima_exec,
    COALESCE(s.falhas_7d, (0)::bigint) AS falhas_7d,
    COALESCE(s.sucessos_7d, (0)::bigint) AS sucessos_7d,
    s.duracao_media_ms,
    u.status_ultima
   FROM ((cron.job j
     LEFT JOIN stats s ON ((s.jobid = j.jobid)))
     LEFT JOIN ultima u ON ((u.jobid = j.jobid)));


ALTER VIEW public.vw_cron_saude OWNER TO postgres;

--
-- Name: vw_dashboard_curadoria; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.vw_dashboard_curadoria WITH (security_invoker='true') AS
 WITH parametros AS (
         SELECT (now() - '30 days'::interval) AS d30_inicio,
            (now() - '7 days'::interval) AS d7_inicio,
            (now() - '24:00:00'::interval) AS d24_inicio
        ), custo_30d AS (
         SELECT (COALESCE(sum(logs_requisicao_llm.custo_total), (0)::numeric))::numeric(12,4) AS custo_total_usd,
            count(*) AS chamadas_total
           FROM public.logs_requisicao_llm,
            parametros p
          WHERE (logs_requisicao_llm.created_at >= p.d30_inicio)
        ), conversas_periodo AS (
         SELECT count(*) FILTER (WHERE (conversas.created_at >= p.d24_inicio)) AS conversas_24h,
            count(*) FILTER (WHERE (conversas.created_at >= p.d7_inicio)) AS conversas_7d,
            count(*) FILTER (WHERE (conversas.created_at >= p.d30_inicio)) AS conversas_30d
           FROM public.conversas,
            parametros p
        ), leads_atuais AS (
         SELECT count(*) FILTER (WHERE (leads.desfecho IS NULL)) AS leads_ativos,
            count(*) FILTER (WHERE (leads.desfecho = 'convertido'::text)) AS leads_convertidos,
            count(*) FILTER (WHERE (leads.desfecho = 'sumido'::text)) AS leads_sumidos,
            count(*) FILTER (WHERE (leads.desfecho = 'recusado'::text)) AS leads_recusados,
            count(*) AS leads_total
           FROM public.leads
          WHERE (leads.deleted_at IS NULL)
        ), mensagens_30d AS (
         SELECT count(*) FILTER (WHERE (mensagens.role = 'human'::text)) AS msgs_humano,
            count(*) FILTER (WHERE (mensagens.role = 'assistant'::text)) AS msgs_agente
           FROM public.mensagens,
            parametros p
          WHERE (mensagens.created_at >= p.d30_inicio)
        )
 SELECT c.custo_total_usd,
    c.chamadas_total,
    cp.conversas_24h,
    cp.conversas_7d,
    cp.conversas_30d,
    la.leads_ativos,
    la.leads_convertidos,
    la.leads_sumidos,
    la.leads_recusados,
    la.leads_total,
        CASE
            WHEN (((la.leads_convertidos + la.leads_sumidos) + la.leads_recusados) > 0) THEN round(((la.leads_convertidos)::numeric / (((la.leads_convertidos + la.leads_sumidos) + la.leads_recusados))::numeric), 4)
            ELSE (0)::numeric
        END AS taxa_conversao_global,
    m.msgs_humano,
    m.msgs_agente,
        CASE
            WHEN (m.msgs_humano > 0) THEN round(((m.msgs_agente)::numeric / (m.msgs_humano)::numeric), 2)
            ELSE (0)::numeric
        END AS msgs_por_humano,
    now() AS calculado_em
   FROM custo_30d c,
    conversas_periodo cp,
    leads_atuais la,
    mensagens_30d m;


ALTER VIEW public.vw_dashboard_curadoria OWNER TO postgres;

