-- Name: VIEW vw_dashboard_curadoria; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON VIEW public.vw_dashboard_curadoria IS 'KPIs agregados pra AbaDashboard. security_invoker=true respeita RLS do user que consulta.';


--
-- Name: vw_dashboard_serie_30d; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.vw_dashboard_serie_30d WITH (security_invoker='true') AS
 WITH dias AS (
         SELECT (generate_series((((now() - '29 days'::interval))::date)::timestamp with time zone, ((now())::date)::timestamp with time zone, '1 day'::interval))::date AS dia
        )
 SELECT d.dia,
    (COALESCE(c.qtd, (0)::bigint))::integer AS conversas
   FROM (dias d
     LEFT JOIN ( SELECT (date_trunc('day'::text, conversas.created_at))::date AS dia,
            count(*) AS qtd
           FROM public.conversas
          WHERE (conversas.created_at >= (now() - '30 days'::interval))
          GROUP BY ((date_trunc('day'::text, conversas.created_at))::date)) c ON ((c.dia = d.dia)))
  ORDER BY d.dia;


