-- Name: vw_dashboard_top_gavetas; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.vw_dashboard_top_gavetas WITH (security_invoker='true') AS
 WITH chaves AS (
         SELECT jsonb_object_keys(prompts_turno.blocos) AS chave,
            prompts_turno.blocos
           FROM public.prompts_turno
          WHERE ((prompts_turno.blocos IS NOT NULL) AND (prompts_turno.criado_em >= (now() - '30 days'::interval)))
        )
 SELECT chave AS gaveta,
    count(*) AS acionamentos
   FROM chaves
  WHERE (COALESCE((blocos ->> chave), ''::text) <> ''::text)
  GROUP BY chave
  ORDER BY (count(*)) DESC
 LIMIT 12;


