--
-- Name: vw_heatmap_humor_7d; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.vw_heatmap_humor_7d WITH (security_invoker='true') AS
 WITH grid AS (
         SELECT dow.d AS dia_semana,
            hr.h AS hora
           FROM (generate_series(0, 6) dow(d)
             CROSS JOIN generate_series(0, 23) hr(h))
        ), mudancas AS (
         SELECT (EXTRACT(dow FROM estado_afetivo_lead.atualizado_em))::integer AS dia_semana,
            (EXTRACT(hour FROM estado_afetivo_lead.atualizado_em))::integer AS hora,
            (count(*))::integer AS qtd,
            (COALESCE(avg(estado_afetivo_lead.valencia), (0)::numeric))::numeric(4,2) AS valencia_media
           FROM public.estado_afetivo_lead
          WHERE (estado_afetivo_lead.atualizado_em >= (now() - '7 days'::interval))
          GROUP BY ((EXTRACT(dow FROM estado_afetivo_lead.atualizado_em))::integer), ((EXTRACT(hour FROM estado_afetivo_lead.atualizado_em))::integer)
        )
 SELECT g.dia_semana,
    g.hora,
    COALESCE(m.qtd, 0) AS qtd,
    COALESCE(m.valencia_media, (0)::numeric) AS valencia_media
   FROM (grid g
     LEFT JOIN mudancas m ON (((m.dia_semana = g.dia_semana) AND (m.hora = g.hora))))
  ORDER BY g.dia_semana, g.hora;


ALTER VIEW public.vw_heatmap_humor_7d OWNER TO postgres;

--
-- Name: vw_metricas_ferramentas_dia; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.vw_metricas_ferramentas_dia WITH (security_invoker='true') AS
 SELECT tenant_id,
    (date_trunc('day'::text, criado_em))::date AS dia,
    tool_name AS ferramenta_nome,
    count(*) FILTER (WHERE (status = 'sucesso'::text)) AS sucessos,
    count(*) FILTER (WHERE (status <> 'sucesso'::text)) AS falhas,
    count(*) AS total
   FROM public.invocacoes_ferramenta
  WHERE (criado_em >= (now() - '30 days'::interval))
  GROUP BY tenant_id, ((date_trunc('day'::text, criado_em))::date), tool_name;


ALTER VIEW public.vw_metricas_ferramentas_dia OWNER TO postgres;

--
-- Name: vw_metricas_motor_dia; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.vw_metricas_motor_dia WITH (security_invoker='true') AS
 SELECT tenant_id,
    (date_trunc('day'::text, criado_em))::date AS dia,
    tipo,
    modelo_llm,
    count(*) AS total_eventos,
    sum(COALESCE(custo_tokens_in, 0)) AS tokens_in,
    sum(COALESCE(custo_tokens_out, 0)) AS tokens_out,
    (avg(latencia_ms))::integer AS latencia_media_ms,
    (percentile_cont((0.95)::double precision) WITHIN GROUP (ORDER BY ((latencia_ms)::double precision)))::integer AS p95_latencia_ms
   FROM public.traces
  WHERE (criado_em >= (now() - '30 days'::interval))
  GROUP BY tenant_id, ((date_trunc('day'::text, criado_em))::date), tipo, modelo_llm;


ALTER VIEW public.vw_metricas_motor_dia OWNER TO postgres;

