-- Name: empresas re_atomizar_empresa_apos_atualizar; Type: TRIGGER; Schema: public; Owner: postgres
--

CREATE TRIGGER re_atomizar_empresa_apos_atualizar AFTER UPDATE ON public.empresas FOR EACH ROW WHEN (((old.endereco IS DISTINCT FROM new.endereco) OR (old.bairro IS DISTINCT FROM new.bairro) OR (old.cidade IS DISTINCT FROM new.cidade) OR (old.estado IS DISTINCT FROM new.estado) OR (old.cep IS DISTINCT FROM new.cep) OR (old.whatsapp IS DISTINCT FROM new.whatsapp) OR (old.instagram IS DISTINCT FROM new.instagram) OR (old.facebook IS DISTINCT FROM new.facebook) OR (old.tiktok IS DISTINCT FROM new.tiktok) OR (old.youtube IS DISTINCT FROM new.youtube) OR (old.site IS DISTINCT FROM new.site) OR (old.cnpj IS DISTINCT FROM new.cnpj) OR (old.descricao IS DISTINCT FROM new.descricao) OR (old.missao IS DISTINCT FROM new.missao) OR (old.horario_funcionamento IS DISTINCT FROM new.horario_funcionamento))) EXECUTE FUNCTION public.gatilho_re_atomizar_empresa();


