CREATE POLICY acao_pausa_select_authenticated ON public.acao_pausa_blocos FOR SELECT TO authenticated USING (((escopo = ANY (ARRAY['global'::text, 'nicho'::text])) OR ((escopo = 'tenant'::text) AND (tenant_id = ( SELECT auth.uid() AS uid)))));


