-- Name: cargo_tarefas cargo_tarefas_admin; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY cargo_tarefas_admin ON public.cargo_tarefas TO authenticated USING ((EXISTS ( SELECT 1
   FROM public.cargos c
  WHERE ((c.id = cargo_tarefas.cargo_id) AND (((c.escopo = 'tenant'::public.escopo_ragentic) AND (c.tenant_id = ( SELECT auth.uid() AS uid))) OR ((c.escopo = 'global'::public.escopo_ragentic) AND public.eh_super_admin(( SELECT auth.uid() AS uid)))))))) WITH CHECK ((EXISTS ( SELECT 1
   FROM public.cargos c
  WHERE ((c.id = cargo_tarefas.cargo_id) AND (((c.escopo = 'tenant'::public.escopo_ragentic) AND (c.tenant_id = ( SELECT auth.uid() AS uid))) OR ((c.escopo = 'global'::public.escopo_ragentic) AND public.eh_super_admin(( SELECT auth.uid() AS uid))))))));


