CREATE POLICY tenant_read_blocos ON public.blocos_comportamento FOR SELECT TO authenticated USING (((((escopo = 'global'::text) AND (ativo = true)) OR ((escopo = 'nicho'::text) AND (ativo = true) AND (nicho_id = ( SELECT p.nicho_id
